('2fb6c295759ca0b350b620ff49ac9be1', 1, 'ทีมสหวิชาชีพในโรงพยาบาลชุมชนแห่งหนึ่ง (รวมถึงเภสัชกรที่ร่วมดูแลผู้ป่วย) พบผู้ป่วยที่มีอาการและประวัติเข้าได้กับโรคติดต่อที่ต้องเฝ้าระวัง แต่ผลตรวจทางห้องปฏิบัติการยืนยันยังไม่ออก ตามหลักการของ พ.ร.บ.โรคติดต่อ พ.ศ. 2558 สถานพยาบาลควรปฏิบัติอย่างไร', '[{"label": "A", "text": "รอผลตรวจยืนยันให้ครบถ้วนก่อน จึงค่อยแจ้งหน่วยงานควบคุมโรค"}, {"label": "B", "text": "แจ้งเฉพาะเมื่อผู้ป่วยหรือญาติยินยอมเป็นลายลักษณ์อักษรเท่านั้น"}, {"label": "C", "text": "แจ้งต่อเจ้าพนักงานควบคุมโรคติดต่อตั้งแต่มีเหตุสงสัย ไม่ต้องรอผลยืนยัน"}, {"label": "D", "text": "แจ้งเฉพาะกรณีที่มีผู้ป่วยตั้งแต่สองรายขึ้นไปในพื้นที่เดียวกัน"}, {"label": "E", "text": "บันทึกในเวชระเบียนไว้เท่านั้น ไม่มีหน้าที่ต้องแจ้งหน่วยงานภายนอก"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. แจ้งเจ้าพนักงานควบคุมโรคติดต่อตั้งแต่มีเหตุสงสัย — กฎหมายมุ่งให้แจ้งเร็วเพื่อควบคุมโรคได้ทันเวลา", "reason": "พ.ร.บ.โรคติดต่อ พ.ศ. 2558 กำหนดให้บุคคลที่เกี่ยวข้อง เช่น ผู้รับผิดชอบสถานพยาบาล ผู้ทำการชันสูตร และเจ้าบ้าน มีหน้าที่แจ้งต่อเจ้าพนักงานควบคุมโรคติดต่อเมื่อปรากฏว่ามีโรคติดต่ออันตราย โรคติดต่อที่ต้องเฝ้าระวัง หรือโรคระบาดเกิดขึ้น หรือมีเหตุสงสัยว่าเกิดขึ้น\n\nหลักสำคัญคือแจ้งได้และต้องแจ้งตั้งแต่ยังเป็นผู้สงสัย ไม่ต้องรอผลยืนยัน และไม่ต้องได้รับความยินยอมจากผู้ป่วย การแจ้งตามหน้าที่ที่กฎหมายกำหนดนี้จึงไม่ใช่การละเมิดความลับผู้ป่วย", "choices": [{"label": "A", "text": "รอผลตรวจยืนยันให้ครบถ้วนก่อน จึงค่อยแจ้งหน่วยงานควบคุมโรค", "is_correct": false, "explanation": "ไม่ถูกต้อง กฎหมายกำหนดให้แจ้งเมื่อพบหรือมีเหตุสงสัยว่าเกิดโรค ไม่ต้องรอผลยืนยัน เพราะการรอทำให้ควบคุมการระบาดได้ช้า"}, {"label": "B", "text": "แจ้งเฉพาะเมื่อผู้ป่วยหรือญาติยินยอมเป็นลายลักษณ์อักษรเท่านั้น", "is_correct": false, "explanation": "ไม่ถูกต้อง การแจ้งโรคเป็นหน้าที่ตามกฎหมาย ไม่ขึ้นกับความยินยอมของผู้ป่วย"}, {"label": "C", "text": "แจ้งต่อเจ้าพนักงานควบคุมโรคติดต่อตั้งแต่มีเหตุสงสัย ไม่ต้องรอผลยืนยัน", "is_correct": true, "explanation": "ถูกต้อง กฎหมายกำหนดให้แจ้งเมื่อพบหรือมีเหตุสงสัยว่าเกิดโรคติดต่ออันตราย โรคติดต่อที่ต้องเฝ้าระวัง หรือโรคระบาด เพื่อให้ควบคุมโรคได้ทันเวลา"}, {"label": "D", "text": "แจ้งเฉพาะกรณีที่มีผู้ป่วยตั้งแต่สองรายขึ้นไปในพื้นที่เดียวกัน", "is_correct": false, "explanation": "ไม่ถูกต้อง หน้าที่แจ้งเกิดขึ้นตั้งแต่พบผู้ป่วยหรือผู้สงสัยแม้เพียงรายเดียว"}, {"label": "E", "text": "บันทึกในเวชระเบียนไว้เท่านั้น ไม่มีหน้าที่ต้องแจ้งหน่วยงานภายนอก", "is_correct": false, "explanation": "ไม่ถูกต้อง การบันทึกเวชระเบียนอย่างเดียวไม่เพียงพอ กฎหมายกำหนดหน้าที่แจ้งต่อเจ้าพนักงานควบคุมโรคติดต่อ"}], "key_takeaway": "โรคติดต่อที่กฎหมายกำหนดให้แจ้ง ต้องแจ้งเจ้าพนักงานควบคุมโรคติดต่อตั้งแต่มีเหตุสงสัย ไม่ต้องรอผลยืนยันหรือความยินยอมของผู้ป่วย"}'::jsonb, 'easy', 'law-day2 • พ.ร.บ.โรคติดต่อ พ.ศ. 2558 - การแจ้งโรค'),
('546bfb8707be03145920f5cdf804c950', 2, 'ตาม พ.ร.บ.โรคติดต่อ พ.ศ. 2558 และประกาศกระทรวงสาธารณสุขที่ออกตามกฎหมายนี้ โรคใดต่อไปนี้ถูกกำหนดเป็น "โรคติดต่ออันตราย"', '[{"label": "A", "text": "โรคติดเชื้อไวรัสอีโบลา (Ebola virus disease)"}, {"label": "B", "text": "ไข้หวัดใหญ่ตามฤดูกาล"}, {"label": "C", "text": "ไข้เลือดออกเดงกี (dengue)"}, {"label": "D", "text": "โรคติดเชื้อไวรัสโคโรนา 2019 (COVID-19) ในปัจจุบัน"}, {"label": "E", "text": "โรคมือ เท้า ปาก"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. โรคติดเชื้อไวรัสอีโบลา — เป็นโรคที่รุนแรงและแพร่ระบาดได้รวดเร็ว จึงประกาศเป็นโรคติดต่ออันตราย", "reason": "พ.ร.บ.โรคติดต่อ พ.ศ. 2558 แบ่งโรคเป็น \"โรคติดต่อ\" \"โรคติดต่อที่ต้องเฝ้าระวัง\" และ \"โรคติดต่ออันตราย\" โรคติดต่ออันตรายคือโรคที่มีความรุนแรงสูงและแพร่ไปสู่ผู้อื่นได้อย่างรวดเร็ว รัฐมนตรีว่าการกระทรวงสาธารณสุขประกาศชื่อโรคโดยคำแนะนำของคณะกรรมการโรคติดต่อแห่งชาติ ตัวอย่างเช่น กาฬโรค ไข้ทรพิษ ไข้เลือดออกไครเมียน-คองโก โรคติดเชื้อไวรัสอีโบลา และโรคทางเดินหายใจตะวันออกกลาง (MERS)\n\nโรคที่พบบ่อยอย่างไข้เลือดออกเดงกีหรือมือ เท้า ปาก จัดเป็นโรคติดต่อที่ต้องเฝ้าระวัง ส่วน COVID-19 ถูกปรับจากโรคติดต่ออันตรายเป็นโรคติดต่อที่ต้องเฝ้าระวังตั้งแต่ 1 ตุลาคม 2565", "choices": [{"label": "A", "text": "โรคติดเชื้อไวรัสอีโบลา (Ebola virus disease)", "is_correct": true, "explanation": "ถูกต้อง โรคติดเชื้อไวรัสอีโบลาประกาศเป็นโรคติดต่ออันตราย ร่วมกับโรค เช่น กาฬโรค ไข้ทรพิษ และโรคทางเดินหายใจตะวันออกกลาง (MERS)"}, {"label": "B", "text": "ไข้หวัดใหญ่ตามฤดูกาล", "is_correct": false, "explanation": "ไม่ถูกต้อง ไข้หวัดใหญ่ตามฤดูกาลไม่ใช่โรคติดต่ออันตราย"}, {"label": "C", "text": "ไข้เลือดออกเดงกี (dengue)", "is_correct": false, "explanation": "ไม่ถูกต้อง ไข้เลือดออกเป็นโรคติดต่อที่ต้องเฝ้าระวัง ไม่ใช่โรคติดต่ออันตราย"}, {"label": "D", "text": "โรคติดเชื้อไวรัสโคโรนา 2019 (COVID-19) ในปัจจุบัน", "is_correct": false, "explanation": "ไม่ถูกต้อง COVID-19 เคยเป็นโรคติดต่ออันตรายในปี 2563 แต่เปลี่ยนเป็นโรคติดต่อที่ต้องเฝ้าระวังตั้งแต่ 1 ตุลาคม 2565"}, {"label": "E", "text": "โรคมือ เท้า ปาก", "is_correct": false, "explanation": "ไม่ถูกต้อง โรคมือ เท้า ปาก เป็นโรคติดต่อที่ต้องเฝ้าระวัง ไม่ใช่โรคติดต่ออันตราย"}], "key_takeaway": "โรคติดต่ออันตรายคือโรครุนแรงและแพร่เร็ว เช่น อีโบลา กาฬโรค MERS ซึ่งต่างจากโรคติดต่อที่ต้องเฝ้าระวังอย่างไข้เลือดออก"}'::jsonb, 'easy', 'law-day2 • พ.ร.บ.โรคติดต่อ พ.ศ. 2558 - โรคติดต่ออันตราย'),
('424faacbe9b1ee0742b8d167bda39aba', 3, 'ร้านยาที่ได้รับอนุญาตแห่งหนึ่งต้องการเปิดบริการเภสัชกรรมทางไกล (telepharmacy) ผ่านวิดีโอคอล ตามหลักการของประกาศสภาเภสัชกรรมเรื่องมาตรฐานการให้บริการเภสัชกรรมทางไกล ข้อใดเป็นแนวปฏิบัติที่ถูกต้อง', '[{"label": "A", "text": "ให้พนักงานร้านที่ผ่านการอบรมตอบแชตและจ่ายยาแทนเภสัชกรได้ในช่วงที่มีผู้ใช้บริการมาก"}, {"label": "B", "text": "ไม่ต้องบันทึกการให้บริการ เพราะประวัติการสนทนาในแอปพลิเคชันถือเป็นหลักฐานเพียงพอแล้ว"}, {"label": "C", "text": "ไม่จำเป็นต้องยืนยันตัวตนผู้รับบริการ หากผู้รับบริการชำระเงินผ่านบัญชีธนาคารแล้ว"}, {"label": "D", "text": "เภสัชกรให้บริการจากที่ใดก็ได้ และส่งยาจากคลังสินค้าที่ไม่ได้รับอนุญาตขายยาได้"}, {"label": "E", "text": "เภสัชกรให้บริการเอง ยืนยันตัวผู้ป่วย บันทึกการให้บริการ และรักษาความลับของข้อมูล"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. เภสัชกรให้บริการเอง ยืนยันตัวผู้ป่วย บันทึก และรักษาความลับ — telepharmacy ใช้มาตรฐานวิชาชีพเดียวกับการพบหน้า", "reason": "สภาเภสัชกรรมออกประกาศกำหนดมาตรฐานการให้บริการเภสัชกรรมทางไกล โดยหลักคือเภสัชกรต้องให้บริการด้วยตนเองผ่านระบบสื่อสารที่เหมาะสม ยืนยันตัวผู้ป่วย ซักประวัติและประเมินอย่างเพียงพอ บันทึกการให้บริการ และคุ้มครองข้อมูลผู้ป่วย การส่งมอบยาต้องปลอดภัย ตรวจสอบย้อนกลับได้ และทำจากสถานที่ที่ได้รับอนุญาต\n\nTelepharmacy เป็นการให้บริการวิชาชีพผ่านช่องทางทางไกล ไม่ได้ยกเว้นข้อกำหนดของ พ.ร.บ.ยา และไม่ทำให้การขายยาในช่องทางที่กฎหมายห้ามกลายเป็นการกระทำที่ชอบด้วยกฎหมาย", "choices": [{"label": "A", "text": "ให้พนักงานร้านที่ผ่านการอบรมตอบแชตและจ่ายยาแทนเภสัชกรได้ในช่วงที่มีผู้ใช้บริการมาก", "is_correct": false, "explanation": "ไม่ถูกต้อง การให้บริการเภสัชกรรมทางไกลต้องทำโดยเภสัชกรเอง มอบหมายให้ผู้ที่ไม่ใช่เภสัชกรทำแทนไม่ได้"}, {"label": "B", "text": "ไม่ต้องบันทึกการให้บริการ เพราะประวัติการสนทนาในแอปพลิเคชันถือเป็นหลักฐานเพียงพอแล้ว", "is_correct": false, "explanation": "ไม่ถูกต้อง เภสัชกรต้องบันทึกข้อมูลการให้บริการอย่างเป็นระบบ เช่น ข้อมูลผู้ป่วย การประเมิน และยาที่จ่าย ประวัติแชตไม่ใช่บันทึกทางวิชาชีพ"}, {"label": "C", "text": "ไม่จำเป็นต้องยืนยันตัวตนผู้รับบริการ หากผู้รับบริการชำระเงินผ่านบัญชีธนาคารแล้ว", "is_correct": false, "explanation": "ไม่ถูกต้อง เภสัชกรต้องยืนยันตัวตนผู้ป่วยหรือผู้รับบริการ การชำระเงินไม่ได้ใช้ยืนยันตัวผู้ป่วยในทางวิชาชีพ"}, {"label": "D", "text": "เภสัชกรให้บริการจากที่ใดก็ได้ และส่งยาจากคลังสินค้าที่ไม่ได้รับอนุญาตขายยาได้", "is_correct": false, "explanation": "ไม่ถูกต้อง telepharmacy ไม่ได้ยกเว้นกฎหมายยา ยาต้องจ่ายจากสถานที่ที่ได้รับอนุญาต และการส่งยาต้องอยู่ในความรับผิดชอบของเภสัชกร"}, {"label": "E", "text": "เภสัชกรให้บริการเอง ยืนยันตัวผู้ป่วย บันทึกการให้บริการ และรักษาความลับของข้อมูล", "is_correct": true, "explanation": "ถูกต้อง นี่คือหลักการสำคัญของมาตรฐานเภสัชกรรมทางไกล เภสัชกรต้องให้บริการเอง ยืนยันตัวผู้ป่วย บันทึก และคุ้มครองข้อมูล โดยมาตรฐานวิชาชีพเท่ากับการให้บริการแบบพบหน้า"}], "key_takeaway": "Telepharmacy ต้องทำโดยเภสัชกรเอง ยืนยันตัวผู้ป่วย บันทึก และรักษาความลับ และไม่ได้ยกเว้นข้อกำหนดของกฎหมายยา"}'::jsonb, 'medium', 'law-day2 • Telepharmacy - มาตรฐานสภาเภสัชกรรม'),
('d778f7af834bffc77e8aaeb042e08740', 4, 'เภสัชกรในโรงพยาบาลของรัฐจ่ายยาผิดขนาดขณะปฏิบัติหน้าที่ ทำให้ผู้ป่วยได้รับความเสียหาย ผู้ป่วยต้องการเรียกค่าสินไหมทดแทนทางแพ่ง ตาม พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539 ผู้ป่วยต้องฟ้องผู้ใด', '[{"label": "A", "text": "ฟ้องเภสัชกรผู้จ่ายยาเป็นการส่วนตัวเท่านั้น"}, {"label": "B", "text": "ฟ้องหน่วยงานของรัฐต้นสังกัด ฟ้องเจ้าหน้าที่โดยตรงไม่ได้"}, {"label": "C", "text": "ฟ้องทั้งเภสัชกรและหน่วยงานเป็นจำเลยร่วมกันเสมอ"}, {"label": "D", "text": "ฟ้องสภาเภสัชกรรมในฐานะผู้ออกใบอนุญาตประกอบวิชาชีพ"}, {"label": "E", "text": "ฟ้องผู้อำนวยการโรงพยาบาลเป็นการส่วนตัวในฐานะผู้บังคับบัญชา"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ฟ้องหน่วยงานของรัฐต้นสังกัด — เจ้าหน้าที่ที่ละเมิดในการปฏิบัติหน้าที่ไม่ถูกฟ้องโดยตรง", "reason": "พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539 วางหลักว่า หากเจ้าหน้าที่ทำละเมิดต่อบุคคลภายนอกในการปฏิบัติหน้าที่ หน่วยงานของรัฐที่เจ้าหน้าที่สังกัดต้องรับผิดต่อผู้เสียหาย ผู้เสียหายฟ้องหน่วยงานได้โดยตรง แต่ฟ้องเจ้าหน้าที่ไม่ได้ กฎหมายยังให้ผู้เสียหายเลือกยื่นคำขอให้หน่วยงานพิจารณาชดใช้ค่าสินไหมทดแทนแทนการฟ้องคดีได้ด้วย\n\nวัตถุประสงค์คือให้เจ้าหน้าที่ปฏิบัติงานได้โดยไม่ต้องกังวลต่อการถูกฟ้องเป็นส่วนตัว และให้ผู้เสียหายได้รับการชดใช้จากหน่วยงานที่มีความสามารถชำระ ส่วนความรับผิดของเจ้าหน้าที่ต่อหน่วยงานพิจารณาภายหลังผ่านการไล่เบี้ย", "choices": [{"label": "A", "text": "ฟ้องเภสัชกรผู้จ่ายยาเป็นการส่วนตัวเท่านั้น", "is_correct": false, "explanation": "ไม่ถูกต้อง เมื่อละเมิดเกิดจากการปฏิบัติหน้าที่ ผู้เสียหายฟ้องเจ้าหน้าที่โดยตรงไม่ได้"}, {"label": "B", "text": "ฟ้องหน่วยงานของรัฐต้นสังกัด ฟ้องเจ้าหน้าที่โดยตรงไม่ได้", "is_correct": true, "explanation": "ถูกต้อง หน่วยงานของรัฐต้องรับผิดต่อผู้เสียหายในผลแห่งละเมิดที่เจ้าหน้าที่ทำในการปฏิบัติหน้าที่ ผู้เสียหายฟ้องหน่วยงานได้โดยตรง แต่ฟ้องเจ้าหน้าที่ไม่ได้"}, {"label": "C", "text": "ฟ้องทั้งเภสัชกรและหน่วยงานเป็นจำเลยร่วมกันเสมอ", "is_correct": false, "explanation": "ไม่ถูกต้อง กฎหมายนี้ไม่ให้ฟ้องเจ้าหน้าที่ร่วมด้วยในกรณีที่ทำในการปฏิบัติหน้าที่"}, {"label": "D", "text": "ฟ้องสภาเภสัชกรรมในฐานะผู้ออกใบอนุญาตประกอบวิชาชีพ", "is_correct": false, "explanation": "ไม่ถูกต้อง สภาเภสัชกรรมไม่ได้เป็นผู้รับผิดทางแพ่งแทนสมาชิก บทบาทของสภาคือดูแลด้านจรรยาบรรณ"}, {"label": "E", "text": "ฟ้องผู้อำนวยการโรงพยาบาลเป็นการส่วนตัวในฐานะผู้บังคับบัญชา", "is_correct": false, "explanation": "ไม่ถูกต้อง ผู้บังคับบัญชาไม่ต้องรับผิดเป็นการส่วนตัว ผู้รับผิดต่อผู้เสียหายคือหน่วยงานของรัฐ"}], "key_takeaway": "ละเมิดที่เจ้าหน้าที่รัฐทำในการปฏิบัติหน้าที่ ผู้เสียหายต้องฟ้องหน่วยงานของรัฐ ฟ้องเจ้าหน้าที่โดยตรงไม่ได้"}'::jsonb, 'easy', 'law-day2 • พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ - การฟ้องหน่วยงาน'),
('e50915db14343dc4aa33d597f35c28c5', 5, 'ผู้ป่วยสิทธิหลักประกันสุขภาพแห่งชาติ (บัตรทอง) รายหนึ่งเกิดความเสียหายรุนแรงจากการรักษาพยาบาลในหน่วยบริการ ญาติต้องการขอเงินช่วยเหลือเบื้องต้นตามมาตรา 41 แห่ง พ.ร.บ.หลักประกันสุขภาพแห่งชาติ พ.ศ. 2545 ข้อใดถูกต้องที่สุดเกี่ยวกับหลักการของเงินช่วยเหลือนี้', '[{"label": "A", "text": "ต้องพิสูจน์ให้ได้ว่าแพทย์หรือเภสัชกรประมาทเลินเล่อก่อน จึงจะได้รับเงิน"}, {"label": "B", "text": "ต้องชนะคดีในศาลก่อน จึงจะยื่นขอเงินช่วยเหลือเบื้องต้นได้"}, {"label": "C", "text": "ผู้ประกอบวิชาชีพที่ให้การรักษาต้องจ่ายเงินช่วยเหลือจากเงินส่วนตัว"}, {"label": "D", "text": "จ่ายจากเงินที่กันไว้ในกองทุน โดยไม่ต้องรอพิสูจน์ว่าผู้ให้บริการกระทำผิด"}, {"label": "E", "text": "ใช้ได้เฉพาะความเสียหายที่เกิดในโรงพยาบาลเอกชนที่ไม่ได้อยู่ในระบบ"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. จ่ายจากเงินที่กันไว้ในกองทุน โดยไม่ต้องพิสูจน์ความผิด — มาตรา 41 มุ่งบรรเทาความเดือดร้อนของผู้เสียหายอย่างรวดเร็ว", "reason": "มาตรา 41 แห่ง พ.ร.บ.หลักประกันสุขภาพแห่งชาติ พ.ศ. 2545 ให้คณะกรรมการหลักประกันสุขภาพแห่งชาติกันเงินจำนวนหนึ่งจากเงินที่จ่ายให้หน่วยบริการ เพื่อจ่ายช่วยเหลือเบื้องต้นแก่ผู้รับบริการที่ได้รับความเสียหายจากการรักษาพยาบาลของหน่วยบริการ โดยไม่ต้องรอพิสูจน์ถูกผิด หลักเกณฑ์ วิธีการ และอัตราการจ่ายเป็นไปตามที่คณะกรรมการกำหนด และจ่ายตามระดับความรุนแรงของความเสียหาย เช่น เสียชีวิต ทุพพลภาพ หรือบาดเจ็บ\n\nแนวคิดแบบ no-fault นี้ช่วยให้ผู้เสียหายได้รับการเยียวยาเร็วโดยไม่ต้องผ่านกระบวนการพิสูจน์ความผิด และช่วยลดการฟ้องร้องระหว่างผู้ป่วยกับผู้ให้บริการ", "choices": [{"label": "A", "text": "ต้องพิสูจน์ให้ได้ว่าแพทย์หรือเภสัชกรประมาทเลินเล่อก่อน จึงจะได้รับเงิน", "is_correct": false, "explanation": "ไม่ถูกต้อง มาตรา 41 จ่ายเงินช่วยเหลือโดยไม่ต้องรอพิสูจน์ว่าใครเป็นผู้ผิด"}, {"label": "B", "text": "ต้องชนะคดีในศาลก่อน จึงจะยื่นขอเงินช่วยเหลือเบื้องต้นได้", "is_correct": false, "explanation": "ไม่ถูกต้อง เงินช่วยเหลือเบื้องต้นเป็นกลไกนอกศาลที่จ่ายได้รวดเร็ว ไม่ต้องรอคำพิพากษา"}, {"label": "C", "text": "ผู้ประกอบวิชาชีพที่ให้การรักษาต้องจ่ายเงินช่วยเหลือจากเงินส่วนตัว", "is_correct": false, "explanation": "ไม่ถูกต้อง เงินช่วยเหลือมาจากเงินที่กันไว้จากกองทุนหลักประกันสุขภาพแห่งชาติ ไม่ได้มาจากผู้ให้บริการเป็นส่วนตัว"}, {"label": "D", "text": "จ่ายจากเงินที่กันไว้ในกองทุน โดยไม่ต้องรอพิสูจน์ว่าผู้ให้บริการกระทำผิด", "is_correct": true, "explanation": "ถูกต้อง มาตรา 41 ให้กันเงินไว้เพื่อจ่ายช่วยเหลือเบื้องต้นแก่ผู้รับบริการที่ได้รับความเสียหายจากการรักษาพยาบาล โดยไม่ต้องรอพิสูจน์ถูกผิด (no-fault)"}, {"label": "E", "text": "ใช้ได้เฉพาะความเสียหายที่เกิดในโรงพยาบาลเอกชนที่ไม่ได้อยู่ในระบบ", "is_correct": false, "explanation": "ไม่ถูกต้อง มาตรา 41 คุ้มครองผู้รับบริการที่ได้รับความเสียหายจากการรักษาพยาบาลของหน่วยบริการในระบบหลักประกันสุขภาพแห่งชาติ"}], "key_takeaway": "เงินช่วยเหลือเบื้องต้นตามมาตรา 41 จ่ายจากกองทุนแก่ผู้เสียหายจากการรักษาพยาบาลโดยไม่ต้องพิสูจน์ความผิด"}'::jsonb, 'medium', 'law-day2 • พ.ร.บ.หลักประกันสุขภาพแห่งชาติ - มาตรา 41'),
('78a7d110e9b3c1fac6bc6f1b16bb0020', 6, 'ผู้ป่วยสิทธิบัตรทองได้รับเงินช่วยเหลือเบื้องต้นตามมาตรา 41 แห่ง พ.ร.บ.หลักประกันสุขภาพแห่งชาติ หลังจากเกิดความเสียหายจากการรักษาพยาบาล ต่อมาครอบครัวต้องการฟ้องคดีเพื่อเรียกค่าสินไหมทดแทนเพิ่มเติม ข้อใดอธิบายสถานะทางกฎหมายได้ถูกต้อง', '[{"label": "A", "text": "ยังฟ้องได้ เพราะเงินช่วยเหลือเบื้องต้นไม่ใช่ค่าสินไหมทดแทนที่ตัดสิทธิฟ้อง"}, {"label": "B", "text": "ฟ้องไม่ได้ เพราะการรับเงินถือเป็นการทำสัญญาประนีประนอมยอมความโดยปริยาย"}, {"label": "C", "text": "ฟ้องได้ แต่ต้องคืนเงินช่วยเหลือเบื้องต้นทั้งหมดให้ สปสช. ก่อนยื่นฟ้อง"}, {"label": "D", "text": "ฟ้องได้เฉพาะคดีอาญา ส่วนคดีแพ่งถือว่าได้รับการเยียวยาครบถ้วนแล้ว"}, {"label": "E", "text": "ฟ้องได้เฉพาะเมื่อคณะกรรมการที่พิจารณาเงินช่วยเหลือมีมติอนุญาตให้ฟ้อง"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ยังฟ้องได้ — เงินช่วยเหลือเบื้องต้นไม่ใช่ค่าสินไหมทดแทนที่ระงับสิทธิดำเนินคดี", "reason": "เงินช่วยเหลือเบื้องต้นตามมาตรา 41 มีลักษณะเป็นการช่วยเหลือเพื่อบรรเทาความเดือดร้อนโดยเร็ว จ่ายโดยไม่ต้องพิสูจน์ความผิด จึงไม่ใช่การชดใช้ค่าเสียหายเต็มจำนวน และไม่ใช่สัญญาประนีประนอมยอมความที่จะระงับสิทธิเรียกร้อง\n\nผู้เสียหายจึงยังใช้สิทธิทางศาลได้ตามปกติ เช่น ฟ้องหน่วยงานของรัฐตาม พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ หรือฟ้องผู้ให้บริการเอกชนตามประมวลกฎหมายแพ่งและพาณิชย์ ศาลจะพิจารณาความรับผิดและค่าเสียหายตามหลักกฎหมายละเมิดอีกครั้ง", "choices": [{"label": "A", "text": "ยังฟ้องได้ เพราะเงินช่วยเหลือเบื้องต้นไม่ใช่ค่าสินไหมทดแทนที่ตัดสิทธิฟ้อง", "is_correct": true, "explanation": "ถูกต้อง เงินตามมาตรา 41 เป็นการช่วยเหลือเบื้องต้นเพื่อบรรเทาความเดือดร้อน ไม่ใช่ค่าสินไหมทดแทนเต็มจำนวน ผู้เสียหายจึงยังดำเนินคดีตามกฎหมายได้"}, {"label": "B", "text": "ฟ้องไม่ได้ เพราะการรับเงินถือเป็นการทำสัญญาประนีประนอมยอมความโดยปริยาย", "is_correct": false, "explanation": "ไม่ถูกต้อง การรับเงินช่วยเหลือเบื้องต้นไม่ใช่สัญญาประนีประนอมยอมความ และไม่ทำให้สิทธิฟ้องระงับ"}, {"label": "C", "text": "ฟ้องได้ แต่ต้องคืนเงินช่วยเหลือเบื้องต้นทั้งหมดให้ สปสช. ก่อนยื่นฟ้อง", "is_correct": false, "explanation": "ไม่ถูกต้อง กฎหมายไม่ได้ตั้งเงื่อนไขให้คืนเงินก่อนจึงจะฟ้องได้"}, {"label": "D", "text": "ฟ้องได้เฉพาะคดีอาญา ส่วนคดีแพ่งถือว่าได้รับการเยียวยาครบถ้วนแล้ว", "is_correct": false, "explanation": "ไม่ถูกต้อง เงินช่วยเหลือเบื้องต้นไม่ได้ตัดสิทธิทางแพ่ง และไม่ถือว่าเป็นการเยียวยาครบถ้วน"}, {"label": "E", "text": "ฟ้องได้เฉพาะเมื่อคณะกรรมการที่พิจารณาเงินช่วยเหลือมีมติอนุญาตให้ฟ้อง", "is_correct": false, "explanation": "ไม่ถูกต้อง สิทธิฟ้องคดีเป็นสิทธิตามกฎหมายทั่วไป ไม่ต้องได้รับอนุญาตจากคณะกรรมการ"}], "key_takeaway": "การรับเงินช่วยเหลือเบื้องต้นตามมาตรา 41 ไม่ระงับสิทธิของผู้เสียหายในการฟ้องคดีเรียกค่าสินไหมทดแทน"}'::jsonb, 'hard', 'law-day2 • พ.ร.บ.หลักประกันสุขภาพแห่งชาติ - มาตรา 41 กับสิทธิฟ้อง'),
('ce6dfe47d6b43b5562230e6e7ae6c635', 7, 'ร้านยาแห่งหนึ่งเข้าร่วมเป็นหน่วยบริการในระบบหลักประกันสุขภาพแห่งชาติ เพื่อให้บริการผู้มีสิทธิบัตรทองที่เจ็บป่วยเล็กน้อย ข้อใดสอดคล้องกับหลักการของบริการนี้มากที่สุด', '[{"label": "A", "text": "ร้านยาเก็บค่ายาจากผู้ป่วยเต็มจำนวน แล้วให้ผู้ป่วยนำใบเสร็จไปเบิกคืนที่โรงพยาบาล"}, {"label": "B", "text": "เภสัชกรจ่ายยาใดก็ได้ตามที่ผู้ป่วยร้องขอ เพราะค่าใช้จ่ายทั้งหมดเบิกได้จากกองทุน"}, {"label": "C", "text": "ผู้ป่วยไม่เสียค่าบริการ ร้านยาเบิกจาก สปสช. และเภสัชกรต้องส่งต่อเมื่อเกินขอบเขต"}, {"label": "D", "text": "พนักงานร้านยาที่ไม่ใช่เภสัชกรให้บริการแทนได้ หากผ่านการอบรมจาก สปสช."}, {"label": "E", "text": "เมื่อร้านยาเข้าร่วมระบบแล้ว ได้รับยกเว้นไม่ต้องปฏิบัติตามมาตรฐานของ พ.ร.บ.ยา"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ผู้ป่วยไม่เสียค่าบริการ ร้านยาเบิกจาก สปสช. และเภสัชกรต้องส่งต่อเมื่อเกินขอบเขต — ร้านยาทำหน้าที่เป็นหน่วยบริการในระบบ", "reason": "พ.ร.บ.หลักประกันสุขภาพแห่งชาติ พ.ศ. 2545 รับรองสิทธิของบุคคลในการรับบริการสาธารณสุขที่มีมาตรฐานผ่านหน่วยบริการที่ขึ้นทะเบียน สปสช. ได้ขยายให้ร้านยาที่มีคุณสมบัติตามเกณฑ์ (เช่น ร้านยาคุณภาพ) ร่วมเป็นหน่วยบริการ เช่น บริการรับยาต่อเนื่องที่ร้านยาและบริการดูแลอาการเจ็บป่วยเล็กน้อยตามกลุ่มอาการที่กำหนด\n\nผู้มีสิทธิรับบริการโดยไม่ต้องเสียค่าใช้จ่าย ร้านยาเบิกค่าบริการจาก สปสช. ตามหลักเกณฑ์ เภสัชกรยังต้องใช้วิจารณญาณทางวิชาชีพ จ่ายยาตามแนวทาง บันทึกและติดตามผล และส่งต่อผู้ป่วยไปหน่วยบริการที่เหมาะสมเมื่ออาการเกินขอบเขต ทั้งนี้ยังต้องปฏิบัติตามกฎหมายยาและมาตรฐานวิชาชีพตามปกติ", "choices": [{"label": "A", "text": "ร้านยาเก็บค่ายาจากผู้ป่วยเต็มจำนวน แล้วให้ผู้ป่วยนำใบเสร็จไปเบิกคืนที่โรงพยาบาล", "is_correct": false, "explanation": "ไม่ถูกต้อง บริการที่อยู่ในสิทธิ ผู้ป่วยไม่ต้องสำรองจ่าย ร้านยาเป็นผู้เบิกจาก สปสช. ตามหลักเกณฑ์"}, {"label": "B", "text": "เภสัชกรจ่ายยาใดก็ได้ตามที่ผู้ป่วยร้องขอ เพราะค่าใช้จ่ายทั้งหมดเบิกได้จากกองทุน", "is_correct": false, "explanation": "ไม่ถูกต้อง การจ่ายยาต้องเป็นไปตามแนวทางการดูแลกลุ่มอาการที่กำหนดและวิจารณญาณทางวิชาชีพ ไม่ใช่ตามคำขอของผู้ป่วย"}, {"label": "C", "text": "ผู้ป่วยไม่เสียค่าบริการ ร้านยาเบิกจาก สปสช. และเภสัชกรต้องส่งต่อเมื่อเกินขอบเขต", "is_correct": true, "explanation": "ถูกต้อง ร้านยาที่ร่วมโครงการให้บริการตามสิทธิโดยผู้ป่วยไม่ต้องจ่าย ร้านเบิกค่าบริการจาก สปสช. และเภสัชกรต้องประเมิน บันทึก ติดตาม และส่งต่อเมื่ออาการเกินขอบเขตหรือมีสัญญาณอันตราย"}, {"label": "D", "text": "พนักงานร้านยาที่ไม่ใช่เภสัชกรให้บริการแทนได้ หากผ่านการอบรมจาก สปสช.", "is_correct": false, "explanation": "ไม่ถูกต้อง บริการในระบบนี้ต้องให้โดยเภสัชกร"}, {"label": "E", "text": "เมื่อร้านยาเข้าร่วมระบบแล้ว ได้รับยกเว้นไม่ต้องปฏิบัติตามมาตรฐานของ พ.ร.บ.ยา", "is_correct": false, "explanation": "ไม่ถูกต้อง การเข้าร่วมระบบหลักประกันสุขภาพไม่ได้ยกเว้นข้อกำหนดของกฎหมายยาหรือมาตรฐานวิชาชีพ"}], "key_takeaway": "ร้านยาที่เป็นหน่วยบริการในระบบบัตรทองให้บริการโดยผู้ป่วยไม่ต้องจ่าย เบิกจาก สปสช. และยังต้องคงมาตรฐานวิชาชีพรวมถึงการส่งต่อ"}'::jsonb, 'medium', 'law-day2 • พ.ร.บ.หลักประกันสุขภาพแห่งชาติ - ร้านยาในระบบ'),
('8590f47bcdd887b75541848b66ae19a8', 8, 'เภสัชกรโรงพยาบาลของรัฐจ่ายยาผิดคน ในเวรที่มีภาระงานสูงผิดปกติ ระบบตรวจสอบซ้ำของโรงพยาบาลยังไม่สมบูรณ์ และไม่มีพฤติการณ์จงใจหรือประมาทอย่างร้ายแรง โรงพยาบาลจ่ายค่าสินไหมทดแทนให้ผู้เสียหายไปแล้ว ตาม พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539 ข้อใดถูกต้อง', '[{"label": "A", "text": "โรงพยาบาลไล่เบี้ยเภสัชกรได้เต็มจำนวนเสมอ เพราะเภสัชกรเป็นผู้ทำละเมิดโดยตรง"}, {"label": "B", "text": "ไล่เบี้ยไม่ได้ เพราะไล่เบี้ยได้เฉพาะกรณีจงใจหรือประมาทเลินเล่ออย่างร้ายแรง"}, {"label": "C", "text": "ไล่เบี้ยได้ครึ่งหนึ่งของค่าสินไหมทดแทนตามอัตราที่กฎหมายกำหนดตายตัว"}, {"label": "D", "text": "ไล่เบี้ยได้ เพราะเภสัชกรได้รับค่าตอบแทนวิชาชีพ จึงต้องรับผิดเหมือนเอกชน"}, {"label": "E", "text": "ไล่เบี้ยได้เฉพาะเมื่อสภาเภสัชกรรมมีมติลงโทษทางจรรยาบรรณก่อน"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ไล่เบี้ยไม่ได้ — การไล่เบี้ยจำกัดเฉพาะเจ้าหน้าที่ที่จงใจหรือประมาทเลินเล่ออย่างร้ายแรง", "reason": "เมื่อหน่วยงานของรัฐชดใช้ค่าสินไหมทดแทนแก่ผู้เสียหายแล้ว หน่วยงานมีสิทธิเรียกให้เจ้าหน้าที่ชดใช้ (ไล่เบี้ย) ได้ก็ต่อเมื่อเจ้าหน้าที่กระทำการไปด้วยความจงใจหรือประมาทเลินเล่ออย่างร้ายแรง หากเป็นเพียงประมาทเลินเล่อธรรมดา หน่วยงานรับภาระแต่ผู้เดียว\n\nแม้ในกรณีที่ไล่เบี้ยได้ จำนวนที่เรียกให้ชดใช้ต้องพิจารณาตามระดับความร้ายแรงแห่งการกระทำและความเป็นธรรม และต้องหักส่วนแห่งความรับผิดออกในกรณีที่ละเมิดเกิดจากความผิดหรือความบกพร่องของหน่วยงานหรือระบบการดำเนินงานส่วนรวม เช่น ภาระงานเกินกำลังหรือระบบตรวจสอบไม่สมบูรณ์", "choices": [{"label": "A", "text": "โรงพยาบาลไล่เบี้ยเภสัชกรได้เต็มจำนวนเสมอ เพราะเภสัชกรเป็นผู้ทำละเมิดโดยตรง", "is_correct": false, "explanation": "ไม่ถูกต้อง การไล่เบี้ยทำได้เฉพาะเมื่อเจ้าหน้าที่จงใจหรือประมาทเลินเล่ออย่างร้ายแรง และแม้ไล่เบี้ยได้ก็ไม่จำเป็นต้องเต็มจำนวน"}, {"label": "B", "text": "ไล่เบี้ยไม่ได้ เพราะไล่เบี้ยได้เฉพาะกรณีจงใจหรือประมาทเลินเล่ออย่างร้ายแรง", "is_correct": true, "explanation": "ถูกต้อง เมื่อเป็นเพียงประมาทเลินเล่อธรรมดาในการปฏิบัติหน้าที่ หน่วยงานรับผิดแต่ผู้เดียวและไล่เบี้ยเจ้าหน้าที่ไม่ได้"}, {"label": "C", "text": "ไล่เบี้ยได้ครึ่งหนึ่งของค่าสินไหมทดแทนตามอัตราที่กฎหมายกำหนดตายตัว", "is_correct": false, "explanation": "ไม่ถูกต้อง กฎหมายไม่ได้กำหนดสัดส่วนตายตัว การไล่เบี้ย (เมื่อทำได้) พิจารณาตามระดับความร้ายแรงและหักส่วนความบกพร่องของหน่วยงาน"}, {"label": "D", "text": "ไล่เบี้ยได้ เพราะเภสัชกรได้รับค่าตอบแทนวิชาชีพ จึงต้องรับผิดเหมือนเอกชน", "is_correct": false, "explanation": "ไม่ถูกต้อง การได้รับค่าตอบแทนวิชาชีพไม่ทำให้หลักการไล่เบี้ยตามกฎหมายนี้เปลี่ยนไป"}, {"label": "E", "text": "ไล่เบี้ยได้เฉพาะเมื่อสภาเภสัชกรรมมีมติลงโทษทางจรรยาบรรณก่อน", "is_correct": false, "explanation": "ไม่ถูกต้อง การไล่เบี้ยทางแพ่งของหน่วยงานไม่ขึ้นกับผลการพิจารณาจรรยาบรรณของสภาวิชาชีพ"}], "key_takeaway": "หน่วยงานของรัฐไล่เบี้ยเจ้าหน้าที่ได้เฉพาะกรณีจงใจหรือประมาทเลินเล่ออย่างร้ายแรง และต้องหักส่วนความบกพร่องของระบบออก"}'::jsonb, 'hard', 'law-day2 • พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ - การไล่เบี้ย'),
('225350fa6f7a0f1ec02eaf78aa6cca49', 9, 'เภสัชกรซึ่งเป็นข้าราชการในโรงพยาบาลของรัฐ ไปปฏิบัติงานนอกเวลาที่ร้านยาเอกชนในวันหยุด และจ่ายยาผิดจนลูกค้าได้รับอันตราย ลูกค้าต้องการเรียกค่าเสียหาย ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ลูกค้าต้องฟ้องโรงพยาบาลของรัฐต้นสังกัด เพราะผู้กระทำมีสถานะเป็นเจ้าหน้าที่รัฐ"}, {"label": "B", "text": "ลูกค้าฟ้องใครไม่ได้ เพราะเจ้าหน้าที่รัฐได้รับความคุ้มครองจากการถูกฟ้องโดยตรง"}, {"label": "C", "text": "ลูกค้าต้องยื่นคำขอต่อกระทรวงสาธารณสุขให้พิจารณาชดใช้ก่อนเสมอ"}, {"label": "D", "text": "ลูกค้าเรียกค่าเสียหายได้เฉพาะจากกองทุนหลักประกันสุขภาพแห่งชาติตามมาตรา 41"}, {"label": "E", "text": "ลูกค้าฟ้องเภสัชกรเป็นการส่วนตัวได้ เพราะไม่ใช่การกระทำในการปฏิบัติหน้าที่ราชการ"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ฟ้องเภสัชกรเป็นการส่วนตัวได้ — ละเมิดที่ไม่ได้ทำในการปฏิบัติหน้าที่ราชการ เจ้าหน้าที่รับผิดเป็นการเฉพาะตัว", "reason": "พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ พ.ศ. 2539 แยกเป็นสองกรณี ถ้าเจ้าหน้าที่ทำละเมิดในการปฏิบัติหน้าที่ หน่วยงานของรัฐรับผิดต่อผู้เสียหายและผู้เสียหายฟ้องเจ้าหน้าที่โดยตรงไม่ได้ แต่ถ้าละเมิดนั้นไม่ได้เกิดจากการปฏิบัติหน้าที่ เจ้าหน้าที่ต้องรับผิดเป็นการเฉพาะตัว และผู้เสียหายฟ้องเจ้าหน้าที่ได้โดยตรง\n\nการปฏิบัติงานนอกเวลาที่ร้านยาเอกชนเป็นกิจกรรมส่วนตัว ไม่ใช่หน้าที่ราชการ จึงใช้หลักละเมิดทั่วไปตามประมวลกฎหมายแพ่งและพาณิชย์ ทั้งนี้ผู้เสียหายอาจเรียกให้ผู้ประกอบการร้านยาซึ่งเป็นนายจ้างร่วมรับผิดได้ด้วย ตามหลักความรับผิดของนายจ้างในผลละเมิดที่ลูกจ้างทำในทางการที่จ้าง", "choices": [{"label": "A", "text": "ลูกค้าต้องฟ้องโรงพยาบาลของรัฐต้นสังกัด เพราะผู้กระทำมีสถานะเป็นเจ้าหน้าที่รัฐ", "is_correct": false, "explanation": "ไม่ถูกต้อง หน่วยงานของรัฐรับผิดเฉพาะละเมิดที่เจ้าหน้าที่ทำในการปฏิบัติหน้าที่ งานที่ร้านยาเอกชนไม่ใช่หน้าที่ราชการ"}, {"label": "B", "text": "ลูกค้าฟ้องใครไม่ได้ เพราะเจ้าหน้าที่รัฐได้รับความคุ้มครองจากการถูกฟ้องโดยตรง", "is_correct": false, "explanation": "ไม่ถูกต้อง ความคุ้มครองไม่ให้ถูกฟ้องโดยตรงใช้เฉพาะละเมิดที่ทำในการปฏิบัติหน้าที่เท่านั้น"}, {"label": "C", "text": "ลูกค้าต้องยื่นคำขอต่อกระทรวงสาธารณสุขให้พิจารณาชดใช้ก่อนเสมอ", "is_correct": false, "explanation": "ไม่ถูกต้อง กรณีนี้ไม่ใช่ละเมิดในการปฏิบัติหน้าที่ของหน่วยงานรัฐ จึงไม่ใช่กลไกของ พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่"}, {"label": "D", "text": "ลูกค้าเรียกค่าเสียหายได้เฉพาะจากกองทุนหลักประกันสุขภาพแห่งชาติตามมาตรา 41", "is_correct": false, "explanation": "ไม่ถูกต้อง มาตรา 41 เป็นเงินช่วยเหลือเบื้องต้นสำหรับผู้รับบริการจากหน่วยบริการในระบบ และไม่ได้ตัดสิทธิฟ้องผู้กระทำละเมิด"}, {"label": "E", "text": "ลูกค้าฟ้องเภสัชกรเป็นการส่วนตัวได้ เพราะไม่ใช่การกระทำในการปฏิบัติหน้าที่ราชการ", "is_correct": true, "explanation": "ถูกต้อง ละเมิดที่ไม่ได้เกิดจากการปฏิบัติหน้าที่ เจ้าหน้าที่ต้องรับผิดเป็นการเฉพาะตัว และผู้เสียหายฟ้องได้โดยตรงตามหลักละเมิดในประมวลกฎหมายแพ่งและพาณิชย์"}], "key_takeaway": "ความคุ้มครองตาม พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ ใช้เฉพาะละเมิดที่ทำในการปฏิบัติหน้าที่ ถ้านอกหน้าที่ เจ้าหน้าที่รับผิดเป็นการเฉพาะตัว"}'::jsonb, 'hard', 'law-day2 • พ.ร.บ.ความรับผิดทางละเมิดของเจ้าหน้าที่ - ละเมิดนอกหน้าที่'),
('2f3736f079e7d78501314b8b43fdcfb1', 10, 'เภสัชกรซึ่งเป็นลูกจ้างของโรงพยาบาลเอกชน จ่ายยาผิดขณะปฏิบัติงานตามที่ได้รับมอบหมาย ทำให้ผู้ป่วยได้รับความเสียหาย ตามหลักความรับผิดฐานละเมิดในประมวลกฎหมายแพ่งและพาณิชย์ ข้อใดถูกต้อง', '[{"label": "A", "text": "ผู้ป่วยฟ้องได้เฉพาะเภสัชกร เพราะโรงพยาบาลไม่ได้เป็นผู้ลงมือกระทำ"}, {"label": "B", "text": "ผู้ป่วยฟ้องได้เฉพาะโรงพยาบาล เพราะลูกจ้างได้รับความคุ้มครองไม่ให้ถูกฟ้องโดยตรง"}, {"label": "C", "text": "โรงพยาบาลรับผิดแทนทั้งหมด และไม่มีสิทธิเรียกคืนจากเภสัชกรไม่ว่ากรณีใด"}, {"label": "D", "text": "โรงพยาบาลร่วมรับผิดกับเภสัชกร และเมื่อชดใช้แล้วเรียกคืนจากเภสัชกรได้"}, {"label": "E", "text": "ผู้ป่วยต้องร้องเรียนต่อสภาเภสัชกรรมให้มีคำวินิจฉัยก่อน จึงจะฟ้องคดีแพ่งได้"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. โรงพยาบาลร่วมรับผิดกับเภสัชกร และไล่เบี้ยเภสัชกรได้ — เป็นหลักความรับผิดของนายจ้างในประมวลกฎหมายแพ่งและพาณิชย์", "reason": "ประมวลกฎหมายแพ่งและพาณิชย์วางหลักว่าผู้ใดจงใจหรือประมาทเลินเล่อทำต่อบุคคลอื่นโดยผิดกฎหมายจนเขาเสียหาย ต้องใช้ค่าสินไหมทดแทน และนายจ้างต้องร่วมกันรับผิดกับลูกจ้างในผลละเมิดที่ลูกจ้างทำในทางการที่จ้าง ผู้เสียหายจึงฟ้องได้ทั้งเภสัชกรและโรงพยาบาลเอกชน\n\nนายจ้างที่ชดใช้ค่าสินไหมทดแทนให้ผู้เสียหายแล้ว มีสิทธิเรียกให้ลูกจ้างชดใช้คืนได้ ซึ่งต่างจากระบบของหน่วยงานรัฐ ที่ห้ามฟ้องเจ้าหน้าที่โดยตรงและไล่เบี้ยได้เฉพาะกรณีจงใจหรือประมาทเลินเล่ออย่างร้ายแรง", "choices": [{"label": "A", "text": "ผู้ป่วยฟ้องได้เฉพาะเภสัชกร เพราะโรงพยาบาลไม่ได้เป็นผู้ลงมือกระทำ", "is_correct": false, "explanation": "ไม่ถูกต้อง นายจ้างต้องร่วมรับผิดกับลูกจ้างในผลละเมิดที่ลูกจ้างทำในทางการที่จ้าง"}, {"label": "B", "text": "ผู้ป่วยฟ้องได้เฉพาะโรงพยาบาล เพราะลูกจ้างได้รับความคุ้มครองไม่ให้ถูกฟ้องโดยตรง", "is_correct": false, "explanation": "ไม่ถูกต้อง หลักห้ามฟ้องเจ้าหน้าที่โดยตรงใช้กับหน่วยงานของรัฐ ไม่ใช่ลูกจ้างเอกชน"}, {"label": "C", "text": "โรงพยาบาลรับผิดแทนทั้งหมด และไม่มีสิทธิเรียกคืนจากเภสัชกรไม่ว่ากรณีใด", "is_correct": false, "explanation": "ไม่ถูกต้อง นายจ้างที่ชดใช้ค่าสินไหมทดแทนแทนลูกจ้างแล้ว มีสิทธิเรียกให้ลูกจ้างชดใช้คืนได้"}, {"label": "D", "text": "โรงพยาบาลร่วมรับผิดกับเภสัชกร และเมื่อชดใช้แล้วเรียกคืนจากเภสัชกรได้", "is_correct": true, "explanation": "ถูกต้อง นายจ้างต้องร่วมกันรับผิดกับลูกจ้างในผลละเมิดที่ทำในทางการที่จ้าง และเมื่อชดใช้แล้วมีสิทธิไล่เบี้ยเอาจากลูกจ้าง"}, {"label": "E", "text": "ผู้ป่วยต้องร้องเรียนต่อสภาเภสัชกรรมให้มีคำวินิจฉัยก่อน จึงจะฟ้องคดีแพ่งได้", "is_correct": false, "explanation": "ไม่ถูกต้อง การฟ้องคดีแพ่งไม่ต้องรอผลการพิจารณาจรรยาบรรณของสภาวิชาชีพ"}], "key_takeaway": "ในภาคเอกชน นายจ้างร่วมรับผิดกับลูกจ้างในละเมิดที่ทำในทางการที่จ้าง และไล่เบี้ยลูกจ้างได้ภายหลัง"}'::jsonb, 'medium', 'law-day2 • ความรับผิดทางแพ่งฐานละเมิด - นายจ้างกับลูกจ้าง'),
('39c10e8f7a11aa98bb60cdc639fc00c0', 11, 'ในการพิจารณาว่าเภสัชกรที่จ่ายยาจนเกิดอันตรายแก่ผู้ป่วย "กระทำโดยประมาท" หรือไม่ ตามความหมายในประมวลกฎหมายอาญา ซึ่งเป็นหลักที่ใช้ประเมินความประมาทในวิชาชีพด้วย ข้อใดเป็นเกณฑ์ที่ถูกต้อง', '[{"label": "A", "text": "กระทำโดยไม่เจตนา แต่ขาดความระมัดระวังที่บุคคลในภาวะเช่นนั้นต้องมี และอาจใช้ได้แต่ไม่ใช้ให้เพียงพอ"}, {"label": "B", "text": "ผู้ป่วยได้รับอันตรายหลังใช้ยา ไม่ว่าเภสัชกรจะใช้ความระมัดระวังมากเพียงใดก็ตาม"}, {"label": "C", "text": "เภสัชกรมีเจตนาให้ผู้ป่วยได้รับอันตรายแต่ไม่คาดคิดว่าจะรุนแรงถึงเพียงนั้น"}, {"label": "D", "text": "เภสัชกรไม่ได้ปฏิบัติตามความต้องการของผู้ป่วยทุกประการ ทำให้ผู้ป่วยไม่พึงพอใจ"}, {"label": "E", "text": "เภสัชกรขาดความระมัดระวังเมื่อเทียบกับผู้เชี่ยวชาญระดับสูงสุดของประเทศในสาขานั้น"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ไม่เจตนา แต่ขาดความระมัดระวังที่บุคคลในภาวะเช่นนั้นต้องมีและอาจใช้ได้ — นี่คือนิยามของการกระทำโดยประมาท", "reason": "ประมวลกฎหมายอาญานิยามการกระทำโดยประมาทว่า เป็นการกระทำความผิดโดยมิใช่เจตนา แต่กระทำโดยปราศจากความระมัดระวังซึ่งบุคคลในภาวะเช่นนั้นจักต้องมีตามวิสัยและพฤติการณ์ และผู้กระทำอาจใช้ความระมัดระวังเช่นว่านั้นได้ แต่หาได้ใช้ให้เพียงพอไม่\n\nสำหรับผู้ประกอบวิชาชีพ \"บุคคลในภาวะเช่นนั้น\" หมายถึงผู้ประกอบวิชาชีพเดียวกันในสถานการณ์ใกล้เคียงกัน เช่น เภสัชกรทั่วไปที่ปฏิบัติงานในบริบทเดียวกัน ไม่ใช่ผู้เชี่ยวชาญที่ดีที่สุด และผลร้ายที่เกิดขึ้นเพียงอย่างเดียวไม่ได้แปลว่าประมาท หลักนี้ใช้เป็นแนวในการพิจารณาความประมาทเลินเล่อทางแพ่งด้วย", "choices": [{"label": "A", "text": "กระทำโดยไม่เจตนา แต่ขาดความระมัดระวังที่บุคคลในภาวะเช่นนั้นต้องมี และอาจใช้ได้แต่ไม่ใช้ให้เพียงพอ", "is_correct": true, "explanation": "ถูกต้อง นี่คือนิยามของการกระทำโดยประมาท ซึ่งเทียบกับความระมัดระวังที่บุคคลในภาวะเช่นนั้นจักต้องมีตามวิสัยและพฤติการณ์ สำหรับเภสัชกรคือมาตรฐานของเภสัชกรในสถานการณ์เดียวกัน"}, {"label": "B", "text": "ผู้ป่วยได้รับอันตรายหลังใช้ยา ไม่ว่าเภสัชกรจะใช้ความระมัดระวังมากเพียงใดก็ตาม", "is_correct": false, "explanation": "ไม่ถูกต้อง ผลร้ายที่เกิดขึ้นเพียงอย่างเดียวไม่ทำให้เป็นความประมาท ต้องพิจารณาว่าขาดความระมัดระวังที่ควรมีหรือไม่"}, {"label": "C", "text": "เภสัชกรมีเจตนาให้ผู้ป่วยได้รับอันตรายแต่ไม่คาดคิดว่าจะรุนแรงถึงเพียงนั้น", "is_correct": false, "explanation": "ไม่ถูกต้อง หากมีเจตนาให้เกิดอันตรายจะเป็นการกระทำโดยเจตนา ไม่ใช่ประมาท"}, {"label": "D", "text": "เภสัชกรไม่ได้ปฏิบัติตามความต้องการของผู้ป่วยทุกประการ ทำให้ผู้ป่วยไม่พึงพอใจ", "is_correct": false, "explanation": "ไม่ถูกต้อง ความไม่พึงพอใจของผู้ป่วยไม่ใช่เกณฑ์ของความประมาท"}, {"label": "E", "text": "เภสัชกรขาดความระมัดระวังเมื่อเทียบกับผู้เชี่ยวชาญระดับสูงสุดของประเทศในสาขานั้น", "is_correct": false, "explanation": "ไม่ถูกต้อง เกณฑ์คือความระมัดระวังของบุคคลในภาวะเช่นนั้นตามวิสัยและพฤติการณ์ ไม่ใช่มาตรฐานของผู้เชี่ยวชาญสูงสุด"}], "key_takeaway": "ความประมาทวัดจากการขาดความระมัดระวังที่ผู้ประกอบวิชาชีพในภาวะเดียวกันพึงมีและอาจใช้ได้ ไม่ใช่วัดจากผลร้ายที่เกิดขึ้น"}'::jsonb, 'medium', 'law-day2 • ความประมาทในวิชาชีพ - นิยามตามประมวลกฎหมายอาญา'),
('f406cd2f102060ed6ac6cc08ccb47ed8', 12, 'เภสัชกรร้านยาทราบจากใบสั่งยาว่าลูกค้ารายหนึ่งรับยาต้านไวรัสเอชไอวี ต่อมานายจ้างของลูกค้าโทรมาสอบถาม เภสัชกรจึงบอกนายจ้างว่าลูกค้าติดเชื้อเอชไอวี ทำให้ลูกค้าถูกเลิกจ้าง การกระทำของเภสัชกรเข้าข่ายกฎหมายใด', '[{"label": "A", "text": "ไม่ผิดกฎหมายใด เพราะนายจ้างมีส่วนได้เสียเกี่ยวกับสุขภาพของลูกจ้าง"}, {"label": "B", "text": "ผิดเฉพาะจรรยาบรรณวิชาชีพ ไม่มีความรับผิดทางอาญา"}, {"label": "C", "text": "อาจเป็นความผิดอาญาฐานเปิดเผยความลับที่ล่วงรู้จากการประกอบวิชาชีพเภสัชกร"}, {"label": "D", "text": "ผิดฐานหมิ่นประมาทเท่านั้น เพราะเป็นการใส่ความผู้อื่นต่อบุคคลที่สาม"}, {"label": "E", "text": "ผิดเฉพาะเมื่อเภสัชกรได้รับค่าตอบแทนจากการให้ข้อมูลแก่นายจ้าง"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. อาจเป็นความผิดอาญาฐานเปิดเผยความลับที่ล่วงรู้จากการประกอบวิชาชีพ — ประมวลกฎหมายอาญาระบุอาชีพเภสัชกรไว้ชัดเจน", "reason": "ประมวลกฎหมายอาญามีบทบัญญัติว่า ผู้ใดล่วงรู้หรือได้มาซึ่งความลับของผู้อื่นเพราะประกอบอาชีพ เช่น แพทย์ เภสัชกร คนจำหน่ายยา นางผดุงครรภ์ ผู้พยาบาล หรือเป็นผู้ช่วยในการประกอบอาชีพนั้น แล้วเปิดเผยความลับนั้นในประการที่น่าจะเกิดความเสียหายแก่ผู้หนึ่งผู้ใด ต้องรับโทษ บทบัญญัตินี้ครอบคลุมผู้ที่ล่วงรู้ความลับจากการศึกษาอบรมในอาชีพดังกล่าวด้วย และความผิดฐานนี้เป็นความผิดอันยอมความได้\n\nการกระทำเดียวกันอาจมีความรับผิดหลายทางพร้อมกัน ทั้งทางอาญา ทางแพ่งฐานละเมิด และทางจรรยาบรรณวิชาชีพ", "choices": [{"label": "A", "text": "ไม่ผิดกฎหมายใด เพราะนายจ้างมีส่วนได้เสียเกี่ยวกับสุขภาพของลูกจ้าง", "is_correct": false, "explanation": "ไม่ถูกต้อง นายจ้างไม่มีสิทธิตามกฎหมายที่จะรู้ข้อมูลสุขภาพของลูกจ้างจากเภสัชกร การเปิดเผยนี้ทำให้ลูกค้าเสียหาย"}, {"label": "B", "text": "ผิดเฉพาะจรรยาบรรณวิชาชีพ ไม่มีความรับผิดทางอาญา", "is_correct": false, "explanation": "ไม่ถูกต้อง นอกจากจรรยาบรรณแล้ว ยังอาจเป็นความผิดอาญาฐานเปิดเผยความลับที่ล่วงรู้จากการประกอบวิชาชีพด้วย"}, {"label": "C", "text": "อาจเป็นความผิดอาญาฐานเปิดเผยความลับที่ล่วงรู้จากการประกอบวิชาชีพเภสัชกร", "is_correct": true, "explanation": "ถูกต้อง ประมวลกฎหมายอาญากำหนดให้ผู้ที่ล่วงรู้ความลับของผู้อื่นจากการประกอบอาชีพ เช่น แพทย์ เภสัชกร คนจำหน่ายยา แล้วเปิดเผยในประการที่น่าจะเกิดความเสียหาย มีความผิด"}, {"label": "D", "text": "ผิดฐานหมิ่นประมาทเท่านั้น เพราะเป็นการใส่ความผู้อื่นต่อบุคคลที่สาม", "is_correct": false, "explanation": "ไม่ถูกต้อง ข้อมูลนี้เป็นความลับที่ล่วงรู้จากการประกอบวิชาชีพ ฐานความผิดที่ตรงคือการเปิดเผยความลับ"}, {"label": "E", "text": "ผิดเฉพาะเมื่อเภสัชกรได้รับค่าตอบแทนจากการให้ข้อมูลแก่นายจ้าง", "is_correct": false, "explanation": "ไม่ถูกต้อง ความผิดฐานเปิดเผยความลับไม่ต้องมีการรับค่าตอบแทน"}], "key_takeaway": "เภสัชกรที่เปิดเผยความลับของผู้ป่วยที่ล่วงรู้จากการประกอบวิชาชีพ จนน่าจะเกิดความเสียหาย อาจมีความผิดทางอาญา นอกเหนือจากความผิดทางจรรยาบรรณ"}'::jsonb, 'easy', 'law-day2 • ประมวลกฎหมายอาญา - การเปิดเผยความลับในวิชาชีพ'),
('a04eae92c0826fecabfe223fde8c82e7', 13, 'งานเภสัชกรรมของโรงพยาบาลแห่งหนึ่งทบทวนระบบจัดการยาเสพติดให้โทษประเภท 2 (เช่น morphine injection) ข้อใดเป็นแนวปฏิบัติที่สอดคล้องกับหลักการควบคุมตามกฎหมายยาเสพติดมากที่สุด', '[{"label": "A", "text": "เก็บรวมกับยาทั่วไปบนชั้นวางยาในห้องจ่ายยา เพื่อให้หยิบได้รวดเร็วในกรณีฉุกเฉิน"}, {"label": "B", "text": "เก็บแยกในตู้มั่นคงที่มีกุญแจ จำกัดผู้เข้าถึง และทำบัญชีรับ-จ่ายที่ตรงกับยาคงเหลือ"}, {"label": "C", "text": "บันทึกการรับ-จ่ายเฉพาะเมื่อมีการสั่งซื้อจากผู้จำหน่าย ส่วนการเบิกจ่ายภายในไม่ต้องบันทึก"}, {"label": "D", "text": "ให้หอผู้ป่วยสำรองยาได้ไม่จำกัดจำนวน โดยไม่ต้องตรวจนับ เพราะอยู่ภายในโรงพยาบาลเดียวกัน"}, {"label": "E", "text": "ให้ผู้ป่วยนอกรับยาไปเก็บเองเป็นปริมาณมากเพื่อลดภาระการเก็บรักษาของโรงพยาบาล"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. เก็บแยกในตู้มั่นคงที่มีกุญแจ จำกัดผู้เข้าถึง และทำบัญชีรับ-จ่ายให้ตรงกับยาคงเหลือ — เพื่อป้องกันการรั่วไหลและตรวจสอบได้", "reason": "ยาเสพติดให้โทษประเภท 2 เป็นยาที่ใช้ทางการแพทย์ได้แต่มีโอกาสนำไปใช้ในทางที่ผิดสูง กฎหมายยาเสพติด (ปัจจุบันคือประมวลกฎหมายยาเสพติด) จึงกำหนดให้ผู้ครอบครองต้องเก็บรักษาอย่างมั่นคง ทำบัญชีรับ-จ่าย และรายงานต่อหน่วยงานที่กำกับ (สำนักงานคณะกรรมการอาหารและยา) ตามที่กำหนด\n\nในทางปฏิบัติ โรงพยาบาลเก็บยาเหล่านี้แยกในตู้หรือห้องที่มั่นคงมีกุญแจ จำกัดผู้ถือกุญแจ ทำบัญชีทุกการรับเข้าและเบิกจ่ายโดยระบุผู้ป่วยและผู้สั่งใช้ ตรวจนับยาคงเหลือให้ตรงบัญชี ยาสำรองบนหอผู้ป่วยมีจำนวนจำกัดและตรวจนับเมื่อส่งเวร และยาที่เหลือหรือไม่ได้ใช้ต้องส่งคืนห้องยาพร้อมบันทึก", "choices": [{"label": "A", "text": "เก็บรวมกับยาทั่วไปบนชั้นวางยาในห้องจ่ายยา เพื่อให้หยิบได้รวดเร็วในกรณีฉุกเฉิน", "is_correct": false, "explanation": "ไม่ถูกต้อง ยาเสพติดให้โทษต้องเก็บแยกในที่มั่นคง มีกุญแจ และจำกัดผู้เข้าถึง ไม่เก็บรวมกับยาทั่วไป"}, {"label": "B", "text": "เก็บแยกในตู้มั่นคงที่มีกุญแจ จำกัดผู้เข้าถึง และทำบัญชีรับ-จ่ายที่ตรงกับยาคงเหลือ", "is_correct": true, "explanation": "ถูกต้อง หลักการคือเก็บรักษาอย่างมั่นคงปลอดภัย จำกัดผู้เข้าถึง ทำบัญชีรับ-จ่ายและตรวจนับให้ตรงกับยาคงเหลือ และรายงานต่อหน่วยงานที่กำกับตามที่กฎหมายกำหนด"}, {"label": "C", "text": "บันทึกการรับ-จ่ายเฉพาะเมื่อมีการสั่งซื้อจากผู้จำหน่าย ส่วนการเบิกจ่ายภายในไม่ต้องบันทึก", "is_correct": false, "explanation": "ไม่ถูกต้อง ทุกการเคลื่อนไหวของยาเสพติดให้โทษ ทั้งรับเข้า เบิกจ่าย และส่งคืน ต้องบันทึกให้ตรวจสอบย้อนกลับได้"}, {"label": "D", "text": "ให้หอผู้ป่วยสำรองยาได้ไม่จำกัดจำนวน โดยไม่ต้องตรวจนับ เพราะอยู่ภายในโรงพยาบาลเดียวกัน", "is_correct": false, "explanation": "ไม่ถูกต้อง ยาสำรองบนหอผู้ป่วยต้องมีจำนวนจำกัด เก็บในที่มั่นคง และตรวจนับสม่ำเสมอ เช่น ทุกครั้งที่ส่งเวร"}, {"label": "E", "text": "ให้ผู้ป่วยนอกรับยาไปเก็บเองเป็นปริมาณมากเพื่อลดภาระการเก็บรักษาของโรงพยาบาล", "is_correct": false, "explanation": "ไม่ถูกต้อง การจ่ายยาเสพติดให้โทษต้องเป็นไปตามคำสั่งใช้ที่ชอบด้วยกฎหมายและความจำเป็นทางการรักษา ไม่ใช่เพื่อลดภาระการเก็บ"}], "key_takeaway": "การจัดการยาเสพติดให้โทษประเภท 2 ในโรงพยาบาลต้องเก็บมั่นคง จำกัดผู้เข้าถึง และมีบัญชีรับ-จ่ายที่ตรวจสอบได้ตรงกับยาคงเหลือ"}'::jsonb, 'medium', 'law-day2 • ยาเสพติดให้โทษประเภท 2 - การเก็บรักษาและบัญชีในโรงพยาบาล'),
('f26c10e37e209cd2f47b098d7ca297cd', 14, 'ห้องยาโรงพยาบาลพบ pethidine injection ซึ่งเป็นยาเสพติดให้โทษประเภท 2 หมดอายุจำนวนหนึ่ง และมีหลอดยาแตกระหว่างจัดเก็บ 1 หลอด ข้อใดเป็นการจัดการที่ถูกต้องตามหลักการ', '[{"label": "A", "text": "ทิ้งรวมกับขยะติดเชื้อของโรงพยาบาลทันที แล้วตัดออกจากบัญชีโดยไม่ต้องมีหลักฐาน"}, {"label": "B", "text": "คืนให้ผู้แทนบริษัทยานำไปทำลายเอง โดยไม่ต้องบันทึกในบัญชีของโรงพยาบาล"}, {"label": "C", "text": "โอนยาหมดอายุไปให้หอผู้ป่วยใช้ก่อน เพื่อไม่ให้สิ้นเปลืองงบประมาณ"}, {"label": "D", "text": "เภสัชกรเก็บไว้ส่วนตัวเพื่อใช้เป็นตัวอย่างสอนนักศึกษา"}, {"label": "E", "text": "แยกเก็บในที่มั่นคง บันทึกพร้อมหลักฐาน และขอทำลายตามขั้นตอนที่กฎหมายกำหนด"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. แยกเก็บ บันทึกพร้อมหลักฐาน และขอทำลายตามขั้นตอนที่กฎหมายกำหนด — ยาเสพติดให้โทษทุกหน่วยต้องตรวจสอบย้อนกลับได้", "reason": "ยาเสพติดให้โทษประเภท 2 ที่หมดอายุ เสื่อมสภาพ หรือแตกเสียหาย ยังอยู่ในการควบคุมตามกฎหมายจนกว่าจะทำลายอย่างถูกต้อง โรงพยาบาลจึงต้องแยกเก็บไว้ในที่มั่นคง บันทึกในบัญชีพร้อมหลักฐาน เช่น บันทึกเหตุการณ์หลอดยาแตกที่มีพยานลงนาม และดำเนินการทำลายตามขั้นตอนที่กฎหมายและสำนักงานคณะกรรมการอาหารและยากำหนด โดยมีคณะกรรมการหรือพนักงานเจ้าหน้าที่กำกับและมีหลักฐาน\n\nการทิ้งเอง การส่งคืนนอกระบบโดยไม่บันทึก หรือการเก็บไว้ส่วนตัว ทำให้ตรวจสอบย้อนกลับไม่ได้ เสี่ยงต่อการรั่วไหล และอาจเป็นความผิดตามกฎหมายยาเสพติด", "choices": [{"label": "A", "text": "ทิ้งรวมกับขยะติดเชื้อของโรงพยาบาลทันที แล้วตัดออกจากบัญชีโดยไม่ต้องมีหลักฐาน", "is_correct": false, "explanation": "ไม่ถูกต้อง การทำลายยาเสพติดให้โทษต้องทำตามขั้นตอนที่กฎหมายกำหนดและมีหลักฐาน จะทิ้งเองและตัดบัญชีโดยไม่มีหลักฐานไม่ได้"}, {"label": "B", "text": "คืนให้ผู้แทนบริษัทยานำไปทำลายเอง โดยไม่ต้องบันทึกในบัญชีของโรงพยาบาล", "is_correct": false, "explanation": "ไม่ถูกต้อง ทุกการเคลื่อนไหวของยาเสพติดให้โทษต้องบันทึกในบัญชี และต้องทำตามขั้นตอนที่กฎหมายกำหนด"}, {"label": "C", "text": "โอนยาหมดอายุไปให้หอผู้ป่วยใช้ก่อน เพื่อไม่ให้สิ้นเปลืองงบประมาณ", "is_correct": false, "explanation": "ไม่ถูกต้อง ห้ามนำยาหมดอายุไปใช้กับผู้ป่วย ทั้งด้านความปลอดภัยและด้านกฎหมาย"}, {"label": "D", "text": "เภสัชกรเก็บไว้ส่วนตัวเพื่อใช้เป็นตัวอย่างสอนนักศึกษา", "is_correct": false, "explanation": "ไม่ถูกต้อง การครอบครองยาเสพติดให้โทษนอกระบบที่ได้รับอนุญาตเป็นความผิด"}, {"label": "E", "text": "แยกเก็บในที่มั่นคง บันทึกพร้อมหลักฐาน และขอทำลายตามขั้นตอนที่กฎหมายกำหนด", "is_correct": true, "explanation": "ถูกต้อง ยาเสพติดให้โทษที่หมดอายุหรือเสียหายต้องแยกเก็บอย่างมั่นคง บันทึกพร้อมหลักฐาน เช่น รายงานหลอดแตกที่มีพยาน และทำลายตามขั้นตอนที่กฎหมายและหน่วยงานกำกับกำหนด"}], "key_takeaway": "ยาเสพติดให้โทษที่หมดอายุหรือเสียหายต้องแยกเก็บ บันทึกพร้อมหลักฐาน และทำลายตามขั้นตอนที่กฎหมายกำหนด ห้ามทิ้งเอง"}'::jsonb, 'medium', 'law-day2 • ยาเสพติดให้โทษประเภท 2 - ยาหมดอายุ/เสียหายในโรงพยาบาล'),
('d84915113b0a08e3f5c9bec510ac2fff', 15, 'โรงพยาบาลศูนย์สังกัดกระทรวงสาธารณสุขผลิตยาเตรียมบางรายการ (เช่น ยาน้ำสำหรับเด็กที่ไม่มีจำหน่ายในท้องตลาด) เพื่อใช้รักษาผู้ป่วยของโรงพยาบาลเอง ตามหลักการของ พ.ร.บ.ยา พ.ศ. 2510 ข้อใดถูกต้อง', '[{"label": "A", "text": "ต้องขอใบอนุญาตผลิตยาแผนปัจจุบันเช่นเดียวกับโรงงานผลิตยาเอกชนทุกประการ"}, {"label": "B", "text": "ได้รับยกเว้น จึงนำยาที่ผลิตไปจำหน่ายเชิงพาณิชย์แก่ร้านยาเอกชนทั่วประเทศได้"}, {"label": "C", "text": "ได้รับยกเว้นเฉพาะเมื่อเภสัชกรผู้ผลิตได้รับอนุญาตเป็นการส่วนตัวจากสภาเภสัชกรรม"}, {"label": "D", "text": "ได้รับยกเว้นไม่ต้องขอใบอนุญาตผลิตยา แต่ยังต้องผลิตให้ได้คุณภาพและความปลอดภัย"}, {"label": "E", "text": "ห้ามผลิตยาเองในโรงพยาบาลของรัฐโดยเด็ดขาด ต้องซื้อจากองค์การเภสัชกรรมเท่านั้น"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ได้รับยกเว้นไม่ต้องขอใบอนุญาตผลิตยา แต่ยังต้องรักษาคุณภาพ — ข้อยกเว้นมีไว้เพื่อหน้าที่ป้องกันและบำบัดโรคของรัฐ", "reason": "พ.ร.บ.ยา พ.ศ. 2510 กำหนดให้การผลิต ขาย และนำเข้ายาแผนปัจจุบันต้องได้รับอนุญาต แต่มีบทยกเว้นสำหรับกระทรวง ทบวง กรม ในหน้าที่ป้องกันหรือบำบัดโรค สภากาชาดไทย และองค์การเภสัชกรรม โรงพยาบาลรัฐจึงผลิตยาเพื่อใช้รักษาผู้ป่วยในหน้าที่ของตนได้โดยไม่ต้องขอใบอนุญาตผลิตยา บทยกเว้นยังครอบคลุมการปรุงยาโดยเภสัชกรตามใบสั่งยาของผู้ประกอบวิชาชีพเวชกรรมสำหรับคนไข้เฉพาะรายด้วย\n\nข้อยกเว้นนี้ยกเว้นเฉพาะการขอใบอนุญาต ไม่ได้ยกเว้นความรับผิดชอบด้านคุณภาพ และไม่ได้ให้สิทธิผลิตเพื่อจำหน่ายเชิงพาณิชย์แก่บุคคลภายนอก โรงพยาบาลยังควรผลิตตามหลักเกณฑ์วิธีการที่ดีและมาตรฐานวิชาชีพ", "choices": [{"label": "A", "text": "ต้องขอใบอนุญาตผลิตยาแผนปัจจุบันเช่นเดียวกับโรงงานผลิตยาเอกชนทุกประการ", "is_correct": false, "explanation": "ไม่ถูกต้อง พ.ร.บ.ยา ยกเว้นกระทรวง ทบวง กรม ในหน้าที่ป้องกันหรือบำบัดโรค ไม่ต้องขอใบอนุญาตผลิตยา"}, {"label": "B", "text": "ได้รับยกเว้น จึงนำยาที่ผลิตไปจำหน่ายเชิงพาณิชย์แก่ร้านยาเอกชนทั่วประเทศได้", "is_correct": false, "explanation": "ไม่ถูกต้อง ข้อยกเว้นมีไว้เพื่อหน้าที่ป้องกันหรือบำบัดโรคของหน่วยงานรัฐ ไม่ใช่เพื่อการค้าทั่วไป"}, {"label": "C", "text": "ได้รับยกเว้นเฉพาะเมื่อเภสัชกรผู้ผลิตได้รับอนุญาตเป็นการส่วนตัวจากสภาเภสัชกรรม", "is_correct": false, "explanation": "ไม่ถูกต้อง ข้อยกเว้นนี้เป็นของหน่วยงานรัฐตามกฎหมายยา ไม่เกี่ยวกับการอนุญาตรายบุคคลจากสภาเภสัชกรรม"}, {"label": "D", "text": "ได้รับยกเว้นไม่ต้องขอใบอนุญาตผลิตยา แต่ยังต้องผลิตให้ได้คุณภาพและความปลอดภัย", "is_correct": true, "explanation": "ถูกต้อง กระทรวง ทบวง กรม ในหน้าที่ป้องกันหรือบำบัดโรค รวมถึงสภากาชาดไทยและองค์การเภสัชกรรม ได้รับยกเว้นใบอนุญาตผลิตยา แต่หน้าที่ทางวิชาชีพในการผลิตยาให้มีคุณภาพยังคงอยู่"}, {"label": "E", "text": "ห้ามผลิตยาเองในโรงพยาบาลของรัฐโดยเด็ดขาด ต้องซื้อจากองค์การเภสัชกรรมเท่านั้น", "is_correct": false, "explanation": "ไม่ถูกต้อง โรงพยาบาลของรัฐผลิตยาเพื่อการบำบัดโรคของตนได้ภายใต้ข้อยกเว้นของกฎหมาย"}], "key_takeaway": "หน่วยงานรัฐในหน้าที่ป้องกันหรือบำบัดโรคได้รับยกเว้นใบอนุญาตผลิตยา แต่ยังต้องผลิตยาให้มีคุณภาพและใช้เพื่อหน้าที่ดังกล่าวเท่านั้น"}'::jsonb, 'medium', 'law-day2 • พ.ร.บ.ยา - ข้อยกเว้นใบอนุญาตผลิตยาของหน่วยงานรัฐ'),
('320bd631d4630bae079e55effdb8f4b4', 16, 'แพทย์ในโรงพยาบาลต้องการใช้ยารักษาโรคหายากที่ยังไม่มีทะเบียนตำรับยาในประเทศไทย สำหรับผู้ป่วยรายหนึ่งที่ไม่มีทางเลือกอื่น ข้อใดเป็นแนวทางที่ถูกต้องตามหลักการของกฎหมายยา', '[{"label": "A", "text": "ให้ญาติสั่งซื้อทางออนไลน์จากต่างประเทศในปริมาณมาก แล้วนำมาเก็บไว้ที่โรงพยาบาล"}, {"label": "B", "text": "ยื่นขออนุญาต อย. เพื่อนำเข้าสำหรับผู้ป่วยเฉพาะราย ในปริมาณที่จำเป็นต่อการรักษา"}, {"label": "C", "text": "ใช้ได้ทันทีโดยไม่ต้องขออนุญาต เพราะเป็นยากำพร้าที่ไม่มีบริษัทใดนำเข้า"}, {"label": "D", "text": "นำเข้าในนามโรงพยาบาลแล้วจำหน่ายให้ผู้ป่วยรายอื่นและร้านยาภายนอกได้ด้วย"}, {"label": "E", "text": "ต้องรอให้บริษัทผู้ผลิตยื่นขอขึ้นทะเบียนตำรับยาจนได้รับอนุมัติก่อนเท่านั้น"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ยื่นขออนุญาต อย. เพื่อนำเข้าสำหรับผู้ป่วยเฉพาะรายในปริมาณที่จำเป็น — เป็นช่องทางที่ถูกกฎหมายสำหรับยาที่ยังไม่มีทะเบียน", "reason": "โดยหลัก ยาแผนปัจจุบันที่จะขายหรือนำเข้าต้องขึ้นทะเบียนตำรับยา แต่กฎหมายยาและหลักเกณฑ์ของสำนักงานคณะกรรมการอาหารและยา (อย.) เปิดช่องให้นำหรือสั่งยาที่ยังไม่มีทะเบียนเข้ามาเพื่อรักษาผู้ป่วยเฉพาะรายหรือในกรณีจำเป็นได้ โดยสถานพยาบาลหรือแพทย์ผู้รักษาต้องยื่นคำขอพร้อมเหตุผลทางการแพทย์ ได้รับอนุญาตก่อน และนำเข้าในปริมาณที่จำเป็นต่อผู้ป่วยตามที่ขอเท่านั้น\n\nสำหรับยากำพร้า กระทรวงสาธารณสุขมีมาตรการสนับสนุนให้เข้าถึงยาได้ เช่น การจัดหาผ่านหน่วยงานของรัฐ แต่ทุกช่องทางยังอยู่ภายใต้การกำกับของ อย. และห้ามนำยาที่นำเข้าเพื่อผู้ป่วยเฉพาะรายไปจำหน่ายทั่วไป", "choices": [{"label": "A", "text": "ให้ญาติสั่งซื้อทางออนไลน์จากต่างประเทศในปริมาณมาก แล้วนำมาเก็บไว้ที่โรงพยาบาล", "is_correct": false, "explanation": "ไม่ถูกต้อง การนำเข้ายาที่ไม่มีทะเบียนต้องผ่านกระบวนการขออนุญาตที่กำหนด และจำกัดปริมาณตามความจำเป็นของผู้ป่วย"}, {"label": "B", "text": "ยื่นขออนุญาต อย. เพื่อนำเข้าสำหรับผู้ป่วยเฉพาะราย ในปริมาณที่จำเป็นต่อการรักษา", "is_correct": true, "explanation": "ถูกต้อง กฎหมายยาเปิดช่องให้นำหรือสั่งยาที่ยังไม่มีทะเบียนเข้ามาเพื่อรักษาผู้ป่วยเฉพาะรายได้ตามหลักเกณฑ์ที่ อย. กำหนด โดยต้องได้รับอนุญาตและจำกัดปริมาณตามความจำเป็น"}, {"label": "C", "text": "ใช้ได้ทันทีโดยไม่ต้องขออนุญาต เพราะเป็นยากำพร้าที่ไม่มีบริษัทใดนำเข้า", "is_correct": false, "explanation": "ไม่ถูกต้อง แม้เป็นยากำพร้าก็ยังต้องนำเข้าผ่านช่องทางที่ได้รับอนุญาต"}, {"label": "D", "text": "นำเข้าในนามโรงพยาบาลแล้วจำหน่ายให้ผู้ป่วยรายอื่นและร้านยาภายนอกได้ด้วย", "is_correct": false, "explanation": "ไม่ถูกต้อง ยาที่นำเข้าเพื่อผู้ป่วยเฉพาะรายต้องใช้ตามวัตถุประสงค์ที่ขออนุญาต จะนำไปจำหน่ายทั่วไปไม่ได้"}, {"label": "E", "text": "ต้องรอให้บริษัทผู้ผลิตยื่นขอขึ้นทะเบียนตำรับยาจนได้รับอนุมัติก่อนเท่านั้น", "is_correct": false, "explanation": "ไม่ถูกต้อง กฎหมายมีช่องทางสำหรับผู้ป่วยเฉพาะรายที่จำเป็น โดยไม่ต้องรอให้ยาขึ้นทะเบียนสำเร็จ"}], "key_takeaway": "ยาที่ยังไม่มีทะเบียนนำเข้าได้เพื่อผู้ป่วยเฉพาะรายเมื่อได้รับอนุญาตจาก อย. ในปริมาณที่จำเป็น และใช้ตามวัตถุประสงค์ที่ขออนุญาตเท่านั้น"}'::jsonb, 'medium', 'law-day2 • พ.ร.บ.ยา - การนำเข้ายาไม่มีทะเบียนเพื่อผู้ป่วยเฉพาะราย/ยากำพร้า'),
('7247194049bc2c1b0cc054ba65bea526', 17, 'บริษัทยาได้รับสิทธิบัตรการประดิษฐ์สำหรับสารออกฤทธิ์ชนิดใหม่ในประเทศไทยตาม พ.ร.บ.สิทธิบัตร พ.ศ. 2522 สิทธิบัตรการประดิษฐ์นี้มีอายุคุ้มครองเท่าใด', '[{"label": "A", "text": "20 ปี นับจากวันยื่นขอรับสิทธิบัตร"}, {"label": "B", "text": "20 ปี นับจากวันที่ยาได้รับทะเบียนตำรับจาก อย."}, {"label": "C", "text": "10 ปี นับจากวันออกสิทธิบัตร และต่ออายุได้ไม่จำกัด"}, {"label": "D", "text": "6 ปี นับจากวันยื่นคำขอ ต่ออายุได้อีกสองครั้ง"}, {"label": "E", "text": "ตลอดอายุของบริษัทผู้ทรงสิทธิบัตร"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. 20 ปี นับจากวันยื่นขอรับสิทธิบัตร — เป็นอายุคุ้มครองสิทธิบัตรการประดิษฐ์ตามกฎหมายไทยซึ่งสอดคล้องกับความตกลง TRIPS", "reason": "พ.ร.บ.สิทธิบัตร พ.ศ. 2522 (แก้ไขเพิ่มเติม) กำหนดให้สิทธิบัตรการประดิษฐ์มีอายุ 20 ปีนับจากวันยื่นขอรับสิทธิบัตรในประเทศไทย และต่ออายุไม่ได้ ผู้ทรงสิทธิบัตรมีสิทธิแต่ผู้เดียวในการผลิต ใช้ ขาย หรือนำเข้าผลิตภัณฑ์ตามสิทธิบัตรในช่วงเวลานี้ เมื่อสิทธิบัตรสิ้นอายุ ผู้ผลิตรายอื่นผลิตยาสามัญ (generic) ได้\n\nส่วนอนุสิทธิบัตรมีอายุสั้นกว่า (6 ปีและต่ออายุได้) ซึ่งเป็นคนละประเภทกับสิทธิบัตรการประดิษฐ์ อายุสิทธิบัตรนับจากวันยื่นคำขอ ไม่เกี่ยวกับวันที่ยาได้รับอนุมัติทะเบียนตำรับ", "choices": [{"label": "A", "text": "20 ปี นับจากวันยื่นขอรับสิทธิบัตร", "is_correct": true, "explanation": "ถูกต้อง สิทธิบัตรการประดิษฐ์มีอายุ 20 ปี นับจากวันยื่นขอรับสิทธิบัตรในประเทศไทย"}, {"label": "B", "text": "20 ปี นับจากวันที่ยาได้รับทะเบียนตำรับจาก อย.", "is_correct": false, "explanation": "ไม่ถูกต้อง อายุสิทธิบัตรนับจากวันยื่นขอรับสิทธิบัตร ไม่เกี่ยวกับวันที่ได้ทะเบียนตำรับยา"}, {"label": "C", "text": "10 ปี นับจากวันออกสิทธิบัตร และต่ออายุได้ไม่จำกัด", "is_correct": false, "explanation": "ไม่ถูกต้อง สิทธิบัตรการประดิษฐ์ต่ออายุไม่ได้ และอายุไม่ใช่ 10 ปี"}, {"label": "D", "text": "6 ปี นับจากวันยื่นคำขอ ต่ออายุได้อีกสองครั้ง", "is_correct": false, "explanation": "ไม่ถูกต้อง ข้อนี้เป็นลักษณะของอนุสิทธิบัตร ไม่ใช่สิทธิบัตรการประดิษฐ์"}, {"label": "E", "text": "ตลอดอายุของบริษัทผู้ทรงสิทธิบัตร", "is_correct": false, "explanation": "ไม่ถูกต้อง สิทธิบัตรมีอายุจำกัด เพื่อให้การประดิษฐ์ตกเป็นสาธารณะเมื่อพ้นอายุคุ้มครอง"}], "key_takeaway": "สิทธิบัตรการประดิษฐ์มีอายุ 20 ปีนับจากวันยื่นขอรับสิทธิบัตร และเมื่อหมดอายุ ยาสามัญเข้าสู่ตลาดได้"}'::jsonb, 'easy', 'law-day2 • พ.ร.บ.สิทธิบัตร - อายุสิทธิบัตรการประดิษฐ์'),
('3273739618dd6f18b94dbe5a1560d490', 18, 'ระหว่าง พ.ศ. 2549-2551 รัฐบาลไทยประกาศใช้สิทธิตามสิทธิบัตรโดยรัฐ (government use / compulsory licensing) กับยาหลายรายการ เช่น efavirenz, lopinavir/ritonavir, clopidogrel และยารักษามะเร็งบางรายการ ข้อใดอธิบายหลักการทางกฎหมายของมาตรการนี้ได้ถูกต้อง', '[{"label": "A", "text": "สิทธิบัตรของยาดังกล่าวถูกเพิกถอนและตกเป็นสาธารณสมบัติทันทีที่รัฐประกาศ"}, {"label": "B", "text": "รัฐต้องได้รับความยินยอมจากผู้ทรงสิทธิบัตรก่อน มิฉะนั้นถือเป็นการละเมิดสิทธิบัตร"}, {"label": "C", "text": "รัฐใช้สิทธิได้โดยไม่ต้องได้รับความยินยอม แต่ต้องจ่ายค่าตอบแทนและแจ้งผู้ทรงสิทธิบัตร"}, {"label": "D", "text": "ใช้ได้เฉพาะเมื่อสิทธิบัตรเหลืออายุไม่ถึงหนึ่งปี และต้องได้รับอนุมัติจากองค์การการค้าโลกก่อน"}, {"label": "E", "text": "เปิดให้ผู้ผลิตเอกชนทุกรายผลิตและจำหน่ายยาดังกล่าวเพื่อการค้าได้โดยเสรีและไม่ต้องจ่ายค่าตอบแทน"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. รัฐใช้สิทธิได้โดยไม่ต้องได้รับความยินยอม แต่ต้องจ่ายค่าตอบแทนและแจ้งผู้ทรงสิทธิบัตร — สิทธิบัตรยังไม่ถูกเพิกถอน", "reason": "พ.ร.บ.สิทธิบัตร พ.ศ. 2522 (แก้ไขเพิ่มเติม) ให้กระทรวง ทบวง กรม ใช้สิทธิตามสิทธิบัตรเพื่อประโยชน์สาธารณะ เช่น การป้องกันหรือบรรเทาการขาดแคลนยา โดยไม่ต้องได้รับความยินยอมจากผู้ทรงสิทธิบัตร แต่ต้องจ่ายค่าตอบแทนและแจ้งผู้ทรงสิทธิบัตร มาตรการนี้สอดคล้องกับความตกลง TRIPS และปฏิญญาโดฮาว่าด้วย TRIPS และการสาธารณสุข\n\nระหว่างปี 2549-2551 กระทรวงสาธารณสุขของไทยประกาศใช้สิทธิกับยาต้านไวรัสเอชไอวี (efavirenz, lopinavir/ritonavir) ยาต้านเกล็ดเลือด (clopidogrel) และยารักษามะเร็งบางรายการ (เช่น letrozole, docetaxel, erlotinib) เพื่อจัดหายาสามัญในราคาต่ำสำหรับผู้ป่วยในระบบหลักประกันสุขภาพภาครัฐ ระหว่างนั้นสิทธิบัตรยังคงมีผล และผู้ทรงสิทธิบัตรยังได้รับค่าตอบแทน", "choices": [{"label": "A", "text": "สิทธิบัตรของยาดังกล่าวถูกเพิกถอนและตกเป็นสาธารณสมบัติทันทีที่รัฐประกาศ", "is_correct": false, "explanation": "ไม่ถูกต้อง การใช้สิทธิโดยรัฐไม่ได้เพิกถอนสิทธิบัตร สิทธิบัตรยังมีผลอยู่"}, {"label": "B", "text": "รัฐต้องได้รับความยินยอมจากผู้ทรงสิทธิบัตรก่อน มิฉะนั้นถือเป็นการละเมิดสิทธิบัตร", "is_correct": false, "explanation": "ไม่ถูกต้อง สาระสำคัญของการใช้สิทธิโดยรัฐคือรัฐใช้สิทธิได้โดยไม่ต้องได้รับความยินยอมจากผู้ทรงสิทธิบัตร"}, {"label": "C", "text": "รัฐใช้สิทธิได้โดยไม่ต้องได้รับความยินยอม แต่ต้องจ่ายค่าตอบแทนและแจ้งผู้ทรงสิทธิบัตร", "is_correct": true, "explanation": "ถูกต้อง พ.ร.บ.สิทธิบัตรให้หน่วยงานของรัฐใช้สิทธิตามสิทธิบัตรเพื่อประโยชน์สาธารณะ เช่น ป้องกันหรือบรรเทาการขาดแคลนยา โดยต้องจ่ายค่าตอบแทนและแจ้งผู้ทรงสิทธิบัตร ซึ่งสอดคล้องกับความตกลง TRIPS"}, {"label": "D", "text": "ใช้ได้เฉพาะเมื่อสิทธิบัตรเหลืออายุไม่ถึงหนึ่งปี และต้องได้รับอนุมัติจากองค์การการค้าโลกก่อน", "is_correct": false, "explanation": "ไม่ถูกต้อง ไม่มีเงื่อนไขเรื่องอายุสิทธิบัตรที่เหลือ และไม่ต้องได้รับอนุมัติจาก WTO ก่อน"}, {"label": "E", "text": "เปิดให้ผู้ผลิตเอกชนทุกรายผลิตและจำหน่ายยาดังกล่าวเพื่อการค้าได้โดยเสรีและไม่ต้องจ่ายค่าตอบแทน", "is_correct": false, "explanation": "ไม่ถูกต้อง การใช้สิทธิโดยรัฐมุ่งประโยชน์สาธารณะที่ไม่ใช่เชิงพาณิชย์ เช่น จัดหายาในระบบหลักประกันสุขภาพ และต้องจ่ายค่าตอบแทนแก่ผู้ทรงสิทธิบัตร"}], "key_takeaway": "การใช้สิทธิโดยรัฐไม่ต้องได้รับความยินยอมจากผู้ทรงสิทธิบัตร แต่ต้องจ่ายค่าตอบแทนและแจ้ง โดยสิทธิบัตรยังคงมีผล"}'::jsonb, 'hard', 'law-day2 • พ.ร.บ.สิทธิบัตร - การใช้สิทธิโดยรัฐ (Compulsory licensing)'),
('2539c1505af19e994278f16c07d4c82d', 19, 'บริษัทยาแห่งหนึ่งกำลังจัดทำ "เอกสารกำกับยาสำหรับประชาชน" (patient information leaflet) ให้แก่ยาของตน ข้อใดเป็นหลักการที่ถูกต้องในการจัดทำเอกสารดังกล่าว', '[{"label": "A", "text": "ใช้ศัพท์ทางการแพทย์ให้ครบถ้วนเหมือนเอกสารสำหรับแพทย์ เพื่อไม่ให้ข้อมูลคลาดเคลื่อน"}, {"label": "B", "text": "ใส่ข้อความเชิงส่งเสริมการขาย เช่น จุดเด่นเหนือยาคู่แข่ง เพื่อให้ผู้ป่วยมั่นใจในยา"}, {"label": "C", "text": "ใช้ภาษาที่ประชาชนเข้าใจง่าย และเนื้อหาสอดคล้องกับข้อมูลที่ได้รับอนุมัติในทะเบียนตำรับยา"}, {"label": "D", "text": "ตัดข้อมูลอาการไม่พึงประสงค์ออก เพื่อไม่ให้ผู้ป่วยกังวลจนไม่ยอมใช้ยา"}, {"label": "E", "text": "เพิ่มข้อบ่งใช้อื่นที่มีงานวิจัยรองรับ แม้ยังไม่ได้รับอนุมัติในทะเบียนตำรับยา"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ใช้ภาษาที่ประชาชนเข้าใจง่าย และเนื้อหาสอดคล้องกับข้อมูลที่ได้รับอนุมัติในทะเบียนตำรับยา — เอกสารกำกับยาสำหรับประชาชนมีไว้ให้ผู้ใช้ยาเข้าใจการใช้ยาอย่างปลอดภัย จึงต้องอ่านง่ายและถูกต้องตามข้อมูลที่ อย. อนุมัติ", "reason": "เอกสารกำกับยาสำหรับประชาชนเป็นข้อมูลยาที่เขียนสำหรับผู้ใช้ยาซึ่งไม่ใช่บุคลากรทางการแพทย์ หลักการสำคัญคือใช้ภาษาง่าย หลีกเลี่ยงศัพท์เทคนิค และครอบคลุมเรื่องที่ผู้ป่วยต้องรู้ เช่น ยานี้คืออะไร ใช้เพื่ออะไร ข้อควรระวังก่อนใช้ วิธีใช้ อาการไม่พึงประสงค์ที่ควรสังเกต และวิธีเก็บรักษา\n\nเนื้อหาทั้งหมดต้องถูกต้องและสอดคล้องกับข้อมูลที่ได้รับอนุมัติในทะเบียนตำรับยา (เช่น ข้อบ่งใช้ ขนาดยา คำเตือน) เอกสารนี้เป็นข้อมูลเพื่อความปลอดภัย ไม่ใช่สื่อส่งเสริมการขาย จึงต้องไม่มีข้อความโอ้อวดหรือข้อมูลที่ไม่ได้รับอนุมัติ และต้องไม่ตัดคำเตือนสำคัญออก", "choices": [{"label": "A", "text": "ใช้ศัพท์ทางการแพทย์ให้ครบถ้วนเหมือนเอกสารสำหรับแพทย์ เพื่อไม่ให้ข้อมูลคลาดเคลื่อน", "is_correct": false, "explanation": "เอกสารสำหรับประชาชนต้องใช้ภาษาที่คนทั่วไปเข้าใจ การใช้ศัพท์เทคนิคแบบเอกสารสำหรับบุคลากรทางการแพทย์จะทำให้ผู้ป่วยไม่เข้าใจ"}, {"label": "B", "text": "ใส่ข้อความเชิงส่งเสริมการขาย เช่น จุดเด่นเหนือยาคู่แข่ง เพื่อให้ผู้ป่วยมั่นใจในยา", "is_correct": false, "explanation": "เอกสารนี้เป็นข้อมูลเพื่อความปลอดภัยในการใช้ยา ไม่ใช่สื่อโฆษณา จึงไม่ควรมีข้อความเชิงส่งเสริมการขายหรือเปรียบเทียบกับคู่แข่ง"}, {"label": "C", "text": "ใช้ภาษาที่ประชาชนเข้าใจง่าย และเนื้อหาสอดคล้องกับข้อมูลที่ได้รับอนุมัติในทะเบียนตำรับยา", "is_correct": true, "explanation": "ถูกต้อง หลักการสำคัญคือต้องอ่านเข้าใจง่ายสำหรับผู้ใช้ยา และถูกต้องตามข้อมูลที่ได้รับอนุมัติ"}, {"label": "D", "text": "ตัดข้อมูลอาการไม่พึงประสงค์ออก เพื่อไม่ให้ผู้ป่วยกังวลจนไม่ยอมใช้ยา", "is_correct": false, "explanation": "อาการไม่พึงประสงค์ที่สำคัญเป็นข้อมูลที่ผู้ป่วยต้องรู้เพื่อสังเกตอาการและไปพบแพทย์ได้ทัน การตัดออกขัดกับวัตถุประสงค์ของเอกสาร"}, {"label": "E", "text": "เพิ่มข้อบ่งใช้อื่นที่มีงานวิจัยรองรับ แม้ยังไม่ได้รับอนุมัติในทะเบียนตำรับยา", "is_correct": false, "explanation": "ข้อมูลในเอกสารต้องสอดคล้องกับที่ได้รับอนุมัติ การใส่ข้อบ่งใช้ที่ไม่ได้รับอนุมัติเป็นการให้ข้อมูลเกินกว่าทะเบียน"}], "key_takeaway": "เอกสารกำกับยาสำหรับประชาชนต้องอ่านเข้าใจง่าย ถูกต้องตามทะเบียนตำรับยา และไม่ใช่สื่อโฆษณา"}'::jsonb, 'easy', 'law-day2 • เอกสารกำกับยาสำหรับประชาชน'),
('7bc3b0f75b45ffea86598c6e1901092b', 20, 'บริษัทผู้ผลิตยาในประเทศต้องการขึ้นทะเบียนยาสามัญ (generic) ของยาเม็ดรับประทานที่หมดสิทธิบัตรแล้ว และมียาต้นแบบที่ขึ้นทะเบียนในประเทศไทยอยู่แล้ว โดยหลักการทั่วไป ข้อมูลสำคัญที่ใช้แสดงว่ายาสามัญนี้ใช้แทนยาต้นแบบได้ แทนการทำการศึกษาทางคลินิกด้านประสิทธิผลทั้งหมดใหม่ คือข้อใด', '[{"label": "A", "text": "ผลการศึกษาชีวสมมูล (bioequivalence) เทียบกับยาต้นแบบ"}, {"label": "B", "text": "ผลการศึกษาทางคลินิกระยะที่ 3 ที่ทำซ้ำในผู้ป่วยไทย"}, {"label": "C", "text": "ผลการศึกษาความเป็นพิษในสัตว์ทดลองชุดใหม่ทั้งหมด"}, {"label": "D", "text": "ใบรับรองว่ายาจำหน่ายในต่างประเทศมาแล้วหลายประเทศ"}, {"label": "E", "text": "ผลสำรวจความพึงพอใจของแพทย์ผู้ทดลองสั่งใช้ยา"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ผลการศึกษาชีวสมมูล (bioequivalence) เทียบกับยาต้นแบบ — ยาสามัญอาศัยข้อมูลความปลอดภัยและประสิทธิผลของยาต้นแบบ โดยแสดงว่าตนมีชีวสมมูลกับยาต้นแบบ", "reason": "ยาใหม่ (new drug) ต้องยื่นข้อมูลครบทั้งด้านคุณภาพ ความปลอดภัยจากการศึกษาไม่ใช่ทางคลินิกและทางคลินิก และประสิทธิผลจากการศึกษาทางคลินิก ส่วนยาสามัญมีตัวยาสำคัญ ความแรง และรูปแบบยาเดียวกับยาต้นแบบที่พิสูจน์ความปลอดภัยและประสิทธิผลแล้ว จึงไม่จำเป็นต้องทำการศึกษาทางคลินิกทั้งหมดซ้ำ\n\nสิ่งที่ยาสามัญต้องแสดงนอกจากคุณภาพตามมาตรฐาน คือชีวสมมูล (bioequivalence) ได้แก่ อัตราและปริมาณการดูดซึมตัวยาเข้าสู่ร่างกาย ซึ่งวัดจากพารามิเตอร์ทางเภสัชจลนศาสตร์ เช่น AUC และ Cmax ต้องไม่ต่างจากยาต้นแบบเกินเกณฑ์ที่กำหนด โดยทั่วไปศึกษาในอาสาสมัครสุขภาพดี เมื่อพิสูจน์ได้จึงถือว่าคาดหวังผลการรักษาและความปลอดภัยได้เทียบเท่ายาต้นแบบ\n\nการทดสอบอื่น เช่น การละลาย (dissolution) อาจใช้สนับสนุนหรือใช้ขอยกเว้นการทำชีวสมมูลในบางกรณีตามเกณฑ์ แต่โดยหลักการทั่วไปของยาเม็ดรับประทาน หลักฐานหลักคือการศึกษาชีวสมมูล", "choices": [{"label": "A", "text": "ผลการศึกษาชีวสมมูล (bioequivalence) เทียบกับยาต้นแบบ", "is_correct": true, "explanation": "ถูกต้อง ยาสามัญใช้การศึกษาชีวสมมูลแสดงว่ามีอัตราและปริมาณการดูดซึมเทียบเท่ายาต้นแบบ"}, {"label": "B", "text": "ผลการศึกษาทางคลินิกระยะที่ 3 ที่ทำซ้ำในผู้ป่วยไทย", "is_correct": false, "explanation": "การศึกษาทางคลินิกระยะที่ 3 เป็นข้อกำหนดของยาใหม่ ยาสามัญไม่จำเป็นต้องทำซ้ำเพราะอ้างอิงยาต้นแบบ"}, {"label": "C", "text": "ผลการศึกษาความเป็นพิษในสัตว์ทดลองชุดใหม่ทั้งหมด", "is_correct": false, "explanation": "ข้อมูลพิษวิทยาในสัตว์ทดลองเป็นส่วนของยาใหม่ ยาสามัญอ้างอิงข้อมูลเดิมของตัวยาได้"}, {"label": "D", "text": "ใบรับรองว่ายาจำหน่ายในต่างประเทศมาแล้วหลายประเทศ", "is_correct": false, "explanation": "การจำหน่ายในต่างประเทศไม่ได้พิสูจน์ว่าผลิตภัณฑ์ของผู้ผลิตรายนี้ดูดซึมเท่ากับยาต้นแบบ"}, {"label": "E", "text": "ผลสำรวจความพึงพอใจของแพทย์ผู้ทดลองสั่งใช้ยา", "is_correct": false, "explanation": "ความพึงพอใจของผู้สั่งใช้ไม่ใช่หลักฐานทางวิทยาศาสตร์ที่ใช้ขึ้นทะเบียนยา"}], "key_takeaway": "ยาสามัญอ้างอิงประสิทธิผลและความปลอดภัยของยาต้นแบบ โดยพิสูจน์ชีวสมมูล (อัตราและปริมาณการดูดซึมเทียบเท่า) กับยาต้นแบบ"}'::jsonb, 'medium', 'law-day2 • การขึ้นทะเบียนยาสามัญและชีวสมมูล'),
('7b81a37380c77642ba067c17ce19d567', 21, 'ยาใหม่ (new chemical entity) ตัวหนึ่งเพิ่งได้รับอนุมัติทะเบียนตำรับยาแบบมีเงื่อนไขในประเทศไทย เภสัชกรเจ้าของร้านยาแห่งหนึ่งต้องการสั่งยานี้มาจำหน่ายในร้าน ข้อใดอธิบายหลักการของทะเบียนตำรับยาใหม่แบบมีเงื่อนไขได้ถูกต้องที่สุด', '[{"label": "A", "text": "ร้านยาจำหน่ายได้ทันที หากเภสัชกรซักประวัติผู้ป่วยและจดบันทึกการขายทุกครั้ง"}, {"label": "B", "text": "ทะเบียนแบบมีเงื่อนไขเป็นทะเบียนชั่วคราว ซึ่งจะสิ้นผลเองหากไม่มีรายงานอาการไม่พึงประสงค์"}, {"label": "C", "text": "เงื่อนไขหมายถึงการให้ผู้รับอนุญาตทำการศึกษาชีวสมมูลเพิ่มเติมหลังวางจำหน่าย"}, {"label": "D", "text": "ยาจำหน่ายได้ทุกช่องทาง แต่ต้องโฆษณาต่อประชาชนเพื่อให้มีผู้ใช้มากพอต่อการติดตาม"}, {"label": "E", "text": "จำหน่ายได้เฉพาะสถานพยาบาลเพื่อใช้ภายใต้การดูแลของแพทย์ ระหว่างติดตามความปลอดภัย"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. จำหน่ายได้เฉพาะสถานพยาบาลเพื่อใช้ภายใต้การดูแลของแพทย์ ระหว่างติดตามความปลอดภัย — ทะเบียนแบบมีเงื่อนไขมีไว้เพื่อติดตามความปลอดภัยของยาใหม่ในการใช้จริง จึงจำกัดการกระจายยาไว้ที่สถานพยาบาลจนกว่าจะเปลี่ยนเป็นทะเบียนแบบไม่มีเงื่อนไข", "reason": "ข้อมูลความปลอดภัยของยาใหม่ในขณะขึ้นทะเบียนมาจากการศึกษาทางคลินิกที่มีผู้ป่วยจำนวนจำกัด อาการไม่พึงประสงค์ที่พบน้อยอาจยังไม่ปรากฏ ประเทศไทยจึงอนุมัติยาใหม่ในรูปแบบทะเบียนมีเงื่อนไข โดยให้ผู้รับอนุญาตติดตามความปลอดภัยของยาหลังออกสู่ตลาดตามที่ อย. กำหนด\n\nระหว่างที่ทะเบียนยังมีเงื่อนไข ยาจะจำหน่ายได้เฉพาะแก่สถานพยาบาล (โรงพยาบาลและคลินิก) และใช้ภายใต้การดูแลของแพทย์ เพื่อให้ติดตามผู้ใช้ยาได้ ร้านยาจึงยังไม่สามารถสั่งมาจำหน่ายได้ เมื่อผู้รับอนุญาตส่งข้อมูลความปลอดภัยครบตามเงื่อนไขและ อย. พิจารณาแล้วเห็นว่าปลอดภัย จึงจะเปลี่ยนเป็นทะเบียนแบบไม่มีเงื่อนไข และจัดประเภทยาตามความเหมาะสมต่อไป\n\nทะเบียนแบบมีเงื่อนไขเป็นทะเบียนที่ถูกต้องตามกฎหมาย ไม่ใช่ทะเบียนชั่วคราวที่หมดอายุเอง และไม่ได้อนุญาตให้ขายได้ทุกช่องทางตั้งแต่วันแรก", "choices": [{"label": "A", "text": "ร้านยาจำหน่ายได้ทันที หากเภสัชกรซักประวัติผู้ป่วยและจดบันทึกการขายทุกครั้ง", "is_correct": false, "explanation": "การจดบันทึกของร้านยาไม่ได้ปลดข้อจำกัด ระหว่างที่ทะเบียนยังมีเงื่อนไขยาต้องจำหน่ายแก่สถานพยาบาลเท่านั้น"}, {"label": "B", "text": "ทะเบียนแบบมีเงื่อนไขเป็นทะเบียนชั่วคราว ซึ่งจะสิ้นผลเองหากไม่มีรายงานอาการไม่พึงประสงค์", "is_correct": false, "explanation": "ทะเบียนไม่ได้สิ้นผลเอง และการไม่มีรายงานไม่ได้แปลว่าปลอดภัย ผู้รับอนุญาตต้องส่งข้อมูลตามเงื่อนไขเพื่อให้ อย. พิจารณาเปลี่ยนเป็นทะเบียนไม่มีเงื่อนไข"}, {"label": "C", "text": "เงื่อนไขหมายถึงการให้ผู้รับอนุญาตทำการศึกษาชีวสมมูลเพิ่มเติมหลังวางจำหน่าย", "is_correct": false, "explanation": "การศึกษาชีวสมมูลเป็นเรื่องของยาสามัญ เงื่อนไขของยาใหม่คือการติดตามความปลอดภัยและการจำกัดช่องทางการจำหน่าย"}, {"label": "D", "text": "ยาจำหน่ายได้ทุกช่องทาง แต่ต้องโฆษณาต่อประชาชนเพื่อให้มีผู้ใช้มากพอต่อการติดตาม", "is_correct": false, "explanation": "ยาไม่ได้จำหน่ายได้ทุกช่องทาง และการโฆษณาเพื่อเพิ่มจำนวนผู้ใช้ยาขัดกับหลักการติดตามความปลอดภัย"}, {"label": "E", "text": "จำหน่ายได้เฉพาะสถานพยาบาลเพื่อใช้ภายใต้การดูแลของแพทย์ ระหว่างติดตามความปลอดภัย", "is_correct": true, "explanation": "ถูกต้อง ทะเบียนแบบมีเงื่อนไขจำกัดการจำหน่ายไว้ที่สถานพยาบาลและกำหนดให้ติดตามความปลอดภัยหลังออกสู่ตลาด"}], "key_takeaway": "ยาใหม่ทะเบียนแบบมีเงื่อนไขจำกัดการจำหน่ายไว้ที่สถานพยาบาลภายใต้การดูแลของแพทย์ระหว่างติดตามความปลอดภัย ร้านยาจึงยังไม่สามารถจำหน่ายได้"}'::jsonb, 'hard', 'law-day2 • ทะเบียนตำรับยาใหม่แบบมีเงื่อนไข'),
('79c965cea99e2f116020a041ca7cdf36', 22, 'บริษัทแห่งหนึ่งยื่นขออนุญาตผลิตยาแผนปัจจุบันชนิดยาเม็ดและยาน้ำ ตาม พ.ร.บ.ยา ผู้รับอนุญาตต้องจัดให้มีบุคคลใดเป็นผู้มีหน้าที่ปฏิบัติการในสถานที่ผลิตยา', '[{"label": "A", "text": "แพทย์ผู้ประกอบวิชาชีพเวชกรรม"}, {"label": "B", "text": "เภสัชกรชั้นหนึ่ง"}, {"label": "C", "text": "นักเคมีที่มีประสบการณ์ด้านการวิเคราะห์"}, {"label": "D", "text": "วิศวกรผู้ควบคุมเครื่องจักรการผลิต"}, {"label": "E", "text": "ผู้รับอนุญาตเอง โดยไม่ต้องมีคุณวุฒิวิชาชีพ"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. เภสัชกรชั้นหนึ่ง — กฎหมายยากำหนดให้สถานที่ผลิตยาแผนปัจจุบันต้องมีเภสัชกรชั้นหนึ่งเป็นผู้มีหน้าที่ปฏิบัติการ เพื่อควบคุมการผลิตและคุณภาพยา", "reason": "พ.ร.บ.ยา กำหนดให้ผู้รับอนุญาตผลิตยาแผนปัจจุบันต้องจัดให้มีเภสัชกรชั้นหนึ่งเป็นผู้มีหน้าที่ปฏิบัติการ ทำหน้าที่ควบคุมการผลิต การตรวจวิเคราะห์ยา การจัดทำฉลากและเอกสารกำกับยา และการปฏิบัติอื่นให้เป็นไปตามกฎหมาย\n\nเหตุผลคือการผลิตยาต้องใช้ความรู้เฉพาะทางเภสัชศาสตร์ทั้งด้านการผลิต การควบคุมคุณภาพ และการประกันคุณภาพ ผู้เชี่ยวชาญสาขาอื่นอาจร่วมทำงานในโรงงานได้ แต่ไม่สามารถทำหน้าที่ผู้มีหน้าที่ปฏิบัติการตามกฎหมายแทนเภสัชกรชั้นหนึ่งได้ และผู้รับอนุญาตที่ไม่ได้เป็นเภสัชกรก็ไม่สามารถทำหน้าที่นี้เองได้", "choices": [{"label": "A", "text": "แพทย์ผู้ประกอบวิชาชีพเวชกรรม", "is_correct": false, "explanation": "แพทย์ไม่ใช่ผู้มีหน้าที่ปฏิบัติการในสถานที่ผลิตยาแผนปัจจุบันตามกฎหมายยา"}, {"label": "B", "text": "เภสัชกรชั้นหนึ่ง", "is_correct": true, "explanation": "ถูกต้อง กฎหมายกำหนดให้สถานที่ผลิตยาแผนปัจจุบันต้องมีเภสัชกรชั้นหนึ่งเป็นผู้มีหน้าที่ปฏิบัติการ"}, {"label": "C", "text": "นักเคมีที่มีประสบการณ์ด้านการวิเคราะห์", "is_correct": false, "explanation": "นักเคมีทำงานในห้องปฏิบัติการได้ แต่ทำหน้าที่ผู้มีหน้าที่ปฏิบัติการตามกฎหมายแทนเภสัชกรชั้นหนึ่งไม่ได้"}, {"label": "D", "text": "วิศวกรผู้ควบคุมเครื่องจักรการผลิต", "is_correct": false, "explanation": "วิศวกรดูแลเครื่องจักรและระบบสนับสนุนได้ แต่ไม่ใช่ผู้มีหน้าที่ปฏิบัติการตามกฎหมายยา"}, {"label": "E", "text": "ผู้รับอนุญาตเอง โดยไม่ต้องมีคุณวุฒิวิชาชีพ", "is_correct": false, "explanation": "ผู้รับอนุญาตที่ไม่ได้เป็นเภสัชกรชั้นหนึ่งไม่สามารถทำหน้าที่นี้เองได้ ต้องจัดให้มีเภสัชกรชั้นหนึ่ง"}], "key_takeaway": "สถานที่ผลิตยาแผนปัจจุบันต้องมีเภสัชกรชั้นหนึ่งเป็นผู้มีหน้าที่ปฏิบัติการ"}'::jsonb, 'easy', 'law-day2 • ผู้มีหน้าที่ปฏิบัติการในสถานที่ผลิตยา'),
('5e787a65af4c890b51efb55a3ee52fc7', 23, 'โรงงานผลิตยาที่ได้มาตรฐาน GMP PIC/S ผลิตยาฉีดเสร็จหนึ่งรุ่น (batch) ฝ่ายขายแจ้งว่าโรงพยาบาลต้องการยาด่วน และขอให้ส่งยาออกก่อนที่ผลการตรวจวิเคราะห์ของฝ่ายควบคุมคุณภาพจะเสร็จ ข้อใดสอดคล้องกับหลักการปล่อยผ่านรุ่นผลิต (batch release) ตาม GMP', '[{"label": "A", "text": "ผู้จัดการฝ่ายขายอนุมัติปล่อยผ่านได้เมื่อมีความจำเป็นเร่งด่วนของลูกค้า"}, {"label": "B", "text": "ส่งยาออกไปก่อน หากผลวิเคราะห์ไม่ผ่านภายหลังจึงค่อยเรียกคืน"}, {"label": "C", "text": "ใช้เฉพาะผลการตรวจระหว่างการผลิต (in-process control) แทนการตรวจยาสำเร็จรูป"}, {"label": "D", "text": "ปล่อยผ่านหลังผลวิเคราะห์ผ่าน และผู้มีอำนาจทบทวนบันทึกการผลิตแล้ว"}, {"label": "E", "text": "ปล่อยผ่านได้ทันที หากรุ่นผลิตก่อนหน้าผ่านการตรวจวิเคราะห์ทุกรุ่น"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ปล่อยผ่านหลังผลวิเคราะห์ผ่าน และผู้มีอำนาจทบทวนบันทึกการผลิตแล้ว — ยาสำเร็จรูปจะปล่อยออกจำหน่ายได้ต่อเมื่อยืนยันแล้วว่าผ่านข้อกำหนดทั้งหมด โดยผู้ได้รับมอบหมายตามระบบคุณภาพเป็นผู้รับรอง แรงกดดันทางการค้าใช้แทนไม่ได้", "reason": "ตามหลัก GMP PIC/S ยาสำเร็จรูปแต่ละรุ่นต้องอยู่ในสถานะกักกัน (quarantine) จนกว่าจะได้รับการรับรองปล่อยผ่าน การรับรองต้องอาศัยผลการตรวจวิเคราะห์ที่เป็นไปตามข้อกำหนด และการทบทวนบันทึกการผลิตของรุ่นนั้น (batch record) รวมถึงการเบี่ยงเบน (deviation) ที่เกิดขึ้นและผลการสอบสวน เพื่อยืนยันว่ารุ่นผลิตนั้นผลิตและควบคุมตาม GMP และตรงตามทะเบียนตำรับยา\n\nผู้ทำหน้าที่รับรองปล่อยผ่านคือบุคลากรที่ได้รับมอบหมายตามระบบคุณภาพ (ในระบบ PIC/S เรียกว่า Authorised Person) ซึ่งต้องเป็นอิสระจากแรงกดดันของฝ่ายผลิตและฝ่ายขาย ยาฉีดเป็นยาปราศจากเชื้อ ผลการทดสอบความปราศจากเชื้อและการทบทวนบันทึกการผลิตแบบปราศจากเชื้อจึงสำคัญมาก การส่งยาออกก่อนผลเสร็จหรือ \"ส่งไปก่อนแล้วค่อยเรียกคืน\" ขัดกับหลักการ", "choices": [{"label": "A", "text": "ผู้จัดการฝ่ายขายอนุมัติปล่อยผ่านได้เมื่อมีความจำเป็นเร่งด่วนของลูกค้า", "is_correct": false, "explanation": "ฝ่ายขายไม่มีอำนาจปล่อยผ่านรุ่นผลิต การตัดสินต้องเป็นของบุคลากรที่ได้รับมอบหมายตามระบบคุณภาพ"}, {"label": "B", "text": "ส่งยาออกไปก่อน หากผลวิเคราะห์ไม่ผ่านภายหลังจึงค่อยเรียกคืน", "is_correct": false, "explanation": "การจำหน่ายก่อนยืนยันคุณภาพแล้วอาศัยการเรียกคืนภายหลังทำให้ผู้ป่วยเสี่ยงได้รับยาที่ไม่ได้มาตรฐาน"}, {"label": "C", "text": "ใช้เฉพาะผลการตรวจระหว่างการผลิต (in-process control) แทนการตรวจยาสำเร็จรูป", "is_correct": false, "explanation": "การตรวจระหว่างการผลิตเป็นส่วนหนึ่งของการควบคุม แต่ใช้แทนการทดสอบยาสำเร็จรูปตามข้อกำหนดและการทบทวนบันทึกทั้งรุ่นไม่ได้"}, {"label": "D", "text": "ปล่อยผ่านหลังผลวิเคราะห์ผ่าน และผู้มีอำนาจทบทวนบันทึกการผลิตแล้ว", "is_correct": true, "explanation": "ถูกต้อง การปล่อยผ่านต้องอาศัยผลตรวจวิเคราะห์ที่ผ่านและการทบทวนบันทึกโดยผู้มีอำนาจตามระบบคุณภาพ"}, {"label": "E", "text": "ปล่อยผ่านได้ทันที หากรุ่นผลิตก่อนหน้าผ่านการตรวจวิเคราะห์ทุกรุ่น", "is_correct": false, "explanation": "ผลของรุ่นก่อนหน้าไม่ได้รับรองคุณภาพของรุ่นปัจจุบัน แต่ละรุ่นต้องได้รับการประเมินและรับรองปล่อยผ่านแยกกัน"}], "key_takeaway": "ไม่มียารุ่นใดออกจากโรงงานได้ก่อนผลการควบคุมคุณภาพผ่านและผู้มีอำนาจรับรองการปล่อยผ่าน แม้มีความต้องการเร่งด่วนทางการค้า"}'::jsonb, 'medium', 'law-day2 • GMP: การปล่อยผ่านรุ่นผลิต'),
('6d397106faf71feedcca76acabba3415', 24, 'ในการตรวจประเมินโรงงานผลิตยาตามหลักเกณฑ์ GMP ผู้ตรวจขอดูเอกสาร "การตรวจสอบความถูกต้อง" (process validation) ของกระบวนการผลิตยาเม็ด ข้อใดอธิบายความหมายของ process validation ได้ถูกต้อง', '[{"label": "A", "text": "หลักฐานเป็นเอกสารว่ากระบวนการผลิตให้ผลิตภัณฑ์ที่ได้ตามข้อกำหนดอย่างสม่ำเสมอ"}, {"label": "B", "text": "การสอบเทียบเครื่องชั่งและเครื่องมือวัดให้มีความแม่นยำตามรอบที่กำหนด"}, {"label": "C", "text": "การตรวจวิเคราะห์ยาสำเร็จรูปรุ่นแรกให้ผ่านข้อกำหนดเพียงครั้งเดียว"}, {"label": "D", "text": "การตรวจยาสำเร็จรูปทุกรุ่นอย่างละเอียด ซึ่งทำให้ไม่ต้องทำ validation"}, {"label": "E", "text": "การทำครั้งเดียวตอนเริ่มผลิต โดยไม่ต้องทบทวนแม้ภายหลังเปลี่ยนเครื่องจักร"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. หลักฐานเป็นเอกสารว่ากระบวนการผลิตให้ผลิตภัณฑ์ที่ได้ตามข้อกำหนดอย่างสม่ำเสมอ — validation คือการพิสูจน์และบันทึกเป็นเอกสารว่ากระบวนการทำงานได้ตามที่ตั้งใจและให้ผลที่เป็นไปตามข้อกำหนดได้ซ้ำ ๆ อย่างสม่ำเสมอ", "reason": "หลัก GMP ถือว่าคุณภาพต้อง \"สร้างเข้าไปในผลิตภัณฑ์\" ผ่านกระบวนการที่ควบคุมได้ ไม่ใช่อาศัยการตรวจยาสำเร็จรูปเพียงอย่างเดียว เพราะการสุ่มตรวจยาสำเร็จรูปไม่สามารถตรวจทุกเม็ดได้ process validation จึงเป็นการรวบรวมหลักฐานที่เป็นเอกสาร (documented evidence) ว่ากระบวนการซึ่งทำภายใต้พารามิเตอร์ที่กำหนดให้ผลิตภัณฑ์ที่ได้ตามข้อกำหนดและคุณลักษณะคุณภาพที่ตั้งไว้อย่างสม่ำเสมอ\n\nvalidation ต่างจากการสอบเทียบ (calibration) ซึ่งเป็นการตรวจความถูกต้องของเครื่องมือวัด และต่างจากการทดสอบรุ่นเดียว เมื่อมีการเปลี่ยนแปลงที่อาจกระทบคุณภาพ เช่น เปลี่ยนเครื่องจักร แหล่งวัตถุดิบ หรือขนาดรุ่นผลิต ต้องประเมินผ่านระบบควบคุมการเปลี่ยนแปลง (change control) และทำ validation ซ้ำตามความจำเป็น", "choices": [{"label": "A", "text": "หลักฐานเป็นเอกสารว่ากระบวนการผลิตให้ผลิตภัณฑ์ที่ได้ตามข้อกำหนดอย่างสม่ำเสมอ", "is_correct": true, "explanation": "ถูกต้อง นี่คือความหมายของ process validation ตามหลัก GMP"}, {"label": "B", "text": "การสอบเทียบเครื่องชั่งและเครื่องมือวัดให้มีความแม่นยำตามรอบที่กำหนด", "is_correct": false, "explanation": "นี่คือการสอบเทียบ (calibration) ซึ่งจำเป็นแต่เป็นคนละเรื่องกับ process validation"}, {"label": "C", "text": "การตรวจวิเคราะห์ยาสำเร็จรูปรุ่นแรกให้ผ่านข้อกำหนดเพียงครั้งเดียว", "is_correct": false, "explanation": "ผลผ่านเพียงรุ่นเดียวไม่ได้แสดงว่ากระบวนการให้ผลได้สม่ำเสมอ"}, {"label": "D", "text": "การตรวจยาสำเร็จรูปทุกรุ่นอย่างละเอียด ซึ่งทำให้ไม่ต้องทำ validation", "is_correct": false, "explanation": "GMP ไม่ยอมรับการพึ่งการตรวจยาสำเร็จรูปแทนการควบคุมกระบวนการ เพราะการสุ่มตรวจไม่ครอบคลุมทุกหน่วย"}, {"label": "E", "text": "การทำครั้งเดียวตอนเริ่มผลิต โดยไม่ต้องทบทวนแม้ภายหลังเปลี่ยนเครื่องจักร", "is_correct": false, "explanation": "การเปลี่ยนแปลงที่อาจกระทบคุณภาพต้องผ่าน change control และอาจต้องทำ validation ซ้ำ"}], "key_takeaway": "process validation คือหลักฐานที่เป็นเอกสารว่ากระบวนการผลิตให้ผลิตภัณฑ์ได้ตามข้อกำหนดอย่างสม่ำเสมอ"}'::jsonb, 'medium', 'law-day2 • GMP: validation'),
('e9bbf1eabbbd0d741ca5697ff45887a8', 25, 'ผู้แทนยา (medical representative) ของบริษัทหนึ่งเตรียมนำเสนอข้อมูลยาลดไขมันในเลือดของบริษัทต่อแพทย์ในโรงพยาบาล ข้อใดเป็นการปฏิบัติที่สอดคล้องกับจริยธรรมการส่งเสริมการขายยาต่อบุคลากรทางการแพทย์', '[{"label": "A", "text": "นำเสนอเฉพาะงานวิจัยที่ให้ผลดี และไม่ต้องกล่าวถึงอาการไม่พึงประสงค์ เพราะแพทย์ทราบอยู่แล้ว"}, {"label": "B", "text": "แนะนำให้ใช้ยาในข้อบ่งใช้ที่ยังไม่ได้รับอนุมัติ หากมีบทคัดย่องานประชุมวิชาการรองรับ"}, {"label": "C", "text": "นำเสนอทั้งประโยชน์และความเสี่ยงอย่างสมดุล ตามข้อบ่งใช้ที่ได้รับอนุมัติ พร้อมอ้างอิงหลักฐาน"}, {"label": "D", "text": "กล่าวว่ายาของบริษัทดีที่สุดในกลุ่ม แม้ไม่มีการศึกษาเปรียบเทียบโดยตรงกับยาอื่น"}, {"label": "E", "text": "เสนอค่าตอบแทนให้แพทย์ตามจำนวนใบสั่งยาที่สั่งยาของบริษัท"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. นำเสนอทั้งประโยชน์และความเสี่ยงอย่างสมดุล ตามข้อบ่งใช้ที่ได้รับอนุมัติ พร้อมอ้างอิงหลักฐาน — ข้อมูลที่ผู้แทนยาให้แก่บุคลากรทางการแพทย์ต้องถูกต้อง สมดุล มีหลักฐานรองรับ และอยู่ในขอบเขตที่ทะเบียนตำรับยาอนุมัติ", "reason": "เกณฑ์จริยธรรมว่าด้วยการส่งเสริมการขายยาของประเทศไทยและจรรยาบรรณของสมาคมผู้วิจัยและผลิตเภสัชภัณฑ์มีหลักการเดียวกัน คือข้อมูลที่ใช้ส่งเสริมการขายต้องถูกต้อง เป็นปัจจุบัน ตรวจสอบได้ และสมดุล ต้องให้ข้อมูลความปลอดภัย ข้อห้ามใช้ และอาการไม่พึงประสงค์ควบคู่กับประโยชน์ และต้องไม่ทำให้เข้าใจผิด\n\nการส่งเสริมการขายต้องอยู่ในขอบเขตข้อบ่งใช้และข้อมูลที่ได้รับอนุมัติในทะเบียน การชักจูงให้ใช้ยานอกข้อบ่งใช้ (off-label promotion) การเลือกเสนอเฉพาะผลการศึกษาที่เป็นบวก หรือการอ้างว่าเหนือกว่ายาอื่นโดยไม่มีหลักฐานเปรียบเทียบที่เหมาะสม ล้วนขัดหลักจริยธรรม นอกจากนี้ผลประโยชน์ที่ผูกกับจำนวนการสั่งใช้ยาถือเป็นการชักจูงที่ไม่เหมาะสม เพราะทำให้การตัดสินใจทางคลินิกไม่เป็นอิสระ", "choices": [{"label": "A", "text": "นำเสนอเฉพาะงานวิจัยที่ให้ผลดี และไม่ต้องกล่าวถึงอาการไม่พึงประสงค์ เพราะแพทย์ทราบอยู่แล้ว", "is_correct": false, "explanation": "การเลือกนำเสนอเฉพาะข้อมูลด้านบวกทำให้ข้อมูลไม่สมดุลและอาจทำให้เข้าใจผิด"}, {"label": "B", "text": "แนะนำให้ใช้ยาในข้อบ่งใช้ที่ยังไม่ได้รับอนุมัติ หากมีบทคัดย่องานประชุมวิชาการรองรับ", "is_correct": false, "explanation": "การส่งเสริมการขายนอกข้อบ่งใช้ที่ได้รับอนุมัติ (off-label promotion) ขัดหลักจริยธรรม แม้จะมีงานวิจัยเบื้องต้นรองรับ"}, {"label": "C", "text": "นำเสนอทั้งประโยชน์และความเสี่ยงอย่างสมดุล ตามข้อบ่งใช้ที่ได้รับอนุมัติ พร้อมอ้างอิงหลักฐาน", "is_correct": true, "explanation": "ถูกต้อง เป็นหลักการให้ข้อมูลที่ถูกต้อง สมดุล และตรวจสอบได้"}, {"label": "D", "text": "กล่าวว่ายาของบริษัทดีที่สุดในกลุ่ม แม้ไม่มีการศึกษาเปรียบเทียบโดยตรงกับยาอื่น", "is_correct": false, "explanation": "การอ้างความเหนือกว่าโดยไม่มีหลักฐานเปรียบเทียบที่เหมาะสมเป็นการให้ข้อมูลที่ทำให้เข้าใจผิด"}, {"label": "E", "text": "เสนอค่าตอบแทนให้แพทย์ตามจำนวนใบสั่งยาที่สั่งยาของบริษัท", "is_correct": false, "explanation": "ผลประโยชน์ที่ผูกกับปริมาณการสั่งใช้ยาเป็นการชักจูงที่ไม่เหมาะสม ทำให้การตัดสินใจทางคลินิกไม่เป็นอิสระ"}], "key_takeaway": "การให้ข้อมูลยาแก่บุคลากรทางการแพทย์ต้องถูกต้อง สมดุลทั้งประโยชน์และความเสี่ยง และอยู่ในข้อบ่งใช้ที่ได้รับอนุมัติ"}'::jsonb, 'medium', 'law-day2 • จริยธรรมผู้แทนยา'),
('c085215df7e4a2f2dd89630321ac6cdf', 26, 'บริษัทผู้นำเข้ายาซึ่งเป็นผู้รับอนุญาตและเจ้าของทะเบียนตำรับยา ได้รับแจ้งจากผู้ผลิตต่างประเทศว่ายาบางรุ่นที่นำเข้ามาจำหน่ายในประเทศไทยแล้วมีปัญหาด้านคุณภาพ ข้อใดเป็นแนวทางที่ถูกต้องตามหลักการเรียกคืนยา', '[{"label": "A", "text": "รอให้ อย. มีคำสั่งเรียกคืนก่อน เพราะบริษัทไม่มีหน้าที่เรียกคืนยาเอง"}, {"label": "B", "text": "บริษัทรับผิดชอบหลัก แจ้ง อย. และเรียกคืนจากทุกจุดตามบันทึกการจำหน่าย"}, {"label": "C", "text": "แจ้งผู้ผลิตต่างประเทศให้ดำเนินการเรียกคืนเอง เพราะปัญหาเกิดจากการผลิต"}, {"label": "D", "text": "เรียกคืนเฉพาะจากลูกค้ารายใหญ่ โดยไม่ต้องแจ้งหน่วยงานใด เพื่อรักษาภาพลักษณ์"}, {"label": "E", "text": "หยุดนำเข้ารุ่นใหม่เท่านั้น ส่วนยาที่จำหน่ายไปแล้วให้ใช้จนหมด"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. บริษัทรับผิดชอบหลัก แจ้ง อย. และเรียกคืนจากทุกจุดตามบันทึกการจำหน่าย — ผู้รับอนุญาตที่เป็นเจ้าของทะเบียนตำรับยาในประเทศไทยต้องรับผิดชอบการเรียกคืนยาที่ตนนำเข้า แม้ต้นเหตุจะอยู่ที่ผู้ผลิตต่างประเทศ", "reason": "ในทางกฎหมาย ผู้รับอนุญาตนำเข้าซึ่งเป็นเจ้าของทะเบียนตำรับยาคือผู้รับผิดชอบผลิตภัณฑ์ในตลาดไทย เมื่อทราบว่ายามีปัญหาคุณภาพหรือความปลอดภัย บริษัทต้องดำเนินการเรียกคืนตามระบบที่มีอยู่ ได้แก่ ประเมินความเสี่ยง แจ้งและประสานงานกับ อย. ใช้บันทึกการจำหน่าย (distribution record) ระบุผู้รับยาทุกราย และเรียกคืนให้ถึงระดับที่กำหนดตามความรุนแรง เช่น ผู้ค้าส่ง สถานพยาบาล ร้านยา หรือถึงผู้บริโภค\n\nหลังเรียกคืน บริษัทต้องกักกันยาที่ได้คืน ทำ reconciliation ระหว่างจำนวนที่จำหน่ายกับที่ได้คืน และรายงานผลต่อหน่วยงานกำกับ การรอให้ อย. สั่งก่อน การโยนความรับผิดชอบให้ผู้ผลิตต่างประเทศ หรือการเรียกคืนแบบไม่เปิดเผยเพียงบางลูกค้า ไม่ใช่แนวทางที่ถูกต้อง", "choices": [{"label": "A", "text": "รอให้ อย. มีคำสั่งเรียกคืนก่อน เพราะบริษัทไม่มีหน้าที่เรียกคืนยาเอง", "is_correct": false, "explanation": "ผู้รับอนุญาตต้องดำเนินการเรียกคืนเมื่อทราบปัญหา ไม่ใช่รอคำสั่ง ความล่าช้าทำให้ผู้ป่วยได้รับความเสี่ยง"}, {"label": "B", "text": "บริษัทรับผิดชอบหลัก แจ้ง อย. และเรียกคืนจากทุกจุดตามบันทึกการจำหน่าย", "is_correct": true, "explanation": "ถูกต้อง เจ้าของทะเบียนในประเทศเป็นผู้รับผิดชอบหลัก ต้องแจ้งหน่วยงานกำกับและติดตามยาคืนจากทุกจุดที่จำหน่าย"}, {"label": "C", "text": "แจ้งผู้ผลิตต่างประเทศให้ดำเนินการเรียกคืนเอง เพราะปัญหาเกิดจากการผลิต", "is_correct": false, "explanation": "ผู้ผลิตต่างประเทศไม่ได้เป็นผู้รับอนุญาตในไทย ผู้นำเข้าที่เป็นเจ้าของทะเบียนต้องรับผิดชอบในตลาดไทย"}, {"label": "D", "text": "เรียกคืนเฉพาะจากลูกค้ารายใหญ่ โดยไม่ต้องแจ้งหน่วยงานใด เพื่อรักษาภาพลักษณ์", "is_correct": false, "explanation": "การเรียกคืนต้องครอบคลุมทุกจุดที่จำหน่ายตามระดับที่กำหนด และต้องแจ้งหน่วยงานกำกับ"}, {"label": "E", "text": "หยุดนำเข้ารุ่นใหม่เท่านั้น ส่วนยาที่จำหน่ายไปแล้วให้ใช้จนหมด", "is_correct": false, "explanation": "การหยุดนำเข้าไม่ได้แก้ปัญหายาที่มีความเสี่ยงซึ่งอยู่ในตลาดแล้ว ต้องเรียกคืนยารุ่นที่มีปัญหา"}], "key_takeaway": "เจ้าของทะเบียนตำรับยา (ผู้ผลิตหรือผู้นำเข้า) เป็นผู้รับผิดชอบหลักในการเรียกคืนยา ต้องแจ้ง อย. และติดตามยาคืนจากทุกจุดที่จำหน่ายออกไป"}'::jsonb, 'medium', 'law-day2 • การเรียกคืนยาโดยผู้นำเข้า'),
('a6c0ce6409eca8f81246a496bfe06c5f', 27, 'ผู้รับอนุญาตผลิตยาได้รับรายงานปัญหาผลิตภัณฑ์ 5 กรณีดังต่อไปนี้ หากจัดระดับการเรียกคืนตามความเสี่ยงต่อสุขภาพของผู้ใช้ยา กรณีใดควรจัดอยู่ในระดับรุนแรงที่สุด (ระดับที่อาจทำให้เกิดอันตรายร้ายแรงหรือเสียชีวิต)', '[{"label": "A", "text": "กล่องกระดาษชั้นนอกบุบเสียหาย แต่แผงยาด้านในอยู่ในสภาพสมบูรณ์"}, {"label": "B", "text": "ฉลากกล่องสะกดชื่อผู้จัดจำหน่ายผิดหนึ่งตัวอักษร"}, {"label": "C", "text": "เลขที่ผลิตบนกล่องพิมพ์จาง แต่บนแผงยายังอ่านได้ครบถ้วน"}, {"label": "D", "text": "วิตามินเม็ดรุ่นหนึ่งมีผลการละลายต่ำกว่าข้อกำหนดเล็กน้อย"}, {"label": "E", "text": "ยาฉีดที่ฉลากระบุยาหนึ่ง แต่บรรจุตัวยาอื่นที่มีความแรงสูง"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ยาฉีดที่ฉลากระบุยาหนึ่ง แต่บรรจุตัวยาอื่นที่มีความแรงสูง — การปะปนสลับตัวยา (mix-up) ทำให้ผู้ป่วยได้รับยาผิดชนิดโดยไม่รู้ตัว ซึ่งอาจเกิดอันตรายร้ายแรงหรือเสียชีวิต จึงจัดเป็นระดับรุนแรงที่สุด", "reason": "การเรียกคืนยาจัดระดับตามความเสี่ยงต่อสุขภาพ โดยภาพรวมแบ่งเป็น 3 ระดับ ระดับรุนแรงที่สุด คือยาที่อาจทำให้เกิดอันตรายร้ายแรงต่อสุขภาพหรือเสียชีวิต ระดับกลาง คือยาที่อาจทำให้เกิดอันตรายชั่วคราวหรือไม่ร้ายแรง หรือมีโอกาสเกิดอันตรายร้ายแรงน้อย ระดับต่ำ คือยาที่ไม่น่าจะก่อให้เกิดอันตรายต่อสุขภาพ แต่ไม่เป็นไปตามข้อกำหนดหรือกฎหมาย ระดับยิ่งสูงยิ่งต้องเรียกคืนเร็วและลึกถึงระดับผู้ใช้ยามากขึ้น\n\nยาฉีดที่ฉลากไม่ตรงกับตัวยาจริงและเป็นตัวยาที่มีความแรงสูง ทำให้ผู้ป่วยได้รับยาผิดชนิดและผิดขนาดเข้าสู่กระแสเลือดโดยตรง จึงเป็นกรณีที่เสี่ยงต่อชีวิตชัดเจนที่สุด ส่วนกรณีอื่น เช่น บรรจุภัณฑ์ชั้นนอกชำรุด การสะกดผิดเล็กน้อยที่ไม่กระทบข้อมูลสำคัญ หรือการพิมพ์ไม่ชัดบนกล่องแต่ข้อมูลบนแผงยังครบถ้วน มีความเสี่ยงต่ำกว่า การละลายของวิตามินไม่ผ่านข้อกำหนดเป็นปัญหาคุณภาพที่ต้องจัดการ แต่ความเสี่ยงต่อชีวิตต่ำกว่า", "choices": [{"label": "A", "text": "กล่องกระดาษชั้นนอกบุบเสียหาย แต่แผงยาด้านในอยู่ในสภาพสมบูรณ์", "is_correct": false, "explanation": "บรรจุภัณฑ์ปฐมภูมิยังสมบูรณ์ คุณภาพยาไม่น่าได้รับผลกระทบ ความเสี่ยงต่อสุขภาพต่ำ"}, {"label": "B", "text": "ฉลากกล่องสะกดชื่อผู้จัดจำหน่ายผิดหนึ่งตัวอักษร", "is_correct": false, "explanation": "เป็นข้อบกพร่องด้านฉลากที่ไม่กระทบข้อมูลสำคัญต่อการใช้ยา ไม่น่าก่ออันตราย จัดเป็นระดับต่ำ"}, {"label": "C", "text": "เลขที่ผลิตบนกล่องพิมพ์จาง แต่บนแผงยายังอ่านได้ครบถ้วน", "is_correct": false, "explanation": "ข้อมูลยังตรวจสอบย้อนกลับได้จากแผงยา ความเสี่ยงต่อผู้ใช้ยาต่ำ"}, {"label": "D", "text": "วิตามินเม็ดรุ่นหนึ่งมีผลการละลายต่ำกว่าข้อกำหนดเล็กน้อย", "is_correct": false, "explanation": "เป็นปัญหาคุณภาพที่ต้องจัดการ แต่โอกาสก่ออันตรายร้ายแรงหรือเสียชีวิตต่ำกว่ากรณียาฉีดบรรจุผิดตัวยามาก"}, {"label": "E", "text": "ยาฉีดที่ฉลากระบุยาหนึ่ง แต่บรรจุตัวยาอื่นที่มีความแรงสูง", "is_correct": true, "explanation": "ถูกต้อง การได้รับยาฉีดผิดชนิดที่มีความแรงสูงอาจทำให้เกิดอันตรายร้ายแรงหรือเสียชีวิต จึงเป็นระดับรุนแรงที่สุด"}], "key_takeaway": "การจัดระดับการเรียกคืนยึดความเสี่ยงต่อสุขภาพผู้ใช้ยา และการปะปนสลับตัวยาที่มีความแรงสูงเป็นตัวอย่างของระดับรุนแรงที่สุด"}'::jsonb, 'hard', 'law-day2 • ระดับความรุนแรงของการเรียกคืนยา'),
('0040ea281cc13135a4e6782769b02156', 28, 'บริษัทแห่งหนึ่งได้รับใบอนุญาตนำหรือสั่งยาแผนปัจจุบันเข้ามาในราชอาณาจักร ข้อใดเป็นหน้าที่ของผู้รับอนุญาตนำเข้ายาตามหลักการของ พ.ร.บ.ยา', '[{"label": "A", "text": "ขายปลีกยาที่นำเข้าให้ประชาชนทั่วไปที่โกดังได้ เพราะเป็นเจ้าของยาเอง"}, {"label": "B", "text": "นำเข้ายาที่ยังไม่ได้ขึ้นทะเบียนตำรับมาเก็บไว้ก่อน แล้วขายเมื่อได้ทะเบียนภายหลัง"}, {"label": "C", "text": "ไม่ต้องมีเภสัชกร หากสถานที่เก็บยามีระบบควบคุมอุณหภูมิอัตโนมัติ"}, {"label": "D", "text": "มีเภสัชกรประจำ ทำบัญชีนำเข้าและขายยา และเก็บยาตามสภาวะที่กำหนด"}, {"label": "E", "text": "เปลี่ยนฉลากหรือแบ่งบรรจุยาจากขนาดใหญ่เป็นขนาดเล็กได้เองตามความต้องการของตลาด"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. มีเภสัชกรประจำ ทำบัญชีนำเข้าและขายยา และเก็บยาตามสภาวะที่กำหนด — ผู้รับอนุญาตนำเข้ายาต้องมีเภสัชกรควบคุม จัดทำบัญชียา และเก็บรักษายาให้คงคุณภาพ เพื่อให้ตรวจสอบย้อนกลับได้และยาคงคุณภาพจนถึงมือผู้ใช้", "reason": "ผู้รับอนุญาตนำหรือสั่งยาแผนปัจจุบันเข้ามาในราชอาณาจักรมีหน้าที่ในภาพรวม คือต้องจัดให้มีเภสัชกรชั้นหนึ่งเป็นผู้มีหน้าที่ปฏิบัติการ จัดให้มีฉลากและเอกสารกำกับยาตามที่กฎหมายกำหนด จัดทำบัญชียาที่นำเข้าและที่ขาย และเก็บรักษายาในสถานที่และสภาวะที่เหมาะสม ยาที่นำเข้าต้องได้รับทะเบียนตำรับยาแล้ว และต้องนำเข้าผ่านด่านตรวจสอบอาหารและยาเพื่อให้พนักงานเจ้าหน้าที่ตรวจสอบ\n\nบัญชียามีความสำคัญมากต่อการตรวจสอบย้อนกลับ โดยเฉพาะเมื่อต้องเรียกคืนยา ส่วนการเก็บรักษาต้องเป็นไปตามสภาวะที่ระบุของยาแต่ละตัว เช่น ยาที่ต้องเก็บในตู้เย็น ผู้นำเข้าไม่มีสิทธิ์ขายปลีกแก่ประชาชนทั่วไปจากใบอนุญาตนำเข้า และไม่สามารถเปลี่ยนฉลากหรือแบ่งบรรจุโดยพลการ", "choices": [{"label": "A", "text": "ขายปลีกยาที่นำเข้าให้ประชาชนทั่วไปที่โกดังได้ เพราะเป็นเจ้าของยาเอง", "is_correct": false, "explanation": "ใบอนุญาตนำเข้าไม่ได้ให้สิทธิ์ขายปลีกแก่ประชาชน การขายปลีกต้องทำในสถานที่ที่ได้รับอนุญาตขายยา"}, {"label": "B", "text": "นำเข้ายาที่ยังไม่ได้ขึ้นทะเบียนตำรับมาเก็บไว้ก่อน แล้วขายเมื่อได้ทะเบียนภายหลัง", "is_correct": false, "explanation": "การนำเข้ายาเพื่อการค้าต้องเป็นยาที่ได้รับทะเบียนตำรับยาแล้ว ยกเว้นกรณีที่กฎหมายกำหนดเฉพาะ"}, {"label": "C", "text": "ไม่ต้องมีเภสัชกร หากสถานที่เก็บยามีระบบควบคุมอุณหภูมิอัตโนมัติ", "is_correct": false, "explanation": "ระบบควบคุมอุณหภูมิใช้แทนเภสัชกรผู้มีหน้าที่ปฏิบัติการตามกฎหมายไม่ได้"}, {"label": "D", "text": "มีเภสัชกรประจำ ทำบัญชีนำเข้าและขายยา และเก็บยาตามสภาวะที่กำหนด", "is_correct": true, "explanation": "ถูกต้อง เป็นหน้าที่หลักของผู้รับอนุญาตนำเข้ายา"}, {"label": "E", "text": "เปลี่ยนฉลากหรือแบ่งบรรจุยาจากขนาดใหญ่เป็นขนาดเล็กได้เองตามความต้องการของตลาด", "is_correct": false, "explanation": "การแบ่งบรรจุหรือเปลี่ยนฉลากเป็นการกระทำที่อยู่ในความหมายของการผลิต และต้องตรงกับที่ได้รับอนุมัติ ทำเองโดยพลการไม่ได้"}], "key_takeaway": "ผู้รับอนุญาตนำเข้ายาต้องมีเภสัชกรผู้มีหน้าที่ปฏิบัติการ จัดทำบัญชีการนำเข้าและการขาย และเก็บรักษายาตามสภาวะที่กำหนด"}'::jsonb, 'medium', 'law-day2 • หน้าที่ผู้รับอนุญาตนำเข้ายา'),
('7a3d1ca26ac406452ba01f65aa41844d', 29, 'คลังสินค้าของผู้จัดจำหน่ายยาที่ปฏิบัติตามหลักการ Good Distribution Practice รับวัคซีนชนิดที่ต้องเก็บที่ 2–8 °C เมื่อเปิดดูข้อมูลจากเครื่องบันทึกอุณหภูมิ (data logger) พบว่าระหว่างขนส่งอุณหภูมิออกนอกช่วงที่กำหนด แต่ลักษณะภายนอกของวัคซีนดูปกติ ข้อใดเป็นการปฏิบัติที่ถูกต้อง', '[{"label": "A", "text": "กักกันในสภาวะ 2–8 °C งดจ่าย บันทึกเหตุการณ์ และรอผลประเมินจากผู้ผลิต"}, {"label": "B", "text": "จำหน่ายต่อได้ทันทีเพราะลักษณะภายนอกปกติ และไม่มีตะกอนหรือการเปลี่ยนสี"}, {"label": "C", "text": "นำเข้าช่องแช่แข็งชั่วคราวเพื่อลดอุณหภูมิให้กลับเข้าช่วงโดยเร็ว"}, {"label": "D", "text": "ทิ้งทำลายทันทีโดยไม่ต้องบันทึก เพื่อตัดปัญหาและประหยัดเวลา"}, {"label": "E", "text": "ติดฉลากวันหมดอายุใหม่ให้สั้นลงเอง แล้วจำหน่ายให้ใช้ให้หมดเร็วขึ้น"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. กักกันในสภาวะ 2–8 °C งดจ่าย บันทึกเหตุการณ์ และรอผลประเมินจากผู้ผลิต — วัคซีนที่อุณหภูมิออกนอกช่วงที่กำหนดอาจเสื่อมคุณภาพโดยดูจากภายนอกไม่ออก จึงต้องกักกันและให้ผู้ผลิตประเมินจากข้อมูลความคงตัวก่อนตัดสินใจ", "reason": "วัคซีนและชีววัตถุส่วนใหญ่ไวต่ออุณหภูมิ ทั้งความร้อนและการแช่แข็ง การเสื่อมฤทธิ์มักมองไม่เห็นจากภายนอก หลัก GDP/GSP จึงกำหนดให้ควบคุมและบันทึกอุณหภูมิตลอดห่วงโซ่ความเย็น (cold chain) และเมื่อพบการเบี่ยงเบนของอุณหภูมิ (temperature excursion) ต้องกักกัน (quarantine) วัคซีนนั้นแยกไว้ในสภาวะที่ถูกต้องโดยติดป้ายห้ามจ่าย บันทึกรายละเอียดเหตุการณ์ (ช่วงอุณหภูมิและระยะเวลา) และส่งข้อมูลให้ผู้ผลิตหรือเจ้าของผลิตภัณฑ์ประเมินกับข้อมูลความคงตัว\n\nการตัดสินว่าจะใช้ต่อหรือทำลายต้องอาศัยผลประเมินนั้น ไม่ใช่ลักษณะภายนอก การนำไปแช่แข็งเพื่อ \"ทำให้เย็นเร็ว\" เป็นอันตรายต่อวัคซีนหลายชนิด และการทิ้งโดยไม่บันทึกทำให้ตรวจสอบย้อนกลับไม่ได้และไม่ได้แก้ต้นเหตุ ผู้จัดจำหน่ายไม่มีสิทธิ์กำหนดวันหมดอายุใหม่เอง", "choices": [{"label": "A", "text": "กักกันในสภาวะ 2–8 °C งดจ่าย บันทึกเหตุการณ์ และรอผลประเมินจากผู้ผลิต", "is_correct": true, "explanation": "ถูกต้อง เป็นแนวทางจัดการ temperature excursion ตามหลัก GDP"}, {"label": "B", "text": "จำหน่ายต่อได้ทันทีเพราะลักษณะภายนอกปกติ และไม่มีตะกอนหรือการเปลี่ยนสี", "is_correct": false, "explanation": "การเสื่อมฤทธิ์ของวัคซีนมักมองไม่เห็นจากภายนอก การจำหน่ายโดยไม่ประเมินเสี่ยงต่อการได้วัคซีนไร้ประสิทธิภาพ"}, {"label": "C", "text": "นำเข้าช่องแช่แข็งชั่วคราวเพื่อลดอุณหภูมิให้กลับเข้าช่วงโดยเร็ว", "is_correct": false, "explanation": "การแช่แข็งทำลายวัคซีนหลายชนิด เช่น วัคซีนที่มีสารเสริมฤทธิ์อะลูมิเนียม จึงเป็นการทำให้เสียหายเพิ่ม"}, {"label": "D", "text": "ทิ้งทำลายทันทีโดยไม่ต้องบันทึก เพื่อตัดปัญหาและประหยัดเวลา", "is_correct": false, "explanation": "การทำลายโดยไม่บันทึกและไม่ประเมินทำให้ตรวจสอบย้อนกลับไม่ได้ และไม่ได้แก้ปัญหาในระบบขนส่ง"}, {"label": "E", "text": "ติดฉลากวันหมดอายุใหม่ให้สั้นลงเอง แล้วจำหน่ายให้ใช้ให้หมดเร็วขึ้น", "is_correct": false, "explanation": "ผู้จัดจำหน่ายไม่มีอำนาจกำหนดวันหมดอายุใหม่ การเปลี่ยนแปลงฉลากต้องเป็นไปตามที่ได้รับอนุมัติ"}], "key_takeaway": "เมื่อวัคซีนมีอุณหภูมิออกนอก 2–8 °C ต้องกักกัน งดจ่าย บันทึกเหตุการณ์ และรอผลประเมินจากผู้ผลิต ไม่ตัดสินจากลักษณะภายนอก"}'::jsonb, 'hard', 'law-day2 • GDP: cold chain วัคซีน'),
('cd84a794d726c759339cafd865321b76', 30, 'ผู้รับอนุญาตขายส่งยาแผนปัจจุบันรายหนึ่งได้รับคำสั่งซื้อยาอันตรายจำนวนมากจากผู้ติดต่อทางโทรศัพท์ซึ่งไม่เคยซื้อขายกันมาก่อน ข้อใดเป็นการปฏิบัติที่ถูกต้องตามหลักการขายส่งยาและ Good Distribution Practice', '[{"label": "A", "text": "ขายได้ทันทีหากผู้ซื้อชำระเงินล่วงหน้าเต็มจำนวนก่อนส่งของ"}, {"label": "B", "text": "ขายได้หากผู้ซื้อแสดงทะเบียนพาณิชย์ของร้านขายของชำ"}, {"label": "C", "text": "ตรวจว่าผู้ซื้อมีสิทธิ์ตามกฎหมาย เช่น ร้านยาหรือสถานพยาบาล และบันทึกการขาย"}, {"label": "D", "text": "ขายได้โดยไม่ต้องบันทึก เพราะการบันทึกเป็นหน้าที่ของผู้ซื้อเท่านั้น"}, {"label": "E", "text": "ขายได้หากผู้ซื้อยืนยันเป็นหนังสือว่าจะนำยาไปใช้เองในครอบครัว"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ตรวจว่าผู้ซื้อมีสิทธิ์ตามกฎหมาย เช่น ร้านยาหรือสถานพยาบาล และบันทึกการขาย — การขายส่งยาต้องขายแก่ผู้ที่กฎหมายกำหนดเท่านั้น ผู้ขายส่งจึงต้องตรวจสอบสถานะผู้ซื้อและบันทึกการขายเพื่อป้องกันยารั่วไหลออกนอกระบบ", "reason": "ตามกฎหมายยา \"ขายส่ง\" หมายถึงการขายแก่ผู้ที่กฎหมายกำหนด เช่น ผู้รับอนุญาตขายยา ผู้รับอนุญาตผลิตหรือนำเข้ายา หน่วยงานของรัฐ สถานพยาบาล หรือผู้ประกอบวิชาชีพที่มีสิทธิ์ ไม่ใช่ขายแก่ใครก็ได้ที่ซื้อปริมาณมาก หลัก GDP กำหนดให้ผู้จัดจำหน่ายตรวจสอบคุณสมบัติของลูกค้าว่าได้รับอนุญาตหรือมีสิทธิ์ซื้อยาจริง และเก็บบันทึกการขายเพื่อตรวจสอบย้อนกลับได้\n\nการตรวจสอบนี้ช่วยป้องกันไม่ให้ยารั่วไหลไปยังผู้ไม่มีสิทธิ์ เช่น ร้านค้าทั่วไปหรือผู้ที่นำไปขายผิดกฎหมาย ทะเบียนพาณิชย์หรือเลขผู้เสียภาษีไม่ใช่ใบอนุญาตเกี่ยวกับยา และการแจ้งว่าจะใช้เองก็ไม่ได้ทำให้บุคคลทั่วไปมีสิทธิ์ซื้อยาแบบขายส่ง", "choices": [{"label": "A", "text": "ขายได้ทันทีหากผู้ซื้อชำระเงินล่วงหน้าเต็มจำนวนก่อนส่งของ", "is_correct": false, "explanation": "การชำระเงินไม่ได้ทำให้ผู้ซื้อมีสิทธิ์ซื้อยาแบบขายส่งตามกฎหมาย"}, {"label": "B", "text": "ขายได้หากผู้ซื้อแสดงทะเบียนพาณิชย์ของร้านขายของชำ", "is_correct": false, "explanation": "ทะเบียนพาณิชย์ไม่ใช่ใบอนุญาตขายยา ร้านขายของชำไม่มีสิทธิ์ซื้อยาอันตรายเพื่อนำไปจำหน่าย"}, {"label": "C", "text": "ตรวจว่าผู้ซื้อมีสิทธิ์ตามกฎหมาย เช่น ร้านยาหรือสถานพยาบาล และบันทึกการขาย", "is_correct": true, "explanation": "ถูกต้อง ผู้ขายส่งต้องตรวจสอบสถานะผู้ซื้อและเก็บบันทึกการขายตามหลัก GDP"}, {"label": "D", "text": "ขายได้โดยไม่ต้องบันทึก เพราะการบันทึกเป็นหน้าที่ของผู้ซื้อเท่านั้น", "is_correct": false, "explanation": "ผู้ขายส่งต้องเก็บบันทึกการจำหน่ายของตนเอง เพื่อใช้ตรวจสอบย้อนกลับและเรียกคืนยาได้"}, {"label": "E", "text": "ขายได้หากผู้ซื้อยืนยันเป็นหนังสือว่าจะนำยาไปใช้เองในครอบครัว", "is_correct": false, "explanation": "การขายส่งไม่ใช่การขายแก่บุคคลทั่วไปเพื่อใช้เอง ผู้ซื้อแบบนี้ไม่มีสิทธิ์ซื้อยาแบบขายส่ง"}], "key_takeaway": "ผู้ขายส่งยาต้องขายแก่ผู้ที่มีสิทธิ์ตามกฎหมายเท่านั้น โดยตรวจสอบใบอนุญาตหรือสถานะของผู้ซื้อและเก็บบันทึกการขาย"}'::jsonb, 'medium', 'law-day2 • การขายส่งยาและ GDP'),
('82f75c912a399738b4a50146d304985a', 31, 'ตาม พ.ร.บ.วัตถุอันตราย พ.ศ. 2535 วัตถุอันตรายแบ่งเป็น 4 ประเภทตามความจำเป็นในการควบคุม ข้อใดจับคู่ประเภทกับการควบคุมได้ถูกต้อง', '[{"label": "A", "text": "ประเภทที่ 1 ห้ามผลิต นำเข้า ส่งออก หรือมีไว้ในครอบครองโดยเด็ดขาด"}, {"label": "B", "text": "ประเภทที่ 3 ต้องได้รับใบอนุญาตก่อนผลิต นำเข้า ส่งออก หรือมีไว้ในครอบครอง"}, {"label": "C", "text": "ประเภทที่ 4 เพียงแจ้งให้พนักงานเจ้าหน้าที่ทราบก่อนดำเนินการ"}, {"label": "D", "text": "ประเภทที่ 2 ต้องได้รับใบอนุญาตก่อนดำเนินการทุกกรณี"}, {"label": "E", "text": "ทุกประเภทควบคุมเท่ากัน ต่างกันเพียงหน่วยงานที่รับผิดชอบ"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ประเภทที่ 3 ต้องได้รับใบอนุญาตก่อนผลิต นำเข้า ส่งออก หรือมีไว้ในครอบครอง — วัตถุอันตรายประเภทที่ 3 เป็นประเภทที่ต้องขอใบอนุญาต ส่วนประเภทที่ 4 ห้ามทั้งหมด", "reason": "พ.ร.บ.วัตถุอันตราย พ.ศ. 2535 แบ่งวัตถุอันตรายตามระดับการควบคุมจากน้อยไปมาก ดังนี้\n- ประเภทที่ 1: การผลิต นำเข้า ส่งออก หรือมีไว้ในครอบครอง ต้องปฏิบัติตามหลักเกณฑ์และวิธีการที่กำหนด\n- ประเภทที่ 2: ต้องแจ้งให้พนักงานเจ้าหน้าที่ทราบก่อน และปฏิบัติตามหลักเกณฑ์ที่กำหนด\n- ประเภทที่ 3: ต้องได้รับใบอนุญาต\n- ประเภทที่ 4: ห้ามผลิต นำเข้า ส่งออก หรือมีไว้ในครอบครอง\n\nหลักจำง่ายคือเลขประเภทยิ่งสูงยิ่งควบคุมเข้มงวด จากปฏิบัติตามเกณฑ์ ไปสู่การแจ้ง การขออนุญาต และการห้ามโดยสิ้นเชิง", "choices": [{"label": "A", "text": "ประเภทที่ 1 ห้ามผลิต นำเข้า ส่งออก หรือมีไว้ในครอบครองโดยเด็ดขาด", "is_correct": false, "explanation": "การห้ามโดยเด็ดขาดเป็นการควบคุมของประเภทที่ 4 ประเภทที่ 1 เพียงต้องปฏิบัติตามหลักเกณฑ์ที่กำหนด"}, {"label": "B", "text": "ประเภทที่ 3 ต้องได้รับใบอนุญาตก่อนผลิต นำเข้า ส่งออก หรือมีไว้ในครอบครอง", "is_correct": true, "explanation": "ถูกต้อง ประเภทที่ 3 ต้องได้รับใบอนุญาต"}, {"label": "C", "text": "ประเภทที่ 4 เพียงแจ้งให้พนักงานเจ้าหน้าที่ทราบก่อนดำเนินการ", "is_correct": false, "explanation": "ประเภทที่ 4 ห้ามผลิต นำเข้า ส่งออก หรือมีไว้ในครอบครอง การแจ้งเป็นการควบคุมของประเภทที่ 2"}, {"label": "D", "text": "ประเภทที่ 2 ต้องได้รับใบอนุญาตก่อนดำเนินการทุกกรณี", "is_correct": false, "explanation": "ประเภทที่ 2 ต้องแจ้งให้ทราบก่อน การขอใบอนุญาตเป็นการควบคุมของประเภทที่ 3"}, {"label": "E", "text": "ทุกประเภทควบคุมเท่ากัน ต่างกันเพียงหน่วยงานที่รับผิดชอบ", "is_correct": false, "explanation": "แต่ละประเภทมีระดับการควบคุมต่างกันชัดเจน ตั้งแต่ปฏิบัติตามเกณฑ์จนถึงห้ามโดยสิ้นเชิง"}], "key_takeaway": "วัตถุอันตรายประเภท 1 ปฏิบัติตามเกณฑ์ ประเภท 2 ต้องแจ้ง ประเภท 3 ต้องขออนุญาต และประเภท 4 ห้ามโดยสิ้นเชิง"}'::jsonb, 'easy', 'law-day2 • ประเภทวัตถุอันตราย'),
('aef828bb112348f6fe3aa8a3f23856dc', 32, 'ภายใต้ พ.ร.บ.วัตถุอันตราย พ.ศ. 2535 หน่วยงานที่รับผิดชอบแบ่งตามลักษณะการใช้ของวัตถุอันตราย ผลิตภัณฑ์ใดต่อไปนี้อยู่ในความรับผิดชอบของสำนักงานคณะกรรมการอาหารและยา (อย.)', '[{"label": "A", "text": "สารกำจัดวัชพืชที่เกษตรกรใช้ฉีดพ่นในนาข้าว"}, {"label": "B", "text": "ตัวทำละลายเคมีที่ใช้ในกระบวนการผลิตของโรงงาน"}, {"label": "C", "text": "น้ำยาฆ่าเชื้อที่ใช้พ่นในโรงเรือนเลี้ยงสุกร"}, {"label": "D", "text": "สารเคมีที่ใช้ปรับสภาพน้ำในบ่อเลี้ยงกุ้ง"}, {"label": "E", "text": "สเปรย์กำจัดยุงและแมลงสาบที่ใช้ภายในบ้านเรือน"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. สเปรย์กำจัดยุงและแมลงสาบที่ใช้ภายในบ้านเรือน — อย. รับผิดชอบวัตถุอันตรายที่ใช้ในบ้านเรือนหรือทางสาธารณสุข เช่น ผลิตภัณฑ์กำจัดแมลงที่ใช้ในบ้าน", "reason": "พ.ร.บ.วัตถุอันตราย พ.ศ. 2535 กระจายความรับผิดชอบไปตามหน่วยงานที่เกี่ยวข้องกับการใช้งาน อย. รับผิดชอบวัตถุอันตรายที่ใช้ในบ้านเรือนหรือทางสาธารณสุข เช่น ผลิตภัณฑ์กำจัดแมลงและยุงที่ใช้ในบ้าน ผลิตภัณฑ์ทำความสะอาดพื้นผิวบางชนิด และผลิตภัณฑ์ฆ่าเชื้อที่ใช้กับพื้นผิวในบ้านเรือนหรือทางสาธารณสุข\n\nส่วนวัตถุอันตรายทางการเกษตร (เช่น สารกำจัดวัชพืชในนาข้าว) อยู่ในความรับผิดชอบของกรมวิชาการเกษตร วัตถุอันตรายที่ใช้ในโรงงานอุตสาหกรรมอยู่ในความรับผิดชอบของกรมโรงงานอุตสาหกรรม สารที่ใช้ในการปศุสัตว์อยู่ในความรับผิดชอบของกรมปศุสัตว์ และสารที่ใช้ในการประมงอยู่ในความรับผิดชอบของกรมประมง", "choices": [{"label": "A", "text": "สารกำจัดวัชพืชที่เกษตรกรใช้ฉีดพ่นในนาข้าว", "is_correct": false, "explanation": "เป็นวัตถุอันตรายทางการเกษตร อยู่ในความรับผิดชอบของกรมวิชาการเกษตร"}, {"label": "B", "text": "ตัวทำละลายเคมีที่ใช้ในกระบวนการผลิตของโรงงาน", "is_correct": false, "explanation": "เป็นวัตถุอันตรายที่ใช้ในอุตสาหกรรม อยู่ในความรับผิดชอบของกรมโรงงานอุตสาหกรรม"}, {"label": "C", "text": "น้ำยาฆ่าเชื้อที่ใช้พ่นในโรงเรือนเลี้ยงสุกร", "is_correct": false, "explanation": "เป็นสารที่ใช้ในการปศุสัตว์ อยู่ในความรับผิดชอบของกรมปศุสัตว์"}, {"label": "D", "text": "สารเคมีที่ใช้ปรับสภาพน้ำในบ่อเลี้ยงกุ้ง", "is_correct": false, "explanation": "เป็นสารที่ใช้ในการประมง อยู่ในความรับผิดชอบของกรมประมง"}, {"label": "E", "text": "สเปรย์กำจัดยุงและแมลงสาบที่ใช้ภายในบ้านเรือน", "is_correct": true, "explanation": "ถูกต้อง เป็นวัตถุอันตรายที่ใช้ในบ้านเรือน อยู่ในความรับผิดชอบของ อย."}], "key_takeaway": "วัตถุอันตรายที่ใช้ในบ้านเรือนหรือทางสาธารณสุข เช่น ยาฆ่าแมลงในบ้าน อยู่ในความรับผิดชอบของ อย."}'::jsonb, 'easy', 'law-day2 • วัตถุอันตรายที่ใช้ในบ้านเรือนหรือทางสาธารณสุข'),
('de3e9899faa7dfd766272a4e96ed9450', 33, 'เภสัชกรได้รับเชิญไปให้ความรู้แก่ผู้ประกอบการร้านค้าในชุมชนเรื่อง พ.ร.บ.ควบคุมผลิตภัณฑ์ยาสูบ พ.ศ. 2560 ข้อใดเป็นข้อกำหนดที่ถูกต้องตามกฎหมายนี้', '[{"label": "A", "text": "ห้ามขายผลิตภัณฑ์ยาสูบแก่บุคคลที่อายุต่ำกว่า 20 ปีบริบูรณ์"}, {"label": "B", "text": "ห้ามขายผลิตภัณฑ์ยาสูบแก่บุคคลที่อายุต่ำกว่า 18 ปีบริบูรณ์เท่านั้น"}, {"label": "C", "text": "แบ่งขายบุหรี่ซิกาแรตเป็นรายมวนได้ หากผู้ซื้ออายุ 20 ปีขึ้นไป"}, {"label": "D", "text": "ขายผ่านเครื่องขายอัตโนมัติได้ หากติดตั้งในอาคารที่มีผู้ดูแล"}, {"label": "E", "text": "จัดโปรโมชันลดราคาหรือแจกแถมได้ หากแสดงคำเตือนด้านสุขภาพครบถ้วน"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ห้ามขายผลิตภัณฑ์ยาสูบแก่บุคคลที่อายุต่ำกว่า 20 ปีบริบูรณ์ — พ.ร.บ.ควบคุมผลิตภัณฑ์ยาสูบ พ.ศ. 2560 ปรับอายุขั้นต่ำของผู้ซื้อเป็น 20 ปีบริบูรณ์", "reason": "พ.ร.บ.ควบคุมผลิตภัณฑ์ยาสูบ พ.ศ. 2560 ยกเลิกกฎหมายควบคุมยาสูบฉบับเดิมและเพิ่มความเข้มงวดหลายด้าน ข้อกำหนดสำคัญคือห้ามขายหรือให้ผลิตภัณฑ์ยาสูบแก่บุคคลที่อายุต่ำกว่า 20 ปีบริบูรณ์ (กฎหมายเดิมกำหนด 18 ปี) ผู้ขายจึงควรตรวจสอบอายุของผู้ซื้อเมื่อมีข้อสงสัย\n\nกฎหมายยังห้ามแบ่งขายบุหรี่ซิกาแรตเป็นรายมวนโดยไม่มีซอง ห้ามขายผ่านเครื่องขายอัตโนมัติ และควบคุมการโฆษณาและการส่งเสริมการขายผลิตภัณฑ์ยาสูบ เช่น การลดราคาหรือแจกแถม หลักการเหล่านี้มีเป้าหมายลดการเข้าถึงยาสูบของเยาวชนเป็นสำคัญ", "choices": [{"label": "A", "text": "ห้ามขายผลิตภัณฑ์ยาสูบแก่บุคคลที่อายุต่ำกว่า 20 ปีบริบูรณ์", "is_correct": true, "explanation": "ถูกต้อง พ.ร.บ.ควบคุมผลิตภัณฑ์ยาสูบ พ.ศ. 2560 กำหนดอายุขั้นต่ำของผู้ซื้อเป็น 20 ปีบริบูรณ์"}, {"label": "B", "text": "ห้ามขายผลิตภัณฑ์ยาสูบแก่บุคคลที่อายุต่ำกว่า 18 ปีบริบูรณ์เท่านั้น", "is_correct": false, "explanation": "18 ปีเป็นเกณฑ์ของกฎหมายฉบับเดิม กฎหมายปี 2560 ปรับเป็น 20 ปีบริบูรณ์"}, {"label": "C", "text": "แบ่งขายบุหรี่ซิกาแรตเป็นรายมวนได้ หากผู้ซื้ออายุ 20 ปีขึ้นไป", "is_correct": false, "explanation": "กฎหมายห้ามแบ่งขายบุหรี่ซิกาแรตเป็นรายมวน ไม่ว่าผู้ซื้ออายุเท่าใด"}, {"label": "D", "text": "ขายผ่านเครื่องขายอัตโนมัติได้ หากติดตั้งในอาคารที่มีผู้ดูแล", "is_correct": false, "explanation": "กฎหมายห้ามขายผลิตภัณฑ์ยาสูบผ่านเครื่องขายอัตโนมัติ"}, {"label": "E", "text": "จัดโปรโมชันลดราคาหรือแจกแถมได้ หากแสดงคำเตือนด้านสุขภาพครบถ้วน", "is_correct": false, "explanation": "กฎหมายควบคุมการส่งเสริมการขายผลิตภัณฑ์ยาสูบ การลดราคาหรือแจกแถมเพื่อจูงใจถือเป็นสิ่งต้องห้าม"}], "key_takeaway": "ห้ามขายผลิตภัณฑ์ยาสูบแก่ผู้อายุต่ำกว่า 20 ปีบริบูรณ์ และห้ามแบ่งขายบุหรี่เป็นรายมวน"}'::jsonb, 'easy', 'law-day2 • พ.ร.บ.ควบคุมผลิตภัณฑ์ยาสูบ พ.ศ. 2560'),
('6d7044da82d2a5ed59b8853b49197078', 34, 'เจ้าของร้านยาแห่งหนึ่งซึ่งได้รับอนุญาตขายยาแผนปัจจุบัน ต้องการวางจำหน่ายเบียร์และสุราในร้านเพื่อเพิ่มรายได้ ตาม พ.ร.บ.ควบคุมเครื่องดื่มแอลกอฮอล์ พ.ศ. 2551 ข้อใดถูกต้อง', '[{"label": "A", "text": "ทำได้ หากได้รับใบอนุญาตขายสุราจากกรมสรรพสามิต"}, {"label": "B", "text": "ทำได้ หากขายเฉพาะผู้ซื้อที่อายุ 20 ปีบริบูรณ์ขึ้นไป"}, {"label": "C", "text": "ทำได้ หากขายเฉพาะช่วงเวลาที่เภสัชกรไม่ได้อยู่ปฏิบัติหน้าที่"}, {"label": "D", "text": "ทำไม่ได้ เพราะร้านขายยาเป็นสถานที่ห้ามขายเครื่องดื่มแอลกอฮอล์"}, {"label": "E", "text": "ทำได้ หากแยกตู้แช่เครื่องดื่มไว้ห่างจากชั้นวางยาอย่างชัดเจน"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ทำไม่ได้ เพราะร้านขายยาเป็นสถานที่ห้ามขายเครื่องดื่มแอลกอฮอล์ — พ.ร.บ.ควบคุมเครื่องดื่มแอลกอฮอล์ พ.ศ. 2551 กำหนดให้ร้านขายยาเป็นหนึ่งในสถานที่ห้ามขายเครื่องดื่มแอลกอฮอล์", "reason": "พ.ร.บ.ควบคุมเครื่องดื่มแอลกอฮอล์ พ.ศ. 2551 กำหนดสถานที่ห้ามขายเครื่องดื่มแอลกอฮอล์ไว้ เช่น วัดหรือสถานที่ปฏิบัติพิธีกรรมทางศาสนา สถานบริการสาธารณสุขของรัฐ สถานพยาบาล และร้านขายยาตามกฎหมายว่าด้วยยา สถานที่ราชการ สถานศึกษา สถานีบริการน้ำมัน และสวนสาธารณะของทางราชการ เหตุผลคือสถานที่เหล่านี้เกี่ยวข้องกับสุขภาพ ศาสนา การศึกษา หรือความปลอดภัย\n\nข้อห้ามเรื่องสถานที่นี้ใช้ไม่ว่าผู้ประกอบการจะมีใบอนุญาตขายสุราจากกรมสรรพสามิตหรือไม่ และไม่ว่าจะขายในเวลาใดหรือแก่ผู้ซื้ออายุเท่าใด นอกจากนี้กฎหมายยังห้ามขายแก่บุคคลที่อายุต่ำกว่า 20 ปีบริบูรณ์ และกำหนดช่วงเวลาที่ขายได้ด้วย แต่ข้อกำหนดเหล่านั้นไม่ทำให้ร้านยากลับมาขายได้", "choices": [{"label": "A", "text": "ทำได้ หากได้รับใบอนุญาตขายสุราจากกรมสรรพสามิต", "is_correct": false, "explanation": "ใบอนุญาตขายสุราไม่ได้ยกเว้นข้อห้ามด้านสถานที่ตาม พ.ร.บ.ควบคุมเครื่องดื่มแอลกอฮอล์"}, {"label": "B", "text": "ทำได้ หากขายเฉพาะผู้ซื้อที่อายุ 20 ปีบริบูรณ์ขึ้นไป", "is_correct": false, "explanation": "การจำกัดอายุผู้ซื้อเป็นข้อกำหนดอีกข้อหนึ่ง แต่ไม่ได้ทำให้ร้านยาซึ่งเป็นสถานที่ห้ามขายกลับมาขายได้"}, {"label": "C", "text": "ทำได้ หากขายเฉพาะช่วงเวลาที่เภสัชกรไม่ได้อยู่ปฏิบัติหน้าที่", "is_correct": false, "explanation": "ข้อห้ามผูกกับตัวสถานที่ที่เป็นร้านขายยา ไม่ได้ขึ้นกับว่าเภสัชกรอยู่หรือไม่"}, {"label": "D", "text": "ทำไม่ได้ เพราะร้านขายยาเป็นสถานที่ห้ามขายเครื่องดื่มแอลกอฮอล์", "is_correct": true, "explanation": "ถูกต้อง ร้านขายยาตามกฎหมายว่าด้วยยาเป็นสถานที่ห้ามขายตาม พ.ร.บ.ควบคุมเครื่องดื่มแอลกอฮอล์ พ.ศ. 2551"}, {"label": "E", "text": "ทำได้ หากแยกตู้แช่เครื่องดื่มไว้ห่างจากชั้นวางยาอย่างชัดเจน", "is_correct": false, "explanation": "การแยกตู้ภายในร้านไม่ได้เปลี่ยนสถานะว่าเป็นการขายในร้านขายยา"}], "key_takeaway": "ร้านขายยาตามกฎหมายว่าด้วยยาเป็นสถานที่ห้ามขายเครื่องดื่มแอลกอฮอล์ แม้จะมีใบอนุญาตขายสุราหรือขายเฉพาะผู้ที่อายุครบเกณฑ์"}'::jsonb, 'medium', 'law-day2 • พ.ร.บ.ควบคุมเครื่องดื่มแอลกอฮอล์ พ.ศ. 2551'),
('1cada54305856b8307971739b43e08da', 35, 'ผู้ป่วยรายหนึ่งต้องการเลิกบุหรี่ จึงสอบถามเภสัชกรเกี่ยวกับผลิตภัณฑ์ช่วยเลิกบุหรี่ต่าง ๆ ที่พบในท้องตลาด ข้อใดอธิบายสถานะทางกฎหมายของผลิตภัณฑ์เหล่านี้ในประเทศไทยได้ถูกต้อง', '[{"label": "A", "text": "บุหรี่ไฟฟ้าขายในร้านยาได้ หากเภสัชกรให้คำแนะนำว่าใช้เพื่อเลิกบุหรี่"}, {"label": "B", "text": "หมากฝรั่งนิโคตินเป็นยาต้องขึ้นทะเบียน ส่วนบุหรี่ไฟฟ้าห้ามนำเข้าและห้ามขาย"}, {"label": "C", "text": "หมากฝรั่งนิโคตินเป็นผลิตภัณฑ์เสริมอาหาร จึงวางขายในร้านค้าทั่วไปได้"}, {"label": "D", "text": "แผ่นแปะนิโคตินเป็นผลิตภัณฑ์ยาสูบตาม พ.ร.บ.ควบคุมผลิตภัณฑ์ยาสูบ"}, {"label": "E", "text": "บุหรี่ไฟฟ้าถูกกฎหมายหากนำเข้ามาพร้อมฉลากภาษาไทยและคำเตือนด้านสุขภาพ"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. หมากฝรั่งนิโคตินเป็นยาต้องขึ้นทะเบียน ส่วนบุหรี่ไฟฟ้าห้ามนำเข้าและห้ามขาย — ผลิตภัณฑ์นิโคตินทดแทน (NRT) เป็นยาตาม พ.ร.บ.ยา ส่วนบุหรี่ไฟฟ้าไม่ใช่ผลิตภัณฑ์ช่วยเลิกบุหรี่ที่ได้รับอนุญาต และถูกห้ามนำเข้าและห้ามขายในประเทศไทย", "reason": "ผลิตภัณฑ์นิโคตินทดแทน (nicotine replacement therapy) เช่น หมากฝรั่งนิโคตินและแผ่นแปะนิโคติน รวมถึงยาช่วยเลิกบุหรี่อื่นที่ต้องสั่งใช้โดยแพทย์ ถือเป็นยาตาม พ.ร.บ.ยา ต้องได้รับทะเบียนตำรับยาและจำหน่ายผ่านช่องทางที่กฎหมายยาอนุญาต ไม่ใช่สินค้าทั่วไปหรือผลิตภัณฑ์เสริมอาหาร\n\nบุหรี่ไฟฟ้า (electronic cigarette) ไม่ได้รับการขึ้นทะเบียนเป็นยาช่วยเลิกบุหรี่ในประเทศไทย และมีมาตรการห้ามนำเข้าตามประกาศกระทรวงพาณิชย์ และห้ามขายหรือให้บริการตามคำสั่งคณะกรรมการคุ้มครองผู้บริโภค ดังนั้นการจำหน่ายบุหรี่ไฟฟ้าในร้านยาไม่ว่าจะอ้างวัตถุประสงค์ช่วยเลิกบุหรี่หรือไม่ ก็ไม่ชอบด้วยกฎหมาย เภสัชกรควรแนะนำผลิตภัณฑ์ที่ได้รับอนุญาตและบริการช่วยเลิกบุหรี่ที่มีหลักฐานรองรับ", "choices": [{"label": "A", "text": "บุหรี่ไฟฟ้าขายในร้านยาได้ หากเภสัชกรให้คำแนะนำว่าใช้เพื่อเลิกบุหรี่", "is_correct": false, "explanation": "บุหรี่ไฟฟ้าห้ามนำเข้าและห้ามขายในประเทศไทย การอ้างวัตถุประสงค์ช่วยเลิกบุหรี่ไม่ได้ทำให้ถูกกฎหมาย"}, {"label": "B", "text": "หมากฝรั่งนิโคตินเป็นยาต้องขึ้นทะเบียน ส่วนบุหรี่ไฟฟ้าห้ามนำเข้าและห้ามขาย", "is_correct": true, "explanation": "ถูกต้อง NRT เป็นยาตาม พ.ร.บ.ยา ส่วนบุหรี่ไฟฟ้าถูกห้ามนำเข้าและห้ามขาย"}, {"label": "C", "text": "หมากฝรั่งนิโคตินเป็นผลิตภัณฑ์เสริมอาหาร จึงวางขายในร้านค้าทั่วไปได้", "is_correct": false, "explanation": "หมากฝรั่งนิโคตินมีตัวยาสำคัญเพื่อบำบัดการติดนิโคติน จึงเป็นยา ไม่ใช่ผลิตภัณฑ์เสริมอาหาร"}, {"label": "D", "text": "แผ่นแปะนิโคตินเป็นผลิตภัณฑ์ยาสูบตาม พ.ร.บ.ควบคุมผลิตภัณฑ์ยาสูบ", "is_correct": false, "explanation": "แผ่นแปะนิโคตินที่ใช้รักษาการติดบุหรี่เป็นยาที่ขึ้นทะเบียนตาม พ.ร.บ.ยา ไม่ได้จัดเป็นผลิตภัณฑ์ยาสูบ"}, {"label": "E", "text": "บุหรี่ไฟฟ้าถูกกฎหมายหากนำเข้ามาพร้อมฉลากภาษาไทยและคำเตือนด้านสุขภาพ", "is_correct": false, "explanation": "การมีฉลากภาษาไทยไม่ได้ทำให้การนำเข้าและขายบุหรี่ไฟฟ้าถูกกฎหมาย"}], "key_takeaway": "ผลิตภัณฑ์นิโคตินทดแทนเป็นยาที่ต้องขึ้นทะเบียน ส่วนบุหรี่ไฟฟ้าห้ามนำเข้าและห้ามขายในไทย แม้อ้างว่าช่วยเลิกบุหรี่"}'::jsonb, 'hard', 'law-day2 • สถานะทางกฎหมายของผลิตภัณฑ์ช่วยเลิกบุหรี่'),
('b98a3823236e06f9017b46854a8022c6', 36, 'ระหว่างตรวจนับสต็อกประจำปี ผู้รับอนุญาตขายส่งยาพบยาหมดอายุหลายรายการ รวมถึงยาต้านมะเร็งชนิดรับประทานและยาปฏิชีวนะ ข้อใดเป็นแนวทางที่ถูกต้องตามหลักกฎหมายและมาตรฐานการจัดการยาหมดอายุ', '[{"label": "A", "text": "ลดราคาขายให้คลินิกที่ต้องการใช้ทันที เพราะยาเพิ่งหมดอายุไม่นาน"}, {"label": "B", "text": "บดยาทั้งหมดแล้วเทลงท่อระบายน้ำ เพื่อป้องกันการนำกลับไปใช้"}, {"label": "C", "text": "แยกเก็บติดป้ายห้ามขาย บันทึก แล้วส่งคืนผู้ผลิตหรือผู้รับกำจัดที่ได้รับอนุญาต"}, {"label": "D", "text": "ทิ้งรวมกับขยะทั่วไปของอาคาร เพราะยารับประทานไม่ถือเป็นของเสียอันตราย"}, {"label": "E", "text": "บริจาคให้หน่วยงานการกุศลในต่างประเทศ เพราะยายังมีฤทธิ์อยู่บางส่วน"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. แยกเก็บติดป้ายห้ามขาย บันทึก แล้วส่งคืนผู้ผลิตหรือผู้รับกำจัดที่ได้รับอนุญาต — ยาหมดอายุห้ามจำหน่าย ต้องแยกออกจากยาที่ขายได้ บันทึกเพื่อตรวจสอบได้ และกำจัดอย่างถูกวิธีผ่านช่องทางที่ได้รับอนุญาต", "reason": "ยาที่หมดอายุถือเป็นยาเสื่อมคุณภาพ ซึ่งกฎหมายยาห้ามขาย ผู้รับอนุญาตจึงต้องแยกยาหมดอายุออกจากยาที่จำหน่ายได้ ติดป้ายชัดเจนว่าห้ามจำหน่าย และบันทึกรายการ จำนวน และเลขที่ผลิต เพื่อให้ตรวจสอบได้และป้องกันไม่ให้ยาย้อนกลับเข้าสู่ระบบจำหน่าย\n\nยาหมดอายุเป็นของเสียจากยา (pharmaceutical waste) ซึ่งบางกลุ่มเป็นของเสียอันตราย เช่น ยาต้านมะเร็ง การกำจัดต้องทำผ่านช่องทางที่ถูกต้อง เช่น ส่งคืนผู้ผลิตหรือผู้นำเข้าตามข้อตกลง หรือส่งให้ผู้รับกำจัดของเสียที่ได้รับอนุญาต ซึ่งมักใช้การเผาในเตาที่อุณหภูมิสูง และเก็บหลักฐานการทำลาย การทิ้งรวมกับขยะทั่วไป การเทลงท่อระบายน้ำ หรือการบริจาคยาหมดอายุ ล้วนก่อความเสี่ยงต่อสิ่งแวดล้อม เช่น ปัญหาเชื้อดื้อยาจากยาปฏิชีวนะ และต่อสุขภาพของผู้อื่น", "choices": [{"label": "A", "text": "ลดราคาขายให้คลินิกที่ต้องการใช้ทันที เพราะยาเพิ่งหมดอายุไม่นาน", "is_correct": false, "explanation": "ยาหมดอายุเป็นยาเสื่อมคุณภาพซึ่งห้ามขาย ไม่ว่าจะเพิ่งหมดอายุหรือขายในราคาเท่าใด"}, {"label": "B", "text": "บดยาทั้งหมดแล้วเทลงท่อระบายน้ำ เพื่อป้องกันการนำกลับไปใช้", "is_correct": false, "explanation": "การทิ้งยาลงท่อระบายน้ำทำให้ตัวยาปนเปื้อนสิ่งแวดล้อม โดยเฉพาะยาปฏิชีวนะและยาต้านมะเร็ง"}, {"label": "C", "text": "แยกเก็บติดป้ายห้ามขาย บันทึก แล้วส่งคืนผู้ผลิตหรือผู้รับกำจัดที่ได้รับอนุญาต", "is_correct": true, "explanation": "ถูกต้อง เป็นแนวทางที่ป้องกันการจำหน่ายยาเสื่อมคุณภาพและกำจัดของเสียจากยาอย่างถูกวิธี"}, {"label": "D", "text": "ทิ้งรวมกับขยะทั่วไปของอาคาร เพราะยารับประทานไม่ถือเป็นของเสียอันตราย", "is_correct": false, "explanation": "ยาบางกลุ่ม เช่น ยาต้านมะเร็ง เป็นของเสียอันตราย และการทิ้งรวมกับขยะทั่วไปเสี่ยงต่อการนำกลับไปใช้"}, {"label": "E", "text": "บริจาคให้หน่วยงานการกุศลในต่างประเทศ เพราะยายังมีฤทธิ์อยู่บางส่วน", "is_correct": false, "explanation": "การบริจาคยาหมดอายุขัดหลักจริยธรรมและความปลอดภัย และไม่ได้รับรองว่ายายังมีคุณภาพ"}], "key_takeaway": "ยาหมดอายุต้องแยกเก็บพร้อมป้ายห้ามจำหน่าย บันทึก และกำจัดผ่านช่องทางที่ได้รับอนุญาต ห้ามขาย บริจาค หรือทิ้งรวมกับขยะทั่วไป"}'::jsonb, 'medium', 'law-day2 • การจัดการยาหมดอายุและของเสียจากยา'),
('7bd9c88a44d1d9525306f0c6c714204b', 37, 'พนักงานร้านขายยาแผนปัจจุบัน (ขย.1) ได้ยินมาว่า พ.ร.บ.วัตถุที่ออกฤทธิ์ต่อจิตและประสาท พ.ศ. 2518 ถูกยกเลิกไปแล้ว จึงเสนอเภสัชกรว่าต่อไปร้านสามารถขาย diazepam ให้ลูกค้าที่ขอซื้อได้โดยไม่ต้องมีใบสั่งยาและไม่ต้องลงบัญชี ข้อใดเป็นการให้เหตุผลทางกฎหมายที่ถูกต้อง', '[{"label": "A", "text": "ถูกต้อง เพราะเมื่อกฎหมายเฉพาะถูกยกเลิก ยากลุ่มนี้จึงเหลือการควบคุมเพียงในฐานะยาอันตราย"}, {"label": "B", "text": "ถูกต้องบางส่วน คือร้านขายได้โดยไม่ต้องมีใบสั่งยา แต่ยังต้องลงบัญชีรับ-จ่ายตามแบบเดิมต่อไป"}, {"label": "C", "text": "ไม่ถูกต้อง เพราะกฎหมายเดิมถูกรวมและแทนที่ด้วยประมวลกฎหมายยาเสพติด พ.ศ. 2564 ซึ่งยังควบคุมอยู่"}, {"label": "D", "text": "ไม่ถูกต้อง เพราะ พ.ร.บ. พ.ศ. 2518 ยังมีผลใช้บังคับคู่ขนานกับประมวลกฎหมายยาเสพติดจนถึงปัจจุบัน"}, {"label": "E", "text": "ไม่ถูกต้อง เพราะ diazepam ถูกโอนไปควบคุมเป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา แทนแล้ว"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ยังถูกควบคุมภายใต้ประมวลกฎหมายยาเสพติด พ.ศ. 2564 — การยกเลิกกฎหมายเดิมเกิดจากการรวมกฎหมายเข้าเป็นประมวลฯ ไม่ใช่การยกเลิกการควบคุม", "reason": "พระราชบัญญัติให้ใช้ประมวลกฎหมายยาเสพติด พ.ศ. 2564 ได้ยกเลิกกฎหมายยาเสพติดหลายฉบับ รวมถึง พ.ร.บ.วัตถุที่ออกฤทธิ์ต่อจิตและประสาท พ.ศ. 2518 และ พ.ร.บ.ยาเสพติดให้โทษ พ.ศ. 2522 แล้วนำหลักการควบคุมมารวมไว้ในประมวลกฎหมายยาเสพติดฉบับเดียว ดังนั้นวัตถุออกฤทธิ์ต่อจิตและประสาท เช่น benzodiazepines ยังคงถูกควบคุมอยู่\n\nร้านขายยาจึงยังต้องได้รับอนุญาตเกี่ยวกับวัตถุออกฤทธิ์ จ่ายตามใบสั่งยาโดยเภสัชกร และจัดทำบัญชีและรายงานตามที่กฎหมายกำหนด การอ่านว่า \"กฎหมายถูกยกเลิก = ไม่มีการควบคุม\" เป็นการให้เหตุผลที่ผิด", "choices": [{"label": "A", "text": "ถูกต้อง เพราะเมื่อกฎหมายเฉพาะถูกยกเลิก ยากลุ่มนี้จึงเหลือการควบคุมเพียงในฐานะยาอันตราย", "is_correct": false, "explanation": "ผิด การยกเลิก พ.ร.บ. เดิมไม่ได้ทำให้การควบคุมตามกฎหมายยาเสพติดหมดไป เพราะประมวลฯ ใช้บังคับแทน"}, {"label": "B", "text": "ถูกต้องบางส่วน คือร้านขายได้โดยไม่ต้องมีใบสั่งยา แต่ยังต้องลงบัญชีรับ-จ่ายตามแบบเดิมต่อไป", "is_correct": false, "explanation": "ผิด การจ่ายวัตถุออกฤทธิ์ในร้านยายังต้องเป็นไปตามใบสั่งยา ไม่ใช่ยกเว้นเฉพาะเรื่องใบสั่ง"}, {"label": "C", "text": "ไม่ถูกต้อง เพราะกฎหมายเดิมถูกรวมและแทนที่ด้วยประมวลกฎหมายยาเสพติด พ.ศ. 2564 ซึ่งยังควบคุมอยู่", "is_correct": true, "explanation": "ถูก ประมวลกฎหมายยาเสพติด พ.ศ. 2564 รวมและแทนที่กฎหมายเดิม วัตถุออกฤทธิ์จึงยังถูกควบคุม"}, {"label": "D", "text": "ไม่ถูกต้อง เพราะ พ.ร.บ. พ.ศ. 2518 ยังมีผลใช้บังคับคู่ขนานกับประมวลกฎหมายยาเสพติดจนถึงปัจจุบัน", "is_correct": false, "explanation": "ผิด พ.ร.บ. พ.ศ. 2518 ถูกยกเลิกแล้ว ไม่ได้ใช้บังคับคู่ขนาน"}, {"label": "E", "text": "ไม่ถูกต้อง เพราะ diazepam ถูกโอนไปควบคุมเป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา แทนแล้ว", "is_correct": false, "explanation": "ผิด ไม่มีการโอน diazepam ไปเป็นยาควบคุมพิเศษ ยานี้ยังถูกควบคุมตามประมวลกฎหมายยาเสพติด"}], "key_takeaway": "กฎหมายวัตถุออกฤทธิ์และยาเสพติดให้โทษฉบับเดิมถูกแทนที่ด้วยประมวลกฎหมายยาเสพติด พ.ศ. 2564 การควบคุมจึงยังคงอยู่ครบถ้วน"}'::jsonb, 'easy', 'law-day2 • กฎหมายเดิมถูกยกเลิก: วัตถุออกฤทธิ์ยังถูกควบคุม'),
('a3c5d352e550a7d7d3af7ab7f0d29efe', 38, 'เภสัชกรผู้จัดการคุณภาพของโรงพยาบาลเอกชนทบทวนคู่มือปฏิบัติงาน (SOP) เรื่องการจัดการยาเสพติดและวัตถุออกฤทธิ์ พบว่ายังอ้างอิง พ.ร.บ.ยาเสพติดให้โทษ พ.ศ. 2522 และ พ.ร.บ.วัตถุที่ออกฤทธิ์ต่อจิตและประสาท พ.ศ. 2518 รวมทั้งแบบฟอร์มบัญชีตามประกาศที่ออกภายใต้กฎหมายเดิม ข้อใดเป็นแนวทางที่ถูกต้องที่สุด', '[{"label": "A", "text": "เปลี่ยนไปอ้างอิงประมวลกฎหมายยาเสพติด และตรวจสอบสถานะของประกาศและแบบฟอร์มเดิมแต่ละฉบับ"}, {"label": "B", "text": "คงการอ้างอิงเดิมไว้ทั้งหมด เพราะ พ.ร.บ. ทั้งสองฉบับยังใช้บังคับจนกว่าใบอนุญาตทุกฉบับจะหมดอายุ"}, {"label": "C", "text": "ยกเลิกแบบฟอร์มบัญชีเดิมทันที และหยุดลงบัญชีจนกว่าจะมีประกาศใหม่ภายใต้ประมวลฯ ออกมา"}, {"label": "D", "text": "อ้างอิงประมวลกฎหมายอาญาแทน เพราะความผิดเกี่ยวกับยาเสพติดถูกย้ายไปอยู่ในประมวลกฎหมายอาญาแล้ว"}, {"label": "E", "text": "อ้างอิงเฉพาะ พ.ร.บ.ยา พ.ศ. 2510 เพราะยาเสพติดที่ใช้ทางการแพทย์อยู่ภายใต้ พ.ร.บ.ยา เพียงฉบับเดียว"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. อ้างอิงประมวลกฎหมายยาเสพติดและตรวจสอบอนุบัญญัติที่ยังใช้บังคับ — กฎหมายเดิมถูกยกเลิก แต่บทเฉพาะกาลให้อนุบัญญัติเดิมใช้ต่อได้เท่าที่ไม่ขัดหรือแย้งจนกว่าจะมีฉบับใหม่", "reason": "พระราชบัญญัติให้ใช้ประมวลกฎหมายยาเสพติด พ.ศ. 2564 ยกเลิก พ.ร.บ.ยาเสพติดให้โทษ พ.ศ. 2522 และ พ.ร.บ.วัตถุที่ออกฤทธิ์ต่อจิตและประสาท พ.ศ. 2518 (รวมฉบับแก้ไขเพิ่มเติม) เอกสารอ้างอิงในองค์กรจึงควรปรับเป็นประมวลกฎหมายยาเสพติด\n\nอย่างไรก็ดี บทเฉพาะกาลกำหนดให้กฎกระทรวง ประกาศ ระเบียบ หรือคำสั่งที่ออกตามกฎหมายเดิมยังคงใช้บังคับต่อไปเท่าที่ไม่ขัดหรือแย้งกับประมวลฯ จนกว่าจะมีอนุบัญญัติใหม่ออกมาแทน ดังนั้นการแก้ SOP ที่ถูกต้องคือเปลี่ยนการอ้างอิงตัวบทหลัก และตรวจสอบสถานะของประกาศ/แบบฟอร์มแต่ละฉบับว่ายังใช้อยู่หรือมีฉบับใหม่แทนแล้ว ไม่ใช่หยุดลงบัญชีหรือทิ้งระบบเดิมทันที", "choices": [{"label": "A", "text": "เปลี่ยนไปอ้างอิงประมวลกฎหมายยาเสพติด และตรวจสอบสถานะของประกาศและแบบฟอร์มเดิมแต่ละฉบับ", "is_correct": true, "explanation": "ถูก เป็นการปรับการอ้างอิงตัวบทหลักให้ถูกต้อง และคำนึงถึงบทเฉพาะกาลเรื่องอนุบัญญัติเดิม"}, {"label": "B", "text": "คงการอ้างอิงเดิมไว้ทั้งหมด เพราะ พ.ร.บ. ทั้งสองฉบับยังใช้บังคับจนกว่าใบอนุญาตทุกฉบับจะหมดอายุ", "is_correct": false, "explanation": "ผิด พ.ร.บ. ทั้งสองฉบับถูกยกเลิกแล้ว การอ้างอิงเดิมจึงไม่ถูกต้อง"}, {"label": "C", "text": "ยกเลิกแบบฟอร์มบัญชีเดิมทันที และหยุดลงบัญชีจนกว่าจะมีประกาศใหม่ภายใต้ประมวลฯ ออกมา", "is_correct": false, "explanation": "ผิด การหยุดลงบัญชีเป็นการฝ่าฝืนหน้าที่ อนุบัญญัติเดิมยังใช้ได้เท่าที่ไม่ขัดกับประมวลฯ"}, {"label": "D", "text": "อ้างอิงประมวลกฎหมายอาญาแทน เพราะความผิดเกี่ยวกับยาเสพติดถูกย้ายไปอยู่ในประมวลกฎหมายอาญาแล้ว", "is_correct": false, "explanation": "ผิด ความผิดเกี่ยวกับยาเสพติดอยู่ในประมวลกฎหมายยาเสพติด ไม่ได้ย้ายไปประมวลกฎหมายอาญา"}, {"label": "E", "text": "อ้างอิงเฉพาะ พ.ร.บ.ยา พ.ศ. 2510 เพราะยาเสพติดที่ใช้ทางการแพทย์อยู่ภายใต้ พ.ร.บ.ยา เพียงฉบับเดียว", "is_correct": false, "explanation": "ผิด พ.ร.บ.ยา ใช้ควบคุมยาทั่วไป แต่ยาเสพติดให้โทษและวัตถุออกฤทธิ์ยังต้องปฏิบัติตามประมวลกฎหมายยาเสพติดด้วย"}], "key_takeaway": "เมื่ออ้างอิงกฎหมายยาเสพติด ให้ใช้ประมวลกฎหมายยาเสพติด พ.ศ. 2564 และตรวจสอบสถานะอนุบัญญัติแต่ละฉบับ ไม่ใช่ทิ้งระบบควบคุมเดิมทันที"}'::jsonb, 'hard', 'law-day2 • กฎหมายเดิมถูกยกเลิก: การปรับปรุง SOP และบทเฉพาะกาล'),
('6c3c61a73f1fc30fd059b008c78238f1', 39, 'ระหว่างติวสอบ นักศึกษาเภสัชศาสตร์พบข้อสอบเก่าข้อหนึ่งเฉลยว่า methamphetamine เป็น "วัตถุออกฤทธิ์ต่อจิตและประสาทประเภท 2" ข้อใดถูกต้องตามประมวลกฎหมายยาเสพติด พ.ศ. 2564', '[{"label": "A", "text": "เฉลยถูกต้อง เพราะ methamphetamine ยังมีข้อบ่งใช้ทางการแพทย์ในบางประเทศอยู่"}, {"label": "B", "text": "methamphetamine เป็นยาเสพติดให้โทษประเภท 2 เช่นเดียวกับ morphine"}, {"label": "C", "text": "methamphetamine เป็นวัตถุออกฤทธิ์ประเภท 1 เพราะไม่มีประโยชน์ทางการแพทย์"}, {"label": "D", "text": "methamphetamine เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา เช่นเดียวกับ tramadol"}, {"label": "E", "text": "methamphetamine เป็นยาเสพติดให้โทษประเภท 1 เฉลยในข้อสอบเก่าจึงไม่ถูกต้อง"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. methamphetamine เป็นยาเสพติดให้โทษประเภท 1 — methamphetamine ถูกควบคุมเป็นยาเสพติดให้โทษประเภท 1 ร่วมกับ heroin และ MDMA", "reason": "ประเทศไทยย้ายแอมเฟตามีนและอนุพันธ์ รวมถึง methamphetamine จากการควบคุมในฐานะวัตถุออกฤทธิ์ไปเป็นยาเสพติดให้โทษประเภท 1 ตั้งแต่ปี พ.ศ. 2539 และประมวลกฎหมายยาเสพติด พ.ศ. 2564 ยังคงการจัดประเภทนี้ไว้ ยาเสพติดให้โทษประเภท 1 เป็นกลุ่มที่ห้ามผลิต นำเข้า ส่งออก จำหน่าย หรือมีไว้ในครอบครอง เว้นแต่ได้รับอนุญาตเป็นกรณีพิเศษ เช่น เพื่อการศึกษาวิจัย\n\nข้อสอบเก่าที่เรียก methamphetamine ว่า \"วัตถุออกฤทธิ์ประเภท 2\" จึงผิดและไม่ควรนำมาใช้", "choices": [{"label": "A", "text": "เฉลยถูกต้อง เพราะ methamphetamine ยังมีข้อบ่งใช้ทางการแพทย์ในบางประเทศอยู่", "is_correct": false, "explanation": "ผิด การจัดประเภทในไทยไม่ได้ขึ้นกับการใช้ทางการแพทย์ในต่างประเทศ และ methamphetamine ไม่ใช่วัตถุออกฤทธิ์"}, {"label": "B", "text": "methamphetamine เป็นยาเสพติดให้โทษประเภท 2 เช่นเดียวกับ morphine", "is_correct": false, "explanation": "ผิด ยาเสพติดให้โทษประเภท 2 คือกลุ่มที่ใช้ทางการแพทย์ภายใต้การควบคุม เช่น morphine, pethidine"}, {"label": "C", "text": "methamphetamine เป็นวัตถุออกฤทธิ์ประเภท 1 เพราะไม่มีประโยชน์ทางการแพทย์", "is_correct": false, "explanation": "ผิด methamphetamine ไม่ได้อยู่ในบัญชีวัตถุออกฤทธิ์"}, {"label": "D", "text": "methamphetamine เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา เช่นเดียวกับ tramadol", "is_correct": false, "explanation": "ผิด tramadol เป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา แต่ methamphetamine เป็นยาเสพติดให้โทษ"}, {"label": "E", "text": "methamphetamine เป็นยาเสพติดให้โทษประเภท 1 เฉลยในข้อสอบเก่าจึงไม่ถูกต้อง", "is_correct": true, "explanation": "ถูก methamphetamine เป็นยาเสพติดให้โทษประเภท 1 ตามประมวลกฎหมายยาเสพติด"}], "key_takeaway": "Methamphetamine, heroin และ MDMA เป็นยาเสพติดให้โทษประเภท 1 ไม่ใช่วัตถุออกฤทธิ์"}'::jsonb, 'easy', 'law-day2 • การจัดประเภท: methamphetamine'),
('4d0d7ea3aa99476b9959eba6ea8127e4', 40, 'แพทย์จากคลินิกเวชกรรมใกล้ร้านโทรศัพท์มาที่ร้านขายยาแผนปัจจุบันซึ่งได้รับอนุญาตเกี่ยวกับวัตถุออกฤทธิ์ ขอให้เภสัชกรจ่าย alprazolam ให้ผู้ป่วยรายหนึ่งที่กำลังเดินทางมาที่ร้าน โดยบอกว่าจะส่งใบสั่งยาตัวจริงตามมาในสัปดาห์หน้า เภสัชกรควรปฏิบัติอย่างไร', '[{"label": "A", "text": "จ่ายยาได้ทันที เพราะแพทย์เป็นผู้สั่งด้วยตนเองทางโทรศัพท์ จึงถือเป็นใบสั่งยาที่สมบูรณ์แล้ว"}, {"label": "B", "text": "ไม่จ่ายจนกว่าผู้ป่วยจะนำใบสั่งยาที่ถูกต้องและแพทย์ลงนามแล้วมาแสดง และแจ้งแพทย์ตามนั้น"}, {"label": "C", "text": "จ่ายยาไปก่อน แล้วลงบัญชีเมื่อได้รับใบสั่งยาตัวจริงในสัปดาห์หน้า"}, {"label": "D", "text": "จ่ายยาได้หากผู้ป่วยลงลายมือชื่อรับรองแทนแพทย์ไว้ในสมุดบันทึกของร้าน"}, {"label": "E", "text": "จ่ายยาได้ครึ่งหนึ่งของจำนวนที่แพทย์แจ้ง ที่เหลือจ่ายเมื่อได้รับใบสั่งยา"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ไม่จ่ายจนกว่าจะมีใบสั่งยาที่ถูกต้อง — การจ่ายวัตถุออกฤทธิ์ในร้านยาต้องอาศัยใบสั่งยาที่เป็นลายลักษณ์อักษรจากผู้มีสิทธิ์สั่ง ไม่ใช่การสั่งด้วยวาจา", "reason": "ร้านขายยาที่ได้รับอนุญาตจะจ่ายวัตถุออกฤทธิ์ได้เฉพาะตามใบสั่งยาของผู้ประกอบวิชาชีพที่กฎหมายกำหนด ใบสั่งยาเป็นเอกสารที่ร้านต้องเก็บไว้เป็นหลักฐานประกอบบัญชีรับ-จ่าย การสั่งทางโทรศัพท์ไม่มีเอกสารยืนยันตัวผู้สั่ง จึงไม่สามารถใช้แทนใบสั่งยาได้\n\nแนวทางที่เหมาะสมคือแจ้งแพทย์ด้วยความสุภาพว่าร้านต้องได้รับใบสั่งยาที่ถูกต้องก่อน และให้ผู้ป่วยรับใบสั่งยาจากคลินิกหรือรับยาจากคลินิกโดยตรง", "choices": [{"label": "A", "text": "จ่ายยาได้ทันที เพราะแพทย์เป็นผู้สั่งด้วยตนเองทางโทรศัพท์ จึงถือเป็นใบสั่งยาที่สมบูรณ์แล้ว", "is_correct": false, "explanation": "ผิด คำสั่งทางโทรศัพท์ไม่ใช่ใบสั่งยาที่ร้านเก็บเป็นหลักฐานได้ และยืนยันตัวผู้สั่งไม่ได้"}, {"label": "B", "text": "ไม่จ่ายจนกว่าผู้ป่วยจะนำใบสั่งยาที่ถูกต้องและแพทย์ลงนามแล้วมาแสดง และแจ้งแพทย์ตามนั้น", "is_correct": true, "explanation": "ถูก ร้านยาจ่ายวัตถุออกฤทธิ์ได้เมื่อมีใบสั่งยาที่ถูกต้องและสมบูรณ์เท่านั้น"}, {"label": "C", "text": "จ่ายยาไปก่อน แล้วลงบัญชีเมื่อได้รับใบสั่งยาตัวจริงในสัปดาห์หน้า", "is_correct": false, "explanation": "ผิด การจ่ายก่อนมีใบสั่งยาเป็นการจ่ายโดยไม่มีหลักฐานตามกฎหมาย และบัญชีจะไม่ตรงกับข้อเท็จจริง"}, {"label": "D", "text": "จ่ายยาได้หากผู้ป่วยลงลายมือชื่อรับรองแทนแพทย์ไว้ในสมุดบันทึกของร้าน", "is_correct": false, "explanation": "ผิด ผู้ป่วยไม่มีอำนาจรับรองแทนผู้สั่งใช้ยา"}, {"label": "E", "text": "จ่ายยาได้ครึ่งหนึ่งของจำนวนที่แพทย์แจ้ง ที่เหลือจ่ายเมื่อได้รับใบสั่งยา", "is_correct": false, "explanation": "ผิด การลดจำนวนไม่ได้ทำให้การจ่ายโดยไม่มีใบสั่งยาถูกกฎหมาย"}], "key_takeaway": "ร้านยาจ่ายวัตถุออกฤทธิ์ได้เมื่อมีใบสั่งยาที่ถูกต้องอยู่ในมือเท่านั้น การสั่งทางโทรศัพท์ใช้แทนไม่ได้"}'::jsonb, 'medium', 'law-day2 • การสั่งยาทางโทรศัพท์'),
('7c4ac27ba799d3fc9194aea17b0cd26b', 41, 'ผู้ป่วยรายหนึ่งเคยรับ clonazepam ตามใบสั่งยาที่ร้านนี้เมื่อ 10 วันก่อน (ร้านจ่ายครบตามใบสั่งและเก็บใบสั่งยาไว้แล้ว) วันนี้กลับมาแจ้งว่ายาหายระหว่างเดินทาง และขอรับยาเพิ่มโดยแสดงภาพถ่ายใบสั่งยาเดิมในโทรศัพท์ เภสัชกรควรปฏิบัติอย่างไร', '[{"label": "A", "text": "จ่ายยาได้ เพราะภาพถ่ายยืนยันว่าแพทย์เคยสั่งยานี้ให้ผู้ป่วยจริง"}, {"label": "B", "text": "จ่ายยาได้ หากผู้ป่วยนำใบแจ้งความเรื่องยาหายจากสถานีตำรวจมาแสดงประกอบด้วย"}, {"label": "C", "text": "จ่ายยาให้เฉพาะจำนวนที่พอใช้ถึงวันนัดพบแพทย์ครั้งถัดไป"}, {"label": "D", "text": "ไม่จ่าย เพราะใบสั่งเดิมใช้ไปแล้ว ให้ติดต่อแพทย์เพื่อรับใบสั่งยาใหม่"}, {"label": "E", "text": "จ่ายยาได้ หากผู้ป่วยยินยอมให้ร้านเก็บสำเนาบัตรประชาชนไว้เป็นหลักฐาน"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ไม่จ่าย ให้รับใบสั่งยาใหม่จากแพทย์ — ใบสั่งยาที่จ่ายครบแล้วไม่สามารถนำกลับมาใช้ซ้ำได้ และภาพถ่ายไม่ใช่ใบสั่งยาใหม่", "reason": "เมื่อร้านจ่ายยาครบตามใบสั่งแล้ว ใบสั่งยานั้นถือว่าใช้ไปแล้ว การจ่ายวัตถุออกฤทธิ์ซ้ำโดยอาศัยภาพถ่ายหรือสำเนาของใบสั่งเดิมจึงเท่ากับจ่ายโดยไม่มีใบสั่งยา นอกจากนี้กรณีขอรับยาก่อนกำหนดด้วยเหตุยาหายเป็นสัญญาณที่ต้องระวังการใช้ในทางที่ผิดหรือการนำยาไปให้ผู้อื่น\n\nแนวทางที่ถูกต้องคืออธิบายเหตุผล แนะนำให้ผู้ป่วยติดต่อแพทย์ผู้สั่งเพื่อประเมินและออกใบสั่งยาใหม่ (แพทย์จะได้ทราบเรื่องยาหายด้วย) และบันทึกเหตุการณ์ไว้ตามระบบของร้าน", "choices": [{"label": "A", "text": "จ่ายยาได้ เพราะภาพถ่ายยืนยันว่าแพทย์เคยสั่งยานี้ให้ผู้ป่วยจริง", "is_correct": false, "explanation": "ผิด ภาพถ่ายของใบสั่งที่ใช้ไปแล้วไม่ใช่ใบสั่งยาใหม่"}, {"label": "B", "text": "จ่ายยาได้ หากผู้ป่วยนำใบแจ้งความเรื่องยาหายจากสถานีตำรวจมาแสดงประกอบด้วย", "is_correct": false, "explanation": "ผิด ใบแจ้งความไม่ใช่ใบสั่งยา จึงไม่ทำให้ร้านมีอำนาจจ่ายยาซ้ำ"}, {"label": "C", "text": "จ่ายยาให้เฉพาะจำนวนที่พอใช้ถึงวันนัดพบแพทย์ครั้งถัดไป", "is_correct": false, "explanation": "ผิด การลดจำนวนยาไม่ได้แก้ปัญหาการจ่ายโดยไม่มีใบสั่งยา"}, {"label": "D", "text": "ไม่จ่าย เพราะใบสั่งเดิมใช้ไปแล้ว ให้ติดต่อแพทย์เพื่อรับใบสั่งยาใหม่", "is_correct": true, "explanation": "ถูก ใบสั่งยาเดิมใช้ไปแล้ว ต้องให้แพทย์ประเมินและออกใบสั่งยาใหม่"}, {"label": "E", "text": "จ่ายยาได้ หากผู้ป่วยยินยอมให้ร้านเก็บสำเนาบัตรประชาชนไว้เป็นหลักฐาน", "is_correct": false, "explanation": "ผิด การเก็บสำเนาบัตรประชาชนไม่ได้แทนใบสั่งยา"}], "key_takeaway": "ใบสั่งยาที่จ่ายครบแล้วใช้ซ้ำไม่ได้ กรณียาหายต้องให้แพทย์ประเมินและออกใบสั่งใหม่"}'::jsonb, 'medium', 'law-day2 • การขอรับยาก่อนกำหนด/ยาหาย'),
('d39c52dd989e7d55152d6ae54e5ae349', 42, 'ผู้ป่วยนำใบสั่งยา diazepam จากคลินิกเวชกรรมในจังหวัดอื่นมาที่ร้านขายยาแผนปัจจุบันซึ่งได้รับอนุญาตเกี่ยวกับวัตถุออกฤทธิ์ ใบสั่งยามีข้อมูลครบถ้วนและแพทย์ลงนาม เภสัชกรไม่รู้จักคลินิกนี้มาก่อน ข้อใดถูกต้อง', '[{"label": "A", "text": "รับใบสั่งยาได้ หากตรวจสอบแล้วเป็นใบสั่งที่ถูกต้องจริง โดยจ่ายและลงบัญชีตามปกติ"}, {"label": "B", "text": "รับไม่ได้ เพราะร้านรับได้เฉพาะใบสั่งยาจากแพทย์ที่ปฏิบัติงานในจังหวัดเดียวกับที่ตั้งร้าน"}, {"label": "C", "text": "รับไม่ได้ เพราะวัตถุออกฤทธิ์ต้องรับจากสถานพยาบาลที่ออกใบสั่งยาเท่านั้น"}, {"label": "D", "text": "รับได้โดยไม่ต้องตรวจสอบใด ๆ เพราะความรับผิดชอบทั้งหมดอยู่ที่แพทย์ผู้สั่ง"}, {"label": "E", "text": "รับได้ แต่ต้องส่งใบสั่งยาตัวจริงคืนผู้ป่วยเพื่อใช้ที่ร้านอื่นในครั้งต่อไป"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. รับได้เมื่อตรวจสอบว่าใบสั่งยาถูกต้อง — กฎหมายไม่ได้จำกัดพื้นที่ของผู้สั่งใช้ยา แต่เภสัชกรต้องตรวจสอบความถูกต้องของใบสั่งยา", "reason": "ใบสั่งยาที่ออกโดยผู้ประกอบวิชาชีพที่มีสิทธิ์สั่งใช้ยา และมีข้อมูลครบถ้วน สามารถนำมารับยาที่ร้านขายยาที่ได้รับอนุญาตได้ ไม่ว่าคลินิกจะตั้งอยู่ที่ใด\n\nอย่างไรก็ตาม เภสัชกรยังมีหน้าที่ตรวจสอบความถูกต้องของใบสั่งยา เช่น ข้อมูลผู้ป่วย ชื่อและเลขที่ใบอนุญาตของผู้สั่ง ขนาดยาและจำนวน และหากสงสัยควรติดต่อคลินิกเพื่อยืนยัน เมื่อจ่ายแล้วต้องเก็บใบสั่งยาไว้เป็นหลักฐานและลงบัญชีรับ-จ่ายตามที่กำหนด", "choices": [{"label": "A", "text": "รับใบสั่งยาได้ หากตรวจสอบแล้วเป็นใบสั่งที่ถูกต้องจริง โดยจ่ายและลงบัญชีตามปกติ", "is_correct": true, "explanation": "ถูก ใบสั่งยาที่ถูกต้องใช้ได้โดยไม่จำกัดพื้นที่ แต่เภสัชกรต้องตรวจสอบก่อนจ่าย"}, {"label": "B", "text": "รับไม่ได้ เพราะร้านรับได้เฉพาะใบสั่งยาจากแพทย์ที่ปฏิบัติงานในจังหวัดเดียวกับที่ตั้งร้าน", "is_correct": false, "explanation": "ผิด ไม่มีข้อกำหนดให้รับใบสั่งยาได้เฉพาะจากจังหวัดเดียวกัน"}, {"label": "C", "text": "รับไม่ได้ เพราะวัตถุออกฤทธิ์ต้องรับจากสถานพยาบาลที่ออกใบสั่งยาเท่านั้น", "is_correct": false, "explanation": "ผิด ผู้ป่วยสามารถนำใบสั่งยาไปรับยาที่ร้านขายยาที่ได้รับอนุญาตได้"}, {"label": "D", "text": "รับได้โดยไม่ต้องตรวจสอบใด ๆ เพราะความรับผิดชอบทั้งหมดอยู่ที่แพทย์ผู้สั่ง", "is_correct": false, "explanation": "ผิด เภสัชกรมีหน้าที่ตรวจสอบความถูกต้องของใบสั่งยาก่อนจ่ายเสมอ"}, {"label": "E", "text": "รับได้ แต่ต้องส่งใบสั่งยาตัวจริงคืนผู้ป่วยเพื่อใช้ที่ร้านอื่นในครั้งต่อไป", "is_correct": false, "explanation": "ผิด ร้านต้องเก็บใบสั่งยาที่จ่ายแล้วไว้เป็นหลักฐานประกอบบัญชี ไม่คืนให้นำไปใช้ซ้ำ"}], "key_takeaway": "ใบสั่งยาที่ถูกต้องจากผู้มีสิทธิ์สั่งใช้ได้ทุกพื้นที่ แต่เภสัชกรต้องตรวจสอบและเก็บไว้เป็นหลักฐาน"}'::jsonb, 'easy', 'law-day2 • ใบสั่งยาจากคลินิกต่างจังหวัด'),
('9836109938d6ad7e12a5b777008c1dc1', 43, 'ร้านขายยาแผนปัจจุบันซึ่งได้รับอนุญาตเกี่ยวกับวัตถุออกฤทธิ์ได้รับใบสั่งยา diazepam จากผู้สั่ง 5 ราย ใบสั่งยาจากผู้สั่งในข้อใดที่เภสัชกรสามารถรับและจ่ายยาได้', '[{"label": "A", "text": "พยาบาลวิชาชีพที่ปฏิบัติงานในหน่วยบริการปฐมภูมิ"}, {"label": "B", "text": "นักกายภาพบำบัดที่ให้บริการในคลินิกกายภาพบำบัด"}, {"label": "C", "text": "ทันตแพทย์ที่สั่งใช้ก่อนทำหัตถการทางทันตกรรม"}, {"label": "D", "text": "เภสัชกรจากร้านขายยาอีกแห่งหนึ่งที่เขียนใบส่งต่อ"}, {"label": "E", "text": "ผู้ช่วยแพทย์ในคลินิกที่ลงนามแทนแพทย์เจ้าของไข้"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ทันตแพทย์ — ใบสั่งยาวัตถุออกฤทธิ์ต้องออกโดยผู้ประกอบวิชาชีพเวชกรรม ทันตกรรม หรือการสัตวแพทย์", "reason": "ตามประมวลกฎหมายยาเสพติด การจ่ายวัตถุออกฤทธิ์ในร้านขายยาต้องเป็นไปตามใบสั่งยาของผู้ประกอบวิชาชีพเวชกรรม ผู้ประกอบวิชาชีพทันตกรรม หรือผู้ประกอบวิชาชีพการสัตวแพทย์ (สำหรับสัตว์) ทันตแพทย์ที่สั่งใช้ยาเพื่อการรักษาทางทันตกรรมจึงเป็นผู้มีสิทธิ์ออกใบสั่งยา\n\nพยาบาล นักกายภาพบำบัด และเภสัชกรเป็นผู้ประกอบวิชาชีพด้านสุขภาพ แต่ไม่มีสิทธิ์สั่งใช้วัตถุออกฤทธิ์ ส่วนการลงนามแทนแพทย์โดยบุคคลอื่นทำให้ใบสั่งยาไม่ถูกต้อง", "choices": [{"label": "A", "text": "พยาบาลวิชาชีพที่ปฏิบัติงานในหน่วยบริการปฐมภูมิ", "is_correct": false, "explanation": "ผิด พยาบาลไม่มีสิทธิ์สั่งใช้วัตถุออกฤทธิ์"}, {"label": "B", "text": "นักกายภาพบำบัดที่ให้บริการในคลินิกกายภาพบำบัด", "is_correct": false, "explanation": "ผิด นักกายภาพบำบัดไม่ใช่ผู้มีสิทธิ์สั่งใช้ยา"}, {"label": "C", "text": "ทันตแพทย์ที่สั่งใช้ก่อนทำหัตถการทางทันตกรรม", "is_correct": true, "explanation": "ถูก ผู้ประกอบวิชาชีพทันตกรรมเป็นผู้มีสิทธิ์ออกใบสั่งยาวัตถุออกฤทธิ์"}, {"label": "D", "text": "เภสัชกรจากร้านขายยาอีกแห่งหนึ่งที่เขียนใบส่งต่อ", "is_correct": false, "explanation": "ผิด เภสัชกรเป็นผู้จ่ายยา ไม่ใช่ผู้สั่งใช้วัตถุออกฤทธิ์"}, {"label": "E", "text": "ผู้ช่วยแพทย์ในคลินิกที่ลงนามแทนแพทย์เจ้าของไข้", "is_correct": false, "explanation": "ผิด ใบสั่งยาต้องลงนามโดยผู้สั่งใช้เอง ผู้อื่นลงนามแทนไม่ได้"}], "key_takeaway": "ผู้ออกใบสั่งยาวัตถุออกฤทธิ์ได้คือแพทย์ ทันตแพทย์ และสัตวแพทย์ (สำหรับสัตว์)"}'::jsonb, 'medium', 'law-day2 • ผู้มีสิทธิ์ออกใบสั่งยาวัตถุออกฤทธิ์'),
('0131913b8ed10ba09b2a678e3d4f6733', 44, 'ชายวัยรุ่นเข้ามาที่ร้านขายยาขอซื้อ alprazolam 20 เม็ดโดยไม่มีใบสั่งยา บอกว่าเพื่อนเคยซื้อที่ร้านนี้ได้ และยินดีจ่ายเงินเพิ่ม เภสัชกรควรปฏิบัติอย่างไร', '[{"label": "A", "text": "ขายให้ได้ในจำนวนน้อย เพื่อไม่ให้ลูกค้าหันไปหาซื้อจากแหล่งที่ผิดกฎหมายแทน"}, {"label": "B", "text": "ขายให้ได้ หากลูกค้ามีอายุครบ 20 ปีบริบูรณ์และแสดงบัตรประชาชน"}, {"label": "C", "text": "ขายให้ได้ หากลูกค้าเขียนหนังสือรับรองว่าจะใช้เอง"}, {"label": "D", "text": "ปฏิเสธ แล้วแจ้งตำรวจให้มาจับกุมลูกค้าที่ร้านทันที"}, {"label": "E", "text": "ปฏิเสธเพราะไม่มีใบสั่งยา ให้คำแนะนำ และเสนอการส่งต่อหากมีปัญหาการใช้ยา"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ปฏิเสธ ให้คำแนะนำ และเสนอการส่งต่อ — ร้านยาจ่ายวัตถุออกฤทธิ์ได้ตามใบสั่งยาเท่านั้น และควรมองผู้ที่อาจมีปัญหาการใช้ยาเป็นผู้ที่ควรได้รับการดูแล", "reason": "การขายวัตถุออกฤทธิ์โดยไม่มีใบสั่งยาเป็นความผิดตามประมวลกฎหมายยาเสพติด ไม่ว่าจะขายในจำนวนเท่าใดหรือลูกค้าอายุเท่าใด เภสัชกรจึงต้องปฏิเสธ\n\nในขณะเดียวกัน ประมวลกฎหมายยาเสพติดเน้นการมองผู้ใช้ยาเป็นผู้ป่วย เภสัชกรจึงควรอธิบายเหตุผล ซักถามด้วยท่าทีไม่ตัดสิน ให้ข้อมูลความเสี่ยง และเสนอการส่งต่อพบแพทย์หรือสถานบำบัดหากมีปัญหานอนไม่หลับ วิตกกังวล หรือการใช้ยาไม่เหมาะสม การปฏิเสธการขายไม่จำเป็นต้องตามด้วยการแจ้งจับกุม", "choices": [{"label": "A", "text": "ขายให้ได้ในจำนวนน้อย เพื่อไม่ให้ลูกค้าหันไปหาซื้อจากแหล่งที่ผิดกฎหมายแทน", "is_correct": false, "explanation": "ผิด การขายโดยไม่มีใบสั่งยาเป็นความผิดไม่ว่าจำนวนเท่าใด"}, {"label": "B", "text": "ขายให้ได้ หากลูกค้ามีอายุครบ 20 ปีบริบูรณ์และแสดงบัตรประชาชน", "is_correct": false, "explanation": "ผิด อายุของผู้ซื้อไม่ได้ทดแทนใบสั่งยา"}, {"label": "C", "text": "ขายให้ได้ หากลูกค้าเขียนหนังสือรับรองว่าจะใช้เอง", "is_correct": false, "explanation": "ผิด หนังสือรับรองของผู้ซื้อไม่ใช่ใบสั่งยา"}, {"label": "D", "text": "ปฏิเสธ แล้วแจ้งตำรวจให้มาจับกุมลูกค้าที่ร้านทันที", "is_correct": false, "explanation": "ผิด การขอซื้อโดยไม่มีใบสั่งยายังไม่ใช่เหตุให้ต้องแจ้งจับกุม และขัดกับแนวทางการมองผู้ใช้ยาเป็นผู้ป่วย"}, {"label": "E", "text": "ปฏิเสธเพราะไม่มีใบสั่งยา ให้คำแนะนำ และเสนอการส่งต่อหากมีปัญหาการใช้ยา", "is_correct": true, "explanation": "ถูก ปฏิเสธการขายตามกฎหมาย และดูแลด้วยการให้คำแนะนำและส่งต่อ"}], "key_takeaway": "ห้ามขายวัตถุออกฤทธิ์โดยไม่มีใบสั่งยา แต่ควรดูแลผู้ขอซื้อด้วยการให้คำแนะนำและส่งต่อแทนการลงโทษ"}'::jsonb, 'easy', 'law-day2 • ลูกค้าขอซื้อวัตถุออกฤทธิ์อย่างน่าสงสัย'),
('0f57943d0bf70e3c86cb914ad3322f00', 45, 'เภสัชกรร้านยาได้รับใบสั่งยา clonazepam จำนวนมากผิดปกติ บนหัวกระดาษของคลินิกแห่งหนึ่ง เมื่อโทรศัพท์สอบถาม คลินิกยืนยันว่าไม่ได้ออกใบสั่งยานี้ และเลขที่ใบอนุญาตบนใบสั่งเป็นของแพทย์ที่ไม่ได้ปฏิบัติงานที่คลินิก ข้อใดเป็นการปฏิบัติที่เหมาะสมที่สุด', '[{"label": "A", "text": "จ่ายยาเพียงบางส่วน เพราะยังพิสูจน์ไม่ได้ว่าผู้ป่วยเป็นผู้ปลอมใบสั่งยาเอง"}, {"label": "B", "text": "ไม่จ่ายยา บันทึกรายละเอียดหรือสำเนาเป็นหลักฐาน และแจ้งคลินิกกับพนักงานเจ้าหน้าที่"}, {"label": "C", "text": "ไม่จ่ายยา และควบคุมตัวผู้ถือใบสั่งยาไว้ในร้านจนกว่าเจ้าของคลินิกจะเดินทางมาถึง"}, {"label": "D", "text": "ไม่จ่ายยา และโพสต์ภาพผู้ถือใบสั่งยาในสื่อสังคมออนไลน์เพื่อเตือนร้านอื่น"}, {"label": "E", "text": "จ่ายยาตามใบสั่ง เพราะใบสั่งมีตราคลินิกและลายมือชื่อครบถ้วน ร้านจึงไม่ต้องรับผิดใด ๆ"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ไม่จ่าย เก็บหลักฐาน และแจ้งคลินิกกับเจ้าหน้าที่ — ใบสั่งยาปลอมไม่ใช่ใบสั่งยาที่ถูกต้อง เภสัชกรต้องไม่จ่ายและควรส่งเรื่องให้ผู้มีอำนาจดำเนินการ", "reason": "เมื่อผู้ที่ถูกอ้างว่าเป็นผู้ออกใบสั่งยายืนยันว่าไม่ได้ออก ใบสั่งยานี้จึงไม่ใช่ใบสั่งยาที่ชอบด้วยกฎหมาย การจ่ายวัตถุออกฤทธิ์ตามใบสั่งดังกล่าวเท่ากับจ่ายโดยไม่มีใบสั่งยา และการที่เภสัชกรทราบความจริงแล้วยังจ่ายย่อมไม่อาจอ้างความสุจริตได้\n\nแนวทางที่เหมาะสมคือไม่จ่ายยา บันทึกข้อมูลหรือเก็บสำเนาไว้เป็นหลักฐาน แจ้งคลินิกที่ถูกแอบอ้าง และแจ้งพนักงานเจ้าหน้าที่ (เช่น สำนักงานสาธารณสุขจังหวัด) หรือตำรวจตามแนวทางของร้าน โดยหลีกเลี่ยงการเผชิญหน้า การควบคุมตัวบุคคลเองหรือเผยแพร่ภาพในสื่อออนไลน์อาจละเมิดสิทธิและก่อความรับผิดแก่ร้านเอง", "choices": [{"label": "A", "text": "จ่ายยาเพียงบางส่วน เพราะยังพิสูจน์ไม่ได้ว่าผู้ป่วยเป็นผู้ปลอมใบสั่งยาเอง", "is_correct": false, "explanation": "ผิด การจ่ายบางส่วนตามใบสั่งยาปลอมยังเป็นการจ่ายโดยไม่มีใบสั่งยาที่ถูกต้อง"}, {"label": "B", "text": "ไม่จ่ายยา บันทึกรายละเอียดหรือสำเนาเป็นหลักฐาน และแจ้งคลินิกกับพนักงานเจ้าหน้าที่", "is_correct": true, "explanation": "ถูก ไม่จ่ายยา เก็บหลักฐาน และส่งเรื่องให้ผู้มีอำนาจดำเนินการ"}, {"label": "C", "text": "ไม่จ่ายยา และควบคุมตัวผู้ถือใบสั่งยาไว้ในร้านจนกว่าเจ้าของคลินิกจะเดินทางมาถึง", "is_correct": false, "explanation": "ผิด การควบคุมตัวบุคคลโดยพลการอาจเป็นการละเมิดเสรีภาพและไม่ปลอดภัย"}, {"label": "D", "text": "ไม่จ่ายยา และโพสต์ภาพผู้ถือใบสั่งยาในสื่อสังคมออนไลน์เพื่อเตือนร้านอื่น", "is_correct": false, "explanation": "ผิด การเผยแพร่ภาพบุคคลอาจละเมิดสิทธิส่วนบุคคลและเป็นการหมิ่นประมาท"}, {"label": "E", "text": "จ่ายยาตามใบสั่ง เพราะใบสั่งมีตราคลินิกและลายมือชื่อครบถ้วน ร้านจึงไม่ต้องรับผิดใด ๆ", "is_correct": false, "explanation": "ผิด เมื่อคลินิกยืนยันว่าไม่ได้ออกใบสั่ง เภสัชกรย่อมทราบว่าใบสั่งไม่ถูกต้อง"}], "key_takeaway": "เมื่อพบใบสั่งยาปลอม ให้ปฏิเสธการจ่าย เก็บหลักฐาน และแจ้งผู้มีอำนาจ โดยไม่ใช้วิธีการนอกกฎหมาย"}'::jsonb, 'hard', 'law-day2 • ใบสั่งยาปลอม'),
('e8e4a5142a752b1ce98254208ef0fbda', 46, 'พนักงานเจ้าหน้าที่เข้าตรวจร้านขายยาแผนปัจจุบันที่ได้รับอนุญาตเกี่ยวกับวัตถุออกฤทธิ์ การปฏิบัติของร้านในข้อใดถูกต้องตามหลักการของประมวลกฎหมายยาเสพติด', '[{"label": "A", "text": "ลงบัญชีเฉพาะยอดที่ซื้อเข้า ส่วนการจ่ายดูได้จากใบเสร็จรับเงินของระบบขายหน้าร้าน"}, {"label": "B", "text": "ลงบัญชีเป็นยอดรวมสิ้นเดือน โดยไม่ระบุข้อมูลผู้ป่วยและผู้สั่งใช้ยาในแต่ละครั้ง"}, {"label": "C", "text": "เก็บใบสั่งยาไว้เพียงจนถึงสิ้นเดือน แล้วทำลายเพื่อรักษาความลับของผู้ป่วย"}, {"label": "D", "text": "ทำบัญชีรับ-จ่ายแยกรายการ เก็บใบสั่งยาเป็นหลักฐาน และส่งรายงานตามที่กำหนด"}, {"label": "E", "text": "ให้พนักงานขายทั่วไปจัดทำบัญชีแทนเภสัชกร โดยไม่ต้องตรวจทานยอดคงเหลือ"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ทำบัญชีแยกรายการ เก็บใบสั่งยา และส่งรายงาน — ผู้รับอนุญาตต้องทำบัญชีรับ-จ่ายที่ตรวจสอบย้อนกลับได้ เก็บหลักฐาน และรายงานตามที่กฎหมายกำหนด", "reason": "ผู้รับอนุญาตเกี่ยวกับวัตถุออกฤทธิ์มีหน้าที่จัดทำบัญชีรับ-จ่ายแยกตามรายการ แสดงทั้งการรับเข้าและการจ่ายออก พร้อมข้อมูลที่ตรวจสอบย้อนกลับได้ เช่น วันที่ ผู้ป่วย ผู้สั่งใช้ยา จำนวน และยอดคงเหลือ เก็บใบสั่งยาไว้เป็นหลักฐาน และจัดทำรายงานส่งพนักงานเจ้าหน้าที่ตามรอบที่กำหนด เภสัชกรผู้มีหน้าที่ปฏิบัติการต้องควบคุมให้บัญชีถูกต้องตรงกับยาคงเหลือจริง\n\nเอกสารต้องเก็บไว้ตามระยะเวลาที่กฎหมายกำหนด การรักษาความลับของผู้ป่วยทำได้โดยจัดเก็บอย่างปลอดภัย ไม่ใช่การทำลายหลักฐานก่อนกำหนด", "choices": [{"label": "A", "text": "ลงบัญชีเฉพาะยอดที่ซื้อเข้า ส่วนการจ่ายดูได้จากใบเสร็จรับเงินของระบบขายหน้าร้าน", "is_correct": false, "explanation": "ผิด บัญชีต้องแสดงทั้งการรับและการจ่าย ใบเสร็จรับเงินไม่ใช่บัญชีตามกฎหมาย"}, {"label": "B", "text": "ลงบัญชีเป็นยอดรวมสิ้นเดือน โดยไม่ระบุข้อมูลผู้ป่วยและผู้สั่งใช้ยาในแต่ละครั้ง", "is_correct": false, "explanation": "ผิด ยอดรวมรายเดือนตรวจสอบย้อนกลับไม่ได้ว่าจ่ายให้ใครตามใบสั่งของผู้ใด"}, {"label": "C", "text": "เก็บใบสั่งยาไว้เพียงจนถึงสิ้นเดือน แล้วทำลายเพื่อรักษาความลับของผู้ป่วย", "is_correct": false, "explanation": "ผิด ใบสั่งยาเป็นหลักฐานที่ต้องเก็บตามระยะเวลาที่กำหนด การรักษาความลับทำได้ด้วยการเก็บอย่างปลอดภัย"}, {"label": "D", "text": "ทำบัญชีรับ-จ่ายแยกรายการ เก็บใบสั่งยาเป็นหลักฐาน และส่งรายงานตามที่กำหนด", "is_correct": true, "explanation": "ถูก เป็นหน้าที่หลักของผู้รับอนุญาตด้านบัญชี หลักฐาน และการรายงาน"}, {"label": "E", "text": "ให้พนักงานขายทั่วไปจัดทำบัญชีแทนเภสัชกร โดยไม่ต้องตรวจทานยอดคงเหลือ", "is_correct": false, "explanation": "ผิด เภสัชกรต้องควบคุมและรับผิดชอบความถูกต้องของบัญชีและยอดคงเหลือ"}], "key_takeaway": "บัญชีรับ-จ่ายวัตถุออกฤทธิ์ต้องแยกรายการ ตรวจสอบย้อนกลับได้ มีใบสั่งยาเป็นหลักฐาน และรายงานตามกำหนด"}'::jsonb, 'medium', 'law-day2 • บัญชีรับ-จ่ายวัตถุออกฤทธิ์ในร้านยา'),
('ce80f72a13e73c7f49af50dd8d237a07', 47, 'ระหว่างตรวจนับสต็อกประจำสัปดาห์ เภสัชกรร้านขายยาพบว่า clonazepam ขาดหายจากยอดในบัญชี 50 เม็ด และภาพจากกล้องวงจรปิดบ่งชี้ว่าพนักงานคนหนึ่งเป็นผู้นำยาออกไป ข้อใดเป็นการปฏิบัติที่ถูกต้อง', '[{"label": "A", "text": "ปรับยอดในบัญชีให้ตรงกับยาคงเหลือ แล้วรายงานรวมไว้ในรายงานประจำปี"}, {"label": "B", "text": "ซื้อยาเข้ามาทดแทนให้ครบยอด เพื่อไม่ให้บัญชีมีส่วนต่าง"}, {"label": "C", "text": "แจ้งความต่อตำรวจและแจ้งพนักงานเจ้าหน้าที่โดยเร็ว พร้อมบันทึกหลักฐานในบัญชี"}, {"label": "D", "text": "หักค่ายาจากเงินเดือนพนักงาน และให้ออกจากงานโดยไม่ต้องแจ้งหน่วยงานใด"}, {"label": "E", "text": "รอให้การสอบสวนภายในร้านเสร็จก่อน หากไม่ได้ยาคืนจึงค่อยพิจารณาแจ้งหน่วยงานที่เกี่ยวข้อง"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. แจ้งตำรวจและพนักงานเจ้าหน้าที่โดยเร็ว พร้อมบันทึกหลักฐาน — การสูญหายหรือถูกลักวัตถุออกฤทธิ์ต้องแจ้งผู้มีอำนาจโดยเร็ว ไม่ใช่จัดการภายในหรือปรับบัญชีเงียบ ๆ", "reason": "ผู้รับอนุญาตมีหน้าที่แจ้งพนักงานเจ้าหน้าที่เมื่อวัตถุออกฤทธิ์สูญหายหรือถูกลัก และกรณีเป็นการลักทรัพย์ควรแจ้งความต่อพนักงานสอบสวน เพื่อให้มีหลักฐานทางราชการและป้องกันไม่ให้ยารั่วไหลไปสู่การใช้ในทางที่ผิด ส่วนต่างในบัญชีต้องบันทึกพร้อมเอกสารอ้างอิง ไม่ใช่ปรับยอดโดยไม่มีคำอธิบาย\n\nหลังจากนั้นร้านควรทบทวนระบบการเก็บรักษา เช่น การจำกัดผู้เข้าถึงกุญแจและการตรวจนับสม่ำเสมอ การซื้อยามาเติม การปรับยอด หรือการจัดการแค่ภายในร้าน ล้วนทำให้บัญชีไม่ตรงกับความจริงและเป็นการละเลยหน้าที่", "choices": [{"label": "A", "text": "ปรับยอดในบัญชีให้ตรงกับยาคงเหลือ แล้วรายงานรวมไว้ในรายงานประจำปี", "is_correct": false, "explanation": "ผิด การปรับยอดเงียบ ๆ ทำให้บัญชีไม่สะท้อนเหตุการณ์จริงและละเลยหน้าที่แจ้งการสูญหาย"}, {"label": "B", "text": "ซื้อยาเข้ามาทดแทนให้ครบยอด เพื่อไม่ให้บัญชีมีส่วนต่าง", "is_correct": false, "explanation": "ผิด การซื้อเติมเพื่อปิดส่วนต่างเป็นการปกปิดการสูญหาย"}, {"label": "C", "text": "แจ้งความต่อตำรวจและแจ้งพนักงานเจ้าหน้าที่โดยเร็ว พร้อมบันทึกหลักฐานในบัญชี", "is_correct": true, "explanation": "ถูก ต้องแจ้งผู้มีอำนาจโดยเร็วและบันทึกหลักฐานให้ตรวจสอบได้"}, {"label": "D", "text": "หักค่ายาจากเงินเดือนพนักงาน และให้ออกจากงานโดยไม่ต้องแจ้งหน่วยงานใด", "is_correct": false, "explanation": "ผิด การจัดการทางวินัยภายในไม่ได้ทดแทนหน้าที่แจ้งหน่วยงานตามกฎหมาย"}, {"label": "E", "text": "รอให้การสอบสวนภายในร้านเสร็จก่อน หากไม่ได้ยาคืนจึงค่อยพิจารณาแจ้งหน่วยงานที่เกี่ยวข้อง", "is_correct": false, "explanation": "ผิด การรอสอบสวนภายในทำให้แจ้งล่าช้า และยาอาจรั่วไหลไปแล้ว"}], "key_takeaway": "เมื่อวัตถุออกฤทธิ์สูญหายหรือถูกลัก ให้แจ้งพนักงานเจ้าหน้าที่และตำรวจโดยเร็ว และบันทึกส่วนต่างพร้อมหลักฐาน"}'::jsonb, 'medium', 'law-day2 • วัตถุออกฤทธิ์สูญหาย/ถูกลักในร้านยา'),
('8f9efb56a79137cb013d847db50b64a1', 48, 'ร้านขายยาเครือข่ายเดียวกันมี 2 สาขา สาขา ก ได้รับอนุญาตเกี่ยวกับวัตถุออกฤทธิ์ ส่วนสาขา ข มีเพียงใบอนุญาตขายยาแผนปัจจุบัน (ขย.1) ผู้จัดการต้องการนำ diazepam จากสาขา ก ไปไว้ที่สาขา ข เพื่อจ่ายให้ผู้ป่วยที่มีใบสั่งยา เพราะทั้งสองสาขามีเภสัชกรประจำและเป็นนิติบุคคลเดียวกัน ข้อใดถูกต้อง', '[{"label": "A", "text": "ทำไม่ได้ เพราะใบอนุญาตผูกกับสถานที่ สาขา ข ต้องได้รับอนุญาตของตนเองก่อน"}, {"label": "B", "text": "ทำได้ เพราะเป็นนิติบุคคลเดียวกัน ใบอนุญาตของสาขา ก จึงครอบคลุมทุกสาขา"}, {"label": "C", "text": "ทำได้ หากสาขา ข จ่ายเฉพาะตามใบสั่งยาและส่งใบสั่งยากลับไปเก็บที่สาขา ก"}, {"label": "D", "text": "ทำได้ หากย้ายยาไปเพียงชั่วคราวไม่เกินหนึ่งสัปดาห์และบันทึกไว้ในสมุดของสาขา ก"}, {"label": "E", "text": "ทำได้ เพราะใบอนุญาต ขย.1 ของสาขา ข ครอบคลุมการขายวัตถุออกฤทธิ์ตามใบสั่งยาแล้ว"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ทำไม่ได้ สาขา ข ต้องมีใบอนุญาตของตนเอง — ใบอนุญาตเกี่ยวกับวัตถุออกฤทธิ์ออกให้เฉพาะสถานที่ที่ระบุ และแยกจากใบอนุญาตขายยาตาม พ.ร.บ.ยา", "reason": "ใบอนุญาตตามประมวลกฎหมายยาเสพติดออกให้แก่ผู้รับอนุญาตสำหรับสถานที่ที่ระบุในใบอนุญาต การมีไว้ในครอบครองหรือจ่ายวัตถุออกฤทธิ์ ณ สถานที่อื่นที่ไม่ได้รับอนุญาตจึงไม่อยู่ในขอบเขตของใบอนุญาต แม้จะเป็นนิติบุคคลเดียวกันก็ตาม\n\nใบอนุญาต ขย.1 ตาม พ.ร.บ.ยา เป็นใบอนุญาตขายยาแผนปัจจุบัน ไม่ได้ครอบคลุมการจำหน่ายวัตถุออกฤทธิ์ ซึ่งต้องได้รับอนุญาตตามประมวลกฎหมายยาเสพติดแยกต่างหาก ทางเลือกที่ถูกต้องคือให้ผู้ป่วยไปรับยาที่สาขา ก หรือให้สาขา ข ยื่นขออนุญาตของตนเอง", "choices": [{"label": "A", "text": "ทำไม่ได้ เพราะใบอนุญาตผูกกับสถานที่ สาขา ข ต้องได้รับอนุญาตของตนเองก่อน", "is_correct": true, "explanation": "ถูก ใบอนุญาตผูกกับสถานที่ สาขา ข ต้องได้รับอนุญาตแยกต่างหาก"}, {"label": "B", "text": "ทำได้ เพราะเป็นนิติบุคคลเดียวกัน ใบอนุญาตของสาขา ก จึงครอบคลุมทุกสาขา", "is_correct": false, "explanation": "ผิด ใบอนุญาตไม่ได้ครอบคลุมทุกสถานที่ของนิติบุคคลเดียวกัน"}, {"label": "C", "text": "ทำได้ หากสาขา ข จ่ายเฉพาะตามใบสั่งยาและส่งใบสั่งยากลับไปเก็บที่สาขา ก", "is_correct": false, "explanation": "ผิด การจ่ายตามใบสั่งยาที่สาขาไม่ได้รับอนุญาตยังเป็นการครอบครองและจำหน่ายนอกสถานที่ที่ได้รับอนุญาต"}, {"label": "D", "text": "ทำได้ หากย้ายยาไปเพียงชั่วคราวไม่เกินหนึ่งสัปดาห์และบันทึกไว้ในสมุดของสาขา ก", "is_correct": false, "explanation": "ผิด ระยะเวลาสั้นหรือการบันทึกไม่ได้ทำให้การครอบครองนอกสถานที่ที่ได้รับอนุญาตถูกต้อง"}, {"label": "E", "text": "ทำได้ เพราะใบอนุญาต ขย.1 ของสาขา ข ครอบคลุมการขายวัตถุออกฤทธิ์ตามใบสั่งยาแล้ว", "is_correct": false, "explanation": "ผิด ใบอนุญาต ขย.1 ไม่ครอบคลุมวัตถุออกฤทธิ์ ต้องได้รับอนุญาตตามประมวลกฎหมายยาเสพติดเพิ่ม"}], "key_takeaway": "ใบอนุญาตวัตถุออกฤทธิ์เป็นของแต่ละสถานที่ และใบอนุญาต ขย.1 อย่างเดียวไม่ครอบคลุมวัตถุออกฤทธิ์"}'::jsonb, 'hard', 'law-day2 • ใบอนุญาตเฉพาะสถานที่: สาขาที่ไม่ได้รับอนุญาต'),
('b0021ed70d608fb6ac370e1a3d4ce80f', 49, 'ร้านขายยาแผนปัจจุบันที่ได้รับอนุญาตเกี่ยวกับวัตถุออกฤทธิ์มี lorazepam ใกล้หมดอายุจำนวนหนึ่ง และบริษัทผู้จำหน่ายซึ่งได้รับอนุญาตยินดีรับคืน ข้อใดเป็นการปฏิบัติที่ถูกต้อง', '[{"label": "A", "text": "ส่งคืนผ่านพนักงานขายของบริษัทได้ทันที โดยไม่ต้องลงบัญชี เพราะการส่งคืนไม่ใช่การขาย"}, {"label": "B", "text": "ส่งคืนให้ผู้รับอนุญาตรายเดิมพร้อมเอกสารการส่งคืน และลงบัญชีจ่ายออกให้ตรงยอด"}, {"label": "C", "text": "ขายต่อให้คลินิกใกล้ร้านในราคาทุน เพื่อให้ยาถูกใช้ก่อนหมดอายุ"}, {"label": "D", "text": "แจกให้ผู้ป่วยประจำที่มีใบสั่งยาเก่า เพื่อไม่ให้ยาเสียเปล่า"}, {"label": "E", "text": "บดยาแล้วทิ้งลงท่อระบายน้ำในร้าน และตัดยอดออกจากบัญชีในวันเดียวกัน"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ส่งคืนผู้รับอนุญาตพร้อมเอกสาร และลงบัญชีจ่ายออก — การเคลื่อนย้ายวัตถุออกฤทธิ์ออกจากร้านทุกครั้งต้องไปยังผู้ที่ได้รับอนุญาต มีเอกสาร และลงบัญชี", "reason": "การส่งคืนวัตถุออกฤทธิ์ให้ผู้จำหน่ายเป็นการเปลี่ยนการครอบครองจากผู้รับอนุญาตหนึ่งไปยังอีกผู้รับอนุญาตหนึ่ง จึงต้องมีเอกสารหลักฐานการส่งคืนและบันทึกเป็นรายการจ่ายออกในบัญชีรับ-จ่าย เพื่อให้ยอดคงเหลือตรวจสอบย้อนกลับได้\n\nการขายต่อให้คลินิกนอกระบบ การแจกผู้ป่วยโดยไม่มีใบสั่งยาใหม่ หรือการทำลายเองโดยไม่มีพยานหลักฐานและไม่ได้ปฏิบัติตามขั้นตอนที่กำหนด ล้วนทำให้เกิดการรั่วไหลหรือบัญชีที่ตรวจสอบไม่ได้", "choices": [{"label": "A", "text": "ส่งคืนผ่านพนักงานขายของบริษัทได้ทันที โดยไม่ต้องลงบัญชี เพราะการส่งคืนไม่ใช่การขาย", "is_correct": false, "explanation": "ผิด การส่งคืนเป็นการจ่ายออกจากสต็อก ต้องลงบัญชีและมีเอกสาร"}, {"label": "B", "text": "ส่งคืนให้ผู้รับอนุญาตรายเดิมพร้อมเอกสารการส่งคืน และลงบัญชีจ่ายออกให้ตรงยอด", "is_correct": true, "explanation": "ถูก ส่งคืนแก่ผู้รับอนุญาตพร้อมเอกสาร และลงบัญชีให้ตรงยอด"}, {"label": "C", "text": "ขายต่อให้คลินิกใกล้ร้านในราคาทุน เพื่อให้ยาถูกใช้ก่อนหมดอายุ", "is_correct": false, "explanation": "ผิด ร้านขายยาไม่ได้รับอนุญาตให้จำหน่ายส่งต่อให้สถานพยาบาลอื่นนอกขอบเขตใบอนุญาต"}, {"label": "D", "text": "แจกให้ผู้ป่วยประจำที่มีใบสั่งยาเก่า เพื่อไม่ให้ยาเสียเปล่า", "is_correct": false, "explanation": "ผิด ใบสั่งยาเก่าที่ใช้ไปแล้วไม่ใช่หลักฐานการจ่ายครั้งใหม่"}, {"label": "E", "text": "บดยาแล้วทิ้งลงท่อระบายน้ำในร้าน และตัดยอดออกจากบัญชีในวันเดียวกัน", "is_correct": false, "explanation": "ผิด การทำลายต้องปฏิบัติตามขั้นตอนที่กำหนดและมีหลักฐาน ไม่ใช่ทิ้งลงท่อเอง"}], "key_takeaway": "วัตถุออกฤทธิ์ที่ออกจากร้านต้องไปยังผู้ที่ได้รับอนุญาตเท่านั้น พร้อมเอกสารและการลงบัญชี"}'::jsonb, 'medium', 'law-day2 • การส่งคืนวัตถุออกฤทธิ์แก่ผู้ขาย'),
('11139f6d24deecdbaeebbebcf0c90475', 50, 'ร้านขายยาแผนปัจจุบันเพิ่งได้รับอนุญาตเกี่ยวกับวัตถุออกฤทธิ์ เจ้าของร้านถามเภสัชกรว่าควรจัดเก็บยากลุ่มนี้อย่างไร ข้อใดเหมาะสมที่สุด', '[{"label": "A", "text": "วางบนชั้นหลังเคาน์เตอร์ร่วมกับยาอันตรายอื่น เพื่อให้พนักงานหยิบได้สะดวก"}, {"label": "B", "text": "เก็บไว้ที่บ้านของเจ้าของร้านทุกครั้งที่ปิดร้าน เพื่อป้องกันการโจรกรรมในช่วงเวลากลางคืน"}, {"label": "C", "text": "จัดแสดงในตู้กระจกหน้าร้าน เพื่อให้ลูกค้าเห็นว่าร้านได้รับอนุญาตถูกต้อง"}, {"label": "D", "text": "เก็บรวมกับยาสามัญประจำบ้าน แต่ติดสติกเกอร์สีแดงเพื่อแยกให้เห็นชัดเจน"}, {"label": "E", "text": "เก็บแยกในตู้ที่ปิดล็อกได้ภายในสถานที่ที่ได้รับอนุญาต และให้เภสัชกรควบคุมกุญแจ"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. เก็บแยกในตู้ล็อกภายในร้าน เภสัชกรควบคุมกุญแจ — วัตถุออกฤทธิ์ต้องเก็บแยก มั่นคงปลอดภัย และอยู่ภายใต้การควบคุมของเภสัชกร ณ สถานที่ที่ได้รับอนุญาต", "reason": "การเก็บรักษาวัตถุออกฤทธิ์ควรป้องกันการเข้าถึงโดยไม่ได้รับอนุญาตและการรั่วไหล โดยเก็บแยกจากยาอื่นในตู้หรือที่เก็บที่ปิดล็อกได้ ภายในสถานที่ที่ระบุในใบอนุญาต และให้เภสัชกรผู้มีหน้าที่ปฏิบัติการเป็นผู้ควบคุมการเข้าถึง พร้อมตรวจนับให้ตรงกับบัญชีอย่างสม่ำเสมอ\n\nการนำยาออกไปเก็บนอกสถานที่ที่ได้รับอนุญาต แม้มีเจตนาป้องกันการโจรกรรม ถือเป็นการครอบครองนอกขอบเขตใบอนุญาต", "choices": [{"label": "A", "text": "วางบนชั้นหลังเคาน์เตอร์ร่วมกับยาอันตรายอื่น เพื่อให้พนักงานหยิบได้สะดวก", "is_correct": false, "explanation": "ผิด การวางรวมกับยาอื่นในที่พนักงานหยิบได้ง่ายไม่ได้ควบคุมการเข้าถึง"}, {"label": "B", "text": "เก็บไว้ที่บ้านของเจ้าของร้านทุกครั้งที่ปิดร้าน เพื่อป้องกันการโจรกรรมในช่วงเวลากลางคืน", "is_correct": false, "explanation": "ผิด การเก็บนอกสถานที่ที่ได้รับอนุญาตเป็นการครอบครองนอกขอบเขตใบอนุญาต"}, {"label": "C", "text": "จัดแสดงในตู้กระจกหน้าร้าน เพื่อให้ลูกค้าเห็นว่าร้านได้รับอนุญาตถูกต้อง", "is_correct": false, "explanation": "ผิด การจัดแสดงต่อลูกค้าเพิ่มความเสี่ยงและไม่เหมาะกับยาควบคุม"}, {"label": "D", "text": "เก็บรวมกับยาสามัญประจำบ้าน แต่ติดสติกเกอร์สีแดงเพื่อแยกให้เห็นชัดเจน", "is_correct": false, "explanation": "ผิด ต้องเก็บแยกในที่ปลอดภัย ไม่ใช่รวมกับยาที่ประชาชนหยิบได้"}, {"label": "E", "text": "เก็บแยกในตู้ที่ปิดล็อกได้ภายในสถานที่ที่ได้รับอนุญาต และให้เภสัชกรควบคุมกุญแจ", "is_correct": true, "explanation": "ถูก เก็บแยก ปิดล็อก ภายในสถานที่ที่ได้รับอนุญาต และเภสัชกรควบคุมการเข้าถึง"}], "key_takeaway": "วัตถุออกฤทธิ์ต้องเก็บแยกในที่ปิดล็อก ณ สถานที่ที่ได้รับอนุญาต ภายใต้การควบคุมของเภสัชกร"}'::jsonb, 'easy', 'law-day2 • การเก็บรักษาวัตถุออกฤทธิ์ในร้านยา'),
('a1c73af046ad0e9132fd8828b104d471', 51, 'ร้านขายยาแผนปัจจุบันที่ได้รับอนุญาตเกี่ยวกับวัตถุออกฤทธิ์จะเลิกกิจการ และยังมี diazepam กับ alprazolam คงเหลืออยู่จำนวนหนึ่ง ข้อใดเป็นการจัดการที่ถูกต้อง', '[{"label": "A", "text": "ให้เภสัชกรนำยาที่เหลือกลับไปเก็บไว้ที่บ้าน เพื่อใช้เมื่อเปิดร้านใหม่ในอนาคต"}, {"label": "B", "text": "ขายยาคงเหลือให้ลูกค้าประจำในราคาพิเศษก่อนปิดร้าน โดยไม่ต้องใช้ใบสั่งยา"}, {"label": "C", "text": "ปิดร้านและทิ้งยาไว้ในร้าน แล้วรอให้พนักงานเจ้าหน้าที่มาตรวจเมื่อใบอนุญาตหมดอายุ"}, {"label": "D", "text": "แจ้งพนักงานเจ้าหน้าที่ และจัดการยาคงเหลือตามขั้นตอนที่กำหนดพร้อมหลักฐาน"}, {"label": "E", "text": "ยกยาทั้งหมดให้คลินิกของเพื่อนที่ไม่มีใบอนุญาต เพื่อใช้รักษาผู้ป่วยต่อ"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. แจ้งพนักงานเจ้าหน้าที่และจัดการยาตามขั้นตอนที่กำหนด — เมื่อเลิกกิจการ วัตถุออกฤทธิ์คงเหลือต้องได้รับการจัดการภายใต้การกำกับของพนักงานเจ้าหน้าที่ ไม่ใช่จัดการเอง", "reason": "เมื่อผู้รับอนุญาตเลิกกิจการ อำนาจในการครอบครองตามใบอนุญาตย่อมสิ้นสุดลง ผู้รับอนุญาตต้องแจ้งพนักงานเจ้าหน้าที่ แสดงยอดคงเหลือตามบัญชี และจัดการยาที่เหลือตามขั้นตอนที่กฎหมายกำหนด เช่น จำหน่ายหรือส่งคืนให้ผู้ที่ได้รับอนุญาต หรือดำเนินการตามที่พนักงานเจ้าหน้าที่สั่ง โดยมีเอกสารหลักฐานครบถ้วน\n\nการนำยาไปเก็บที่บ้าน การขายโดยไม่มีใบสั่งยา การยกให้ผู้ไม่ได้รับอนุญาต หรือการทิ้งไว้โดยไม่มีผู้ควบคุม ล้วนเป็นการครอบครองหรือจำหน่ายโดยไม่ได้รับอนุญาต หรือเสี่ยงต่อการรั่วไหล", "choices": [{"label": "A", "text": "ให้เภสัชกรนำยาที่เหลือกลับไปเก็บไว้ที่บ้าน เพื่อใช้เมื่อเปิดร้านใหม่ในอนาคต", "is_correct": false, "explanation": "ผิด เป็นการครอบครองนอกสถานที่และนอกขอบเขตใบอนุญาต"}, {"label": "B", "text": "ขายยาคงเหลือให้ลูกค้าประจำในราคาพิเศษก่อนปิดร้าน โดยไม่ต้องใช้ใบสั่งยา", "is_correct": false, "explanation": "ผิด การขายโดยไม่มีใบสั่งยาเป็นความผิด ไม่ว่าจะเป็นช่วงปิดกิจการหรือไม่"}, {"label": "C", "text": "ปิดร้านและทิ้งยาไว้ในร้าน แล้วรอให้พนักงานเจ้าหน้าที่มาตรวจเมื่อใบอนุญาตหมดอายุ", "is_correct": false, "explanation": "ผิด การทิ้งยาไว้โดยไม่มีผู้ควบคุมเสี่ยงต่อการสูญหายและไม่ได้ปฏิบัติตามหน้าที่แจ้ง"}, {"label": "D", "text": "แจ้งพนักงานเจ้าหน้าที่ และจัดการยาคงเหลือตามขั้นตอนที่กำหนดพร้อมหลักฐาน", "is_correct": true, "explanation": "ถูก ต้องแจ้งพนักงานเจ้าหน้าที่และจัดการยาคงเหลือตามขั้นตอนพร้อมหลักฐาน"}, {"label": "E", "text": "ยกยาทั้งหมดให้คลินิกของเพื่อนที่ไม่มีใบอนุญาต เพื่อใช้รักษาผู้ป่วยต่อ", "is_correct": false, "explanation": "ผิด การโอนให้ผู้ไม่ได้รับอนุญาตเป็นการจำหน่ายและครอบครองโดยไม่ชอบด้วยกฎหมาย"}], "key_takeaway": "เมื่อเลิกกิจการ ต้องแจ้งพนักงานเจ้าหน้าที่และจัดการวัตถุออกฤทธิ์คงเหลือตามขั้นตอน ห้ามนำไปหรือยกให้ใครเอง"}'::jsonb, 'medium', 'law-day2 • การเลิกกิจการ: วัตถุออกฤทธิ์คงเหลือ'),
('003fd6d441c4e2bdb11edd0a5967d69a', 52, 'ในการตรวจนับยาสำรองหอผู้ป่วยขณะส่งเวร พยาบาลพบว่า diazepam injection ขาดไป 1 หลอดจากยอดที่กำหนด โดยไม่พบคำสั่งแพทย์หรือบันทึกการให้ยาแก่ผู้ป่วยรายใด ข้อใดเป็นการปฏิบัติที่ถูกต้องที่สุด', '[{"label": "A", "text": "เบิกยาจากหอผู้ป่วยอื่นมาเติมให้ครบยอดก่อน แล้วค่อยตรวจสอบภายหลัง"}, {"label": "B", "text": "บันทึกว่าหลอดยาแตกระหว่างเตรียม เพื่อให้ยอดในบัญชีสอดคล้องกับยาที่มีอยู่"}, {"label": "C", "text": "รายงานหัวหน้าเวรและเภสัชกรทันทีตามระเบียบ บันทึกส่วนต่าง และร่วมสอบสวนหาสาเหตุ"}, {"label": "D", "text": "รอดูการตรวจนับในเวรถัดไป เผื่อพบว่าเป็นความผิดพลาดในการนับของเวรก่อน"}, {"label": "E", "text": "ให้พยาบาลทั้งสองเวรร่วมกันซื้อยามาคืนหอผู้ป่วย และไม่ต้องรายงานให้ฝ่ายเภสัชกรรมทราบ"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. รายงานทันทีตามระเบียบ บันทึกส่วนต่าง และสอบสวน — ส่วนต่างของยาควบคุมในหอผู้ป่วยต้องรายงานและสอบสวนทันที ห้ามปรับยอดหรือปกปิด", "reason": "ยาสำรองหอผู้ป่วยที่เป็นยาควบคุมตามประมวลกฎหมายยาเสพติดยังอยู่ในความรับผิดชอบของโรงพยาบาลในฐานะผู้รับอนุญาต ทุกการใช้ต้องมีคำสั่งแพทย์และบันทึกการให้ยาที่ตรวจสอบย้อนกลับได้ เมื่อยอดไม่ตรง ต้องรายงานผู้รับผิดชอบและเภสัชกรทันทีตามระเบียบของโรงพยาบาล บันทึกส่วนต่างตามจริง และสอบสวนหาสาเหตุ หากยืนยันว่าสูญหายหรือถูกลัก โรงพยาบาลต้องดำเนินการแจ้งหน่วยงานตามที่กฎหมายกำหนด\n\nการเติมยาจากที่อื่น การบันทึกเท็จว่าหลอดแตก หรือการซื้อยามาคืนเอง เป็นการปกปิดข้อเท็จจริงและทำให้บัญชีไม่ถูกต้อง", "choices": [{"label": "A", "text": "เบิกยาจากหอผู้ป่วยอื่นมาเติมให้ครบยอดก่อน แล้วค่อยตรวจสอบภายหลัง", "is_correct": false, "explanation": "ผิด การเติมยาก่อนตรวจสอบเป็นการปกปิดส่วนต่างและทำให้อีกหอผู้ป่วยมียอดผิด"}, {"label": "B", "text": "บันทึกว่าหลอดยาแตกระหว่างเตรียม เพื่อให้ยอดในบัญชีสอดคล้องกับยาที่มีอยู่", "is_correct": false, "explanation": "ผิด เป็นการบันทึกเอกสารเท็จ"}, {"label": "C", "text": "รายงานหัวหน้าเวรและเภสัชกรทันทีตามระเบียบ บันทึกส่วนต่าง และร่วมสอบสวนหาสาเหตุ", "is_correct": true, "explanation": "ถูก รายงานทันที บันทึกตามจริง และสอบสวนตามระเบียบ"}, {"label": "D", "text": "รอดูการตรวจนับในเวรถัดไป เผื่อพบว่าเป็นความผิดพลาดในการนับของเวรก่อน", "is_correct": false, "explanation": "ผิด การรอทำให้รายงานล่าช้า และยาอาจรั่วไหลไปแล้ว"}, {"label": "E", "text": "ให้พยาบาลทั้งสองเวรร่วมกันซื้อยามาคืนหอผู้ป่วย และไม่ต้องรายงานให้ฝ่ายเภสัชกรรมทราบ", "is_correct": false, "explanation": "ผิด บุคลากรไม่สามารถจัดหายาควบคุมมาคืนเองได้ และเป็นการปกปิดเหตุการณ์"}], "key_takeaway": "เมื่อยอดยาควบคุมในหอผู้ป่วยไม่ตรง ให้รายงานทันที บันทึกตามจริง และสอบสวน ห้ามเติมหรือแก้บันทึกเพื่อปิดส่วนต่าง"}'::jsonb, 'medium', 'law-day2 • ยาสำรองหอผู้ป่วย: ยอดไม่ตรง'),
('53222edf68f1767ff2312bdc8e60c9cc', 53, 'ผู้ป่วยในโปรแกรมบำบัดด้วย methadone ระยะยาวของโรงพยาบาลรัฐ มาที่ร้านขายยาแผนปัจจุบัน (ขย.1) ช่วงวันหยุดยาว แสดงบัตรประจำตัวผู้ป่วยในโปรแกรม และขอซื้อ methadone เพื่อใช้ระหว่างที่โรงพยาบาลปิดทำการ ข้อใดถูกต้อง', '[{"label": "A", "text": "ร้านจ่ายไม่ได้ ให้ผู้ป่วยติดต่อสถานพยาบาลตามช่องทางที่โปรแกรมกำหนด"}, {"label": "B", "text": "จ่ายได้ เพราะบัตรประจำตัวผู้ป่วยในโปรแกรมใช้แทนใบสั่งยาได้ในกรณีฉุกเฉิน"}, {"label": "C", "text": "จ่ายได้ หากเภสัชกรโทรศัพท์ยืนยันขนาดยากับพยาบาลเวรของโรงพยาบาลก่อน"}, {"label": "D", "text": "จ่ายได้ เพราะ methadone ที่ใช้บำบัดผู้ติดยาเป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา"}, {"label": "E", "text": "จ่ายได้เฉพาะในวันหยุดราชการ โดยต้องลงบันทึกในสมุดยาอันตรายของร้าน"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ร้านจ่ายไม่ได้ ให้ติดต่อสถานพยาบาลในโปรแกรม — methadone เป็นยาเสพติดให้โทษประเภท 2 การใช้บำบัดผู้ติดยาทำได้ในสถานพยาบาลที่ได้รับอนุญาตภายใต้โปรแกรม", "reason": "methadone เป็นยาเสพติดให้โทษประเภท 2 ตามประมวลกฎหมายยาเสพติด การใช้ในโปรแกรมบำบัดผู้ติดยาเสพติดดำเนินการโดยสถานพยาบาลที่ได้รับอนุญาตและอยู่ในระบบบำบัดรักษา ภายใต้การสั่งใช้และการกำกับของแพทย์ในโปรแกรม รวมถึงการกำหนดว่าผู้ป่วยรายใดรับยากลับบ้านได้หรือไม่\n\nร้านขายยาที่มีเพียงใบอนุญาต ขย.1 ไม่มีอำนาจครอบครองหรือจำหน่าย methadone แก่ผู้ป่วย เภสัชกรควรแนะนำให้ผู้ป่วยติดต่อสถานพยาบาลตามช่องทางฉุกเฉินหรือช่องทางที่โปรแกรมกำหนด เพื่อไม่ให้การรักษาขาดช่วง", "choices": [{"label": "A", "text": "ร้านจ่ายไม่ได้ ให้ผู้ป่วยติดต่อสถานพยาบาลตามช่องทางที่โปรแกรมกำหนด", "is_correct": true, "explanation": "ถูก ร้าน ขย.1 ไม่มีอำนาจจ่าย methadone ต้องให้ผู้ป่วยรับยาผ่านสถานพยาบาลในโปรแกรม"}, {"label": "B", "text": "จ่ายได้ เพราะบัตรประจำตัวผู้ป่วยในโปรแกรมใช้แทนใบสั่งยาได้ในกรณีฉุกเฉิน", "is_correct": false, "explanation": "ผิด บัตรประจำตัวผู้ป่วยไม่ใช่ใบสั่งยา และร้านไม่มีอำนาจจ่ายยาเสพติดให้โทษประเภท 2"}, {"label": "C", "text": "จ่ายได้ หากเภสัชกรโทรศัพท์ยืนยันขนาดยากับพยาบาลเวรของโรงพยาบาลก่อน", "is_correct": false, "explanation": "ผิด การยืนยันทางโทรศัพท์ไม่ได้ทำให้ร้านมีใบอนุญาตครอบครองหรือจำหน่าย methadone"}, {"label": "D", "text": "จ่ายได้ เพราะ methadone ที่ใช้บำบัดผู้ติดยาเป็นยาควบคุมพิเศษตาม พ.ร.บ.ยา", "is_correct": false, "explanation": "ผิด methadone เป็นยาเสพติดให้โทษประเภท 2 ไม่ใช่ยาควบคุมพิเศษ"}, {"label": "E", "text": "จ่ายได้เฉพาะในวันหยุดราชการ โดยต้องลงบันทึกในสมุดยาอันตรายของร้าน", "is_correct": false, "explanation": "ผิด วันหยุดราชการไม่ใช่ข้อยกเว้นให้ร้านยาจ่ายยาเสพติดให้โทษ"}], "key_takeaway": "Methadone เป็นยาเสพติดให้โทษประเภท 2 การบำบัดด้วย methadone ต้องผ่านสถานพยาบาลที่ได้รับอนุญาตในโปรแกรม ไม่ใช่ร้านยา"}'::jsonb, 'medium', 'law-day2 • Methadone maintenance: ขอบเขตของร้านยา'),
('211d926376d2128f28ec808fbfc221b1', 54, 'ชายอายุ 30 ปีมาสอบถามเภสัชกรที่ร้านยาว่ายาต้านซึมเศร้าที่ได้รับจากโรงพยาบาลจะเกิดอันตรายหรือไม่ หากเขายังใช้ methamphetamine อยู่บ้าง และถามว่าเภสัชกรจะแจ้งตำรวจหรือไม่ ข้อใดเป็นการปฏิบัติที่สอดคล้องกับแนวทางของประมวลกฎหมายยาเสพติดและจรรยาบรรณวิชาชีพมากที่สุด', '[{"label": "A", "text": "แจ้งตำรวจทันที เพราะเภสัชกรมีหน้าที่ตามกฎหมายต้องรายงานผู้เสพทุกรายที่ทราบ"}, {"label": "B", "text": "ให้ข้อมูลความเสี่ยง รักษาความลับ และเสนอการส่งต่อเพื่อเข้ารับการบำบัดโดยสมัครใจ"}, {"label": "C", "text": "ปฏิเสธการให้คำปรึกษา เพราะการให้ข้อมูลแก่ผู้เสพถือเป็นการสนับสนุนการกระทำผิด"}, {"label": "D", "text": "โทรศัพท์แจ้งครอบครัวของผู้ป่วยทันที เพื่อให้ครอบครัวพาไปบำบัดโดยไม่ต้องขอความยินยอม"}, {"label": "E", "text": "บันทึกชื่อลงในรายชื่อเฝ้าระวังของร้าน และส่งต่อรายชื่อให้ร้านยาอื่นในพื้นที่"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ให้ข้อมูลความเสี่ยง รักษาความลับ และเสนอการบำบัดโดยสมัครใจ — ประมวลกฎหมายยาเสพติดมองผู้ใช้ยาเป็นผู้ป่วยที่ควรได้รับการบำบัด และเภสัชกรมีหน้าที่รักษาความลับของผู้รับบริการ", "reason": "ประมวลกฎหมายยาเสพติด พ.ศ. 2564 ปรับแนวคิดให้มองผู้เสพเป็นผู้ป่วย และเปิดทางให้เข้ารับการบำบัดรักษาโดยสมัครใจ เภสัชกรจึงควรให้ข้อมูลความเสี่ยงของการใช้ methamphetamine ร่วมกับยาต้านซึมเศร้า ซักถามด้วยท่าทีไม่ตัดสิน และเสนอการส่งต่อไปยังแพทย์ผู้รักษาหรือสถานบำบัด\n\nข้อมูลที่ได้จากการให้บริการเป็นความลับของผู้รับบริการ เภสัชกรไม่ควรเปิดเผยต่อบุคคลอื่นโดยไม่ได้รับความยินยอม เว้นแต่มีกฎหมายบังคับหรือมีเหตุจำเป็นเพื่อป้องกันอันตรายร้ายแรง การแจ้งตำรวจ การปฏิเสธการดูแล หรือการเผยแพร่รายชื่อ ขัดทั้งแนวทางการบำบัดและจรรยาบรรณ", "choices": [{"label": "A", "text": "แจ้งตำรวจทันที เพราะเภสัชกรมีหน้าที่ตามกฎหมายต้องรายงานผู้เสพทุกรายที่ทราบ", "is_correct": false, "explanation": "ผิด ไม่มีหน้าที่ทั่วไปให้เภสัชกรต้องแจ้งตำรวจเมื่อทราบว่าผู้รับบริการใช้ยาเสพติด"}, {"label": "B", "text": "ให้ข้อมูลความเสี่ยง รักษาความลับ และเสนอการส่งต่อเพื่อเข้ารับการบำบัดโดยสมัครใจ", "is_correct": true, "explanation": "ถูก สอดคล้องกับหลักผู้เสพคือผู้ป่วยและการรักษาความลับของผู้รับบริการ"}, {"label": "C", "text": "ปฏิเสธการให้คำปรึกษา เพราะการให้ข้อมูลแก่ผู้เสพถือเป็นการสนับสนุนการกระทำผิด", "is_correct": false, "explanation": "ผิด การให้ข้อมูลเพื่อลดอันตรายและส่งต่อการรักษาไม่ใช่การสนับสนุนการกระทำผิด"}, {"label": "D", "text": "โทรศัพท์แจ้งครอบครัวของผู้ป่วยทันที เพื่อให้ครอบครัวพาไปบำบัดโดยไม่ต้องขอความยินยอม", "is_correct": false, "explanation": "ผิด การเปิดเผยข้อมูลแก่ครอบครัวโดยไม่ได้รับความยินยอมละเมิดความลับของผู้รับบริการ"}, {"label": "E", "text": "บันทึกชื่อลงในรายชื่อเฝ้าระวังของร้าน และส่งต่อรายชื่อให้ร้านยาอื่นในพื้นที่", "is_correct": false, "explanation": "ผิด การเผยแพร่รายชื่อละเมิดความลับและสิทธิส่วนบุคคล"}], "key_takeaway": "เภสัชกรควรดูแลผู้ใช้ยาเสพติดในฐานะผู้ป่วย ให้ข้อมูลความเสี่ยง รักษาความลับ และส่งต่อการบำบัด"}'::jsonb, 'medium', 'law-day2 • ผู้ใช้ยาเสพติดในฐานะผู้ป่วย: บทบาทเภสัชกร'),
('52a9cc0196a891f27ac7f49159fc41e0', 55, 'ร้านขายยาแผนปัจจุบัน (ขย.1) แห่งหนึ่งต้องการจำหน่ายยาน้ำแก้ไอสูตรผสมที่มี codeine ร่วมกับตัวยาอื่นตามตำรับที่ขึ้นทะเบียนไว้ เจ้าของร้านเข้าใจว่าใบอนุญาต ขย.1 ที่มีอยู่เพียงพอแล้ว ข้อใดถูกต้อง', '[{"label": "A", "text": "ใบอนุญาต ขย.1 เพียงพอ เพราะยาสูตรผสม codeine เป็นยาอันตรายตาม พ.ร.บ.ยา เท่านั้น"}, {"label": "B", "text": "ใบอนุญาต ขย.1 เพียงพอ หากเภสัชกรอยู่ปฏิบัติการตลอดเวลาที่เปิดร้าน"}, {"label": "C", "text": "ร้านต้องได้รับอนุญาตจำหน่ายวัตถุออกฤทธิ์ เพราะยาสูตรผสม codeine จัดเป็นวัตถุออกฤทธิ์"}, {"label": "D", "text": "ต้องได้รับอนุญาตเกี่ยวกับยาเสพติดให้โทษประเภท 3 เพิ่ม และจัดทำบัญชีตามที่กำหนด"}, {"label": "E", "text": "ร้านยาไม่สามารถจำหน่ายยาสูตรผสม codeine ได้เลย เพราะเป็นยาเสพติดให้โทษประเภท 1"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ต้องได้รับอนุญาตเกี่ยวกับยาเสพติดให้โทษประเภท 3 เพิ่ม — ตำรับยาที่มี codeine ผสมอยู่ตามที่กำหนดเป็นยาเสพติดให้โทษประเภท 3 จึงต้องได้รับอนุญาตตามประมวลกฎหมายยาเสพติดแยกจาก ขย.1", "reason": "ตามประมวลกฎหมายยาเสพติด ยาเสพติดให้โทษประเภท 3 คือยาเสพติดให้โทษที่มีลักษณะเป็นตำรับยาซึ่งมียาเสพติดให้โทษประเภท 2 (เช่น codeine) ผสมอยู่ตามที่กำหนด ยาน้ำแก้ไอสูตรผสม codeine ที่ขึ้นทะเบียนเป็นตำรับจึงจัดอยู่ในกลุ่มนี้\n\nใบอนุญาต ขย.1 ออกตาม พ.ร.บ.ยา ซึ่งอนุญาตให้ขายยาแผนปัจจุบันทั่วไป แต่ไม่ครอบคลุมการจำหน่ายยาเสพติดให้โทษ ร้านจึงต้องได้รับอนุญาตตามประมวลกฎหมายยาเสพติดเพิ่มเติม และปฏิบัติตามหน้าที่ของผู้รับอนุญาต เช่น การจัดทำบัญชีรับ-จ่ายและรายงาน", "choices": [{"label": "A", "text": "ใบอนุญาต ขย.1 เพียงพอ เพราะยาสูตรผสม codeine เป็นยาอันตรายตาม พ.ร.บ.ยา เท่านั้น", "is_correct": false, "explanation": "ผิด ตำรับยาที่มี codeine ผสมจัดเป็นยาเสพติดให้โทษประเภท 3 ต้องปฏิบัติตามประมวลกฎหมายยาเสพติดด้วย"}, {"label": "B", "text": "ใบอนุญาต ขย.1 เพียงพอ หากเภสัชกรอยู่ปฏิบัติการตลอดเวลาที่เปิดร้าน", "is_correct": false, "explanation": "ผิด การมีเภสัชกรประจำไม่ได้ทดแทนใบอนุญาตตามประมวลกฎหมายยาเสพติด"}, {"label": "C", "text": "ร้านต้องได้รับอนุญาตจำหน่ายวัตถุออกฤทธิ์ เพราะยาสูตรผสม codeine จัดเป็นวัตถุออกฤทธิ์", "is_correct": false, "explanation": "ผิด codeine และตำรับที่ผสม codeine เป็นยาเสพติดให้โทษ ไม่ใช่วัตถุออกฤทธิ์"}, {"label": "D", "text": "ต้องได้รับอนุญาตเกี่ยวกับยาเสพติดให้โทษประเภท 3 เพิ่ม และจัดทำบัญชีตามที่กำหนด", "is_correct": true, "explanation": "ถูก ต้องได้รับอนุญาตเกี่ยวกับยาเสพติดให้โทษประเภท 3 แยกจาก ขย.1 และทำบัญชีตามที่กำหนด"}, {"label": "E", "text": "ร้านยาไม่สามารถจำหน่ายยาสูตรผสม codeine ได้เลย เพราะเป็นยาเสพติดให้โทษประเภท 1", "is_correct": false, "explanation": "ผิด ยาเสพติดให้โทษประเภท 1 คือกลุ่ม heroin, methamphetamine ตำรับผสม codeine เป็นประเภท 3"}], "key_takeaway": "ตำรับยาผสม codeine เป็นยาเสพติดให้โทษประเภท 3 ร้าน ขย.1 ต้องได้รับอนุญาตตามประมวลกฎหมายยาเสพติดเพิ่มก่อนจำหน่าย"}'::jsonb, 'hard', 'law-day2 • ยาเสพติดให้โทษประเภท 3: ใบอนุญาตของร้านยา'),
('6dbe7efe7e21d4f86bc646a7dd5f9fd0', 56, 'ลูกค้าหญิงอายุ 22 ปีเข้ามาที่ร้านขายยา ขย.1 โดยไม่มีใบสั่งยา และขอซื้อยาหลายรายการ เภสัชกรซักประวัติแล้ว ยาข้อใดที่เภสัชกรไม่สามารถขายให้ได้ตามพระราชบัญญัติยา แม้จะประเมินแล้วว่าเหมาะสมกับอาการ', '[{"label": "A", "text": "Amoxicillin แคปซูล สำหรับการติดเชื้อที่ประเมินแล้วว่าเหมาะสม"}, {"label": "B", "text": "Isotretinoin แคปซูล สำหรับสิวอักเสบที่เป็นมานานหลายเดือน"}, {"label": "C", "text": "Levonorgestrel ชนิดเม็ดคุมกำเนิดฉุกเฉิน หลังมีเพศสัมพันธ์"}, {"label": "D", "text": "ยาเม็ดคุมกำเนิดชนิดฮอร์โมนรวม สำหรับใช้คุมกำเนิดต่อเนื่อง"}, {"label": "E", "text": "Diclofenac ชนิดเม็ด สำหรับอาการปวดกล้ามเนื้อหลังออกกำลังกาย"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. Isotretinoin แคปซูล — isotretinoin ชนิดรับประทานเป็นยาควบคุมพิเศษ ร้าน ขย.1 ขายได้เฉพาะตามใบสั่งยาเท่านั้น", "reason": "พ.ร.บ.ยา แบ่งยาแผนปัจจุบันที่ขายในร้าน ขย.1 ออกเป็นหลายระดับ ยาอันตรายเป็นยาที่เภสัชกรผู้มีหน้าที่ปฏิบัติการขายและส่งมอบได้เองหลังจากซักประวัติและประเมินผู้ป่วย โดยไม่ต้องมีใบสั่งยา ส่วนยาควบคุมพิเศษเป็นยาที่ร้านขายยาขายได้เฉพาะเมื่อมีใบสั่งยาของผู้ประกอบวิชาชีพที่กฎหมายกำหนด เช่น แพทย์หรือทันตแพทย์ แม้เภสัชกรจะประเมินว่าเหมาะสมก็ไม่มีอำนาจขายเอง\n\nIsotretinoin ชนิดรับประทานจัดเป็นยาควบคุมพิเศษ เพราะทำให้ทารกในครรภ์พิการร้ายแรงและมีอาการไม่พึงประสงค์อื่น ส่วน amoxicillin, levonorgestrel สำหรับคุมกำเนิดฉุกเฉิน, ยาเม็ดคุมกำเนิดชนิดฮอร์โมนรวม และ diclofenac ชนิดเม็ด จัดเป็นยาอันตราย ซึ่งเภสัชกรขายได้หลังจากประเมินผู้ป่วยแล้ว", "choices": [{"label": "A", "text": "Amoxicillin แคปซูล สำหรับการติดเชื้อที่ประเมินแล้วว่าเหมาะสม", "is_correct": false, "explanation": "Amoxicillin เป็นยาอันตราย เภสัชกรขายได้หลังซักประวัติและประเมินว่าเหมาะสม จึงไม่ใช่คำตอบ"}, {"label": "B", "text": "Isotretinoin แคปซูล สำหรับสิวอักเสบที่เป็นมานานหลายเดือน", "is_correct": true, "explanation": "ถูกต้อง isotretinoin ชนิดรับประทานเป็นยาควบคุมพิเศษ ร้านขายยาขายได้เฉพาะตามใบสั่งยา ไม่ว่าเภสัชกรจะประเมินผลอย่างไร"}, {"label": "C", "text": "Levonorgestrel ชนิดเม็ดคุมกำเนิดฉุกเฉิน หลังมีเพศสัมพันธ์", "is_correct": false, "explanation": "ยาคุมกำเนิดฉุกเฉิน levonorgestrel เป็นยาอันตราย เภสัชกรขายได้พร้อมให้คำแนะนำ"}, {"label": "D", "text": "ยาเม็ดคุมกำเนิดชนิดฮอร์โมนรวม สำหรับใช้คุมกำเนิดต่อเนื่อง", "is_correct": false, "explanation": "ยาเม็ดคุมกำเนิดชนิดฮอร์โมนรวมเป็นยาอันตราย เภสัชกรขายได้หลังคัดกรองข้อห้ามใช้"}, {"label": "E", "text": "Diclofenac ชนิดเม็ด สำหรับอาการปวดกล้ามเนื้อหลังออกกำลังกาย", "is_correct": false, "explanation": "Diclofenac ชนิดเม็ดเป็นยาอันตราย เภสัชกรขายได้หลังประเมินผู้ป่วย"}], "key_takeaway": "ยาอันตรายเภสัชกรขายได้เองหลังประเมินผู้ป่วย แต่ยาควบคุมพิเศษ เช่น isotretinoin ร้านขายยาขายได้เฉพาะตามใบสั่งยาเท่านั้น"}'::jsonb, 'easy', 'law-day2 • ยาควบคุมพิเศษ vs ยาอันตราย (ขายตามใบสั่งยา)'),
('4c9ac31e9cafe7be0ffb1465abfe8636', 57, 'หญิงอายุ 24 ปีนำใบสั่งยา isotretinoin ใบเดิมมาที่ร้าน ขย.1 ใบสั่งยานี้สั่งยาสำหรับ 1 เดือน และร้านได้จ่ายยาครบตามจำนวนไปแล้วเมื่อเดือนก่อน พร้อมประทับตราว่าจ่ายครบแล้ว เธอบอกว่าแพทย์เคยพูดว่าต้องใช้ยาต่ออีกหลายเดือน แต่ยังไม่มีเวลาไปพบแพทย์ จึงขอซื้อเพิ่มอีก 1 เดือน ข้อใดเป็นการปฏิบัติที่ถูกต้องที่สุด', '[{"label": "A", "text": "ขายได้ 1 เดือน เพราะเป็นยาเดิมของผู้ป่วยรายเดิม แล้วบันทึกการขายอ้างอิงใบสั่งยาใบเดิม"}, {"label": "B", "text": "ขายได้เพียงไม่กี่วันเพื่อไม่ให้การรักษาขาดช่วง แล้วแนะนำให้ไปพบแพทย์โดยเร็ว"}, {"label": "C", "text": "ขายได้ถ้าผู้ป่วยมีผลตรวจการตั้งครรภ์เป็นลบ และลงลายมือชื่อรับทราบความเสี่ยงไว้"}, {"label": "D", "text": "ไม่ขาย เพราะใบสั่งยาใช้ไปครบแล้ว ให้กลับไปพบแพทย์ และย้ำเรื่องการป้องกันการตั้งครรภ์"}, {"label": "E", "text": "ขายได้ถ้าเภสัชกรโทรศัพท์แจ้งแพทย์ไว้ก่อน แม้แพทย์จะยังไม่ได้ออกใบสั่งยาใหม่ให้"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ไม่ขาย เพราะใบสั่งยาใช้ไปครบแล้ว — การขายยาควบคุมพิเศษต้องอาศัยใบสั่งยาที่ยังไม่ได้จ่ายครบ ใบที่จ่ายครบแล้วนำมาใช้ซ้ำไม่ได้", "reason": "ร้านขายยาขายยาควบคุมพิเศษได้เฉพาะตามใบสั่งยา ใบสั่งยาที่จ่ายครบตามจำนวนแล้วถือว่าใช้ไปแล้ว นำมาเป็นหลักฐานขายซ้ำไม่ได้ คำบอกเล่าของผู้ป่วยว่าแพทย์ให้ใช้ยาต่อก็ไม่ใช่ใบสั่งยา เภสัชกรต้องให้ผู้ป่วยกลับไปพบแพทย์เพื่อรับการประเมินและใบสั่งยาใหม่\n\nกรณี isotretinoin การให้ผู้ป่วยกลับไปพบแพทย์ยังมีเหตุผลทางคลินิกด้วย เพราะยานี้ต้องติดตามผลการรักษาและอาการไม่พึงประสงค์ และผู้หญิงวัยเจริญพันธุ์ต้องป้องกันการตั้งครรภ์อย่างเคร่งครัดทั้งระหว่างใช้ยาและหลังหยุดยาระยะหนึ่ง เภสัชกรจึงควรใช้โอกาสนี้ย้ำเรื่องการคุมกำเนิดและการไม่แบ่งยาให้ผู้อื่น ผลตรวจการตั้งครรภ์หรือการเซ็นรับทราบความเสี่ยงไม่ได้ทำให้ขายยาควบคุมพิเศษโดยไม่มีใบสั่งยาได้", "choices": [{"label": "A", "text": "ขายได้ 1 เดือน เพราะเป็นยาเดิมของผู้ป่วยรายเดิม แล้วบันทึกการขายอ้างอิงใบสั่งยาใบเดิม", "is_correct": false, "explanation": "ใบสั่งยาที่จ่ายครบแล้วนำมาใช้ขายซ้ำไม่ได้ การบันทึกอ้างอิงใบเดิมเป็นการขายยาควบคุมพิเศษโดยไม่มีใบสั่งยา"}, {"label": "B", "text": "ขายได้เพียงไม่กี่วันเพื่อไม่ให้การรักษาขาดช่วง แล้วแนะนำให้ไปพบแพทย์โดยเร็ว", "is_correct": false, "explanation": "การขายแม้เพียงไม่กี่วันก็ยังเป็นการขายยาควบคุมพิเศษโดยไม่มีใบสั่งยา กฎหมายไม่มีข้อยกเว้นให้ขายเพื่อไม่ให้การรักษาขาดช่วง"}, {"label": "C", "text": "ขายได้ถ้าผู้ป่วยมีผลตรวจการตั้งครรภ์เป็นลบ และลงลายมือชื่อรับทราบความเสี่ยงไว้", "is_correct": false, "explanation": "ผลตรวจการตั้งครรภ์และการเซ็นรับทราบเป็นแนวปฏิบัติด้านความปลอดภัย แต่ใช้แทนใบสั่งยาไม่ได้"}, {"label": "D", "text": "ไม่ขาย เพราะใบสั่งยาใช้ไปครบแล้ว ให้กลับไปพบแพทย์ และย้ำเรื่องการป้องกันการตั้งครรภ์", "is_correct": true, "explanation": "ถูกต้อง ใบสั่งยาที่จ่ายครบแล้วใช้ซ้ำไม่ได้ ต้องให้ผู้ป่วยไปพบแพทย์เพื่อประเมินและรับใบสั่งยาใหม่ พร้อมแนะนำเรื่องการป้องกันการตั้งครรภ์"}, {"label": "E", "text": "ขายได้ถ้าเภสัชกรโทรศัพท์แจ้งแพทย์ไว้ก่อน แม้แพทย์จะยังไม่ได้ออกใบสั่งยาใหม่ให้", "is_correct": false, "explanation": "การโทรศัพท์แจ้งแพทย์โดยแพทย์ยังไม่ได้ออกใบสั่งยาใหม่ ไม่ทำให้มีใบสั่งยาตามที่กฎหมายกำหนด"}], "key_takeaway": "ใบสั่งยาที่จ่ายครบแล้วนำมาขายยาควบคุมพิเศษซ้ำไม่ได้ ต้องให้ผู้ป่วยกลับไปพบแพทย์เพื่อรับใบสั่งยาใหม่"}'::jsonb, 'hard', 'law-day2 • ยาควบคุมพิเศษ: การใช้ใบสั่งยาซ้ำ (isotretinoin)'),
('d506565328f701e59a92c8c3b5fdda8a', 58, 'ผู้ป่วยนำใบสั่งยาจากคลินิกเวชกรรมมาที่ร้าน ขย.1 ใบสั่งยามีชื่อคลินิก ชื่อและลายมือชื่อแพทย์ ชื่อผู้ป่วย วันที่ ชื่อยา และจำนวน แต่ไม่ได้ระบุความแรงและวิธีใช้ โดยยานี้มีจำหน่ายสองความแรง ข้อใดเป็นการปฏิบัติที่ถูกต้องที่สุด', '[{"label": "A", "text": "ติดต่อแพทย์ผู้สั่งเพื่อยืนยันความแรงและวิธีใช้ แล้วบันทึกผลการยืนยันไว้ก่อนส่งมอบยา"}, {"label": "B", "text": "จ่ายยาความแรงต่ำกว่าไว้ก่อนเพื่อความปลอดภัย แล้วให้ผู้ป่วยกลับไปถามแพทย์เอง"}, {"label": "C", "text": "ถามผู้ป่วยว่าเคยใช้ความแรงใด แล้วจ่ายยาตามที่ผู้ป่วยบอกโดยไม่ต้องติดต่อแพทย์"}, {"label": "D", "text": "จ่ายความแรงที่ร้านมีในสต็อก และเขียนวิธีใช้ตามขนาดยามาตรฐานในตำราลงบนฉลากยา"}, {"label": "E", "text": "คืนใบสั่งยาให้ผู้ป่วยทันทีโดยไม่ดำเนินการใด ๆ เพราะใบสั่งยาไม่ครบถ้วนจึงใช้ไม่ได้"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ติดต่อแพทย์ผู้สั่งเพื่อยืนยัน — เมื่อใบสั่งยาขาดข้อมูลสำคัญ เภสัชกรต้องยืนยันกับผู้สั่งใช้ยา ไม่ใช้วิธีเดาหรือเลือกเอง", "reason": "ใบสั่งยาที่สมบูรณ์ควรมีข้อมูลผู้สั่งใช้ยาและสถานพยาบาล ชื่อผู้ป่วย วันที่ ชื่อยา ความแรง รูปแบบยา จำนวน วิธีใช้ และลายมือชื่อผู้สั่ง เมื่อขาดข้อมูลที่มีผลต่อความปลอดภัยของผู้ป่วย เช่น ความแรงของยาที่มีหลายขนาด หรือวิธีใช้ เภสัชกรต้องติดต่อผู้สั่งใช้ยาเพื่อยืนยันก่อนส่งมอบยา และบันทึกสิ่งที่ยืนยัน (ชื่อผู้ยืนยัน วันเวลา สิ่งที่แก้ไข) ไว้เป็นหลักฐาน\n\nการเลือกความแรงเอง การเชื่อตามคำบอกเล่าของผู้ป่วย หรือใช้ขนาดยามาตรฐานจากตำรา เท่ากับเภสัชกรเปลี่ยนคำสั่งการรักษาเองโดยไม่มีข้อมูลยืนยัน ส่วนการคืนใบสั่งยาโดยไม่ดำเนินการใดเลยไม่ได้ช่วยแก้ปัญหาให้ผู้ป่วย และไม่ใช่สิ่งที่วิชาชีพคาดหวัง", "choices": [{"label": "A", "text": "ติดต่อแพทย์ผู้สั่งเพื่อยืนยันความแรงและวิธีใช้ แล้วบันทึกผลการยืนยันไว้ก่อนส่งมอบยา", "is_correct": true, "explanation": "ถูกต้อง การยืนยันกับผู้สั่งใช้ยาและบันทึกไว้เป็นแนวปฏิบัติมาตรฐานเมื่อใบสั่งยาขาดข้อมูลสำคัญ"}, {"label": "B", "text": "จ่ายยาความแรงต่ำกว่าไว้ก่อนเพื่อความปลอดภัย แล้วให้ผู้ป่วยกลับไปถามแพทย์เอง", "is_correct": false, "explanation": "การจ่ายความแรงต่ำไว้ก่อนเป็นการเดา ผู้ป่วยอาจได้รับการรักษาไม่เพียงพอ และเภสัชกรไม่ได้แก้ปัญหาที่ต้นเหตุ"}, {"label": "C", "text": "ถามผู้ป่วยว่าเคยใช้ความแรงใด แล้วจ่ายยาตามที่ผู้ป่วยบอกโดยไม่ต้องติดต่อแพทย์", "is_correct": false, "explanation": "คำบอกเล่าของผู้ป่วยอาจคลาดเคลื่อน ใช้แทนการยืนยันกับผู้สั่งใช้ยาไม่ได้"}, {"label": "D", "text": "จ่ายความแรงที่ร้านมีในสต็อก และเขียนวิธีใช้ตามขนาดยามาตรฐานในตำราลงบนฉลากยา", "is_correct": false, "explanation": "การเลือกตามสต็อกและใช้ขนาดยาจากตำราเป็นการเปลี่ยนคำสั่งการรักษาเองโดยไม่มีข้อมูลยืนยัน"}, {"label": "E", "text": "คืนใบสั่งยาให้ผู้ป่วยทันทีโดยไม่ดำเนินการใด ๆ เพราะใบสั่งยาไม่ครบถ้วนจึงใช้ไม่ได้", "is_correct": false, "explanation": "เภสัชกรควรพยายามติดต่อผู้สั่งใช้ยาเพื่อแก้ไขปัญหาก่อน การคืนใบสั่งยาทันทีไม่ใช่แนวปฏิบัติที่เหมาะสม"}], "key_takeaway": "เมื่อใบสั่งยาขาดข้อมูลสำคัญ เภสัชกรต้องติดต่อผู้สั่งใช้ยาเพื่อยืนยันและบันทึกไว้ ห้ามเดาหรือเลือกเอง"}'::jsonb, 'medium', 'law-day2 • ใบสั่งยาที่ข้อมูลไม่ครบถ้วน'),
('5582b2475d167514226ac71891c53290', 59, 'ร้านขายยา ขย.1 ได้รับใบสั่งยาหลายใบในวันเดียวกัน แต่ละใบสั่งยาซึ่งจัดเป็นยาควบคุมพิเศษ ใบสั่งยาข้อใดที่เภสัชกรไม่สามารถใช้เป็นหลักฐานในการขายยาควบคุมพิเศษได้', '[{"label": "A", "text": "ใบสั่งยาจากแพทย์ที่คลินิกเวชกรรมในต่างจังหวัด ซึ่งข้อมูลครบถ้วนและยืนยันตัวแพทย์ได้"}, {"label": "B", "text": "ใบสั่งยาจากทันตแพทย์สำหรับการรักษาทางทันตกรรมของผู้ป่วย ซึ่งข้อมูลครบถ้วน"}, {"label": "C", "text": "ใบสั่งยาจากแพทย์โรงพยาบาลรัฐที่ห้องยาโรงพยาบาลไม่มียานี้ ผู้ป่วยจึงนำมาซื้อที่ร้าน"}, {"label": "D", "text": "ใบสั่งยาที่แพทย์ออกให้ผู้ป่วยถูกต้องครบถ้วน แต่ญาติเป็นผู้ถือมาซื้อยาแทนผู้ป่วย"}, {"label": "E", "text": "ใบสั่งยาที่พยาบาลวิชาชีพประจำ รพ.สต. เขียนและลงลายมือชื่อพยาบาลเพียงผู้เดียว"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ใบสั่งยาที่พยาบาลวิชาชีพเขียนเพียงผู้เดียว — ใบสั่งยาสำหรับยาควบคุมพิเศษต้องออกโดยผู้ประกอบวิชาชีพที่กฎหมายกำหนด เช่น แพทย์หรือทันตแพทย์ พยาบาลไม่อยู่ในกลุ่มนี้", "reason": "พ.ร.บ.ยา ให้ร้านขายยาขายยาควบคุมพิเศษได้เฉพาะตามใบสั่งยาของผู้ประกอบวิชาชีพที่กฎหมายกำหนด ได้แก่ ผู้ประกอบวิชาชีพเวชกรรม ผู้ประกอบวิชาชีพทันตกรรม และผู้ประกอบวิชาชีพการสัตวแพทย์ (สำหรับสัตว์) รวมถึงผู้ประกอบโรคศิลปะตามที่กฎหมายกำหนด พยาบาลวิชาชีพแม้จะได้รับมอบหมายให้รักษาโรคเบื้องต้นและจ่ายยาตามขอบเขตที่สภาการพยาบาลกำหนดในหน่วยบริการของตน แต่ไม่มีสิทธิออกใบสั่งยาเพื่อให้ร้านขายยาขายยาควบคุมพิเศษ\n\nใบสั่งยาจากแพทย์ในจังหวัดอื่นหรือแพทย์โรงพยาบาลรัฐใช้ได้ถ้าข้อมูลครบและตรวจสอบได้ ทันตแพทย์สั่งยาได้ในขอบเขตทันตกรรม ส่วนการให้ญาติถือใบสั่งยามาซื้อแทน กฎหมายไม่ได้ห้าม แต่เภสัชกรควรตรวจสอบข้อมูลผู้ป่วยและให้คำแนะนำการใช้ยาให้ถึงผู้ป่วย", "choices": [{"label": "A", "text": "ใบสั่งยาจากแพทย์ที่คลินิกเวชกรรมในต่างจังหวัด ซึ่งข้อมูลครบถ้วนและยืนยันตัวแพทย์ได้", "is_correct": false, "explanation": "แพทย์ในต่างจังหวัดเป็นผู้ประกอบวิชาชีพเวชกรรม ใบสั่งยาใช้ได้ถ้าข้อมูลครบและตรวจสอบได้"}, {"label": "B", "text": "ใบสั่งยาจากทันตแพทย์สำหรับการรักษาทางทันตกรรมของผู้ป่วย ซึ่งข้อมูลครบถ้วน", "is_correct": false, "explanation": "ทันตแพทย์เป็นผู้ประกอบวิชาชีพที่ออกใบสั่งยาได้ในขอบเขตการรักษาทางทันตกรรม"}, {"label": "C", "text": "ใบสั่งยาจากแพทย์โรงพยาบาลรัฐที่ห้องยาโรงพยาบาลไม่มียานี้ ผู้ป่วยจึงนำมาซื้อที่ร้าน", "is_correct": false, "explanation": "ใบสั่งยาจากแพทย์โรงพยาบาลรัฐใช้ซื้อยาที่ร้านขายยาได้ ไม่จำเป็นต้องรับยาที่โรงพยาบาลเท่านั้น"}, {"label": "D", "text": "ใบสั่งยาที่แพทย์ออกให้ผู้ป่วยถูกต้องครบถ้วน แต่ญาติเป็นผู้ถือมาซื้อยาแทนผู้ป่วย", "is_correct": false, "explanation": "กฎหมายไม่ได้ห้ามญาติถือใบสั่งยามาซื้อแทน เภสัชกรควรตรวจสอบและให้คำแนะนำการใช้ยาให้ถึงผู้ป่วย"}, {"label": "E", "text": "ใบสั่งยาที่พยาบาลวิชาชีพประจำ รพ.สต. เขียนและลงลายมือชื่อพยาบาลเพียงผู้เดียว", "is_correct": true, "explanation": "ถูกต้อง พยาบาลวิชาชีพไม่อยู่ในกลุ่มผู้ที่ออกใบสั่งยาเพื่อให้ร้านขายยาขายยาควบคุมพิเศษได้"}], "key_takeaway": "ร้านขายยาขายยาควบคุมพิเศษได้เฉพาะตามใบสั่งยาของผู้ประกอบวิชาชีพที่กฎหมายกำหนด เช่น แพทย์หรือทันตแพทย์ ใบสั่งยาที่พยาบาลออกเองใช้ไม่ได้"}'::jsonb, 'medium', 'law-day2 • ผู้มีสิทธิออกใบสั่งยาควบคุมพิเศษ'),
('11ef3a6a0c35a5e170fdf7aa896367de', 60, 'ร้านขายยา ขย.1 มีเภสัชกรผู้มีหน้าที่ปฏิบัติการอยู่ปฏิบัติงาน และมีผู้ช่วยเภสัชกรที่ผ่านการอบรมแล้วอีก 1 คน งานใดที่มอบหมายให้ผู้ช่วยเภสัชกรทำได้ภายใต้การกำกับของเภสัชกร', '[{"label": "A", "text": "ตรวจสอบใบสั่งยาควบคุมพิเศษและส่งมอบยาให้ผู้ป่วยแทนเภสัชกรขณะที่ร้านมีลูกค้ามาก"}, {"label": "B", "text": "ซักประวัติลูกค้าที่ขอซื้อยาปฏิชีวนะ แล้วเลือกและส่งมอบยาอันตรายให้ลูกค้าเอง"}, {"label": "C", "text": "ตรวจรับยาเข้าร้าน จัดเรียงยาบนชั้นตามวันสิ้นอายุ และนับสต็อกยาตามที่เภสัชกรมอบหมาย"}, {"label": "D", "text": "ให้คำแนะนำการใช้ยาเม็ดคุมกำเนิดฉุกเฉินแก่ลูกค้าแทนเภสัชกรที่กำลังพักรับประทานอาหาร"}, {"label": "E", "text": "ลงลายมือชื่อในบัญชีการขายยาควบคุมพิเศษในฐานะผู้ส่งมอบยาแทนเภสัชกรผู้มีหน้าที่ฯ"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ตรวจรับยา จัดเรียงตามวันสิ้นอายุ และนับสต็อก — งานสนับสนุนด้านการจัดการยามอบหมายได้ แต่การคัดกรองผู้ป่วย การตรวจใบสั่งยา และการส่งมอบยาอันตรายหรือยาควบคุมพิเศษเป็นงานของเภสัชกร", "reason": "ผู้ช่วยเภสัชกรช่วยงานในร้านขายยาได้ภายใต้การกำกับของเภสัชกร เช่น ตรวจรับสินค้า จัดเรียงยาตามหลัก FEFO นับสต็อก ทำความสะอาด และเตรียมยาตามที่เภสัชกรมอบหมาย แต่งานที่ต้องใช้วิจารณญาณทางวิชาชีพเภสัชกรรม คือ การซักประวัติและประเมินผู้ป่วยเพื่อเลือกยาอันตราย การตรวจสอบใบสั่งยา การส่งมอบยาอันตรายและยาควบคุมพิเศษ และการให้คำแนะนำการใช้ยา เป็นหน้าที่ของเภสัชกรผู้มีหน้าที่ปฏิบัติการ\n\nข้อนี้ต่างจากกรณีที่เภสัชกรไม่อยู่ร้าน แม้เภสัชกรอยู่ในร้าน ก็ยังมอบงานเฉพาะของวิชาชีพให้ผู้ช่วยทำแทนไม่ได้ ไม่ว่าจะลูกค้ามากหรือเภสัชกรติดภารกิจ", "choices": [{"label": "A", "text": "ตรวจสอบใบสั่งยาควบคุมพิเศษและส่งมอบยาให้ผู้ป่วยแทนเภสัชกรขณะที่ร้านมีลูกค้ามาก", "is_correct": false, "explanation": "การตรวจใบสั่งยาและส่งมอบยาควบคุมพิเศษเป็นหน้าที่ของเภสัชกร ลูกค้ามากก็ไม่ใช่เหตุให้มอบหมายได้"}, {"label": "B", "text": "ซักประวัติลูกค้าที่ขอซื้อยาปฏิชีวนะ แล้วเลือกและส่งมอบยาอันตรายให้ลูกค้าเอง", "is_correct": false, "explanation": "การซักประวัติเพื่อเลือกยาอันตรายและส่งมอบยาเป็นงานของเภสัชกร"}, {"label": "C", "text": "ตรวจรับยาเข้าร้าน จัดเรียงยาบนชั้นตามวันสิ้นอายุ และนับสต็อกยาตามที่เภสัชกรมอบหมาย", "is_correct": true, "explanation": "ถูกต้อง งานด้านการจัดการคลังยาเป็นงานสนับสนุนที่มอบหมายให้ผู้ช่วยทำได้ภายใต้การกำกับของเภสัชกร"}, {"label": "D", "text": "ให้คำแนะนำการใช้ยาเม็ดคุมกำเนิดฉุกเฉินแก่ลูกค้าแทนเภสัชกรที่กำลังพักรับประทานอาหาร", "is_correct": false, "explanation": "ยาเม็ดคุมกำเนิดฉุกเฉินเป็นยาอันตราย การให้คำแนะนำและส่งมอบต้องทำโดยเภสัชกร"}, {"label": "E", "text": "ลงลายมือชื่อในบัญชีการขายยาควบคุมพิเศษในฐานะผู้ส่งมอบยาแทนเภสัชกรผู้มีหน้าที่ฯ", "is_correct": false, "explanation": "การลงนามเป็นผู้ส่งมอบยาควบคุมพิเศษต้องเป็นเภสัชกรผู้ส่งมอบจริง การลงนามแทนทำให้บันทึกไม่ถูกต้อง"}], "key_takeaway": "ผู้ช่วยเภสัชกรช่วยงานคลังและงานสนับสนุนได้ แต่การประเมินผู้ป่วย การตรวจใบสั่งยา และการส่งมอบยาอันตรายหรือยาควบคุมพิเศษเป็นงานของเภสัชกร"}'::jsonb, 'easy', 'law-day2 • ขอบเขตงานผู้ช่วยเภสัชกร'),
('4de0b109fb912f3135797cd776371ce2', 61, 'เด็กชายอายุประมาณ 12 ปีเดินเข้ามาที่ร้าน ขย.1 พร้อมกระดาษที่ยายเขียนว่า "ยาแก้อักเสบ 1 แผง" เด็กบอกว่ายายเจ็บคอมา 2 วันแต่ไม่รู้รายละเอียดอื่น เภสัชกรควรปฏิบัติอย่างไรจึงเหมาะสมที่สุด', '[{"label": "A", "text": "ขายยาปฏิชีวนะที่ใช้บ่อยได้ทันที เพราะ พ.ร.บ.ยา ไม่ได้กำหนดอายุขั้นต่ำของผู้ซื้อยาอันตราย"}, {"label": "B", "text": "ติดต่อสอบถามอาการจากยายหรือผู้ดูแลโดยตรงก่อน ถ้าประเมินไม่ได้จึงให้ผู้ป่วยมาพบเภสัชกร"}, {"label": "C", "text": "ปฏิเสธการขายทุกกรณี เพราะ พ.ร.บ.ยา ห้ามขายยาทุกชนิดให้ผู้ที่อายุต่ำกว่า 18 ปี"}, {"label": "D", "text": "ขายยาได้ถ้าเด็กลงชื่อในสมุดบันทึกการขาย และระบุชื่อยายเป็นผู้ใช้ยาไว้เป็นหลักฐาน"}, {"label": "E", "text": "ให้ผู้ช่วยเภสัชกรเลือกยาให้ตามที่ยายเขียนมา เพราะยายเป็นผู้ระบุยาเองแล้วตั้งแต่ต้น"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. สอบถามจากผู้ป่วยหรือผู้ดูแลโดยตรงก่อน — ยาอันตรายต้องส่งมอบหลังเภสัชกรประเมินผู้ป่วยตัวจริงได้ เมื่อข้อมูลไม่พอต้องหาข้อมูลจากผู้ป่วยก่อน", "reason": "พ.ร.บ.ยา ไม่ได้มีบทบัญญัติทั่วไปที่ห้ามขายยาทุกชนิดให้ผู้เยาว์ แต่ยาอันตรายต้องขายโดยเภสัชกรซึ่งต้องประเมินผู้ป่วยตามมาตรฐานวิชาชีพ ในกรณีนี้ผู้ป่วยตัวจริงคือยาย และเด็กให้ข้อมูลได้น้อยมาก ทั้งอาการ โรคประจำตัว ประวัติแพ้ยา และยาที่ใช้อยู่ คำว่า \"ยาแก้อักเสบ\" ก็อาจหมายถึงยาปฏิชีวนะหรือยาต้านการอักเสบ และอาการเจ็บคออาจไม่จำเป็นต้องใช้ยาปฏิชีวนะเลย\n\nแนวปฏิบัติที่เหมาะสมคือ ติดต่อยายหรือผู้ดูแลโดยตรง เช่น ทางโทรศัพท์ เพื่อซักประวัติให้พอประเมินได้ ถ้ายังประเมินไม่ได้ก็ไม่ควรส่งมอบยาอันตราย และแนะนำให้ผู้ป่วยมาพบเภสัชกรหรือแพทย์ การให้เด็กลงชื่อหรือการที่ผู้ซื้อระบุชื่อยามาเองใช้แทนการประเมินไม่ได้", "choices": [{"label": "A", "text": "ขายยาปฏิชีวนะที่ใช้บ่อยได้ทันที เพราะ พ.ร.บ.ยา ไม่ได้กำหนดอายุขั้นต่ำของผู้ซื้อยาอันตราย", "is_correct": false, "explanation": "แม้ไม่มีอายุขั้นต่ำของผู้ซื้อ แต่การขายยาอันตรายโดยไม่ได้ประเมินผู้ป่วยตัวจริงขัดกับมาตรฐานวิชาชีพ"}, {"label": "B", "text": "ติดต่อสอบถามอาการจากยายหรือผู้ดูแลโดยตรงก่อน ถ้าประเมินไม่ได้จึงให้ผู้ป่วยมาพบเภสัชกร", "is_correct": true, "explanation": "ถูกต้อง เภสัชกรควรได้ข้อมูลจากผู้ป่วยหรือผู้ดูแลโดยตรงก่อน ถ้าประเมินไม่ได้ก็ไม่ควรส่งมอบยาอันตราย"}, {"label": "C", "text": "ปฏิเสธการขายทุกกรณี เพราะ พ.ร.บ.ยา ห้ามขายยาทุกชนิดให้ผู้ที่อายุต่ำกว่า 18 ปี", "is_correct": false, "explanation": "พ.ร.บ.ยา ไม่มีข้อห้ามทั่วไปเรื่องการขายยาทุกชนิดให้ผู้ที่อายุต่ำกว่า 18 ปี ข้อนี้จึงอ้างกฎหมายผิด"}, {"label": "D", "text": "ขายยาได้ถ้าเด็กลงชื่อในสมุดบันทึกการขาย และระบุชื่อยายเป็นผู้ใช้ยาไว้เป็นหลักฐาน", "is_correct": false, "explanation": "การลงชื่อเป็นเพียงเอกสาร ไม่ได้ทำให้เภสัชกรได้ข้อมูลพอจะประเมินผู้ป่วย"}, {"label": "E", "text": "ให้ผู้ช่วยเภสัชกรเลือกยาให้ตามที่ยายเขียนมา เพราะยายเป็นผู้ระบุยาเองแล้วตั้งแต่ต้น", "is_correct": false, "explanation": "การเลือกและส่งมอบยาอันตรายเป็นหน้าที่ของเภสัชกร และคำว่า \"ยาแก้อักเสบ\" ที่ผู้ซื้อเขียนมาไม่ใช่การวินิจฉัย"}], "key_takeaway": "เมื่อผู้ซื้อไม่ใช่ผู้ป่วยและให้ข้อมูลได้ไม่พอ เภสัชกรต้องหาข้อมูลจากผู้ป่วยตัวจริงก่อนส่งมอบยาอันตราย"}'::jsonb, 'medium', 'law-day2 • การขายยาให้ผู้เยาว์/บุคคลที่สาม'),
('3a20f06343b8636c41e8d2e3d70fb9d5', 62, 'ตัวแทนจำหน่ายรายหนึ่งเสนอขายผลิตภัณฑ์สมุนไพรแก้ปวดเมื่อยชนิดเม็ดลูกกลอนให้ร้าน ขย.1 โดยอ้างว่า "เห็นผลเร็ว ลูกค้าติดใจ" ต่อมาร้านพบประกาศของ อย. ว่าผลิตภัณฑ์ยี่ห้อนี้ตรวจพบสารสเตียรอยด์ (dexamethasone) ปนอยู่ เภสัชกรควรปฏิบัติอย่างไร', '[{"label": "A", "text": "ไม่รับหรือไม่จำหน่ายผลิตภัณฑ์นี้ แยกของที่มีอยู่ออกจากชั้นขาย และแจ้ง อย. หรือ สสจ."}, {"label": "B", "text": "จำหน่ายได้ต่อไปถ้าผลิตภัณฑ์มีเลขทะเบียน แต่ต้องแนะนำให้ลูกค้ากินไม่เกินวันละครั้ง"}, {"label": "C", "text": "จำหน่ายได้เฉพาะเมื่อเภสัชกรซักประวัติและเห็นว่าลูกค้าไม่มีโรคประจำตัวที่เป็นข้อห้ามใช้"}, {"label": "D", "text": "ย้ายผลิตภัณฑ์ไปไว้หลังเคาน์เตอร์และขายได้เฉพาะลูกค้าประจำที่เคยใช้แล้วไม่มีปัญหา"}, {"label": "E", "text": "ลดราคาเพื่อระบายสต็อกที่มีอยู่ให้หมดโดยเร็ว แล้วหยุดสั่งผลิตภัณฑ์นี้เพิ่มในครั้งต่อไป"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ไม่จำหน่าย แยกออกจากชั้นขาย และแจ้งหน่วยงาน — ผลิตภัณฑ์สมุนไพรที่ปลอมปนยาแผนปัจจุบันเป็นผลิตภัณฑ์ผิดกฎหมายที่ห้ามขาย และเป็นอันตรายต่อผู้บริโภค", "reason": "ผลิตภัณฑ์แผนโบราณหรือผลิตภัณฑ์สมุนไพรที่ลักลอบใส่สเตียรอยด์เป็นปัญหาที่ อย. เตือนอยู่บ่อยครั้ง ผู้ใช้ต่อเนื่องอาจเกิดกลุ่มอาการคุชชิง ภาวะต่อมหมวกไตกดการทำงาน การติดเชื้อ และเลือดออกในทางเดินอาหาร ผลิตภัณฑ์ที่มีส่วนประกอบไม่ตรงกับที่ขึ้นทะเบียนหรือจดแจ้งไว้ถือเป็นผลิตภัณฑ์ปลอมหรือผิดกฎหมายตามกฎหมายที่กำกับผลิตภัณฑ์นั้น (ปัจจุบันผลิตภัณฑ์สมุนไพรอยู่ภายใต้ พ.ร.บ.ผลิตภัณฑ์สมุนไพร พ.ศ. 2562) ผู้ขายจึงมีความผิดด้วยแม้จะไม่ได้เป็นผู้ผลิต\n\nเภสัชกรต้องไม่รับหรือไม่จำหน่ายผลิตภัณฑ์นี้ แยกของที่มีอยู่ออกจากพื้นที่ขายพร้อมทำป้ายห้ามจำหน่าย แจ้งหน่วยงานที่กำกับดูแล และถ้ารู้ว่ามีลูกค้าซื้อไปแล้ว ควรแนะนำให้หยุดใช้และพบแพทย์ ไม่ควรให้หยุดเองทันทีถ้าใช้มานาน เพราะอาจเกิดภาวะขาดสเตียรอยด์", "choices": [{"label": "A", "text": "ไม่รับหรือไม่จำหน่ายผลิตภัณฑ์นี้ แยกของที่มีอยู่ออกจากชั้นขาย และแจ้ง อย. หรือ สสจ.", "is_correct": true, "explanation": "ถูกต้อง ต้องไม่จำหน่าย แยกของออกจากพื้นที่ขาย และแจ้งหน่วยงานที่กำกับดูแล"}, {"label": "B", "text": "จำหน่ายได้ต่อไปถ้าผลิตภัณฑ์มีเลขทะเบียน แต่ต้องแนะนำให้ลูกค้ากินไม่เกินวันละครั้ง", "is_correct": false, "explanation": "เลขทะเบียนไม่ได้ทำให้ผลิตภัณฑ์ที่ตรวจพบสารปลอมปนกลายเป็นของถูกกฎหมาย การจำกัดขนาดรับประทานก็ไม่ได้แก้ปัญหา"}, {"label": "C", "text": "จำหน่ายได้เฉพาะเมื่อเภสัชกรซักประวัติและเห็นว่าลูกค้าไม่มีโรคประจำตัวที่เป็นข้อห้ามใช้", "is_correct": false, "explanation": "การคัดกรองลูกค้าไม่ทำให้ขายผลิตภัณฑ์ที่ผิดกฎหมายได้"}, {"label": "D", "text": "ย้ายผลิตภัณฑ์ไปไว้หลังเคาน์เตอร์และขายได้เฉพาะลูกค้าประจำที่เคยใช้แล้วไม่มีปัญหา", "is_correct": false, "explanation": "การย้ายไปหลังเคาน์เตอร์และขายเฉพาะลูกค้าประจำก็ยังเป็นการจำหน่ายผลิตภัณฑ์ผิดกฎหมาย"}, {"label": "E", "text": "ลดราคาเพื่อระบายสต็อกที่มีอยู่ให้หมดโดยเร็ว แล้วหยุดสั่งผลิตภัณฑ์นี้เพิ่มในครั้งต่อไป", "is_correct": false, "explanation": "การระบายสต็อกที่รู้ว่าปลอมปนเป็นการจงใจจำหน่ายผลิตภัณฑ์ผิดกฎหมาย และทำให้ผู้บริโภคได้รับอันตราย"}], "key_takeaway": "ผลิตภัณฑ์สมุนไพรที่ตรวจพบสเตียรอยด์ปลอมปนต้องไม่จำหน่าย ต้องแยกออกจากพื้นที่ขายและแจ้งหน่วยงานที่กำกับดูแล"}'::jsonb, 'easy', 'law-day2 • การปฏิเสธจำหน่ายผลิตภัณฑ์สมุนไพรปลอมปนสเตียรอยด์'),
('29f50ad5c32dab824d01adab93fc7f55', 63, 'ผู้ป่วยโรคเรื้อรังนำใบสั่งยามาซื้อยาที่ร้าน ขย.1 ตามใบสั่งต้องใช้ยาต่อเนื่อง 3 เดือน ยาที่มีในร้านขณะนั้นเป็นล็อตเดียวกันทั้งหมด และจะสิ้นอายุในอีก 1 เดือน ข้อใดเป็นการปฏิบัติที่ถูกต้องที่สุด', '[{"label": "A", "text": "จ่ายยาครบ 3 เดือนจากล็อตนี้ได้ เพราะวันที่ส่งมอบยายังไม่ถึงวันสิ้นอายุตามฉลาก"}, {"label": "B", "text": "จ่ายยาครบ 3 เดือนจากล็อตนี้ และบอกผู้ป่วยว่ายาหลังวันสิ้นอายุยังใช้ได้อีกระยะหนึ่ง"}, {"label": "C", "text": "แก้ไขวันสิ้นอายุบนฉลากที่ร้านพิมพ์ให้ยาวขึ้น เพื่อให้สอดคล้องกับระยะเวลาการใช้ยา"}, {"label": "D", "text": "จ่ายเฉพาะจำนวนที่ใช้หมดก่อนวันสิ้นอายุ แจ้งผู้ป่วย แล้วจัดหายาล็อตใหม่ให้ส่วนที่เหลือ"}, {"label": "E", "text": "ปฏิเสธการจ่ายยาทั้งหมด และให้ผู้ป่วยกลับไปรับยาที่โรงพยาบาลแทนการซื้อที่ร้าน"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. จ่ายเฉพาะจำนวนที่ใช้หมดก่อนวันสิ้นอายุ — การส่งมอบยาที่รู้ว่าจะสิ้นอายุระหว่างที่ผู้ป่วยยังใช้อยู่ ทำให้ผู้ป่วยต้องใช้ยาเสื่อมคุณภาพ", "reason": "ยาที่พ้นวันสิ้นอายุตามฉลากถือเป็นยาเสื่อมคุณภาพตาม พ.ร.บ.ยา และห้ามขาย แม้วันส่งมอบยายังไม่ถึงวันสิ้นอายุ แต่ถ้าเภสัชกรรู้ว่าผู้ป่วยจะต้องใช้ยาต่อไปหลังวันนั้นอีก 2 เดือน ก็เท่ากับปล่อยให้ผู้ป่วยใช้ยาเสื่อมคุณภาพ ซึ่งขัดกับหน้าที่ดูแลความปลอดภัยของผู้ป่วยตามมาตรฐานวิชาชีพ\n\nแนวปฏิบัติที่เหมาะสมคือ ส่งมอบเฉพาะจำนวนที่ใช้หมดก่อนวันสิ้นอายุ แจ้งผู้ป่วยให้ชัดเจน และนัดรับยาล็อตใหม่ (หรือส่งต่อให้ร้านที่มียา) สำหรับส่วนที่เหลือ ในระดับร้าน ควรใช้หลัก FEFO ติดตามยาใกล้หมดอายุเป็นประจำ และติดต่อคืนยาให้ผู้จำหน่ายตามเงื่อนไขก่อนยาจะสิ้นอายุ การแก้ไขวันสิ้นอายุให้ยาวขึ้นเป็นการแสดงข้อมูลเท็จ และอาจเข้าข่ายยาปลอม", "choices": [{"label": "A", "text": "จ่ายยาครบ 3 เดือนจากล็อตนี้ได้ เพราะวันที่ส่งมอบยายังไม่ถึงวันสิ้นอายุตามฉลาก", "is_correct": false, "explanation": "วันส่งมอบยายังไม่ถึงวันสิ้นอายุก็จริง แต่ผู้ป่วยจะต้องใช้ยาหลังวันสิ้นอายุอีก 2 เดือน ซึ่งไม่ปลอดภัยและขัดกับมาตรฐานวิชาชีพ"}, {"label": "B", "text": "จ่ายยาครบ 3 เดือนจากล็อตนี้ และบอกผู้ป่วยว่ายาหลังวันสิ้นอายุยังใช้ได้อีกระยะหนึ่ง", "is_correct": false, "explanation": "การบอกว่ายาหลังวันสิ้นอายุยังใช้ได้เป็นข้อมูลที่ไม่ถูกต้อง และยิ่งทำให้ผู้ป่วยใช้ยาเสื่อมคุณภาพ"}, {"label": "C", "text": "แก้ไขวันสิ้นอายุบนฉลากที่ร้านพิมพ์ให้ยาวขึ้น เพื่อให้สอดคล้องกับระยะเวลาการใช้ยา", "is_correct": false, "explanation": "การแสดงวันสิ้นอายุที่ยาวกว่าจริงเป็นการแสดงข้อมูลเท็จ และอาจเข้าข่ายยาปลอม"}, {"label": "D", "text": "จ่ายเฉพาะจำนวนที่ใช้หมดก่อนวันสิ้นอายุ แจ้งผู้ป่วย แล้วจัดหายาล็อตใหม่ให้ส่วนที่เหลือ", "is_correct": true, "explanation": "ถูกต้อง ส่งมอบเฉพาะจำนวนที่ใช้หมดก่อนวันสิ้นอายุ แจ้งผู้ป่วย และจัดหายาล็อตใหม่ให้ส่วนที่เหลือ"}, {"label": "E", "text": "ปฏิเสธการจ่ายยาทั้งหมด และให้ผู้ป่วยกลับไปรับยาที่โรงพยาบาลแทนการซื้อที่ร้าน", "is_correct": false, "explanation": "ยาส่วนที่ใช้ได้ก่อนวันสิ้นอายุยังจ่ายได้ การปฏิเสธทั้งหมดทำให้ผู้ป่วยขาดยาโดยไม่จำเป็น"}], "key_takeaway": "การส่งมอบยาต้องคำนึงว่ายาจะยังไม่สิ้นอายุตลอดช่วงที่ผู้ป่วยใช้ ไม่ใช่ดูแค่ว่าวันที่ส่งมอบยายังไม่หมดอายุ"}'::jsonb, 'medium', 'law-day2 • การจัดการยาใกล้หมดอายุเมื่อส่งมอบ'),
('8bdba51cbecca3f8a60e41928bd125c3', 64, 'ร้านขายยา ขย.1 แห่งหนึ่งได้รับข้อเสนอให้ซื้อยาราคาถูกจากหลายช่องทาง ช่องทางใดที่ร้านควรซื้อยาเข้าร้านจึงถูกต้องตามกฎหมายและมาตรฐานร้านยา', '[{"label": "A", "text": "บุคคลในกลุ่มไลน์ที่ขายยาเหลือใช้จากโรงพยาบาลแห่งหนึ่ง โดยยังไม่เปิดกล่องและไม่หมดอายุ"}, {"label": "B", "text": "คลินิกเวชกรรมที่กำลังจะปิดกิจการและต้องการระบายยาที่เหลือในสต็อกให้หมดโดยเร็ว"}, {"label": "C", "text": "ผู้รับอนุญาตผลิต นำเข้า หรือขายส่งยา ที่ออกใบส่งของหรือใบกำกับภาษีให้ตรวจสอบย้อนกลับได้"}, {"label": "D", "text": "ผู้แทนยาที่นำยาตัวอย่าง (sample) ที่บริษัทแจกให้แพทย์มาขายต่อในราคาต่ำกว่าท้องตลาด"}, {"label": "E", "text": "ผู้ที่หิ้วยาจากต่างประเทศมาขาย โดยเป็นยาที่มีตัวยาสำคัญเดียวกับยาที่ขึ้นทะเบียนในไทย"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ผู้รับอนุญาตผลิต นำเข้า หรือขายส่งยา พร้อมเอกสารการซื้อ — ร้านขายยาต้องซื้อยาจากผู้ได้รับอนุญาตที่ตรวจสอบย้อนกลับได้ เพื่อยืนยันแหล่งที่มาและคุณภาพของยา", "reason": "มาตรฐานร้านขายยา (GPP) กำหนดให้ร้านจัดซื้อยาจากผู้รับอนุญาตผลิต นำเข้า หรือขายส่งยาที่ถูกต้องตามกฎหมาย และเก็บหลักฐานการซื้อ เช่น ใบส่งของหรือใบกำกับภาษี ซึ่งต้องใช้ทำบัญชีการซื้อยาและใช้ตรวจสอบย้อนกลับเมื่อมีการเรียกคืนยา\n\nยาจากบุคคลทั่วไป ยาเหลือใช้ ยาตัวอย่าง หรือยาจากคลินิกที่ปิดกิจการ เป็นยาที่ไม่รู้ว่าเก็บรักษามาอย่างไร อาจเป็นยาที่ได้มาโดยมิชอบ และผู้ขายไม่ได้รับอนุญาตให้ขายยาแก่ร้านขายยา ส่วนยาที่หิ้วจากต่างประเทศเป็นยาที่ไม่ได้ขึ้นทะเบียนตำรับในไทยและนำเข้ามาโดยไม่ได้รับอนุญาต แม้จะมีตัวยาสำคัญเดียวกันก็ตาม", "choices": [{"label": "A", "text": "บุคคลในกลุ่มไลน์ที่ขายยาเหลือใช้จากโรงพยาบาลแห่งหนึ่ง โดยยังไม่เปิดกล่องและไม่หมดอายุ", "is_correct": false, "explanation": "บุคคลทั่วไปไม่ได้รับอนุญาตให้ขายยา และไม่มีหลักฐานว่ายาเก็บรักษามาอย่างถูกต้อง"}, {"label": "B", "text": "คลินิกเวชกรรมที่กำลังจะปิดกิจการและต้องการระบายยาที่เหลือในสต็อกให้หมดโดยเร็ว", "is_correct": false, "explanation": "คลินิกไม่ได้รับอนุญาตให้ขายยาแก่ร้านขายยาในลักษณะขายส่ง และตรวจสอบย้อนกลับได้ยาก"}, {"label": "C", "text": "ผู้รับอนุญาตผลิต นำเข้า หรือขายส่งยา ที่ออกใบส่งของหรือใบกำกับภาษีให้ตรวจสอบย้อนกลับได้", "is_correct": true, "explanation": "ถูกต้อง ต้องซื้อจากผู้ได้รับอนุญาตและมีเอกสารการซื้อที่ตรวจสอบย้อนกลับได้"}, {"label": "D", "text": "ผู้แทนยาที่นำยาตัวอย่าง (sample) ที่บริษัทแจกให้แพทย์มาขายต่อในราคาต่ำกว่าท้องตลาด", "is_correct": false, "explanation": "ยาตัวอย่างไม่ได้มีไว้เพื่อขาย และผู้แทนยาไม่ได้เป็นผู้รับอนุญาตขายยา"}, {"label": "E", "text": "ผู้ที่หิ้วยาจากต่างประเทศมาขาย โดยเป็นยาที่มีตัวยาสำคัญเดียวกับยาที่ขึ้นทะเบียนในไทย", "is_correct": false, "explanation": "ยาที่หิ้วจากต่างประเทศไม่ได้ขึ้นทะเบียนตำรับในไทย แม้มีตัวยาสำคัญเหมือนกันก็ห้ามขาย"}], "key_takeaway": "ร้านขายยาต้องซื้อยาจากผู้รับอนุญาตผลิต นำเข้า หรือขายส่งยาเท่านั้น และเก็บเอกสารการซื้อไว้ตรวจสอบย้อนกลับได้"}'::jsonb, 'easy', 'law-day2 • การจัดซื้อยาจากแหล่งที่ได้รับอนุญาต'),
('8923e98afa41e17c2424ec7eaf7a7bee', 65, 'พนักงานเจ้าหน้าที่เข้าตรวจร้านขายยา ขย.1 ที่เพิ่งเปิดใหม่ ร้านเก็บใบอนุญาตขายยาฉบับจริงไว้ในตู้เอกสารหลังร้านเพราะกลัวสูญหาย และยังไม่ได้ติดป้ายใด ๆ ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ไม่เป็นปัญหา ถ้าสามารถนำใบอนุญาตออกมาแสดงได้ทันทีเมื่อเจ้าหน้าที่หรือลูกค้าขอดู"}, {"label": "B", "text": "ติดสำเนาใบอนุญาตที่หน้าร้านก็เพียงพอ และไม่จำเป็นต้องแสดงชื่อเภสัชกรหรือเวลาปฏิบัติการ"}, {"label": "C", "text": "ต้องติดใบอนุญาตฉบับจริงไว้ที่ร้านของเภสัชกรผู้มีหน้าที่ปฏิบัติการ แทนการติดที่ร้านขายยา"}, {"label": "D", "text": "ต้องแสดงเฉพาะใบอนุญาตประกอบวิชาชีพของเภสัชกร ส่วนใบอนุญาตขายยาเก็บไว้ในร้านได้"}, {"label": "E", "text": "ต้องแสดงใบอนุญาตขายยาในที่เปิดเผยเห็นได้ง่ายในร้าน พร้อมป้ายชื่อเภสัชกรและเวลาปฏิบัติการ"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. แสดงใบอนุญาตในที่เปิดเผยพร้อมป้ายเภสัชกร — กฎหมายกำหนดให้แสดงใบอนุญาตขายยาไว้ในที่เปิดเผยเห็นได้ง่ายที่สถานที่ขายยา และต้องมีป้ายแสดงผู้มีหน้าที่ปฏิบัติการและเวลาปฏิบัติการ", "reason": "พ.ร.บ.ยา กำหนดให้ผู้รับอนุญาตแสดงใบอนุญาตไว้ในที่เปิดเผยเห็นได้ง่ายที่สถานที่ที่ได้รับอนุญาต และต้องจัดให้มีป้ายแสดงว่าเป็นสถานที่ขายยา ป้ายแสดงชื่อผู้มีหน้าที่ปฏิบัติการ และเวลาปฏิบัติการตามที่กำหนด เพื่อให้ประชาชนรู้ว่าร้านได้รับอนุญาตถูกต้อง และรู้ว่าในช่วงเวลาใดมีเภสัชกรอยู่ให้บริการ\n\nการเก็บใบอนุญาตไว้ในตู้แล้วนำออกมาแสดงเมื่อถูกขอดูไม่ถือเป็นการแสดงในที่เปิดเผย การแสดงใบอนุญาตประกอบวิชาชีพของเภสัชกรก็ไม่ได้แทนใบอนุญาตขายยาของร้าน เพราะเป็นเอกสารคนละประเภท", "choices": [{"label": "A", "text": "ไม่เป็นปัญหา ถ้าสามารถนำใบอนุญาตออกมาแสดงได้ทันทีเมื่อเจ้าหน้าที่หรือลูกค้าขอดู", "is_correct": false, "explanation": "กฎหมายกำหนดให้แสดงใบอนุญาตไว้ในที่เปิดเผยเห็นได้ง่าย ไม่ใช่นำออกมาแสดงเมื่อมีผู้ขอดู"}, {"label": "B", "text": "ติดสำเนาใบอนุญาตที่หน้าร้านก็เพียงพอ และไม่จำเป็นต้องแสดงชื่อเภสัชกรหรือเวลาปฏิบัติการ", "is_correct": false, "explanation": "การติดป้ายชื่อเภสัชกรและเวลาปฏิบัติการเป็นสิ่งที่ต้องมี ข้อนี้จึงไม่ถูกต้อง"}, {"label": "C", "text": "ต้องติดใบอนุญาตฉบับจริงไว้ที่ร้านของเภสัชกรผู้มีหน้าที่ปฏิบัติการ แทนการติดที่ร้านขายยา", "is_correct": false, "explanation": "ใบอนุญาตขายยาเป็นของสถานที่ขายยาที่ได้รับอนุญาต ต้องแสดงที่ร้านนั้น"}, {"label": "D", "text": "ต้องแสดงเฉพาะใบอนุญาตประกอบวิชาชีพของเภสัชกร ส่วนใบอนุญาตขายยาเก็บไว้ในร้านได้", "is_correct": false, "explanation": "ใบอนุญาตประกอบวิชาชีพไม่ได้แทนใบอนุญาตขายยา ร้านยังต้องแสดงใบอนุญาตขายยาอยู่ดี"}, {"label": "E", "text": "ต้องแสดงใบอนุญาตขายยาในที่เปิดเผยเห็นได้ง่ายในร้าน พร้อมป้ายชื่อเภสัชกรและเวลาปฏิบัติการ", "is_correct": true, "explanation": "ถูกต้อง ต้องแสดงใบอนุญาตขายยาในที่เปิดเผยพร้อมป้ายแสดงผู้มีหน้าที่ปฏิบัติการและเวลาปฏิบัติการ"}], "key_takeaway": "ร้านขายยาต้องแสดงใบอนุญาตขายยาไว้ในที่เปิดเผยเห็นได้ง่าย และมีป้ายแสดงชื่อเภสัชกรผู้มีหน้าที่ปฏิบัติการและเวลาปฏิบัติการ"}'::jsonb, 'easy', 'law-day2 • การแสดงใบอนุญาตและป้ายร้านขายยา'),
('4f2815b219673b88b1bf7bf44d02677a', 66, 'ผู้รับอนุญาตร้านขายยา ขย.1 ถูกเจ้าของอาคารบอกเลิกสัญญาเช่า จึงต้องการย้ายร้านไปเปิดที่อาคารพาณิชย์อีกแห่งห่างไป 2 กิโลเมตรในอำเภอเดียวกัน โดยใช้ชื่อร้าน ผู้รับอนุญาต และเภสัชกรคนเดิม ข้อใดถูกต้อง', '[{"label": "A", "text": "ต้องได้รับอนุญาตให้ย้ายสถานที่ขายยาก่อน และสถานที่ใหม่ต้องผ่านเกณฑ์ที่กฎหมายกำหนด"}, {"label": "B", "text": "ย้ายไปเปิดได้ทันที แล้วแจ้งที่อยู่ใหม่ให้ผู้อนุญาตทราบภายหลังเมื่อถึงรอบต่ออายุใบอนุญาต"}, {"label": "C", "text": "ย้ายได้โดยไม่ต้องดำเนินการใด เพราะใบอนุญาตออกให้แก่ผู้รับอนุญาต ไม่ได้ผูกกับสถานที่"}, {"label": "D", "text": "ย้ายได้ทันทีถ้าอยู่ในอำเภอเดียวกัน แต่ถ้าย้ายข้ามจังหวัดต้องยื่นขออนุญาตก่อนย้าย"}, {"label": "E", "text": "เปิดขายที่ร้านใหม่ได้ระหว่างรอการตรวจ ถ้าเภสัชกรผู้มีหน้าที่ปฏิบัติการอยู่ประจำร้านใหม่"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ต้องได้รับอนุญาตให้ย้ายสถานที่ก่อน — ใบอนุญาตขายยาผูกกับสถานที่ที่ได้รับอนุญาต การย้ายสถานที่ต้องได้รับอนุญาตก่อนขายยาที่สถานที่ใหม่", "reason": "ใบอนุญาตขายยาออกให้ผู้รับอนุญาตสำหรับสถานที่ขายยาที่ระบุไว้ในใบอนุญาต พ.ร.บ.ยา กำหนดให้ผู้รับอนุญาตที่จะย้ายสถานที่ขายยาต้องได้รับอนุญาตจากผู้อนุญาตก่อน และสถานที่ใหม่ต้องมีลักษณะและอุปกรณ์ตามที่กฎหมายและมาตรฐานร้านขายยากำหนด ซึ่งเจ้าหน้าที่จะตรวจก่อนอนุญาต\n\nการเปิดขายยาที่สถานที่ใหม่ก่อนได้รับอนุญาตเท่ากับขายยาในสถานที่ที่ไม่ได้รับอนุญาต แม้จะใช้ผู้รับอนุญาตและเภสัชกรคนเดิม และกฎหมายไม่ได้ยกเว้นให้กรณีย้ายในอำเภอเดียวกัน", "choices": [{"label": "A", "text": "ต้องได้รับอนุญาตให้ย้ายสถานที่ขายยาก่อน และสถานที่ใหม่ต้องผ่านเกณฑ์ที่กฎหมายกำหนด", "is_correct": true, "explanation": "ถูกต้อง การย้ายสถานที่ขายยาต้องได้รับอนุญาตก่อน และสถานที่ใหม่ต้องผ่านเกณฑ์"}, {"label": "B", "text": "ย้ายไปเปิดได้ทันที แล้วแจ้งที่อยู่ใหม่ให้ผู้อนุญาตทราบภายหลังเมื่อถึงรอบต่ออายุใบอนุญาต", "is_correct": false, "explanation": "การย้ายแล้วค่อยแจ้งภายหลังเป็นการขายยาในสถานที่ที่ยังไม่ได้รับอนุญาต"}, {"label": "C", "text": "ย้ายได้โดยไม่ต้องดำเนินการใด เพราะใบอนุญาตออกให้แก่ผู้รับอนุญาต ไม่ได้ผูกกับสถานที่", "is_correct": false, "explanation": "ใบอนุญาตขายยาผูกกับสถานที่ที่ระบุไว้ในใบอนุญาต ไม่ใช่ใช้ได้ทุกที่"}, {"label": "D", "text": "ย้ายได้ทันทีถ้าอยู่ในอำเภอเดียวกัน แต่ถ้าย้ายข้ามจังหวัดต้องยื่นขออนุญาตก่อนย้าย", "is_correct": false, "explanation": "กฎหมายไม่ได้ยกเว้นให้ย้ายได้ทันทีเพียงเพราะอยู่ในอำเภอเดียวกัน"}, {"label": "E", "text": "เปิดขายที่ร้านใหม่ได้ระหว่างรอการตรวจ ถ้าเภสัชกรผู้มีหน้าที่ปฏิบัติการอยู่ประจำร้านใหม่", "is_correct": false, "explanation": "การมีเภสัชกรประจำร้านใหม่ไม่ได้ทำให้สถานที่ใหม่ได้รับอนุญาต ต้องรอได้รับอนุญาตก่อน"}], "key_takeaway": "ใบอนุญาตขายยาผูกกับสถานที่ การย้ายร้านต้องได้รับอนุญาตก่อนจึงจะขายยาที่สถานที่ใหม่ได้"}'::jsonb, 'medium', 'law-day2 • การย้ายสถานที่ขายยา'),
('c7df3dbc237652d8922b4ace214c0d2a', 67, 'นาย ก. เป็นผู้รับอนุญาตร้านขายยา ขย.1 และขายกิจการทั้งร้าน ทั้งสต็อกยาและอุปกรณ์ ให้นาง ข. ซึ่งไม่ได้เป็นเภสัชกร นาง ข. จ้างเภสัชกรคนเดิมทำงานต่อ และต้องการเปิดร้านต่อทันทีโดยใช้ใบอนุญาตเดิมของนาย ก. จนกว่าจะหมดอายุ ข้อใดถูกต้อง', '[{"label": "A", "text": "ทำได้ เพราะใบอนุญาตผูกกับสถานที่ ไม่ได้ผูกกับตัวผู้รับอนุญาต จึงโอนตามกิจการได้เลย"}, {"label": "B", "text": "ทำไม่ได้ ใบอนุญาตเป็นของนาย ก. เป็นการเฉพาะ นาง ข. ต้องยื่นขอรับใบอนุญาตในนามตนเองก่อน"}, {"label": "C", "text": "ทำได้ ถ้านาย ก. ทำหนังสือมอบอำนาจให้นาง ข. ดำเนินกิจการแทนจนกว่าใบอนุญาตจะหมดอายุ"}, {"label": "D", "text": "ทำได้ เพราะเภสัชกรผู้มีหน้าที่ปฏิบัติการยังเป็นคนเดิม การเปลี่ยนเจ้าของจึงไม่มีผลต่อใบอนุญาต"}, {"label": "E", "text": "ทำไม่ได้ เพราะผู้ที่ไม่ได้เป็นเภสัชกรไม่มีสิทธิขอรับใบอนุญาตขายยาแผนปัจจุบันในทุกกรณี"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ใบอนุญาตเป็นของนาย ก. เป็นการเฉพาะ — ใบอนุญาตขายยาออกให้เฉพาะตัวผู้รับอนุญาต ผู้ซื้อกิจการต้องขอรับใบอนุญาตในนามตนเอง", "reason": "ใบอนุญาตขายยาตาม พ.ร.บ.ยา ออกให้แก่ผู้รับอนุญาตแต่ละรายสำหรับสถานที่ที่ระบุไว้ จึงมีลักษณะเฉพาะตัวทั้งผู้รับอนุญาตและสถานที่ การขายกิจการทำให้สต็อกและอุปกรณ์เปลี่ยนมือได้ แต่ใบอนุญาตไม่ได้โอนไปด้วย นาง ข. ต้องยื่นขอรับใบอนุญาตขายยาในนามตนเองและได้รับอนุญาตก่อน จึงจะขายยาได้ การใช้ใบอนุญาตของผู้อื่นหรือรับมอบอำนาจให้ดำเนินกิจการแทน เท่ากับนาง ข. ขายยาโดยไม่ได้รับอนุญาต\n\nผู้รับอนุญาตไม่จำเป็นต้องเป็นเภสัชกร บุคคลทั่วไปหรือนิติบุคคลเป็นผู้รับอนุญาตได้ ถ้ามีเภสัชกรเป็นผู้มีหน้าที่ปฏิบัติการตามที่กฎหมายกำหนด นาง ข. จึงขอใบอนุญาตได้ เพียงแต่ใช้ใบอนุญาตของนาย ก. ไม่ได้", "choices": [{"label": "A", "text": "ทำได้ เพราะใบอนุญาตผูกกับสถานที่ ไม่ได้ผูกกับตัวผู้รับอนุญาต จึงโอนตามกิจการได้เลย", "is_correct": false, "explanation": "ใบอนุญาตไม่ได้ผูกกับสถานที่เพียงอย่างเดียว แต่ออกให้ผู้รับอนุญาตเฉพาะราย จึงไม่โอนไปพร้อมกิจการ"}, {"label": "B", "text": "ทำไม่ได้ ใบอนุญาตเป็นของนาย ก. เป็นการเฉพาะ นาง ข. ต้องยื่นขอรับใบอนุญาตในนามตนเองก่อน", "is_correct": true, "explanation": "ถูกต้อง ผู้ซื้อกิจการต้องขอรับใบอนุญาตในนามตนเองก่อนจึงจะขายยาได้"}, {"label": "C", "text": "ทำได้ ถ้านาย ก. ทำหนังสือมอบอำนาจให้นาง ข. ดำเนินกิจการแทนจนกว่าใบอนุญาตจะหมดอายุ", "is_correct": false, "explanation": "หนังสือมอบอำนาจไม่ได้ทำให้นาง ข. ได้รับอนุญาต และเป็นการหลีกเลี่ยงกฎหมาย"}, {"label": "D", "text": "ทำได้ เพราะเภสัชกรผู้มีหน้าที่ปฏิบัติการยังเป็นคนเดิม การเปลี่ยนเจ้าของจึงไม่มีผลต่อใบอนุญาต", "is_correct": false, "explanation": "เภสัชกรคนเดิมไม่ได้ทำให้ใบอนุญาตของนาย ก. ครอบคลุมนาง ข. เพราะผู้รับอนุญาตเปลี่ยนไปแล้ว"}, {"label": "E", "text": "ทำไม่ได้ เพราะผู้ที่ไม่ได้เป็นเภสัชกรไม่มีสิทธิขอรับใบอนุญาตขายยาแผนปัจจุบันในทุกกรณี", "is_correct": false, "explanation": "ผู้ที่ไม่ได้เป็นเภสัชกรเป็นผู้รับอนุญาตได้ ถ้ามีเภสัชกรเป็นผู้มีหน้าที่ปฏิบัติการ"}], "key_takeaway": "ใบอนุญาตขายยาโอนไปพร้อมกับการขายกิจการไม่ได้ ผู้ซื้อกิจการต้องยื่นขอรับใบอนุญาตในนามตนเองก่อนขายยา"}'::jsonb, 'medium', 'law-day2 • การเปลี่ยนผู้รับอนุญาต (ขายกิจการ)'),
('b68d14f58f6373690b987d0ea55edb6f', 68, 'ในโรงพยาบาลแห่งหนึ่ง ผู้ป่วยในได้รับคำสั่งให้กลับบ้านช่วงเย็น แพทย์สั่งยากลับบ้าน (home medication) 2 รายการ พยาบาลประจำหอผู้ป่วยเห็นว่าห้องยายังไม่ได้ส่งยามา จึงจะหยิบยาจากยาสำรองประจำหอผู้ป่วย (ward stock) ใส่ถุงให้ผู้ป่วยไปก่อน ข้อใดเป็นแนวปฏิบัติที่ถูกต้อง', '[{"label": "A", "text": "ทำได้ เพราะยาสำรองประจำหอผู้ป่วยเป็นยาของโรงพยาบาล พยาบาลจึงจ่ายให้ผู้ป่วยได้ทุกกรณี"}, {"label": "B", "text": "ทำได้ ถ้าพยาบาลเขียนชื่อยาและวิธีใช้บนถุงด้วยลายมือ และบันทึกในเวชระเบียนไว้ด้วย"}, {"label": "C", "text": "ไม่ควรทำ ยากลับบ้านต้องจ่ายผ่านห้องยาตามคำสั่งแพทย์ พร้อมฉลากและคำแนะนำจากเภสัชกร"}, {"label": "D", "text": "ไม่ควรทำ เพราะยากลับบ้านต้องให้ผู้ป่วยไปซื้อจากร้านขายยาภายนอกโรงพยาบาลเท่านั้น"}, {"label": "E", "text": "ทำได้ ถ้าแพทย์เจ้าของไข้อยู่ในหอผู้ป่วยขณะนั้น และอนุญาตด้วยวาจาให้พยาบาลจ่ายยาแทน"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ยากลับบ้านต้องจ่ายผ่านห้องยา พร้อมฉลากและคำแนะนำ — ยาสำรองหอผู้ป่วยมีไว้ให้ผู้ป่วยในระหว่างนอนโรงพยาบาล ส่วนยาที่ส่งมอบให้ผู้ป่วยไปใช้เองต้องผ่านการตรวจสอบและส่งมอบโดยเภสัชกร", "reason": "ยาสำรองประจำหอผู้ป่วยมีไว้เพื่อให้พยาบาลให้ยาแก่ผู้ป่วยในตามคำสั่งแพทย์ระหว่างที่ผู้ป่วยอยู่ในความดูแลของโรงพยาบาล ยาที่ผู้ป่วยนำกลับไปใช้เองที่บ้านเป็นการส่งมอบยาให้ผู้ป่วยโดยตรง จึงต้องผ่านกระบวนการของห้องยา คือ เภสัชกรตรวจสอบคำสั่งใช้ยา (เช่น ซ้ำซ้อนหรือมีปฏิกิริยากับยาเดิม) จัดยาที่มีฉลากครบตามมาตรฐาน และให้คำแนะนำผู้ป่วยก่อนกลับบ้าน\n\nถ้าดึงยาจาก ward stock ไปให้ผู้ป่วยกลับบ้านโดยตรง ยาจะไม่มีฉลากที่ถูกต้อง ไม่ผ่านการตรวจสอบของเภสัชกร และการควบคุมยาสำรองก็คลาดเคลื่อน ทางที่ถูกคือประสานห้องยาให้จ่ายยากลับบ้านตามคำสั่งแพทย์ ซึ่งยาที่จ่ายจากห้องยาของโรงพยาบาลก็ไม่จำเป็นต้องให้ผู้ป่วยไปซื้อจากร้านภายนอก", "choices": [{"label": "A", "text": "ทำได้ เพราะยาสำรองประจำหอผู้ป่วยเป็นยาของโรงพยาบาล พยาบาลจึงจ่ายให้ผู้ป่วยได้ทุกกรณี", "is_correct": false, "explanation": "ยาสำรองหอผู้ป่วยมีไว้ให้ผู้ป่วยในระหว่างนอนโรงพยาบาล ไม่ใช่ยาที่จ่ายให้ผู้ป่วยกลับบ้าน"}, {"label": "B", "text": "ทำได้ ถ้าพยาบาลเขียนชื่อยาและวิธีใช้บนถุงด้วยลายมือ และบันทึกในเวชระเบียนไว้ด้วย", "is_correct": false, "explanation": "ฉลากที่เขียนด้วยลายมือแทนการตรวจสอบและการให้คำแนะนำโดยเภสัชกรไม่ได้"}, {"label": "C", "text": "ไม่ควรทำ ยากลับบ้านต้องจ่ายผ่านห้องยาตามคำสั่งแพทย์ พร้อมฉลากและคำแนะนำจากเภสัชกร", "is_correct": true, "explanation": "ถูกต้อง ยากลับบ้านต้องจ่ายผ่านห้องยาตามคำสั่งแพทย์ พร้อมฉลากที่ถูกต้องและคำแนะนำจากเภสัชกร"}, {"label": "D", "text": "ไม่ควรทำ เพราะยากลับบ้านต้องให้ผู้ป่วยไปซื้อจากร้านขายยาภายนอกโรงพยาบาลเท่านั้น", "is_correct": false, "explanation": "โรงพยาบาลจ่ายยากลับบ้านให้ผู้ป่วยได้ตามปกติผ่านห้องยา ไม่จำเป็นต้องให้ซื้อจากภายนอก"}, {"label": "E", "text": "ทำได้ ถ้าแพทย์เจ้าของไข้อยู่ในหอผู้ป่วยขณะนั้น และอนุญาตด้วยวาจาให้พยาบาลจ่ายยาแทน", "is_correct": false, "explanation": "การที่แพทย์อนุญาตด้วยวาจาไม่ได้ทำให้ข้ามขั้นตอนการตรวจสอบและส่งมอบยาโดยเภสัชกรได้"}], "key_takeaway": "ยาสำรองหอผู้ป่วยใช้ให้ยาแก่ผู้ป่วยในเท่านั้น ยากลับบ้านต้องจ่ายผ่านห้องยาพร้อมฉลากและคำแนะนำจากเภสัชกร"}'::jsonb, 'medium', 'law-day2 • การจ่ายยาในโรงพยาบาล: ยาสำรองหอผู้ป่วย vs ยากลับบ้าน'),
('2560c585076ef521842c766e61f8743b', 69, 'เภสัชกรผู้มีหน้าที่ปฏิบัติการร้าน ขย.1 ได้รับใบสั่งยาจากแพทย์ผิวหนังให้ผสมครีมยาสูตรเฉพาะสำหรับผู้ป่วยรายหนึ่ง เภสัชกรจึงผสมให้ 1 กระปุกพร้อมติดฉลาก ต่อมาครีมสูตรนี้ขายดี เจ้าของร้านจึงให้เภสัชกรผสมไว้ล่วงหน้า 50 กระปุก ติดฉลากยี่ห้อของร้าน แล้ววางขายบนชั้นให้ลูกค้าทั่วไป ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ทั้งสองกรณีทำได้ เพราะเภสัชกรเป็นผู้ผสมเองในร้านที่ได้รับใบอนุญาต ขย.1 อยู่แล้ว"}, {"label": "B", "text": "ทั้งสองกรณีเป็นการผลิตยา ร้านต้องขอใบอนุญาตผลิตยาก่อน แม้จะผสมเพียงกระปุกเดียว"}, {"label": "C", "text": "กรณีแรกต้องขึ้นทะเบียนตำรับยา ส่วนกรณีที่สองทำได้ถ้าฉลากแสดงวันผลิตและวันสิ้นอายุ"}, {"label": "D", "text": "กรณีแรกทำได้ เพราะผสมตามใบสั่งยาเฉพาะราย กรณีที่สองเป็นการผลิตยาที่ต้องได้รับอนุญาต"}, {"label": "E", "text": "กรณีที่สองทำได้ ถ้ามีใบสั่งยาฉบับแรกเป็นต้นแบบสูตรตำรับ และขายเฉพาะในร้านนี้เท่านั้น"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. กรณีแรกทำได้ กรณีที่สองเป็นการผลิตยา — การปรุงยาตามใบสั่งยาสำหรับผู้ป่วยเฉพาะรายโดยเภสัชกรในร้านขายยาได้รับยกเว้น แต่การผลิตไว้ล่วงหน้าเพื่อขายทั่วไปเป็นการผลิตยา", "reason": "พ.ร.บ.ยา นิยามการผลิตยาไว้กว้าง ครอบคลุมการทำ ผสม ปรุง และแบ่งบรรจุ แต่มีข้อยกเว้นให้การปรุงยาของเภสัชกรในร้านขายยาแผนปัจจุบัน ตามใบสั่งยาของผู้ประกอบวิชาชีพเวชกรรม (หรือวิชาชีพอื่นที่กฎหมายกำหนด) สำหรับผู้ป่วยเฉพาะราย ไม่ต้องขอใบอนุญาตผลิตยา กรณีแรกจึงทำได้ เภสัชกรต้องปรุงตามหลักวิชาการ และติดฉลากที่มีข้อมูลผู้ป่วย วิธีใช้ วิธีเก็บรักษา และวันที่ควรใช้ให้หมดก่อน\n\nกรณีที่สองเป็นการผลิตไว้ล่วงหน้าในปริมาณมาก ติดยี่ห้อของร้าน และขายแก่บุคคลทั่วไปโดยไม่มีใบสั่งยาเฉพาะราย จึงไม่เข้าข้อยกเว้น เป็นการผลิตยาที่ต้องมีใบอนุญาตผลิตยา และต้องขึ้นทะเบียนตำรับยาก่อนจำหน่าย การมีใบสั่งยาฉบับแรกเป็นต้นแบบหรือการขายเฉพาะในร้านไม่ทำให้กรณีนี้เข้าข้อยกเว้น", "choices": [{"label": "A", "text": "ทั้งสองกรณีทำได้ เพราะเภสัชกรเป็นผู้ผสมเองในร้านที่ได้รับใบอนุญาต ขย.1 อยู่แล้ว", "is_correct": false, "explanation": "ใบอนุญาต ขย.1 เป็นใบอนุญาตขายยา ไม่ครอบคลุมการผลิตยาไว้ขายทั่วไปตามกรณีที่สอง"}, {"label": "B", "text": "ทั้งสองกรณีเป็นการผลิตยา ร้านต้องขอใบอนุญาตผลิตยาก่อน แม้จะผสมเพียงกระปุกเดียว", "is_correct": false, "explanation": "กรณีแรกได้รับยกเว้น เพราะเป็นการปรุงยาตามใบสั่งยาสำหรับผู้ป่วยเฉพาะราย ไม่ต้องขอใบอนุญาตผลิตยา"}, {"label": "C", "text": "กรณีแรกต้องขึ้นทะเบียนตำรับยา ส่วนกรณีที่สองทำได้ถ้าฉลากแสดงวันผลิตและวันสิ้นอายุ", "is_correct": false, "explanation": "ยาที่ปรุงตามใบสั่งยาเฉพาะรายไม่ต้องขึ้นทะเบียนตำรับ ส่วนกรณีที่สองแสดงข้อมูลบนฉลากครบก็ยังไม่ได้รับอนุญาต"}, {"label": "D", "text": "กรณีแรกทำได้ เพราะผสมตามใบสั่งยาเฉพาะราย กรณีที่สองเป็นการผลิตยาที่ต้องได้รับอนุญาต", "is_correct": true, "explanation": "ถูกต้อง กรณีแรกเข้าข้อยกเว้นของการปรุงยาตามใบสั่งยาเฉพาะราย ส่วนกรณีที่สองเป็นการผลิตยาที่ต้องได้รับอนุญาตและขึ้นทะเบียน"}, {"label": "E", "text": "กรณีที่สองทำได้ ถ้ามีใบสั่งยาฉบับแรกเป็นต้นแบบสูตรตำรับ และขายเฉพาะในร้านนี้เท่านั้น", "is_correct": false, "explanation": "ใบสั่งยาฉบับแรกใช้ได้กับผู้ป่วยรายนั้นเท่านั้น จะนำมาอ้างเพื่อผลิตขายแก่บุคคลทั่วไปไม่ได้"}], "key_takeaway": "เภสัชกรปรุงยาในร้านได้ตามใบสั่งยาสำหรับผู้ป่วยเฉพาะราย แต่การผลิตไว้ล่วงหน้าเพื่อขายทั่วไปเป็นการผลิตยาที่ต้องได้รับอนุญาตและขึ้นทะเบียนตำรับ"}'::jsonb, 'hard', 'law-day2 • การปรุงยาตามใบสั่งยาเฉพาะราย vs การผลิตยา'),
('fa0ff353e2408307b16cea0f6f91b6f7', 70, 'พนักงานเจ้าหน้าที่แจ้งว่าจะเข้าตรวจร้านขายยา ขย.1 ตามมาตรฐานร้านขายยาในสัปดาห์หน้า เภสัชกรเตรียมเอกสารหลายรายการ เอกสารใดที่กฎหมายและมาตรฐานร้านขายยาไม่ได้กำหนดให้ร้านต้องจัดทำ', '[{"label": "A", "text": "บัญชีการซื้อยา พร้อมใบส่งของหรือใบกำกับภาษีจากผู้จำหน่ายที่ได้รับอนุญาต"}, {"label": "B", "text": "บัญชีการขายยาควบคุมพิเศษ และใบสั่งยาที่ใช้เป็นหลักฐานการขายยาควบคุมพิเศษ"}, {"label": "C", "text": "บัญชีการขายยาอันตรายเฉพาะรายการที่หน่วยงานกำหนดให้ต้องจัดทำบัญชีการขาย"}, {"label": "D", "text": "บันทึกอุณหภูมิของพื้นที่เก็บยาและตู้เย็นเก็บยาตามระบบคุณภาพของร้านขายยา"}, {"label": "E", "text": "บัญชีการขายยาสามัญประจำบ้าน แยกตามชื่อและที่อยู่ของลูกค้าแต่ละรายทุกครั้ง"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. บัญชีการขายยาสามัญประจำบ้านแยกตามชื่อลูกค้า — กฎหมายไม่ได้กำหนดให้ทำบัญชีการขายยาสามัญประจำบ้านรายบุคคล ส่วนเอกสารอื่นเป็นสิ่งที่ร้านต้องมี", "reason": "ร้านขายยา ขย.1 ต้องจัดทำและเก็บเอกสารตามที่ พ.ร.บ.ยา กฎกระทรวง และมาตรฐานร้านขายยากำหนด ที่สำคัญได้แก่ บัญชีการซื้อยาพร้อมหลักฐานการซื้อเพื่อตรวจสอบแหล่งที่มา บัญชีการขายยาควบคุมพิเศษพร้อมเก็บใบสั่งยา บัญชีการขายยาอันตรายเฉพาะรายการที่มีประกาศให้ต้องทำบัญชี และบันทึกตามระบบคุณภาพ เช่น การควบคุมอุณหภูมิในการเก็บรักษายา\n\nยาสามัญประจำบ้านเป็นยาที่ร้านค้าทั่วไปขายได้โดยไม่ต้องมีใบอนุญาต จึงไม่มีข้อกำหนดให้ทำบัญชีการขายแยกตามชื่อและที่อยู่ลูกค้าทุกครั้ง การเก็บข้อมูลส่วนบุคคลของลูกค้าโดยไม่จำเป็นยังขัดกับหลักการคุ้มครองข้อมูลส่วนบุคคลด้วย", "choices": [{"label": "A", "text": "บัญชีการซื้อยา พร้อมใบส่งของหรือใบกำกับภาษีจากผู้จำหน่ายที่ได้รับอนุญาต", "is_correct": false, "explanation": "บัญชีการซื้อยาพร้อมหลักฐานจากผู้จำหน่ายที่ได้รับอนุญาตเป็นเอกสารที่ร้านต้องมี"}, {"label": "B", "text": "บัญชีการขายยาควบคุมพิเศษ และใบสั่งยาที่ใช้เป็นหลักฐานการขายยาควบคุมพิเศษ", "is_correct": false, "explanation": "บัญชีการขายยาควบคุมพิเศษและใบสั่งยาเป็นหลักฐานที่ร้านต้องจัดทำและเก็บไว้"}, {"label": "C", "text": "บัญชีการขายยาอันตรายเฉพาะรายการที่หน่วยงานกำหนดให้ต้องจัดทำบัญชีการขาย", "is_correct": false, "explanation": "ยาอันตรายบางรายการมีประกาศให้ต้องทำบัญชีการขาย ร้านจึงต้องจัดทำ"}, {"label": "D", "text": "บันทึกอุณหภูมิของพื้นที่เก็บยาและตู้เย็นเก็บยาตามระบบคุณภาพของร้านขายยา", "is_correct": false, "explanation": "การบันทึกอุณหภูมิเป็นส่วนหนึ่งของมาตรฐานร้านขายยาด้านการเก็บรักษายา"}, {"label": "E", "text": "บัญชีการขายยาสามัญประจำบ้าน แยกตามชื่อและที่อยู่ของลูกค้าแต่ละรายทุกครั้ง", "is_correct": true, "explanation": "ถูกต้อง ไม่มีข้อกำหนดให้ทำบัญชีการขายยาสามัญประจำบ้านแยกตามชื่อและที่อยู่ลูกค้า"}], "key_takeaway": "เอกสารหลักที่ร้าน ขย.1 ต้องมี ได้แก่ บัญชีการซื้อยา บัญชีขายยาควบคุมพิเศษพร้อมใบสั่งยา บัญชีขายยาอันตรายที่ประกาศกำหนด และบันทึกตามระบบคุณภาพ"}'::jsonb, 'medium', 'law-day2 • เอกสารที่พนักงานเจ้าหน้าที่ตรวจในร้าน ขย.1'),
('8da417f1f7252280a380a83b3286450e', 71, 'ร้านขายยา ขย.1 แห่งหนึ่งถูกสั่งพักใช้ใบอนุญาตขายยาเป็นเวลาหนึ่งตามคำสั่งของผู้อนุญาต ผู้รับอนุญาตเสนอทางเลือกหลายทางเพื่อไม่ให้ขาดรายได้ระหว่างนี้ ข้อใดถูกต้อง', '[{"label": "A", "text": "ต้องหยุดขายยาที่ต้องใช้ใบอนุญาตตลอดช่วงพักใช้ ถ้าฝ่าฝืนถือว่าขายยาโดยไม่ได้รับอนุญาต"}, {"label": "B", "text": "ขายยาอันตรายต่อได้ ถ้าเภสัชกรผู้มีหน้าที่ปฏิบัติการอยู่ประจำร้านตลอดเวลาที่เปิดทำการ"}, {"label": "C", "text": "ขายยาควบคุมพิเศษได้เฉพาะตามใบสั่งยา เพราะเป็นการขายที่มีแพทย์รับผิดชอบการสั่งใช้แล้ว"}, {"label": "D", "text": "เภสัชกรผู้มีหน้าที่ปฏิบัติการขายยาต่อในร้านเดิมได้ โดยถือว่าใช้ใบอนุญาตประกอบวิชาชีพของตน"}, {"label": "E", "text": "ย้ายการขายยาอันตรายไปเป็นการรับคำสั่งซื้อทางออนไลน์ แล้วจัดส่งยาจากร้านถึงบ้านลูกค้าแทน"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ต้องหยุดขายยาที่ต้องอาศัยใบอนุญาตตลอดช่วงพักใช้ — ระหว่างพักใช้ใบอนุญาต ผู้รับอนุญาตไม่มีสิทธิตามใบอนุญาต การขายยาจึงเท่ากับขายโดยไม่ได้รับอนุญาต", "reason": "การพักใช้ใบอนุญาตเป็นมาตรการทางปกครองที่ทำให้ผู้รับอนุญาตใช้สิทธิตามใบอนุญาตไม่ได้ชั่วคราว ระหว่างนั้นร้านจึงขายยาที่ต้องมีใบอนุญาต เช่น ยาอันตรายและยาควบคุมพิเศษ ไม่ได้ ไม่ว่าจะมีเภสัชกรอยู่ มีใบสั่งยา หรือเปลี่ยนช่องทางการขาย ถ้าฝ่าฝืนถือเป็นการขายยาโดยไม่ได้รับอนุญาตและมีโทษตาม พ.ร.บ.ยา ถ้าการฝ่าฝืนร้ายแรงหรือซ้ำซาก ผู้อนุญาตอาจเพิกถอนใบอนุญาตได้\n\nใบอนุญาตประกอบวิชาชีพเภสัชกรรมเป็นคนละเรื่องกับใบอนุญาตขายยา เภสัชกรจึงใช้ใบอนุญาตประกอบวิชาชีพแทนใบอนุญาตขายยาของร้านไม่ได้ และถ้าเภสัชกรร่วมขายยาในช่วงพักใช้ ก็อาจถูกดำเนินการทางจรรยาบรรณด้วย", "choices": [{"label": "A", "text": "ต้องหยุดขายยาที่ต้องใช้ใบอนุญาตตลอดช่วงพักใช้ ถ้าฝ่าฝืนถือว่าขายยาโดยไม่ได้รับอนุญาต", "is_correct": true, "explanation": "ถูกต้อง ระหว่างพักใช้ใบอนุญาต การขายยาที่ต้องอาศัยใบอนุญาตทำไม่ได้ ถ้าฝ่าฝืนถือเป็นการขายโดยไม่ได้รับอนุญาต"}, {"label": "B", "text": "ขายยาอันตรายต่อได้ ถ้าเภสัชกรผู้มีหน้าที่ปฏิบัติการอยู่ประจำร้านตลอดเวลาที่เปิดทำการ", "is_correct": false, "explanation": "การมีเภสัชกรอยู่ประจำร้านไม่ได้ทำให้ใบอนุญาตที่ถูกพักใช้กลับมาใช้ได้"}, {"label": "C", "text": "ขายยาควบคุมพิเศษได้เฉพาะตามใบสั่งยา เพราะเป็นการขายที่มีแพทย์รับผิดชอบการสั่งใช้แล้ว", "is_correct": false, "explanation": "การมีใบสั่งยาไม่ได้แทนใบอนุญาตขายยา ร้านที่ถูกพักใช้ใบอนุญาตขายยาควบคุมพิเศษไม่ได้"}, {"label": "D", "text": "เภสัชกรผู้มีหน้าที่ปฏิบัติการขายยาต่อในร้านเดิมได้ โดยถือว่าใช้ใบอนุญาตประกอบวิชาชีพของตน", "is_correct": false, "explanation": "ใบอนุญาตประกอบวิชาชีพเภสัชกรรมไม่ใช่ใบอนุญาตขายยา ใช้แทนกันไม่ได้"}, {"label": "E", "text": "ย้ายการขายยาอันตรายไปเป็นการรับคำสั่งซื้อทางออนไลน์ แล้วจัดส่งยาจากร้านถึงบ้านลูกค้าแทน", "is_correct": false, "explanation": "การเปลี่ยนเป็นช่องทางออนไลน์ก็ยังเป็นการขายยาของร้านที่ถูกพักใช้ใบอนุญาต และยังเพิ่มปัญหาการขายยาอันตรายนอกสถานที่"}], "key_takeaway": "ระหว่างพักใช้ใบอนุญาต ร้านขายยาที่ต้องอาศัยใบอนุญาตไม่ได้เลย ไม่ว่าจะมีเภสัชกรอยู่ มีใบสั่งยา หรือเปลี่ยนช่องทางการขาย"}'::jsonb, 'medium', 'law-day2 • ผลของการพักใช้ใบอนุญาตขายยา'),
('2068a134dcd9f461a7e79b39fe5d53ea', 72, 'ร้านขายยาแผนปัจจุบันเฉพาะยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายหรือยาควบคุมพิเศษ (ขย.2) ในชุมชนแห่งหนึ่ง ซื้อยาเม็ดสามัญประจำบ้านขนาดขวดละ 1,000 เม็ดมา แล้วแบ่งใส่ซองละ 10 เม็ดเพื่อขายให้ชาวบ้านในราคาถูกลง ข้อใดถูกต้อง', '[{"label": "A", "text": "ทำได้ เพราะยาสามัญประจำบ้านมีความปลอดภัยสูง ร้านใดก็แบ่งขายได้โดยไม่มีข้อจำกัด"}, {"label": "B", "text": "ทำได้ ถ้าซองที่แบ่งบรรจุมีชื่อยา ความแรง และวันสิ้นอายุของยาตามขวดเดิมกำกับไว้"}, {"label": "C", "text": "ทำไม่ได้ ร้าน ขย.2 ต้องขายยาในภาชนะบรรจุเดิมที่ยังไม่ได้เปิด จะเปิดแบ่งขายเองไม่ได้"}, {"label": "D", "text": "ทำไม่ได้ เพราะยาสามัญประจำบ้านต้องขายในร้านขายของชำเท่านั้น ร้าน ขย.2 ขายไม่ได้"}, {"label": "E", "text": "ทำได้ ถ้าผู้มีหน้าที่ปฏิบัติการของร้าน ขย.2 เป็นผู้แบ่งบรรจุเองทุกครั้งที่มีลูกค้ามาซื้อ"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ร้าน ขย.2 ต้องขายยาในภาชนะบรรจุเดิมที่ยังไม่ได้เปิด — ขย.2 ได้รับอนุญาตให้ขายเฉพาะยาบรรจุเสร็จ การเปิดแบ่งบรรจุทำให้ยานั้นไม่ใช่ยาบรรจุเสร็จตามที่ผู้ผลิตบรรจุไว้อีกต่อไป", "reason": "ยาบรรจุเสร็จคือยาที่ผู้ผลิตบรรจุในภาชนะที่ปิดหรือผนึกไว้และมีฉลากครบถ้วนตาม พ.ร.บ.ยา ใบอนุญาต ขย.2 ให้ขายได้เฉพาะยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายหรือยาควบคุมพิเศษ และผู้รับอนุญาตต้องขายยาในภาชนะบรรจุเดิมโดยไม่เปิด การเปิดขวดใหญ่แล้วแบ่งใส่ซองจึงเกินขอบเขตใบอนุญาต แม้ยาจะเป็นยาสามัญประจำบ้าน และแม้จะเขียนข้อมูลกำกับบนซอง\n\nนอกจากนี้ การแบ่งบรรจุยาแล้วติดฉลากเพื่อขายทั่วไปอาจเข้าข่ายการผลิตยาตามนิยามของ พ.ร.บ.ยา ส่วนร้าน ขย.2 ขายยาสามัญประจำบ้านได้ เพียงต้องขายในภาชนะบรรจุเดิม", "choices": [{"label": "A", "text": "ทำได้ เพราะยาสามัญประจำบ้านมีความปลอดภัยสูง ร้านใดก็แบ่งขายได้โดยไม่มีข้อจำกัด", "is_correct": false, "explanation": "ยาสามัญประจำบ้านที่ขายได้โดยไม่ต้องมีใบอนุญาตหมายถึงยาบรรจุเสร็จในภาชนะเดิม ไม่ใช่การเปิดแบ่งขาย"}, {"label": "B", "text": "ทำได้ ถ้าซองที่แบ่งบรรจุมีชื่อยา ความแรง และวันสิ้นอายุของยาตามขวดเดิมกำกับไว้", "is_correct": false, "explanation": "แม้เขียนข้อมูลบนซอง ร้าน ขย.2 ก็ยังเปิดภาชนะบรรจุแบ่งขายไม่ได้"}, {"label": "C", "text": "ทำไม่ได้ ร้าน ขย.2 ต้องขายยาในภาชนะบรรจุเดิมที่ยังไม่ได้เปิด จะเปิดแบ่งขายเองไม่ได้", "is_correct": true, "explanation": "ถูกต้อง ร้าน ขย.2 ต้องขายยาบรรจุเสร็จในภาชนะบรรจุเดิมโดยไม่เปิดแบ่ง"}, {"label": "D", "text": "ทำไม่ได้ เพราะยาสามัญประจำบ้านต้องขายในร้านขายของชำเท่านั้น ร้าน ขย.2 ขายไม่ได้", "is_correct": false, "explanation": "ร้าน ขย.2 ขายยาสามัญประจำบ้านได้ ไม่ได้จำกัดเฉพาะร้านขายของชำ"}, {"label": "E", "text": "ทำได้ ถ้าผู้มีหน้าที่ปฏิบัติการของร้าน ขย.2 เป็นผู้แบ่งบรรจุเองทุกครั้งที่มีลูกค้ามาซื้อ", "is_correct": false, "explanation": "ผู้มีหน้าที่ปฏิบัติการของร้าน ขย.2 ไม่มีอำนาจเปิดภาชนะบรรจุแบ่งขาย ไม่ว่าใครจะเป็นผู้แบ่ง"}], "key_takeaway": "ร้าน ขย.2 ขายได้เฉพาะยาบรรจุเสร็จในภาชนะบรรจุเดิม ห้ามเปิดแบ่งขาย แม้จะเป็นยาสามัญประจำบ้าน"}'::jsonb, 'medium', 'law-day2 • ขอบเขต ขย.2: ห้ามเปิดภาชนะบรรจุแบ่งขาย'),
('9dfefdb0de182a6b6997c78fe741e3f9', 73, 'พนักงานเจ้าหน้าที่ตรวจร้านในตำบลเดียวกัน 3 แห่ง แล้วพบข้อเท็จจริงดังนี้ (1) ร้านขายของชำขายยาสามัญประจำบ้านบรรจุเสร็จในแผงเดิมที่มีฉลากครบ (2) ร้านขายของชำขายยาแผนปัจจุบันบรรจุเสร็จที่ไม่ใช่ยาอันตราย แต่ไม่ได้เป็นยาสามัญประจำบ้าน (3) ร้าน ขย.2 ขายยาปฏิชีวนะชนิดแคปซูลในแผงบรรจุเสร็จ ขณะที่ผู้มีหน้าที่ปฏิบัติการของร้านอยู่ประจำ (4) ร้าน ขย.1 ขายยาอันตรายให้ลูกค้าโดยเภสัชกรผู้มีหน้าที่ปฏิบัติการเป็นผู้ซักประวัติและส่งมอบยาเอง ข้อใดระบุการกระทำที่ถูกต้องตามกฎหมายได้ครบถ้วน', '[{"label": "A", "text": "(1) และ (2) เท่านั้น"}, {"label": "B", "text": "(1) และ (4) เท่านั้น"}, {"label": "C", "text": "(1), (3) และ (4) เท่านั้น"}, {"label": "D", "text": "(3) และ (4) เท่านั้น"}, {"label": "E", "text": "(1), (2) และ (4) เท่านั้น"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. (1) และ (4) เท่านั้น — ร้านชำขายได้เฉพาะยาสามัญประจำบ้าน ขย.2 ขายยาอันตรายไม่ได้ ส่วน ขย.1 ขายยาอันตรายได้เมื่อเภสัชกรเป็นผู้ส่งมอบ", "reason": "(1) ถูกต้อง การขายยาสามัญประจำบ้านได้รับยกเว้นไม่ต้องมีใบอนุญาตขายยา ร้านขายของชำจึงขายได้ ถ้าเป็นยาบรรจุเสร็จในภาชนะเดิม\n\n(2) ผิด ข้อยกเว้นของร้านขายของชำครอบคลุมเฉพาะยาสามัญประจำบ้าน ยาบรรจุเสร็จที่ไม่ใช่ยาอันตรายแต่ไม่ใช่ยาสามัญประจำบ้าน ต้องขายโดยผู้ได้รับใบอนุญาตอย่างน้อยระดับ ขย.2 ร้านขายของชำจึงขายยานี้ไม่ได้\n\n(3) ผิด ยาปฏิชีวนะชนิดรับประทานเป็นยาอันตราย ใบอนุญาต ขย.2 ไม่ครอบคลุมยาอันตราย แม้จะเป็นยาบรรจุเสร็จและผู้มีหน้าที่ปฏิบัติการอยู่ประจำก็ตาม (4) ถูกต้อง ร้าน ขย.1 ขายยาอันตรายได้ โดยเภสัชกรผู้มีหน้าที่ปฏิบัติการเป็นผู้ควบคุมการขายและส่งมอบ คำตอบจึงเป็น (1) และ (4)", "choices": [{"label": "A", "text": "(1) และ (2) เท่านั้น", "is_correct": false, "explanation": "(2) ผิด ร้านขายของชำขายได้เฉพาะยาสามัญประจำบ้าน ยาบรรจุเสร็จอื่นต้องมีใบอนุญาตขายยา"}, {"label": "B", "text": "(1) และ (4) เท่านั้น", "is_correct": true, "explanation": "ถูกต้อง (1) อยู่ในข้อยกเว้นของยาสามัญประจำบ้าน และ (4) เป็นการขายยาอันตรายใน ขย.1 โดยเภสัชกรเป็นผู้ส่งมอบ"}, {"label": "C", "text": "(1), (3) และ (4) เท่านั้น", "is_correct": false, "explanation": "(3) ผิด ขย.2 ขายยาอันตรายไม่ได้ แม้จะเป็นยาบรรจุเสร็จและผู้มีหน้าที่ปฏิบัติการอยู่ประจำ"}, {"label": "D", "text": "(3) และ (4) เท่านั้น", "is_correct": false, "explanation": "(3) ผิด และละเว้น (1) ซึ่งถูกต้อง"}, {"label": "E", "text": "(1), (2) และ (4) เท่านั้น", "is_correct": false, "explanation": "(2) ผิด เพราะยานั้นไม่ใช่ยาสามัญประจำบ้าน ร้านขายของชำจึงขายไม่ได้"}], "key_takeaway": "ร้านชำขายได้เฉพาะยาสามัญประจำบ้าน ขย.2 ขายได้เฉพาะยาบรรจุเสร็จที่ไม่ใช่ยาอันตราย และยาอันตรายต้องขายใน ขย.1 โดยเภสัชกร"}'::jsonb, 'hard', 'law-day2 • ขอบเขตร้านชำ / ขย.2 / ขย.1 (สถานการณ์ผสม)'),
('e5bf712909739e4b9c6b92748025fd51', 74, 'ยา X ยี่ห้อหนึ่งขึ้นทะเบียนตำรับยาในไทยโดยบริษัทผู้นำเข้า ก. ต่อมาเจ้าของร้าน ขย.1 ซื้อยา X ยี่ห้อเดียวกัน ผลิตจากโรงงานเดียวกัน แต่ฉลากเป็นภาษาต่างประเทศ จากผู้จำหน่ายในประเทศเพื่อนบ้าน และนำเข้ามาเองในราคาถูกกว่าครึ่ง แล้วสั่งให้เภสัชกรวางขาย เภสัชกรควรปฏิบัติอย่างไร', '[{"label": "A", "text": "วางขายได้ เพราะเป็นยาของผู้ผลิตเดียวกันกับยาที่ขึ้นทะเบียนในไทยแล้ว คุณภาพจึงเท่ากัน"}, {"label": "B", "text": "วางขายได้ ถ้าเภสัชกรติดฉลากภาษาไทยที่มีเลขทะเบียนของบริษัท ก. ทับฉลากเดิมทุกกล่อง"}, {"label": "C", "text": "วางขายได้เฉพาะลูกค้าที่มีใบสั่งยาจากแพทย์ เพราะแพทย์เป็นผู้รับผิดชอบการสั่งใช้ยาแล้ว"}, {"label": "D", "text": "ไม่วางขาย เพราะยาที่นำเข้ามานี้ไม่ได้ขึ้นทะเบียนตำรับในไทย และนำเข้าโดยไม่ได้รับอนุญาต"}, {"label": "E", "text": "วางขายได้ ถ้าร้านแจ้งให้ลูกค้าทราบว่าเป็นยานำเข้าและให้ลูกค้าลงชื่อยินยอมก่อนซื้อ"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ไม่วางขาย เพราะไม่ได้ขึ้นทะเบียนตำรับในไทยและนำเข้าโดยไม่ได้รับอนุญาต — ทะเบียนตำรับยาผูกกับผู้รับอนุญาตและผลิตภัณฑ์ที่ขึ้นทะเบียน ยาที่นำเข้ามาเองนอกระบบจึงเป็นยาที่ไม่ได้ขึ้นทะเบียน", "reason": "พ.ร.บ.ยา กำหนดให้การนำหรือสั่งยาเข้ามาในราชอาณาจักรต้องได้รับใบอนุญาตนำเข้า และยาที่จะจำหน่ายต้องขึ้นทะเบียนตำรับยา ทะเบียนตำรับยา X เป็นของบริษัท ก. ในฐานะผู้รับอนุญาตนำเข้า ซึ่งรับผิดชอบคุณภาพ ฉลากภาษาไทย การเก็บรักษาระหว่างขนส่ง และการเรียกคืน ยาที่ร้านนำเข้ามาเองไม่ได้มาภายใต้ทะเบียนนั้น จึงเป็นยาที่ไม่ได้ขึ้นทะเบียนตำรับและนำเข้าโดยไม่ได้รับอนุญาต แม้จะผลิตจากโรงงานเดียวกันก็ตาม\n\nการติดฉลากที่มีเลขทะเบียนของบริษัท ก. ทับ เป็นการแสดงข้อมูลเท็จว่ายาเป็นยาที่ขึ้นทะเบียน ซึ่งทำให้ความผิดร้ายแรงขึ้น ใบสั่งยาหรือความยินยอมของลูกค้าก็ไม่ได้ทำให้ขายยาที่ไม่ได้ขึ้นทะเบียนได้ เภสัชกรผู้มีหน้าที่ปฏิบัติการต้องปฏิเสธ แม้เจ้าของร้านจะสั่ง เพราะเภสัชกรมีหน้าที่ควบคุมการขายยาให้ถูกต้องตามกฎหมาย และอาจต้องรับผิดทั้งตามกฎหมายและจรรยาบรรณ", "choices": [{"label": "A", "text": "วางขายได้ เพราะเป็นยาของผู้ผลิตเดียวกันกับยาที่ขึ้นทะเบียนในไทยแล้ว คุณภาพจึงเท่ากัน", "is_correct": false, "explanation": "ผู้ผลิตเดียวกันไม่ได้ทำให้ยาที่นำเข้ามาเองอยู่ภายใต้ทะเบียนตำรับของผู้นำเข้าที่ได้รับอนุญาต"}, {"label": "B", "text": "วางขายได้ ถ้าเภสัชกรติดฉลากภาษาไทยที่มีเลขทะเบียนของบริษัท ก. ทับฉลากเดิมทุกกล่อง", "is_correct": false, "explanation": "การติดฉลากเลขทะเบียนของบริษัทอื่นทับเป็นการแสดงข้อมูลเท็จ และทำให้ความผิดร้ายแรงขึ้น"}, {"label": "C", "text": "วางขายได้เฉพาะลูกค้าที่มีใบสั่งยาจากแพทย์ เพราะแพทย์เป็นผู้รับผิดชอบการสั่งใช้ยาแล้ว", "is_correct": false, "explanation": "ใบสั่งยาไม่ได้ทำให้ร้านขายยาที่ไม่ได้ขึ้นทะเบียนและนำเข้าโดยไม่ได้รับอนุญาตได้"}, {"label": "D", "text": "ไม่วางขาย เพราะยาที่นำเข้ามานี้ไม่ได้ขึ้นทะเบียนตำรับในไทย และนำเข้าโดยไม่ได้รับอนุญาต", "is_correct": true, "explanation": "ถูกต้อง ยาที่นำเข้ามาเองนอกระบบไม่ได้ขึ้นทะเบียนตำรับในไทย และนำเข้าโดยไม่ได้รับอนุญาต จึงห้ามขาย"}, {"label": "E", "text": "วางขายได้ ถ้าร้านแจ้งให้ลูกค้าทราบว่าเป็นยานำเข้าและให้ลูกค้าลงชื่อยินยอมก่อนซื้อ", "is_correct": false, "explanation": "ความยินยอมของลูกค้าไม่ได้ยกเว้นข้อห้ามขายยาที่ไม่ได้ขึ้นทะเบียนตาม พ.ร.บ.ยา"}], "key_takeaway": "ยาที่นำเข้ามาเองนอกระบบผู้รับอนุญาตเป็นยาไม่ขึ้นทะเบียนตำรับ แม้จะเป็นยี่ห้อและผู้ผลิตเดียวกับยาที่ขึ้นทะเบียนในไทยก็ห้ามขาย"}'::jsonb, 'hard', 'law-day2 • การนำเข้าซ้อน (parallel import) และยาไม่ขึ้นทะเบียน'),
('1d042ccedf7287f09fc0097e72547192', 75, 'ในโรงพยาบาลแห่งหนึ่ง ผู้ช่วยเภสัชกรหยิบยาที่มีชื่อและบรรจุภัณฑ์คล้ายกัน (look-alike sound-alike) ผิดชนิดใส่ตะกร้ายาของผู้ป่วย เภสัชกรตรวจพบระหว่างการตรวจสอบก่อนส่งมอบและแก้ไขได้ทัน ผู้ป่วยไม่ได้รับยาผิด ข้อใดเป็นการปฏิบัติที่เหมาะสมที่สุดตามหลักการบริหารความเสี่ยง', '[{"label": "A", "text": "ไม่ต้องรายงาน เพราะแก้ไขได้ทันและผู้ป่วยไม่ได้รับอันตรายใดๆ"}, {"label": "B", "text": "ตักเตือนผู้ช่วยเภสัชกรเป็นลายลักษณ์อักษรและบันทึกไว้ในแฟ้มประวัติ"}, {"label": "C", "text": "รายงานในระบบรายงานความเสี่ยงของหน่วยงานเพื่อนำไปปรับปรุงระบบ"}, {"label": "D", "text": "รายงานเฉพาะกรณีที่ผู้ช่วยเภสัชกรคนเดิมหยิบยาผิดซ้ำหลายครั้ง"}, {"label": "E", "text": "แจ้งผู้ป่วยรายนั้นและทำเรื่องรายงานต่อสภาเภสัชกรรมทันที"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. รายงานเป็นเหตุการณ์เกือบพลาดในระบบรายงานความเสี่ยงเพื่อหาจุดอ่อนของระบบ — near miss เป็นข้อมูลสำคัญสำหรับป้องกันความคลาดเคลื่อนที่จะเกิดซ้ำ", "reason": "เหตุการณ์ที่ความคลาดเคลื่อนเกิดขึ้นแล้วแต่ถูกดักจับได้ก่อนถึงตัวผู้ป่วยเรียกว่า near miss (เหตุการณ์เกือบพลาด) แม้ไม่มีผู้ใดได้รับอันตราย แต่ก็สะท้อนว่าระบบมีช่องโหว่ เช่น การจัดเก็บยาชื่อพ้อง/รูปคล้ายไว้ใกล้กัน หรือฉลากชั้นวางไม่ชัดเจน\n\nแนวคิดวัฒนธรรมความปลอดภัย (safety culture) สนับสนุนให้รายงานเหตุการณ์ทุกระดับรวมถึง near miss โดยไม่มุ่งกล่าวโทษบุคคล เพื่อให้หน่วยงานนำข้อมูลไปวิเคราะห์และปรับระบบ เช่น แยกตำแหน่งจัดเก็บ ใช้ Tall Man lettering หรือติดสัญลักษณ์เตือน ซึ่งช่วยป้องกันไม่ให้เหตุการณ์เดียวกันลุกลามจนถึงผู้ป่วยในครั้งต่อไป", "choices": [{"label": "A", "text": "ไม่ต้องรายงาน เพราะแก้ไขได้ทันและผู้ป่วยไม่ได้รับอันตรายใดๆ", "is_correct": false, "explanation": "ผิด การไม่รายงาน near miss ทำให้เสียโอกาสแก้ไขจุดอ่อนของระบบ ซึ่งอาจทำให้เกิดความคลาดเคลื่อนถึงตัวผู้ป่วยในครั้งต่อไป"}, {"label": "B", "text": "ตักเตือนผู้ช่วยเภสัชกรเป็นลายลักษณ์อักษรและบันทึกไว้ในแฟ้มประวัติ", "is_correct": false, "explanation": "ผิด การมุ่งลงโทษบุคคลสำหรับความผิดพลาดโดยสุจริตขัดกับวัฒนธรรมการรายงานแบบไม่กล่าวโทษ และทำให้บุคลากรไม่กล้ารายงานในอนาคต"}, {"label": "C", "text": "รายงานในระบบรายงานความเสี่ยงของหน่วยงานเพื่อนำไปปรับปรุงระบบ", "is_correct": true, "explanation": "ถูก near miss ควรรายงานเพื่อวิเคราะห์สาเหตุเชิงระบบ เช่น การจัดเก็บยา LASA และหามาตรการป้องกัน"}, {"label": "D", "text": "รายงานเฉพาะกรณีที่ผู้ช่วยเภสัชกรคนเดิมหยิบยาผิดซ้ำหลายครั้ง", "is_correct": false, "explanation": "ผิด เกณฑ์การรายงานไม่ได้ขึ้นกับจำนวนครั้งของบุคคลใดบุคคลหนึ่ง และการมองที่ตัวบุคคลทำให้มองไม่เห็นปัญหาเชิงระบบ"}, {"label": "E", "text": "แจ้งผู้ป่วยรายนั้นและทำเรื่องรายงานต่อสภาเภสัชกรรมทันที", "is_correct": false, "explanation": "ผิด near miss ไม่ใช่การประพฤติผิดจรรยาบรรณที่ต้องร้องต่อสภาเภสัชกรรม ช่องทางที่เหมาะสมคือระบบรายงานความเสี่ยงภายในหน่วยงาน"}], "key_takeaway": "เหตุการณ์เกือบพลาด (near miss) ต้องรายงานในระบบความเสี่ยงเช่นเดียวกับความคลาดเคลื่อนที่ถึงตัวผู้ป่วย เพื่อใช้ปรับปรุงระบบ"}'::jsonb, 'easy', 'law-day2 • ความปลอดภัยของผู้ป่วย: การรายงานเหตุการณ์เกือบพลาด (near miss)'),
('8e1597297480271469d9087bdaddf791', 76, 'หลังเกิดความคลาดเคลื่อนทางยาหลายกรณีในห้องจ่ายยา หัวหน้ากลุ่มงานเภสัชกรรมต้องการนำแนวคิด "just culture" มาใช้ร่วมกับระบบรายงานแบบไม่กล่าวโทษ (no-blame reporting) ข้อใดอธิบายแนวคิดนี้ได้ถูกต้องที่สุด', '[{"label": "A", "text": "แยกความผิดพลาดโดยไม่ตั้งใจ พฤติกรรมเสี่ยง และพฤติกรรมประมาทจงใจ แล้วจัดการต่างกัน"}, {"label": "B", "text": "ทุกความคลาดเคลื่อนต้องไม่มีผู้ใดรับผิดชอบ ไม่ว่าผู้นั้นจะมีพฤติกรรมอย่างไรก็ตาม"}, {"label": "C", "text": "พิจารณาโทษโดยใช้ความรุนแรงของอันตรายที่ผู้ป่วยได้รับเป็นเกณฑ์หลักในการตัดสิน"}, {"label": "D", "text": "ใช้การวิเคราะห์สาเหตุราก (RCA) เพื่อระบุตัวผู้กระทำผิดและเสนอบทลงโทษที่เหมาะสม"}, {"label": "E", "text": "เปิดเผยชื่อผู้ที่ทำผิดบ่อยต่อที่ประชุมเพื่อให้เกิดความระมัดระวังมากขึ้น"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. แยกพฤติกรรมเป็นความผิดพลาดของมนุษย์ พฤติกรรมเสี่ยง และพฤติกรรมประมาทจงใจ แล้วตอบสนองต่างกัน — just culture ไม่ใช่การไม่รับผิดชอบเลย", "reason": "just culture เป็นแนวคิดที่สร้างสมดุลระหว่างการเรียนรู้จากความผิดพลาดกับความรับผิดชอบของบุคคล โดยแยกพฤติกรรมออกเป็น 3 ลักษณะ ได้แก่ (1) ความผิดพลาดของมนุษย์โดยไม่ตั้งใจ (human error) ซึ่งควรได้รับการปลอบใจ/สนับสนุน และแก้ไขที่ระบบ (2) พฤติกรรมเสี่ยง (at-risk behavior) เช่น การลัดขั้นตอนจนเคยชิน ซึ่งควรได้รับการโค้ชและแก้แรงจูงใจในระบบ และ (3) พฤติกรรมประมาทเลินเล่ออย่างร้ายแรงหรือจงใจละเลยความเสี่ยงที่รู้อยู่ (reckless behavior) ซึ่งอาจต้องมีมาตรการทางวินัย\n\nแนวคิดนี้จึงไม่ใช่ \"ไม่มีใครต้องรับผิดชอบเลย\" และไม่ใช่การลงโทษตามความรุนแรงของผลที่เกิดขึ้น การวิเคราะห์สาเหตุราก (root cause analysis) ที่ใช้ร่วมกันมุ่งหาปัจจัยเชิงระบบ ไม่ได้มีเป้าหมายเพื่อหาผู้กระทำผิดมาลงโทษ", "choices": [{"label": "A", "text": "แยกความผิดพลาดโดยไม่ตั้งใจ พฤติกรรมเสี่ยง และพฤติกรรมประมาทจงใจ แล้วจัดการต่างกัน", "is_correct": true, "explanation": "ถูก เป็นหลักของ just culture: สนับสนุนเมื่อเป็น human error, โค้ชเมื่อเป็น at-risk behavior และใช้มาตรการวินัยเมื่อเป็น reckless behavior"}, {"label": "B", "text": "ทุกความคลาดเคลื่อนต้องไม่มีผู้ใดรับผิดชอบ ไม่ว่าผู้นั้นจะมีพฤติกรรมอย่างไรก็ตาม", "is_correct": false, "explanation": "ผิด just culture ยังคงให้บุคคลรับผิดชอบต่อพฤติกรรมที่จงใจละเลยความเสี่ยง ไม่ใช่การยกเว้นความรับผิดชอบทั้งหมด"}, {"label": "C", "text": "พิจารณาโทษโดยใช้ความรุนแรงของอันตรายที่ผู้ป่วยได้รับเป็นเกณฑ์หลักในการตัดสิน", "is_correct": false, "explanation": "ผิด just culture ประเมินจากพฤติกรรมและการตัดสินใจของบุคคล ไม่ใช่จากผลลัพธ์ เพราะความผิดพลาดเดียวกันอาจให้ผลต่างกันโดยบังเอิญ"}, {"label": "D", "text": "ใช้การวิเคราะห์สาเหตุราก (RCA) เพื่อระบุตัวผู้กระทำผิดและเสนอบทลงโทษที่เหมาะสม", "is_correct": false, "explanation": "ผิด RCA มุ่งหาปัจจัยเชิงระบบและกระบวนการที่เอื้อให้เกิดความผิดพลาด ไม่ใช่เครื่องมือหาผู้ต้องรับโทษ"}, {"label": "E", "text": "เปิดเผยชื่อผู้ที่ทำผิดบ่อยต่อที่ประชุมเพื่อให้เกิดความระมัดระวังมากขึ้น", "is_correct": false, "explanation": "ผิด การประจานรายบุคคลทำลายความไว้วางใจและทำให้บุคลากรปกปิดเหตุการณ์ ขัดต่อวัฒนธรรมการรายงาน"}], "key_takeaway": "just culture = เรียนรู้เชิงระบบจากความผิดพลาดโดยสุจริต แต่ยังคงความรับผิดชอบต่อพฤติกรรมที่จงใจละเลยความเสี่ยง"}'::jsonb, 'hard', 'law-day2 • ความปลอดภัยของผู้ป่วย: just culture และการวิเคราะห์สาเหตุราก'),
('f44048fc502a22b64dd4f9db617afa6b', 77, 'ร้านยาแห่งหนึ่งส่งมอบยาผิดชนิดให้ผู้ป่วย ทำให้ผู้ป่วยมีอาการไม่พึงประสงค์จนต้องไปรับการรักษาที่โรงพยาบาล เมื่อญาติโทรศัพท์มาสอบถาม เจ้าของร้านซึ่งไม่ใช่เภสัชกรสั่งให้เภสัชกรผู้มีหน้าที่ปฏิบัติการตอบว่า "ร้านไม่ได้จ่ายยานั้น" เพื่อป้องกันการถูกฟ้องร้อง เภสัชกรควรปฏิบัติอย่างไร', '[{"label": "A", "text": "ปฏิบัติตามคำสั่งเจ้าของร้าน เพราะเป็นผู้รับอนุญาตและต้องรับผิดตามกฎหมาย"}, {"label": "B", "text": "ไม่ยืนยันหรือปฏิเสธ แนะนำให้ญาติไปปรึกษาทนายความก่อนสื่อสารต่อ"}, {"label": "C", "text": "ยอมรับเฉพาะเมื่อญาตินำหลักฐานซองยาและใบเสร็จรับเงินมาแสดงต่อร้าน"}, {"label": "D", "text": "เสนอเงินชดเชยให้ญาติโดยขอให้ลงนามว่าจะไม่ร้องเรียนต่อหน่วยงานใด"}, {"label": "E", "text": "แจ้งข้อเท็จจริงแก่ญาติ แสดงความเสียใจ และช่วยแก้ไขผลกระทบที่เกิดขึ้น"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. เปิดเผยข้อเท็จจริงอย่างซื่อสัตย์ แสดงความเสียใจ และช่วยเหลือแก้ไขผลกระทบ — หน้าที่ต่อผู้ป่วยอยู่เหนือคำสั่งที่ขัดต่อจรรยาบรรณ", "reason": "เมื่อความคลาดเคลื่อนทางยาก่อให้เกิดอันตรายแก่ผู้ป่วย เภสัชกรมีหน้าที่ทางจริยธรรม (หลักซื่อสัตย์/veracity และไม่ก่อให้เกิดอันตราย) ในการเปิดเผยข้อเท็จจริงแก่ผู้ป่วยหรือญาติอย่างตรงไปตรงมา แสดงความเสียใจ ให้ข้อมูลที่จำเป็นต่อการรักษา (เช่น ชื่อยาที่ได้รับจริง เพื่อให้แพทย์รักษาได้ถูกต้อง) และช่วยดูแลแก้ไขผลกระทบ\n\nการปฏิเสธข้อเท็จจริงตามคำสั่งของเจ้าของร้านไม่เพียงขัดจรรยาบรรณ แต่ยังอาจทำให้ผู้ป่วยได้รับการรักษาล่าช้าหรือผิดพลาด เภสัชกรในฐานะผู้มีหน้าที่ปฏิบัติการต้องรับผิดชอบในทางวิชาชีพของตนเอง คำสั่งของนายจ้างไม่ใช่ข้ออ้างให้พ้นความรับผิดชอบ นอกจากนี้ควรบันทึกและทบทวนเหตุการณ์เพื่อป้องกันการเกิดซ้ำ", "choices": [{"label": "A", "text": "ปฏิบัติตามคำสั่งเจ้าของร้าน เพราะเป็นผู้รับอนุญาตและต้องรับผิดตามกฎหมาย", "is_correct": false, "explanation": "ผิด คำสั่งของนายจ้างที่ให้ปกปิดข้อเท็จจริงขัดต่อจรรยาบรรณ และไม่ทำให้เภสัชกรพ้นความรับผิดชอบทางวิชาชีพ"}, {"label": "B", "text": "ไม่ยืนยันหรือปฏิเสธ แนะนำให้ญาติไปปรึกษาทนายความก่อนสื่อสารต่อ", "is_correct": false, "explanation": "ผิด การหลีกเลี่ยงไม่ให้ข้อมูลทำให้แพทย์ผู้รักษาขาดข้อมูลสำคัญ และไม่เป็นไปตามหน้าที่เปิดเผยข้อเท็จจริงต่อผู้ป่วย"}, {"label": "C", "text": "ยอมรับเฉพาะเมื่อญาตินำหลักฐานซองยาและใบเสร็จรับเงินมาแสดงต่อร้าน", "is_correct": false, "explanation": "ผิด หน้าที่เปิดเผยไม่ได้ขึ้นกับว่าผู้ป่วยมีหลักฐานหรือไม่ เภสัชกรทราบข้อเท็จจริงจึงต้องแจ้งตามความจริง"}, {"label": "D", "text": "เสนอเงินชดเชยให้ญาติโดยขอให้ลงนามว่าจะไม่ร้องเรียนต่อหน่วยงานใด", "is_correct": false, "explanation": "ผิด การใช้เงินแลกกับการไม่ร้องเรียนเป็นการปิดกั้นสิทธิของผู้ป่วยและไม่ใช่การเปิดเผยอย่างซื่อสัตย์"}, {"label": "E", "text": "แจ้งข้อเท็จจริงแก่ญาติ แสดงความเสียใจ และช่วยแก้ไขผลกระทบที่เกิดขึ้น", "is_correct": true, "explanation": "ถูก เป็นหลักการเปิดเผยข้อมูลหลังเกิดอันตราย (disclosure) ที่สอดคล้องกับหลักซื่อสัตย์และประโยชน์สูงสุดของผู้ป่วย"}], "key_takeaway": "เมื่อความคลาดเคลื่อนทางยาก่อให้เกิดอันตราย เภสัชกรต้องเปิดเผยข้อเท็จจริงอย่างซื่อสัตย์และช่วยแก้ไข แม้นายจ้างสั่งให้ปกปิด"}'::jsonb, 'medium', 'law-day2 • การเปิดเผยข้อมูลหลังเกิดอันตรายจากความคลาดเคลื่อนทางยา'),
('af9055da33d019bcdfbc00c34feeb6ef', 78, 'เภสัชกรเวรเช้าในห้องจ่ายยาผู้ป่วยนอกสังเกตว่าเภสัชกรเพื่อนร่วมงานที่มารับเวรต่อมีกลิ่นสุราแรง พูดจาไม่ชัด และเดินเซ ขณะกำลังจะเริ่มตรวจสอบใบสั่งยา ข้อใดเป็นการปฏิบัติที่เหมาะสมที่สุด', '[{"label": "A", "text": "ปล่อยให้ปฏิบัติงานต่อแต่คอยตรวจสอบใบสั่งยาซ้ำทุกใบแทน"}, {"label": "B", "text": "แจ้งหัวหน้างานทันทีเพื่อให้หยุดปฏิบัติงานและจัดผู้ปฏิบัติงานแทน"}, {"label": "C", "text": "ถ่ายคลิปพฤติกรรมไว้แล้วโพสต์ในกลุ่มไลน์ของบุคลากรทั้งโรงพยาบาล"}, {"label": "D", "text": "ไม่แจ้งผู้ใด เพราะเป็นเรื่องส่วนตัวที่ไม่เกี่ยวข้องกับงานวิชาชีพ"}, {"label": "E", "text": "รับเวรแทนให้เงียบๆ และให้เพื่อนไปพักโดยไม่ต้องบันทึกเหตุการณ์ใด"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. แจ้งหัวหน้างานทันทีเพื่อให้ผู้นั้นหยุดปฏิบัติงานและจัดคนแทน — ความปลอดภัยของผู้ป่วยต้องมาก่อน และใช้ช่องทางตามสายงาน", "reason": "ผู้ประกอบวิชาชีพที่อยู่ในสภาพไม่พร้อมปฏิบัติงานจากสุราหรือสารเสพติดเป็นความเสี่ยงโดยตรงต่อผู้ป่วย เภสัชกรที่พบเห็นมีหน้าที่ทางจริยธรรมที่จะไม่นิ่งเฉย โดยลำดับแรกต้องปกป้องผู้ป่วย คือไม่ให้ผู้นั้นปฏิบัติงานในสภาพดังกล่าว และแจ้งผู้บังคับบัญชาตามสายงานทันทีเพื่อจัดการและจัดบุคลากรทดแทน\n\nการจัดการควรทำผ่านช่องทางที่เหมาะสม เคารพศักดิ์ศรีของเพื่อนร่วมงาน และเปิดโอกาสให้ได้รับความช่วยเหลือ (เช่น การบำบัด) แทนการประจานต่อสาธารณะหรือการปิดบังเพื่อช่วยเพื่อน", "choices": [{"label": "A", "text": "ปล่อยให้ปฏิบัติงานต่อแต่คอยตรวจสอบใบสั่งยาซ้ำทุกใบแทน", "is_correct": false, "explanation": "ผิด การปล่อยให้ผู้ที่ไม่พร้อมปฏิบัติงานยังคงทำงานกับผู้ป่วยเป็นความเสี่ยง และไม่ได้แก้ปัญหาผ่านช่องทางที่เหมาะสม"}, {"label": "B", "text": "แจ้งหัวหน้างานทันทีเพื่อให้หยุดปฏิบัติงานและจัดผู้ปฏิบัติงานแทน", "is_correct": true, "explanation": "ถูก ปกป้องผู้ป่วยก่อนเป็นอันดับแรกและใช้ช่องทางตามสายบังคับบัญชา"}, {"label": "C", "text": "ถ่ายคลิปพฤติกรรมไว้แล้วโพสต์ในกลุ่มไลน์ของบุคลากรทั้งโรงพยาบาล", "is_correct": false, "explanation": "ผิด เป็นการประจานที่ไม่เคารพศักดิ์ศรีของผู้ร่วมวิชาชีพ และไม่ใช่ช่องทางแก้ปัญหาที่เหมาะสม"}, {"label": "D", "text": "ไม่แจ้งผู้ใด เพราะเป็นเรื่องส่วนตัวที่ไม่เกี่ยวข้องกับงานวิชาชีพ", "is_correct": false, "explanation": "ผิด การปฏิบัติงานในสภาพมึนเมาเกี่ยวข้องกับความปลอดภัยของผู้ป่วยโดยตรง จึงไม่ใช่เรื่องส่วนตัว"}, {"label": "E", "text": "รับเวรแทนให้เงียบๆ และให้เพื่อนไปพักโดยไม่ต้องบันทึกเหตุการณ์ใด", "is_correct": false, "explanation": "ผิด แม้ปกป้องผู้ป่วยในวันนั้น แต่การปกปิดทำให้ปัญหาไม่ได้รับการแก้ไขและอาจเกิดซ้ำ ควรแจ้งผู้บังคับบัญชา"}], "key_takeaway": "พบผู้ร่วมวิชาชีพไม่พร้อมปฏิบัติงาน ต้องปกป้องผู้ป่วยทันทีและแจ้งผู้บังคับบัญชาตามสายงาน ไม่นิ่งเฉยและไม่ประจาน"}'::jsonb, 'easy', 'law-day2 • ผู้ร่วมวิชาชีพที่ไม่พร้อมปฏิบัติงาน (impaired colleague)'),
('511ca5a87d93bb561280e384beee0496', 79, 'เภสัชกรร้านยาทราบจากผู้ป่วยหลายรายว่าร้านขายของชำในหมู่บ้านใกล้เคียงขายยาปฏิชีวนะและยาสเตียรอยด์แบ่งใส่ถุงพลาสติกไม่มีฉลาก โดยไม่มีใบอนุญาตขายยา และมีผู้ป่วยรายหนึ่งเกิดภาวะแทรกซ้อนจากการใช้ยาดังกล่าว เภสัชกรควรดำเนินการอย่างไรเหมาะสมที่สุด', '[{"label": "A", "text": "ไปที่ร้านขายของชำเพื่อตรวจสอบและยึดยาที่ไม่มีฉลากทั้งหมดมาทำลายด้วยตนเอง"}, {"label": "B", "text": "โพสต์ชื่อร้านและรูปถ่ายลงเพจของร้านยาเพื่อเตือนประชาชนในพื้นที่"}, {"label": "C", "text": "ไม่ดำเนินการใด เพราะเป็นหน้าที่ของเจ้าหน้าที่รัฐที่จะตรวจพบเอง"}, {"label": "D", "text": "แจ้งเบาะแสต่อ สสจ. ในพื้นที่ หรือ อย. ทางสายด่วน 1556"}, {"label": "E", "text": "รวบรวมชื่อผู้ป่วยทุกรายที่เคยซื้อยาและส่งรายชื่อให้สื่อมวลชนเป็นหลักฐาน"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. แจ้งข้อมูลต่อหน่วยงานที่มีอำนาจ เช่น สสจ. หรือ อย. (สายด่วน 1556) — ให้เจ้าหน้าที่ตรวจสอบตามกฎหมาย", "reason": "การขายยาอันตรายโดยไม่มีใบอนุญาตและแบ่งยาใส่ถุงไม่มีฉลากเป็นการกระทำที่ผิดกฎหมายยาและเป็นอันตรายต่อสาธารณะ เภสัชกรในฐานะผู้ประกอบวิชาชีพที่มีหน้าที่คุ้มครองสุขภาพของประชาชนควรแจ้งเบาะแสต่อหน่วยงานที่มีอำนาจ ได้แก่ สำนักงานสาธารณสุขจังหวัด (สสจ.) ในพื้นที่ หรือสำนักงานคณะกรรมการอาหารและยา (อย.) ผ่านสายด่วน 1556 หรือช่องทางออนไลน์ พร้อมรายละเอียดที่ช่วยให้ตรวจสอบได้\n\nเภสัชกรไม่มีอำนาจตรวจค้นหรือยึดของกลางเอง การเผชิญหน้าหรือประจานทางสื่อสังคมอาจเกิดผลเสียและไม่ใช่ช่องทางที่ถูกต้อง ส่วนการเปิดเผยชื่อผู้ป่วยที่ให้ข้อมูลโดยไม่ได้รับความยินยอมขัดกับการรักษาความลับ", "choices": [{"label": "A", "text": "ไปที่ร้านขายของชำเพื่อตรวจสอบและยึดยาที่ไม่มีฉลากทั้งหมดมาทำลายด้วยตนเอง", "is_correct": false, "explanation": "ผิด เภสัชกรไม่มีอำนาจตรวจค้นหรือยึดของกลาง อำนาจนี้เป็นของพนักงานเจ้าหน้าที่ตามกฎหมาย"}, {"label": "B", "text": "โพสต์ชื่อร้านและรูปถ่ายลงเพจของร้านยาเพื่อเตือนประชาชนในพื้นที่", "is_correct": false, "explanation": "ผิด การประจานทางสื่อสังคมไม่ใช่ช่องทางบังคับใช้กฎหมาย อาจเสี่ยงต่อการถูกฟ้องหมิ่นประมาท และไม่ทำให้การขายยุติ"}, {"label": "C", "text": "ไม่ดำเนินการใด เพราะเป็นหน้าที่ของเจ้าหน้าที่รัฐที่จะตรวจพบเอง", "is_correct": false, "explanation": "ผิด เภสัชกรมีหน้าที่ทางวิชาชีพต่อสุขภาพของสาธารณะ เมื่อทราบการกระทำที่เป็นอันตรายควรแจ้งหน่วยงานที่เกี่ยวข้อง"}, {"label": "D", "text": "แจ้งเบาะแสต่อ สสจ. ในพื้นที่ หรือ อย. ทางสายด่วน 1556", "is_correct": true, "explanation": "ถูก เป็นช่องทางที่เหมาะสม ให้หน่วยงานที่มีอำนาจตรวจสอบและดำเนินการตามกฎหมาย"}, {"label": "E", "text": "รวบรวมชื่อผู้ป่วยทุกรายที่เคยซื้อยาและส่งรายชื่อให้สื่อมวลชนเป็นหลักฐาน", "is_correct": false, "explanation": "ผิด เป็นการเปิดเผยข้อมูลสุขภาพของผู้ป่วยโดยไม่ได้รับความยินยอม และสื่อมวลชนไม่ใช่หน่วยงานบังคับใช้กฎหมาย"}], "key_takeaway": "เมื่อพบการขายยาผิดกฎหมาย เภสัชกรควรแจ้ง สสจ. หรือ อย. (1556) ให้ดำเนินการตามอำนาจ ไม่ใช้วิธีจัดการเองหรือประจาน"}'::jsonb, 'medium', 'law-day2 • การแจ้งเบาะแสการขายยาผิดกฎหมาย (whistleblowing)'),
('f6c651307e5484f8f9821f49c48e98f6', 80, 'ผู้ป่วยสูงอายุรายหนึ่งตะโกนต่อว่าเภสัชกรเสียงดังหน้าช่องจ่ายยาว่ารอรับยานานกว่า 1 ชั่วโมงและพนักงานพูดจาไม่สุภาพ ผู้ป่วยรายอื่นเริ่มหันมามอง ข้อใดเป็นแนวทางการจัดการข้อร้องเรียนที่เหมาะสมที่สุด', '[{"label": "A", "text": "อธิบายทันทีว่าความล่าช้าเกิดจากผู้ป่วยมาก และพนักงานไม่ได้ทำผิดแต่อย่างใด"}, {"label": "B", "text": "รับฟังอย่างสงบ แสดงความเข้าใจ แยกพูดคุยในที่เหมาะสม และบันทึกเพื่อแก้ไข"}, {"label": "C", "text": "ขอให้เจ้าหน้าที่รักษาความปลอดภัยพาผู้ป่วยออกนอกบริเวณห้องยาทันที"}, {"label": "D", "text": "จัดยาให้ผู้ป่วยก่อนคิวอื่นทันทีเพื่อให้เรื่องยุติและไม่ต้องบันทึกเหตุการณ์"}, {"label": "E", "text": "แนะนำให้ผู้ป่วยไปร้องเรียนที่ผู้อำนวยการ เพราะห้องยาไม่มีหน้าที่รับเรื่อง"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. รับฟังอย่างตั้งใจ แสดงความเข้าใจ เชิญไปพูดคุยในที่เหมาะสม และบันทึกเพื่อติดตามแก้ไข — เป็นหลักการจัดการข้อร้องเรียนอย่างมืออาชีพ", "reason": "หลักการจัดการผู้ป่วยที่ไม่พอใจคือรักษาความสงบ รับฟังโดยไม่ขัดจังหวะ แสดงความเห็นอกเห็นใจและขอโทษในความไม่สะดวกที่เกิดขึ้น (ไม่จำเป็นต้องยอมรับผิดในสิ่งที่ยังไม่ได้ตรวจสอบ) เชิญไปพูดคุยในบริเวณที่เป็นส่วนตัวเพื่อลดผลกระทบต่อผู้อื่นและรักษาศักดิ์ศรีของผู้ป่วย จากนั้นอธิบายสาเหตุ แก้ไขปัญหาเฉพาะหน้า และบันทึกข้อร้องเรียนเข้าสู่ระบบเพื่อทบทวนและแจ้งผลกลับ\n\nข้อร้องเรียนเป็นข้อมูลที่มีคุณค่าต่อการพัฒนาคุณภาพบริการ การโต้เถียง การเพิกเฉย หรือการให้สิทธิพิเศษเพื่อให้เรื่องจบโดยไม่แก้ที่ระบบ ไม่ใช่แนวทางที่เหมาะสม", "choices": [{"label": "A", "text": "อธิบายทันทีว่าความล่าช้าเกิดจากผู้ป่วยมาก และพนักงานไม่ได้ทำผิดแต่อย่างใด", "is_correct": false, "explanation": "ผิด การปกป้องตนเองทันทีโดยยังไม่รับฟังทำให้ผู้ป่วยรู้สึกไม่ได้รับความใส่ใจและความขัดแย้งรุนแรงขึ้น"}, {"label": "B", "text": "รับฟังอย่างสงบ แสดงความเข้าใจ แยกพูดคุยในที่เหมาะสม และบันทึกเพื่อแก้ไข", "is_correct": true, "explanation": "ถูก เป็นแนวทางจัดการข้อร้องเรียนอย่างมืออาชีพ ทั้งลดความขัดแย้งและนำข้อมูลไปพัฒนาระบบ"}, {"label": "C", "text": "ขอให้เจ้าหน้าที่รักษาความปลอดภัยพาผู้ป่วยออกนอกบริเวณห้องยาทันที", "is_correct": false, "explanation": "ผิด ผู้ป่วยเพียงแสดงความไม่พอใจโดยไม่มีพฤติกรรมคุกคาม การใช้มาตรการรักษาความปลอดภัยเป็นการตอบสนองที่เกินจำเป็น"}, {"label": "D", "text": "จัดยาให้ผู้ป่วยก่อนคิวอื่นทันทีเพื่อให้เรื่องยุติและไม่ต้องบันทึกเหตุการณ์", "is_correct": false, "explanation": "ผิด การแซงคิวเพื่อยุติเรื่องไม่เป็นธรรมต่อผู้ป่วยรายอื่น และการไม่บันทึกทำให้ไม่มีการแก้ปัญหาเชิงระบบ"}, {"label": "E", "text": "แนะนำให้ผู้ป่วยไปร้องเรียนที่ผู้อำนวยการ เพราะห้องยาไม่มีหน้าที่รับเรื่อง", "is_correct": false, "explanation": "ผิด ผู้ให้บริการทุกจุดควรรับฟังและรับเรื่องร้องเรียนเบื้องต้น การปัดความรับผิดชอบทำให้ผู้ป่วยไม่พอใจมากขึ้น"}], "key_takeaway": "จัดการข้อร้องเรียนด้วยการรับฟัง เห็นอกเห็นใจ แยกพูดคุยในที่เหมาะสม และบันทึกเพื่อแก้ไขเชิงระบบ"}'::jsonb, 'easy', 'law-day2 • การจัดการข้อร้องเรียนและผู้ป่วยที่ไม่พอใจ'),
('aa317965b72fbedae2f06a775841c64c', 81, 'เด็กหญิงอายุประมาณ 14 ปี สวมชุดนักเรียน มาที่ร้านยาเพียงลำพัง ขอซื้อยาเม็ดพาราเซตามอล 500 มิลลิกรัม จำนวน 5 แผง ท่าทางเศร้าซึม ไม่สบตา เมื่อถามว่าจะนำไปใช้อย่างไรก็ตอบเลี่ยงๆ ข้อใดเป็นการปฏิบัติที่เหมาะสมที่สุดของเภสัชกร', '[{"label": "A", "text": "จำหน่ายตามที่ขอ เพราะพาราเซตามอลไม่ใช่ยาอันตรายและไม่มีกฎหมายห้ามขายแก่เด็ก"}, {"label": "B", "text": "ปฏิเสธการขายทันที และบอกให้กลับไปพาผู้ปกครองมาซื้อแทนเท่านั้นตามกฎหมาย"}, {"label": "C", "text": "พูดคุยเป็นส่วนตัวเพื่อประเมินความเสี่ยง จำกัดปริมาณยา และแนะนำแหล่งช่วยเหลือ"}, {"label": "D", "text": "จำหน่ายให้ แต่จดชื่อโรงเรียนไว้เพื่อโทรศัพท์แจ้งครูประจำชั้นในภายหลัง"}, {"label": "E", "text": "จำหน่ายเป็นยาน้ำเชื่อมแทนยาเม็ดเพื่อลดความเสี่ยงหากรับประทานเกินขนาด"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. พูดคุยในที่เป็นส่วนตัวเพื่อประเมินความเสี่ยง จำกัดปริมาณยา และแนะนำแหล่งช่วยเหลือ เช่น สายด่วนสุขภาพจิต 1323 — วิจารณญาณทางวิชาชีพเพื่อความปลอดภัยของผู้ซื้อ", "reason": "แม้พาราเซตามอลจะเป็นยาที่หาซื้อได้ทั่วไป แต่เภสัชกรมีหน้าที่ใช้วิจารณญาณทางวิชาชีพเพื่อความปลอดภัยของผู้รับยา การขอซื้อปริมาณมากผิดปกติร่วมกับอาการเศร้าซึมและการตอบเลี่ยงเป็นสัญญาณเตือนความเสี่ยงต่อการทำร้ายตนเอง เภสัชกรจึงไม่ควรขายตามที่ขอโดยไม่ประเมิน\n\nแนวทางที่เหมาะสมคือพูดคุยด้วยท่าทีเป็นมิตรในที่เป็นส่วนตัว สอบถามอาการและความต้องการจริง จำหน่ายเฉพาะปริมาณที่เหมาะสมกับการใช้ (หรืองดจำหน่ายหากมีความเสี่ยงชัดเจน) และแนะนำแหล่งช่วยเหลือ เช่น สายด่วนสุขภาพจิต 1323 หรือการพบผู้เชี่ยวชาญ โดยคำนึงถึงความปลอดภัยเป็นสำคัญ การปฏิเสธอย่างห้วนๆ หรือการตำหนิอาจทำให้เด็กไปหาซื้อที่อื่นโดยไม่ได้รับความช่วยเหลือ", "choices": [{"label": "A", "text": "จำหน่ายตามที่ขอ เพราะพาราเซตามอลไม่ใช่ยาอันตรายและไม่มีกฎหมายห้ามขายแก่เด็ก", "is_correct": false, "explanation": "ผิด แม้ไม่มีข้อห้ามเฉพาะ แต่เภสัชกรต้องใช้วิจารณญาณเมื่อมีสัญญาณเสี่ยง การขายโดยไม่ประเมินอาจก่ออันตรายร้ายแรง"}, {"label": "B", "text": "ปฏิเสธการขายทันที และบอกให้กลับไปพาผู้ปกครองมาซื้อแทนเท่านั้นตามกฎหมาย", "is_correct": false, "explanation": "ผิด การปฏิเสธโดยไม่พูดคุยหรือประเมินทำให้พลาดโอกาสช่วยเหลือ และเด็กอาจไปหาซื้อที่อื่น"}, {"label": "C", "text": "พูดคุยเป็นส่วนตัวเพื่อประเมินความเสี่ยง จำกัดปริมาณยา และแนะนำแหล่งช่วยเหลือ", "is_correct": true, "explanation": "ถูก เป็นการใช้วิจารณญาณทางวิชาชีพเพื่อความปลอดภัย และเชื่อมต่อสู่ความช่วยเหลือ เช่น สายด่วน 1323"}, {"label": "D", "text": "จำหน่ายให้ แต่จดชื่อโรงเรียนไว้เพื่อโทรศัพท์แจ้งครูประจำชั้นในภายหลัง", "is_correct": false, "explanation": "ผิด การขายปริมาณมากยังคงเสี่ยง และการติดต่อโรงเรียนโดยไม่ประเมินหรือไม่ได้รับความยินยอมไม่ใช่แนวทางที่เหมาะสมเป็นลำดับแรก"}, {"label": "E", "text": "จำหน่ายเป็นยาน้ำเชื่อมแทนยาเม็ดเพื่อลดความเสี่ยงหากรับประทานเกินขนาด", "is_correct": false, "explanation": "ผิด การเปลี่ยนรูปแบบยาไม่ได้แก้ไขความเสี่ยงที่แท้จริงและไม่ได้ประเมินหรือช่วยเหลือผู้ซื้อ"}], "key_takeaway": "เมื่อผู้เยาว์ขอซื้อยาในลักษณะที่ส่อความเสี่ยง เภสัชกรต้องประเมิน จำกัดปริมาณ และเชื่อมต่อความช่วยเหลือ ไม่ใช่ขายหรือปฏิเสธโดยอัตโนมัติ"}'::jsonb, 'medium', 'law-day2 • การจ่ายยาให้ผู้เยาว์และการใช้วิจารณญาณทางวิชาชีพ'),
('bcecf67fbbe1b2bdaf39273a334475a9', 82, 'นักเรียนหญิงอายุ 16 ปี มาที่ร้านยาเพียงลำพังเพื่อขอซื้อยาเม็ดคุมกำเนิดฉุกเฉิน และขอร้องเภสัชกรไม่ให้บอกผู้ปกครอง จากการซักถามพบว่ามีเพศสัมพันธ์โดยสมัครใจกับแฟนวัยเดียวกันเมื่อคืนก่อน ข้อใดสอดคล้องกับหลักจริยธรรมและหลักการของ พ.ร.บ.การป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่น พ.ศ. 2559 มากที่สุด', '[{"label": "A", "text": "ต้องได้รับความยินยอมจากผู้ปกครองก่อน เพราะผู้ซื้อยังเป็นผู้เยาว์ตามกฎหมาย"}, {"label": "B", "text": "ไม่จำหน่ายยา แต่ส่งต่อไปโรงพยาบาลเพื่อพบสูติแพทย์ก่อนในทุกกรณีที่เป็นผู้เยาว์"}, {"label": "C", "text": "จำหน่ายยาให้ แต่แจ้งโรงเรียนเพื่อให้ครูแนะแนวช่วยติดตามดูแลนักเรียนต่อไป"}, {"label": "D", "text": "จำหน่ายยาให้ตามที่ขอโดยไม่ซักถามเพิ่มเติม เพื่อเคารพความเป็นส่วนตัวของผู้ซื้อ"}, {"label": "E", "text": "ให้คำปรึกษาเป็นส่วนตัว จ่ายยาตามความเหมาะสม และรักษาความลับของผู้รับบริการ"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. ให้คำปรึกษาและจ่ายยาตามวิจารณญาณทางวิชาชีพโดยรักษาความลับ พร้อมแนะนำการคุมกำเนิดที่เหมาะสมและการป้องกันโรคติดต่อทางเพศสัมพันธ์ — วัยรุ่นมีสิทธิได้รับข้อมูลและบริการอนามัยเจริญพันธุ์โดยรักษาความลับ", "reason": "พ.ร.บ.การป้องกันและแก้ไขปัญหาการตั้งครรภ์ในวัยรุ่น พ.ศ. 2559 รับรองสิทธิของวัยรุ่น (อายุเกิน 10 ปีแต่ยังไม่ถึง 20 ปีบริบูรณ์) ในการตัดสินใจด้วยตนเอง ได้รับข้อมูลข่าวสารและความรู้ ได้รับบริการอนามัยการเจริญพันธุ์ และได้รับการรักษาความลับและความเป็นส่วนตัว โดยปราศจากการเลือกปฏิบัติ ดังนั้นการกำหนดให้ต้องมีความยินยอมของผู้ปกครองก่อนให้คำปรึกษาหรือจ่ายยาคุมกำเนิดฉุกเฉินจึงไม่สอดคล้องกับหลักการนี้ และอาจผลักวัยรุ่นออกจากระบบบริการจนเสี่ยงต่อการตั้งครรภ์ไม่พร้อม\n\nเภสัชกรควรให้คำปรึกษาในที่เป็นส่วนตัว ประเมินความเหมาะสมของการใช้ยา อธิบายว่ายาคุมกำเนิดฉุกเฉินไม่ใช่วิธีคุมกำเนิดประจำ แนะนำการคุมกำเนิดที่เหมาะสมและการใช้ถุงยางอนามัยเพื่อป้องกันโรคติดต่อทางเพศสัมพันธ์ และสังเกตสัญญาณของการถูกบังคับหรือล่วงละเมิด ซึ่งหากพบจะต้องพิจารณาส่งต่อเพื่อการคุ้มครองเด็ก การรักษาความลับไม่ใช่การละเลยความปลอดภัยของวัยรุ่น", "choices": [{"label": "A", "text": "ต้องได้รับความยินยอมจากผู้ปกครองก่อน เพราะผู้ซื้อยังเป็นผู้เยาว์ตามกฎหมาย", "is_correct": false, "explanation": "ผิด หลักการของ พ.ร.บ.ฯ พ.ศ. 2559 รับรองสิทธิวัยรุ่นในการได้รับบริการอนามัยเจริญพันธุ์และตัดสินใจด้วยตนเอง การบังคับให้มีผู้ปกครองอาจทำให้วัยรุ่นไม่เข้ารับบริการ"}, {"label": "B", "text": "ไม่จำหน่ายยา แต่ส่งต่อไปโรงพยาบาลเพื่อพบสูติแพทย์ก่อนในทุกกรณีที่เป็นผู้เยาว์", "is_correct": false, "explanation": "ผิด ไม่มีบทบัญญัติทั่วไปที่กำหนดว่าผู้เยาว์ซื้อยาได้เฉพาะเมื่อมีผู้ปกครอง และการปฏิเสธโดยไม่พูดคุยหรือประเมินทำให้พลาดโอกาสช่วยเหลือ เด็กอาจไปหาซื้อที่อื่น"}, {"label": "C", "text": "จำหน่ายยาให้ แต่แจ้งโรงเรียนเพื่อให้ครูแนะแนวช่วยติดตามดูแลนักเรียนต่อไป", "is_correct": false, "explanation": "ผิด เป็นการเปิดเผยข้อมูลสุขภาพที่อ่อนไหวโดยไม่ได้รับความยินยอม ขัดต่อสิทธิในความลับและความเป็นส่วนตัว"}, {"label": "D", "text": "จำหน่ายยาให้ตามที่ขอโดยไม่ซักถามเพิ่มเติม เพื่อเคารพความเป็นส่วนตัวของผู้ซื้อ", "is_correct": false, "explanation": "ผิด การเคารพความเป็นส่วนตัวไม่ได้หมายถึงงดการประเมินและให้คำปรึกษา เภสัชกรยังต้องให้ข้อมูลการใช้ยา การคุมกำเนิดต่อเนื่อง และประเมินความปลอดภัย"}, {"label": "E", "text": "ให้คำปรึกษาเป็นส่วนตัว จ่ายยาตามความเหมาะสม และรักษาความลับของผู้รับบริการ", "is_correct": true, "explanation": "ถูก สอดคล้องกับสิทธิของวัยรุ่นในการได้รับข้อมูลและบริการอนามัยเจริญพันธุ์โดยรักษาความลับ ร่วมกับหน้าที่ให้คำปรึกษาของเภสัชกร"}], "key_takeaway": "วัยรุ่นมีสิทธิได้รับคำปรึกษาและบริการอนามัยเจริญพันธุ์โดยรักษาความลับ เภสัชกรจึงไม่ควรกำหนดให้ต้องมีผู้ปกครองยินยอม แต่ยังต้องให้คำปรึกษาและประเมินความปลอดภัย"}'::jsonb, 'hard', 'law-day2 • สิทธิวัยรุ่นในบริการอนามัยเจริญพันธุ์และการรักษาความลับ'),
('3c18a8318396d347d240b4c8c50237e0', 83, 'เภสัชกรโรงพยาบาลพบใบสั่งยาที่มีการสั่งยาซ้ำซ้อนน่าสนใจ จึงถ่ายภาพใบสั่งยาซึ่งเห็นชื่อ-นามสกุลผู้ป่วยและเลขประจำตัวผู้ป่วย (HN) แล้วนำไปโพสต์ในกลุ่มเฟซบุ๊กแบบปิดของเภสัชกรเพื่อแลกเปลี่ยนความรู้ ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "ไม่เหมาะสม ต้องลบข้อมูลที่ระบุตัวผู้ป่วยก่อน แม้เป็นกลุ่มปิดเพื่อการศึกษา"}, {"label": "B", "text": "เหมาะสม เพราะสมาชิกในกลุ่มเป็นผู้ประกอบวิชาชีพที่มีหน้าที่รักษาความลับเช่นกัน"}, {"label": "C", "text": "เหมาะสม หากโพสต์นั้นได้รับความเห็นชอบจากแพทย์ผู้สั่งยาก่อนการเผยแพร่"}, {"label": "D", "text": "เหมาะสม หากลบโพสต์ภายใน 24 ชั่วโมงหลังมีผู้แสดงความคิดเห็นแล้ว"}, {"label": "E", "text": "ไม่เหมาะสม เฉพาะกรณีที่ผู้ป่วยทราบเรื่องและยื่นเรื่องร้องเรียนต่อโรงพยาบาล"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ไม่เหมาะสม ต้องปกปิดข้อมูลที่ระบุตัวผู้ป่วยก่อนเผยแพร่ แม้เป็นกลุ่มปิดเพื่อการศึกษา — วัตถุประสงค์ทางวิชาการไม่ยกเว้นหน้าที่รักษาความลับ", "reason": "ข้อมูลในใบสั่งยาเป็นข้อมูลสุขภาพซึ่งเป็นข้อมูลส่วนบุคคลที่อ่อนไหว เภสัชกรมีหน้าที่รักษาความลับของผู้ป่วยทั้งตามจรรยาบรรณวิชาชีพและกฎหมาย (เช่น พ.ร.บ.สุขภาพแห่งชาติ และ พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคล) การนำข้อมูลไปเผยแพร่โดยผู้ป่วยไม่ได้ยินยอมถือเป็นการละเมิด แม้จะโพสต์ในกลุ่มปิดหรือมีเจตนาเพื่อการศึกษา เพราะกลุ่มปิดยังมีสมาชิกจำนวนมากที่ไม่เกี่ยวข้องกับการดูแลผู้ป่วยและข้อมูลอาจถูกส่งต่อได้\n\nหากต้องการแลกเปลี่ยนกรณีศึกษา ควรนำเสนอเฉพาะข้อมูลทางคลินิกที่จำเป็นโดยลบข้อมูลที่ระบุตัวตนได้ทั้งหมด (de-identification) เช่น ชื่อ HN รูปภาพ และรายละเอียดที่ทำให้ระบุตัวได้ รวมทั้งปฏิบัติตามนโยบายของหน่วยงาน", "choices": [{"label": "A", "text": "ไม่เหมาะสม ต้องลบข้อมูลที่ระบุตัวผู้ป่วยก่อน แม้เป็นกลุ่มปิดเพื่อการศึกษา", "is_correct": true, "explanation": "ถูก การรักษาความลับไม่ได้รับการยกเว้นเพราะเป็นกลุ่มปิดหรือมีวัตถุประสงค์ทางวิชาการ ต้อง de-identify ก่อนเผยแพร่"}, {"label": "B", "text": "เหมาะสม เพราะสมาชิกในกลุ่มเป็นผู้ประกอบวิชาชีพที่มีหน้าที่รักษาความลับเช่นกัน", "is_correct": false, "explanation": "ผิด สมาชิกในกลุ่มไม่ได้มีส่วนในการดูแลผู้ป่วยรายนี้ การเปิดเผยแก่บุคคลเหล่านี้โดยไม่จำเป็นยังคงเป็นการละเมิดความลับ"}, {"label": "C", "text": "เหมาะสม หากโพสต์นั้นได้รับความเห็นชอบจากแพทย์ผู้สั่งยาก่อนการเผยแพร่", "is_correct": false, "explanation": "ผิด ข้อมูลเป็นของผู้ป่วย ความเห็นชอบของแพทย์ไม่สามารถแทนความยินยอมของผู้ป่วยหรือทำให้การเปิดเผยชอบธรรม"}, {"label": "D", "text": "เหมาะสม หากลบโพสต์ภายใน 24 ชั่วโมงหลังมีผู้แสดงความคิดเห็นแล้ว", "is_correct": false, "explanation": "ผิด การเปิดเผยเกิดขึ้นแล้วตั้งแต่โพสต์ และข้อมูลอาจถูกบันทึกหรือส่งต่อได้ การลบภายหลังไม่ได้ทำให้การกระทำชอบธรรม"}, {"label": "E", "text": "ไม่เหมาะสม เฉพาะกรณีที่ผู้ป่วยทราบเรื่องและยื่นเรื่องร้องเรียนต่อโรงพยาบาล", "is_correct": false, "explanation": "ผิด ความไม่เหมาะสมเกิดจากการเปิดเผยข้อมูลโดยไม่ได้รับความยินยอม ไม่ได้ขึ้นกับว่าผู้ป่วยจะร้องเรียนหรือไม่"}], "key_takeaway": "การแลกเปลี่ยนกรณีศึกษาทางสื่อออนไลน์ต้องลบข้อมูลระบุตัวผู้ป่วยเสมอ กลุ่มปิดหรือเจตนาทางวิชาการไม่ใช่ข้อยกเว้น"}'::jsonb, 'medium', 'law-day2 • การใช้สื่อสังคมออนไลน์ของเภสัชกรและการรักษาความลับ'),
('d5083cb610724d79e26f5a41467987a3', 84, 'ป้าสมศรีเป็นลูกค้าประจำของร้านยามาหลายปี เภสัชกรช่วยติดตามการใช้ยาโรคเรื้อรังให้ทุกเดือน ช่วงเทศกาลปีใหม่ป้าสมศรีนำขนมที่ทำเองหนึ่งกล่องมามอบให้เพื่อขอบคุณ โดยไม่ได้ขอสิ่งตอบแทนใด ข้อใดเป็นแนวทางที่เหมาะสมที่สุด', '[{"label": "A", "text": "ปฏิเสธทุกกรณี เพราะเภสัชกรห้ามรับสิ่งของใดๆ จากผู้ป่วยโดยเด็ดขาด"}, {"label": "B", "text": "รับไว้ แล้วให้ส่วนลดค่ายาพิเศษแก่ป้าสมศรีทุกครั้งเป็นการตอบแทน"}, {"label": "C", "text": "รับไว้ได้เฉพาะเมื่อป้าสมศรีลงนามในเอกสารว่าให้โดยสมัครใจเท่านั้น"}, {"label": "D", "text": "รับไว้ด้วยความขอบคุณ เพราะเป็นของเล็กน้อยตามประเพณีและไม่มีเงื่อนไขใด"}, {"label": "E", "text": "ขอให้ป้าสมศรีให้เป็นเงินสดแทนเพื่อนำเข้ากองทุนสวัสดิการพนักงานร้าน"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. รับไว้ด้วยความขอบคุณได้ เพราะเป็นของมูลค่าเล็กน้อยตามประเพณีที่ไม่มีผลต่อการตัดสินใจทางวิชาชีพ — แตกต่างจากของที่มีเงื่อนไขหรือคาดหวังสิ่งตอบแทน", "reason": "การรับของขวัญจากผู้ป่วยไม่ได้เป็นสิ่งต้องห้ามโดยเด็ดขาด หลักที่ใช้พิจารณาคือของนั้นมีมูลค่าเล็กน้อย ให้ตามโอกาสหรือประเพณีเพื่อแสดงความขอบคุณ ไม่มีเงื่อนไขหรือคาดหวังการปฏิบัติที่ต่างจากผู้ป่วยรายอื่น และไม่ส่งผลต่อความเป็นกลางในการตัดสินใจทางวิชาชีพ การปฏิเสธของเล็กน้อยด้วยเจตนาดีอาจทำให้ผู้ป่วยเสียความรู้สึกโดยไม่จำเป็น\n\nในทางกลับกัน ของขวัญที่มีมูลค่าสูง เงินสด หรือของที่ให้เพื่อแลกกับสิทธิพิเศษ (เช่น จ่ายยาที่ต้องใช้ใบสั่งแพทย์ให้โดยไม่มีใบสั่ง) ควรปฏิเสธ ส่วนของขวัญจากบริษัทยามีความเสี่ยงต่อผลประโยชน์ทับซ้อนสูงกว่า และอยู่ภายใต้เกณฑ์จริยธรรมว่าด้วยการส่งเสริมการขายยาที่เข้มงวดกว่า", "choices": [{"label": "A", "text": "ปฏิเสธทุกกรณี เพราะเภสัชกรห้ามรับสิ่งของใดๆ จากผู้ป่วยโดยเด็ดขาด", "is_correct": false, "explanation": "ผิด ไม่มีหลักการที่ห้ามรับของเล็กน้อยตามประเพณีจากผู้ป่วยโดยเด็ดขาด การปฏิเสธอาจทำร้ายความรู้สึกของผู้ป่วยโดยไม่จำเป็น"}, {"label": "B", "text": "รับไว้ แล้วให้ส่วนลดค่ายาพิเศษแก่ป้าสมศรีทุกครั้งเป็นการตอบแทน", "is_correct": false, "explanation": "ผิด การให้สิทธิพิเศษตอบแทนทำให้ของขวัญกลายเป็นการแลกเปลี่ยนผลประโยชน์ และไม่เป็นธรรมต่อผู้ป่วยรายอื่น"}, {"label": "C", "text": "รับไว้ได้เฉพาะเมื่อป้าสมศรีลงนามในเอกสารว่าให้โดยสมัครใจเท่านั้น", "is_correct": false, "explanation": "ผิด ของขวัญเล็กน้อยตามประเพณีไม่จำเป็นต้องมีเอกสารยืนยัน ข้อกำหนดเช่นนี้ไม่สมเหตุสมผลและไม่ใช่หลักที่ใช้"}, {"label": "D", "text": "รับไว้ด้วยความขอบคุณ เพราะเป็นของเล็กน้อยตามประเพณีและไม่มีเงื่อนไขใด", "is_correct": true, "explanation": "ถูก ของมูลค่าเล็กน้อยที่ให้ด้วยความขอบคุณโดยไม่มีเงื่อนไขไม่กระทบความเป็นกลางของเภสัชกร"}, {"label": "E", "text": "ขอให้ป้าสมศรีให้เป็นเงินสดแทนเพื่อนำเข้ากองทุนสวัสดิการพนักงานร้าน", "is_correct": false, "explanation": "ผิด การเรียกรับเงินจากผู้ป่วยไม่เหมาะสมต่อวิชาชีพ ไม่ว่าจะนำไปใช้เพื่อวัตถุประสงค์ใด"}], "key_takeaway": "ของขวัญเล็กน้อยตามประเพณีจากผู้ป่วยรับได้หากไม่มีเงื่อนไขและไม่กระทบการตัดสินใจทางวิชาชีพ แต่ต้องปฏิเสธของมูลค่าสูงหรือที่แลกกับสิทธิพิเศษ"}'::jsonb, 'easy', 'law-day2 • การรับของขวัญจากผู้ป่วย'),
('ae205f81116f7bbbec38c864bc069204', 85, 'ช่วงที่ค่าฝุ่น PM2.5 สูงต่อเนื่องและหน้ากากอนามัยชนิด N95 ขาดตลาด เจ้าของร้านยาต้องการขึ้นราคาหน้ากากที่มีอยู่ในสต็อกเป็น 3 เท่าของราคาเดิม และนำป้ายแสดงราคาออกเพื่อให้พนักงานแจ้งราคาตามความเหมาะสมของลูกค้าแต่ละราย เภสัชกรควรให้ความเห็นอย่างไรเหมาะสมที่สุด', '[{"label": "A", "text": "ทำได้ เพราะเป็นกลไกตลาดตามอุปสงค์และอุปทาน และร้านยาเป็นธุรกิจเอกชน"}, {"label": "B", "text": "ทำได้ หากราคาที่ตั้งใหม่ยังต่ำกว่าราคาที่ขายในตลาดออนไลน์ในช่วงเดียวกัน"}, {"label": "C", "text": "ไม่ควรทำ ต้องขายในราคาที่เป็นธรรม แสดงราคาชัดเจน และไม่ค้ากำไรเกินควร"}, {"label": "D", "text": "ทำได้ หากขายเฉพาะลูกค้าทั่วไป แต่คงราคาเดิมไว้สำหรับลูกค้าประจำของร้าน"}, {"label": "E", "text": "ไม่ควรทำ เพราะร้านยาต้องจำหน่ายหน้ากากในราคาทุนตลอดเวลาที่มีค่าฝุ่นสูง"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. ควรจำหน่ายในราคาที่เป็นธรรมและแสดงราคาให้ชัดเจน เพราะการค้ากำไรเกินควรในภาวะขาดแคลนขัดจรรยาบรรณและอาจผิดกฎหมายว่าด้วยราคาสินค้า — ผู้บริโภคร้องเรียนได้ที่กรมการค้าภายใน 1569", "reason": "ผู้ประกอบวิชาชีพเภสัชกรรมต้องไม่แสวงหาผลประโยชน์โดยมิชอบจากความจำเป็นของผู้ป่วยหรือประชาชน การขึ้นราคาสินค้าสุขภาพที่จำเป็นอย่างมากในช่วงขาดแคลนเป็นการค้ากำไรเกินควรซึ่งขัดต่อจรรยาบรรณ นอกจากนี้ พ.ร.บ.ว่าด้วยราคาสินค้าและบริการ พ.ศ. 2542 กำหนดให้ผู้จำหน่ายสินค้าต้องแสดงราคาสินค้าให้ชัดเจน และห้ามการกำหนดราคาซื้อขายที่ไม่เป็นธรรม ทั้งรัฐยังอาจประกาศให้สินค้าบางรายการเป็นสินค้าควบคุมในภาวะวิกฤต\n\nการนำป้ายราคาออกเพื่อกำหนดราคาแตกต่างกันตามลูกค้าแต่ละรายจึงทั้งไม่โปร่งใสและขัดต่อหน้าที่แสดงราคา ผู้บริโภคที่พบการกระทำดังกล่าวสามารถร้องเรียนได้ที่กรมการค้าภายใน สายด่วน 1569", "choices": [{"label": "A", "text": "ทำได้ เพราะเป็นกลไกตลาดตามอุปสงค์และอุปทาน และร้านยาเป็นธุรกิจเอกชน", "is_correct": false, "explanation": "ผิด แม้ร้านยาเป็นธุรกิจ แต่การค้ากำไรเกินควรจากสินค้าจำเป็นในภาวะขาดแคลนขัดต่อจรรยาบรรณ และการไม่แสดงราคาขัดต่อกฎหมาย"}, {"label": "B", "text": "ทำได้ หากราคาที่ตั้งใหม่ยังต่ำกว่าราคาที่ขายในตลาดออนไลน์ในช่วงเดียวกัน", "is_correct": false, "explanation": "ผิด การเทียบกับราคาที่สูงเกินควรในตลาดอื่นไม่ทำให้การขึ้นราคาเป็นธรรม และยังคงต้องแสดงราคาให้ชัดเจน"}, {"label": "C", "text": "ไม่ควรทำ ต้องขายในราคาที่เป็นธรรม แสดงราคาชัดเจน และไม่ค้ากำไรเกินควร", "is_correct": true, "explanation": "ถูก สอดคล้องกับจรรยาบรรณและกฎหมายว่าด้วยราคาสินค้าและบริการ ซึ่งผู้บริโภคร้องเรียนได้ที่สายด่วน 1569"}, {"label": "D", "text": "ทำได้ หากขายเฉพาะลูกค้าทั่วไป แต่คงราคาเดิมไว้สำหรับลูกค้าประจำของร้าน", "is_correct": false, "explanation": "ผิด การตั้งราคาต่างกันตามความพอใจโดยไม่แสดงราคาเป็นการเลือกปฏิบัติและไม่โปร่งใส ไม่ได้แก้ปัญหาการค้ากำไรเกินควร"}, {"label": "E", "text": "ไม่ควรทำ เพราะร้านยาต้องจำหน่ายหน้ากากในราคาทุนตลอดเวลาที่มีค่าฝุ่นสูง", "is_correct": false, "explanation": "ผิด ไม่มีหลักที่บังคับให้ร้านยาขายในราคาทุน ร้านยามีสิทธิได้กำไรที่สมเหตุสมผล ประเด็นคือห้ามค้ากำไรเกินควรและต้องแสดงราคา"}], "key_takeaway": "สินค้าสุขภาพจำเป็นในภาวะขาดแคลนต้องขายในราคาเป็นธรรมและแสดงราคาชัดเจน การค้ากำไรเกินควรขัดจรรยาบรรณและอาจผิดกฎหมาย (ร้องเรียน 1569)"}'::jsonb, 'medium', 'law-day2 • จริยธรรมด้านราคาและการคุ้มครองผู้บริโภค'),
('cd66fd4518b476abcded7841786a97a7', 86, 'ร้านยาเครือข่ายแห่งหนึ่งมีผลิตภัณฑ์เสริมอาหารวิตามินซีตราของร้านเอง (house brand) ซึ่งให้กำไรสูงกว่าตราอื่นมาก ผู้บริหารกำหนดเป้าหมายยอดขายและให้ค่าตอบแทนพิเศษแก่เภสัชกรตามยอดขายตราของร้าน ลูกค้ารายหนึ่งถามเภสัชกรว่าควรซื้อวิตามินซีตราใด ข้อใดเป็นการปฏิบัติที่สอดคล้องกับจรรยาบรรณมากที่สุด', '[{"label": "A", "text": "แนะนำเฉพาะตราของร้าน เพราะเป็นนโยบายของนายจ้างและไม่ใช่ยาที่มีอันตราย"}, {"label": "B", "text": "ประเมินความจำเป็นก่อน แล้วให้ข้อมูลทางเลือกและราคาอย่างเป็นกลาง"}, {"label": "C", "text": "แนะนำตราของร้านพร้อมบอกว่าตราอื่นมักมีสารปนเปื้อนมากกว่า เพื่อให้ลูกค้ามั่นใจ"}, {"label": "D", "text": "ปฏิเสธที่จะแนะนำตราใดเลย และให้ลูกค้าเลือกเองจากชั้นวางโดยไม่ให้ข้อมูล"}, {"label": "E", "text": "แนะนำตราของร้านได้ หากลดราคาให้ลูกค้าเท่ากับตราที่ถูกที่สุดในร้าน"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ประเมินว่าลูกค้าจำเป็นต้องใช้หรือไม่ ให้ข้อมูลทางเลือกตามหลักฐานและราคาอย่างเป็นกลาง และให้ลูกค้าตัดสินใจเอง — ประโยชน์ของผู้รับบริการต้องอยู่เหนือผลประโยชน์ทางการค้า", "reason": "สถานการณ์นี้เป็นผลประโยชน์ทับซ้อน (conflict of interest) เพราะเภสัชกรได้ประโยชน์ส่วนตัวจากการแนะนำตราสินค้าหนึ่ง จรรยาบรรณวิชาชีพเภสัชกรรมกำหนดให้เภสัชกรยึดประโยชน์ของผู้รับบริการเป็นสำคัญ และไม่ให้ผลประโยชน์ทางการค้ามามีอิทธิพลเหนือการให้คำแนะนำทางวิชาชีพ\n\nแนวทางที่เหมาะสมเริ่มจากประเมินว่าลูกค้าจำเป็นต้องใช้ผลิตภัณฑ์หรือไม่ หากเหมาะสมจึงให้ข้อมูลทางเลือกที่มีคุณภาพเทียบเท่ากันอย่างเป็นกลาง รวมถึงราคา เพื่อให้ลูกค้าตัดสินใจเองได้ (autonomy) การแนะนำตราของร้านไม่ผิดในตัวเองหากเป็นทางเลือกที่เหมาะสมและให้ข้อมูลโปร่งใส แต่การปกปิดทางเลือกอื่น การพูดเกินจริง หรือการกล่าวหาตราอื่นโดยไม่มีหลักฐาน เป็นการแสวงหาผลประโยชน์จากความไว้วางใจของผู้ป่วย", "choices": [{"label": "A", "text": "แนะนำเฉพาะตราของร้าน เพราะเป็นนโยบายของนายจ้างและไม่ใช่ยาที่มีอันตราย", "is_correct": false, "explanation": "ผิด นโยบายนายจ้างไม่อยู่เหนือหน้าที่ต่อผู้รับบริการ การแนะนำเฉพาะสินค้าที่ตนได้ประโยชน์โดยไม่ให้ทางเลือกเป็นผลประโยชน์ทับซ้อน"}, {"label": "B", "text": "ประเมินความจำเป็นก่อน แล้วให้ข้อมูลทางเลือกและราคาอย่างเป็นกลาง", "is_correct": true, "explanation": "ถูก ยึดประโยชน์ของผู้รับบริการและเคารพการตัดสินใจของลูกค้า โดยไม่ให้ผลประโยชน์ทางการค้ามีอิทธิพลต่อคำแนะนำ"}, {"label": "C", "text": "แนะนำตราของร้านพร้อมบอกว่าตราอื่นมักมีสารปนเปื้อนมากกว่า เพื่อให้ลูกค้ามั่นใจ", "is_correct": false, "explanation": "ผิด การกล่าวอ้างถึงผลิตภัณฑ์อื่นโดยไม่มีหลักฐานเป็นการให้ข้อมูลเท็จและชักจูงผู้บริโภคอย่างไม่เป็นธรรม"}, {"label": "D", "text": "ปฏิเสธที่จะแนะนำตราใดเลย และให้ลูกค้าเลือกเองจากชั้นวางโดยไม่ให้ข้อมูล", "is_correct": false, "explanation": "ผิด การปฏิเสธให้ข้อมูลเป็นการละทิ้งบทบาทผู้ให้คำปรึกษา ลูกค้าคาดหวังข้อมูลที่เป็นกลางจากเภสัชกร"}, {"label": "E", "text": "แนะนำตราของร้านได้ หากลดราคาให้ลูกค้าเท่ากับตราที่ถูกที่สุดในร้าน", "is_correct": false, "explanation": "ผิด การลดราคาไม่ได้แก้ปัญหาการขาดการประเมินความจำเป็นและการไม่ให้ข้อมูลทางเลือก หลักสำคัญคือคำแนะนำต้องเป็นกลางและเพื่อประโยชน์ของลูกค้า"}], "key_takeaway": "เมื่อมีผลประโยชน์ทางการค้าเกี่ยวข้อง เภสัชกรต้องให้คำแนะนำโดยยึดความจำเป็นของผู้รับบริการและข้อมูลทางเลือกอย่างเป็นกลาง"}'::jsonb, 'hard', 'law-day2 • ผลประโยชน์ทับซ้อนในการแนะนำผลิตภัณฑ์ที่ร้านได้กำไร'),
('8cb78c09782282244a893da7cbd5357c', 87, 'ชายอายุ 30 ปี มาที่ร้านยาด้วยอาการน้ำมูกใส ไอเล็กน้อย เจ็บคอเล็กน้อย ไม่มีไข้ เป็นมา 2 วัน ขอซื้อ "ยาแก้อักเสบ" amoxicillin เพราะเคยกินแล้วหายเร็ว ตามนโยบายการใช้ยาอย่างสมเหตุผล (RDU) และแนวคิด Antibiotics Smart Use เภสัชกรควรปฏิบัติอย่างไร', '[{"label": "A", "text": "จ่าย amoxicillin ตามที่ขอ เพราะเคารพสิทธิในการตัดสินใจของผู้ป่วย"}, {"label": "B", "text": "จ่ายยาปฏิชีวนะเพียง 3 วันแทนจำนวนเต็ม เพื่อลดปัญหาเชื้อดื้อยาในชุมชน"}, {"label": "C", "text": "ปฏิเสธการจ่ายยาทุกชนิด และแนะนำให้ไปพบแพทย์ที่โรงพยาบาลทันที"}, {"label": "D", "text": "จ่ายยาปฏิชีวนะชนิดออกฤทธิ์กว้างกว่าเพื่อให้ครอบคลุมเชื้อหลายชนิด"}, {"label": "E", "text": "อธิบายว่ายาปฏิชีวนะไม่ช่วยโรคนี้ ให้ยาบรรเทาอาการ และแนะนำอาการเตือน"}]'::jsonb, 'E', '{"summary": "คำตอบที่ถูกต้อง: E. อธิบายว่าอาการเข้าได้กับโรคที่มักเกิดจากไวรัสซึ่งยาปฏิชีวนะไม่ช่วย ให้ยาบรรเทาอาการและแนะนำสัญญาณที่ต้องพบแพทย์ — เป็นหน้าที่วิชาชีพในการป้องกันเชื้อดื้อยา", "reason": "อาการหวัดที่มีน้ำมูกใส ไอ เจ็บคอเล็กน้อยโดยไม่มีไข้ ส่วนใหญ่เกิดจากเชื้อไวรัสและหายได้เอง ยาปฏิชีวนะไม่ช่วยให้หายเร็วขึ้นแต่เพิ่มความเสี่ยงต่ออาการไม่พึงประสงค์และเชื้อดื้อยา แนวคิด Antibiotics Smart Use ซึ่งเป็นส่วนหนึ่งของนโยบายส่งเสริมการใช้ยาอย่างสมเหตุผล ส่งเสริมให้บุคลากรสุขภาพรวมทั้งเภสัชกรร้านยาไม่จ่ายยาปฏิชีวนะใน 3 กลุ่มโรคที่พบบ่อย ได้แก่ หวัดเจ็บคอ ท้องร่วงเฉียบพลัน และแผลเลือดออก ที่ไม่มีข้อบ่งใช้\n\nนอกจากนี้ควรอธิบายให้ประชาชนเข้าใจว่า \"ยาแก้อักเสบ\" ที่คนทั่วไปเรียกนั้นคือยาปฏิชีวนะ ซึ่งฆ่าเชื้อแบคทีเรีย ไม่ใช่ยาลดการอักเสบ การปฏิเสธจ่ายยาปฏิชีวนะที่ไม่จำเป็นพร้อมให้ความรู้และการดูแลที่เหมาะสมจึงเป็นหน้าที่ทางวิชาชีพ ไม่ใช่การปฏิเสธการให้บริการ", "choices": [{"label": "A", "text": "จ่าย amoxicillin ตามที่ขอ เพราะเคารพสิทธิในการตัดสินใจของผู้ป่วย", "is_correct": false, "explanation": "ผิด หลัก autonomy ไม่ได้บังคับให้เภสัชกรจ่ายยาที่ไม่มีข้อบ่งใช้และอาจก่อผลเสีย เภสัชกรมีหน้าที่ให้ข้อมูลและใช้วิจารณญาณทางวิชาชีพ"}, {"label": "B", "text": "จ่ายยาปฏิชีวนะเพียง 3 วันแทนจำนวนเต็ม เพื่อลดปัญหาเชื้อดื้อยาในชุมชน", "is_correct": false, "explanation": "ผิด การใช้ยาปฏิชีวนะโดยไม่มีข้อบ่งใช้เป็นปัญหาไม่ว่าจะใช้นานเท่าใด และการใช้ไม่ครบขนาดยิ่งไม่แก้ปัญหาเชื้อดื้อยา"}, {"label": "C", "text": "ปฏิเสธการจ่ายยาทุกชนิด และแนะนำให้ไปพบแพทย์ที่โรงพยาบาลทันที", "is_correct": false, "explanation": "ผิด อาการไม่รุนแรงและดูแลได้ในร้านยา การปฏิเสธโดยไม่ให้การดูแลบรรเทาอาการและไม่ให้ความรู้ไม่ใช่การปฏิบัติที่เหมาะสม"}, {"label": "D", "text": "จ่ายยาปฏิชีวนะชนิดออกฤทธิ์กว้างกว่าเพื่อให้ครอบคลุมเชื้อหลายชนิด", "is_correct": false, "explanation": "ผิด การใช้ยาปฏิชีวนะออกฤทธิ์กว้างโดยไม่มีข้อบ่งใช้ยิ่งเพิ่มความเสี่ยงการเกิดเชื้อดื้อยา ขัดต่อหลัก RDU"}, {"label": "E", "text": "อธิบายว่ายาปฏิชีวนะไม่ช่วยโรคนี้ ให้ยาบรรเทาอาการ และแนะนำอาการเตือน", "is_correct": true, "explanation": "ถูก เป็นแนวทางตามหลัก Antibiotics Smart Use: ไม่จ่ายยาปฏิชีวนะโดยไม่จำเป็น ให้ความรู้ และดูแลตามอาการพร้อมแนะนำสัญญาณเตือน"}], "key_takeaway": "การไม่จ่ายยาปฏิชีวนะที่ไม่มีข้อบ่งใช้ พร้อมให้ความรู้และดูแลตามอาการ เป็นหน้าที่ทางวิชาชีพตามนโยบาย RDU/Antibiotics Smart Use"}'::jsonb, 'easy', 'law-day2 • การใช้ยาปฏิชีวนะอย่างสมเหตุผลในฐานะหน้าที่วิชาชีพ'),
('11877574e6fd4814fd1bd139257da80d', 88, 'คณะกรรมการเภสัชกรรมและการบำบัด (PTC) ของโรงพยาบาลแห่งหนึ่งมอบหมายให้กลุ่มงานเภสัชกรรมประเมินการใช้ยา (drug use evaluation; DUE) ของยาฉีดราคาแพงชนิดหนึ่งในบัญชียาโรงพยาบาล ผลพบว่าร้อยละ 40 ของการสั่งใช้ไม่เป็นไปตามเกณฑ์ที่ PTC กำหนด ข้อใดเป็นขั้นตอนต่อไปที่สอดคล้องกับหลักการของ DUE มากที่สุด', '[{"label": "A", "text": "ตัดยาออกจากบัญชียาโรงพยาบาลทันที เพราะพิสูจน์แล้วว่าใช้ไม่สมเหตุผล"}, {"label": "B", "text": "ส่งรายชื่อแพทย์ที่สั่งใช้ไม่ตรงเกณฑ์ให้ผู้อำนวยการเพื่อพิจารณาโทษทางวินัย"}, {"label": "C", "text": "ให้เภสัชกรปฏิเสธการจ่ายยาทุกครั้งที่ไม่ตรงเกณฑ์ โดยไม่ต้องแจ้ง PTC"}, {"label": "D", "text": "รายงานผลต่อ PTC ป้อนกลับผู้สั่งใช้ ดำเนินมาตรการแก้ไข และประเมินซ้ำเพื่อติดตามผล"}, {"label": "E", "text": "เก็บผลการประเมินไว้เป็นความลับภายในกลุ่มงานเภสัชกรรมเพื่อไม่ให้เกิดความขัดแย้ง"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. นำผลเสนอ PTC และป้อนกลับผู้สั่งใช้ กำหนดมาตรการแก้ไข แล้วประเมินซ้ำ — DUE เป็นกระบวนการพัฒนาคุณภาพแบบต่อเนื่อง ไม่ใช่การจับผิดรายบุคคล", "reason": "DUE เป็นกระบวนการประกันคุณภาพที่ทำอย่างต่อเนื่องและเป็นระบบ โดยกำหนดเกณฑ์การใช้ยาที่ได้รับความเห็นชอบจาก PTC เก็บข้อมูลเทียบกับเกณฑ์ วิเคราะห์ผล แล้วนำผลไปสู่มาตรการแก้ไข เช่น การป้อนกลับข้อมูลแก่ผู้สั่งใช้ การให้ความรู้ การปรับแบบฟอร์มสั่งใช้หรือระบบอนุมัติ และสุดท้ายต้องประเมินซ้ำเพื่อดูว่ามาตรการได้ผลหรือไม่ (ปิดวงจรคุณภาพ)\n\nการดำเนินการควรโปร่งใส ใช้ข้อมูลและเกณฑ์ที่เปิดเผยต่อผู้เกี่ยวข้อง ผ่านกลไกของ PTC ซึ่งเป็นตัวแทนสหวิชาชีพ มากกว่าการลงโทษหรือประจานแพทย์รายบุคคล ส่วนการตัดยาออกจากบัญชีทันทีโดยไม่ได้แก้ไขปัจจัยที่ทำให้ใช้ไม่เหมาะสมอาจส่งผลเสียต่อผู้ป่วยที่มีข้อบ่งใช้จริง", "choices": [{"label": "A", "text": "ตัดยาออกจากบัญชียาโรงพยาบาลทันที เพราะพิสูจน์แล้วว่าใช้ไม่สมเหตุผล", "is_correct": false, "explanation": "ผิด การใช้ไม่ตรงเกณฑ์บางส่วนไม่ได้แปลว่ายาไม่มีประโยชน์ การตัดยาทันทีส่งผลกระทบต่อผู้ป่วยที่มีข้อบ่งใช้จริงและข้ามขั้นตอนการแก้ไข"}, {"label": "B", "text": "ส่งรายชื่อแพทย์ที่สั่งใช้ไม่ตรงเกณฑ์ให้ผู้อำนวยการเพื่อพิจารณาโทษทางวินัย", "is_correct": false, "explanation": "ผิด DUE มุ่งพัฒนาคุณภาพเชิงระบบ การใช้ผลเพื่อลงโทษรายบุคคลทำลายความร่วมมือและไม่ใช่วัตถุประสงค์ของ DUE"}, {"label": "C", "text": "ให้เภสัชกรปฏิเสธการจ่ายยาทุกครั้งที่ไม่ตรงเกณฑ์ โดยไม่ต้องแจ้ง PTC", "is_correct": false, "explanation": "ผิด การกำหนดมาตรการจำกัดการใช้ยาต้องผ่านความเห็นชอบของ PTC อย่างโปร่งใส และเภสัชกรควรสื่อสารกับแพทย์เมื่อมีปัญหา ไม่ปฏิเสธฝ่ายเดียว"}, {"label": "D", "text": "รายงานผลต่อ PTC ป้อนกลับผู้สั่งใช้ ดำเนินมาตรการแก้ไข และประเมินซ้ำเพื่อติดตามผล", "is_correct": true, "explanation": "ถูก เป็นวงจรของ DUE ที่สมบูรณ์ ตั้งแต่การวิเคราะห์ผล การแทรกแซง จนถึงการประเมินซ้ำ ผ่านกลไก PTC อย่างโปร่งใส"}, {"label": "E", "text": "เก็บผลการประเมินไว้เป็นความลับภายในกลุ่มงานเภสัชกรรมเพื่อไม่ให้เกิดความขัดแย้ง", "is_correct": false, "explanation": "ผิด ผลการประเมินที่ไม่ได้นำไปสื่อสารและแก้ไขไม่ทำให้คุณภาพการใช้ยาดีขึ้น และขัดกับหลักความโปร่งใสของ PTC"}], "key_takeaway": "DUE คือวงจรพัฒนาคุณภาพ: เกณฑ์ → ประเมิน → ป้อนกลับ/แก้ไขผ่าน PTC → ประเมินซ้ำ ไม่ใช่เครื่องมือลงโทษรายบุคคล"}'::jsonb, 'hard', 'law-day2 • การประเมินการใช้ยา (DUE) และความโปร่งใสของคณะกรรมการ PTC'),
('ee4add9b9b6eef1642ddc7fb4299483c', 89, 'ร้านยาแห่งหนึ่งจัดบริการคัดกรองระดับน้ำตาลในเลือดด้วยการเจาะเลือดปลายนิ้ว (point-of-care testing) และมีค่าบริการ เภสัชกรต้องการให้การขอความยินยอม (informed consent) ก่อนให้บริการเป็นไปอย่างถูกต้อง ข้อใดถูกต้องที่สุด', '[{"label": "A", "text": "อธิบายวัตถุประสงค์ วิธีการ ความเสี่ยง ค่าใช้จ่าย และสิทธิในการปฏิเสธ"}, {"label": "B", "text": "ให้ผู้รับบริการลงนามในแบบฟอร์มก่อน จากนั้นจึงอธิบายรายละเอียดหากมีผู้ถาม"}, {"label": "C", "text": "ไม่ต้องขอความยินยอม เพราะผู้รับบริการเดินมาขอใช้บริการด้วยตนเองแล้ว"}, {"label": "D", "text": "ความยินยอมต้องเป็นลายลักษณ์อักษรต่อหน้าพยาน 2 คนจึงจะมีผลทุกกรณี"}, {"label": "E", "text": "เมื่อให้ความยินยอมแล้ว ผู้รับบริการไม่สามารถเปลี่ยนใจได้เพราะชำระเงินแล้ว"}]'::jsonb, 'A', '{"summary": "คำตอบที่ถูกต้อง: A. ต้องอธิบายวัตถุประสงค์ วิธีการ ความเสี่ยง ค่าใช้จ่าย และข้อจำกัดของผล และผู้รับบริการมีสิทธิปฏิเสธได้โดยสมัครใจ — องค์ประกอบของ informed consent", "reason": "ความยินยอมโดยได้รับข้อมูล (informed consent) ที่สมบูรณ์มีองค์ประกอบหลัก ได้แก่ การเปิดเผยข้อมูลที่เพียงพอ (วัตถุประสงค์ วิธีการ ความเสี่ยงหรือความไม่สบายที่อาจเกิด ค่าใช้จ่าย ข้อจำกัดของผลตรวจว่าเป็นการคัดกรองไม่ใช่การวินิจฉัย และการส่งต่อเมื่อผลผิดปกติ) ความเข้าใจของผู้รับบริการ ความสมัครใจปราศจากการบังคับ และความสามารถในการตัดสินใจ\n\nความยินยอมไม่จำเป็นต้องเป็นลายลักษณ์อักษรเสมอสำหรับหัตถการที่มีความเสี่ยงต่ำ อาจเป็นการยินยอมด้วยวาจาได้ (แม้การบันทึกไว้จะเป็นแนวปฏิบัติที่ดี) สิ่งสำคัญคือกระบวนการให้ข้อมูลและความเข้าใจ ไม่ใช่แค่ลายมือชื่อ และผู้รับบริการมีสิทธิปฏิเสธหรือถอนความยินยอมได้", "choices": [{"label": "A", "text": "อธิบายวัตถุประสงค์ วิธีการ ความเสี่ยง ค่าใช้จ่าย และสิทธิในการปฏิเสธ", "is_correct": true, "explanation": "ถูก ครอบคลุมการเปิดเผยข้อมูลที่จำเป็นและความสมัครใจ ซึ่งเป็นองค์ประกอบของ informed consent"}, {"label": "B", "text": "ให้ผู้รับบริการลงนามในแบบฟอร์มก่อน จากนั้นจึงอธิบายรายละเอียดหากมีผู้ถาม", "is_correct": false, "explanation": "ผิด การลงนามก่อนได้รับข้อมูลไม่ใช่ความยินยอมโดยได้รับข้อมูล ลายมือชื่อไม่มีความหมายหากไม่มีความเข้าใจ"}, {"label": "C", "text": "ไม่ต้องขอความยินยอม เพราะผู้รับบริการเดินมาขอใช้บริการด้วยตนเองแล้ว", "is_correct": false, "explanation": "ผิด การมาขอรับบริการไม่ได้หมายความว่าได้รับข้อมูลครบถ้วนแล้ว เภสัชกรยังต้องให้ข้อมูลที่จำเป็นต่อการตัดสินใจ"}, {"label": "D", "text": "ความยินยอมต้องเป็นลายลักษณ์อักษรต่อหน้าพยาน 2 คนจึงจะมีผลทุกกรณี", "is_correct": false, "explanation": "ผิด หัตถการความเสี่ยงต่ำอาจยินยอมด้วยวาจาได้ ไม่มีหลักว่าต้องมีพยาน 2 คนทุกกรณี สาระสำคัญอยู่ที่การให้ข้อมูลและความสมัครใจ"}, {"label": "E", "text": "เมื่อให้ความยินยอมแล้ว ผู้รับบริการไม่สามารถเปลี่ยนใจได้เพราะชำระเงินแล้ว", "is_correct": false, "explanation": "ผิด ผู้รับบริการมีสิทธิถอนความยินยอมได้ก่อนรับบริการ การชำระเงินไม่ได้ตัดสิทธินี้"}], "key_takeaway": "informed consent ต้องมีการให้ข้อมูลที่เพียงพอ ความเข้าใจ และความสมัครใจ โดยผู้รับบริการยังมีสิทธิปฏิเสธหรือถอนความยินยอมได้"}'::jsonb, 'medium', 'law-day2 • ความยินยอมโดยได้รับข้อมูลสำหรับบริการในร้านยา'),
('17a8adee1470492cca4d7f934ef86907', 90, 'แรงงานข้ามชาติชาวเมียนมารายหนึ่งซึ่งพูดภาษาไทยได้น้อยมาก มารับยาที่ห้องจ่ายยาของโรงพยาบาลพร้อมใบสั่งยาหลายรายการ ผู้ป่วยรายอื่นต่อคิวยาว เจ้าหน้าที่เสนอให้ส่งมอบยาโดยไม่ต้องอธิบายเพราะสื่อสารไม่ได้ ข้อใดเป็นการปฏิบัติที่เหมาะสมที่สุด', '[{"label": "A", "text": "ส่งมอบยาตามที่เจ้าหน้าที่เสนอ เพราะไม่ควรให้ผู้ป่วยรายอื่นรอนานขึ้น"}, {"label": "B", "text": "ให้ผู้ป่วยกลับไปพาญาติที่พูดไทยได้มารับยาแทนในวันถัดไป"}, {"label": "C", "text": "จัดหาล่ามหรือเครื่องมือช่วยสื่อสาร และตรวจสอบความเข้าใจก่อนส่งมอบยา"}, {"label": "D", "text": "อธิบายเป็นภาษาไทยช้าๆ ตามปกติ แล้วให้ผู้ป่วยลงนามว่ารับทราบวิธีใช้ยาแล้ว"}, {"label": "E", "text": "ส่งต่อให้คลินิกเอกชนที่มีล่ามดูแลแทน เพราะโรงพยาบาลรัฐไม่มีหน้าที่จัดล่าม"}]'::jsonb, 'C', '{"summary": "คำตอบที่ถูกต้อง: C. จัดหาล่ามหรือเครื่องมือช่วยสื่อสาร เช่น ฉลากภาพ เพื่อให้ผู้ป่วยเข้าใจการใช้ยาเท่าเทียมผู้ป่วยอื่น — ผู้ป่วยทุกคนมีสิทธิได้รับบริการโดยไม่ถูกเลือกปฏิบัติ", "reason": "คำประกาศสิทธิและข้อพึงปฏิบัติของผู้ป่วยรับรองสิทธิของผู้ป่วยทุกคนในการได้รับบริการด้านสุขภาพที่มีคุณภาพโดยไม่ถูกเลือกปฏิบัติเพราะเหตุแห่งเชื้อชาติ สัญชาติ ศาสนา ฐานะ เพศ อายุ ความพิการ หรือเหตุอื่น และสิทธิได้รับข้อมูลที่เพียงพอและเข้าใจได้ การส่งมอบยาโดยไม่อธิบายเพราะอุปสรรคด้านภาษาทำให้ผู้ป่วยเสี่ยงต่อการใช้ยาผิด จึงเป็นทั้งปัญหาความปลอดภัยและการเลือกปฏิบัติ\n\nเภสัชกรควรใช้ทรัพยากรที่มีอยู่เพื่อให้ผู้ป่วยเข้าใจ เช่น ล่ามของโรงพยาบาลหรือพนักงานสื่อสารสาธารณสุขต่างด้าว ฉลากยาแบบรูปภาพหรือสองภาษา เครื่องมือแปลภาษา และตรวจสอบความเข้าใจด้วยการให้ผู้ป่วยแสดงวิธีใช้ หลักเดียวกันใช้กับผู้สูงอายุ ผู้พิการทางการได้ยิน หรือผู้มีข้อจำกัดในการอ่าน ที่ต้องปรับวิธีสื่อสารให้เหมาะสม", "choices": [{"label": "A", "text": "ส่งมอบยาตามที่เจ้าหน้าที่เสนอ เพราะไม่ควรให้ผู้ป่วยรายอื่นรอนานขึ้น", "is_correct": false, "explanation": "ผิด ความเร่งรีบไม่ใช่เหตุผลในการลดคุณภาพบริการแก่ผู้ป่วยบางกลุ่ม และการไม่อธิบายทำให้เสี่ยงต่อการใช้ยาผิด"}, {"label": "B", "text": "ให้ผู้ป่วยกลับไปพาญาติที่พูดไทยได้มารับยาแทนในวันถัดไป", "is_correct": false, "explanation": "ผิด การเลื่อนการรับยาอาจทำให้การรักษาล่าช้า และเป็นการผลักภาระให้ผู้ป่วยแทนการจัดหาความช่วยเหลือด้านการสื่อสาร"}, {"label": "C", "text": "จัดหาล่ามหรือเครื่องมือช่วยสื่อสาร และตรวจสอบความเข้าใจก่อนส่งมอบยา", "is_correct": true, "explanation": "ถูก ทำให้ผู้ป่วยได้รับข้อมูลที่เข้าใจได้ เท่าเทียมกับผู้ป่วยอื่น สอดคล้องกับสิทธิผู้ป่วยและความปลอดภัยในการใช้ยา"}, {"label": "D", "text": "อธิบายเป็นภาษาไทยช้าๆ ตามปกติ แล้วให้ผู้ป่วยลงนามว่ารับทราบวิธีใช้ยาแล้ว", "is_correct": false, "explanation": "ผิด การให้ลงนามโดยที่ผู้ป่วยไม่เข้าใจภาษาไม่ได้ทำให้ผู้ป่วยรับทราบจริง เป็นเพียงการปกป้องผู้ให้บริการ"}, {"label": "E", "text": "ส่งต่อให้คลินิกเอกชนที่มีล่ามดูแลแทน เพราะโรงพยาบาลรัฐไม่มีหน้าที่จัดล่าม", "is_correct": false, "explanation": "ผิด การปฏิเสธหรือส่งต่อเพราะเหตุสัญชาติหรือภาษาเป็นการเลือกปฏิบัติ หน่วยบริการควรปรับวิธีการสื่อสารให้ผู้ป่วยเข้าถึงบริการได้"}], "key_takeaway": "ผู้ป่วยกลุ่มเปราะบาง เช่น แรงงานข้ามชาติ ผู้สูงอายุ ผู้พิการ ต้องได้รับข้อมูลยาที่เข้าใจได้โดยปรับวิธีสื่อสาร ไม่ถูกเลือกปฏิบัติ"}'::jsonb, 'medium', 'law-day2 • สิทธิของกลุ่มเปราะบางและการไม่เลือกปฏิบัติ'),
('1770070e918e85ab537d1792ac5c7a4c', 91, 'ตัวแทนจำหน่ายผลิตภัณฑ์สมุนไพรชนิดแคปซูลรายหนึ่งเสนอให้ร้านยาวางจำหน่ายสินค้า โดยมอบแผ่นพับและป้ายตั้งโต๊ะที่มีข้อความว่า "ยับยั้งเซลล์มะเร็ง ใช้แทนเคมีบำบัดได้ ปลอดภัย 100%" และให้ส่วนแบ่งกำไรสูง ข้อใดเป็นการปฏิบัติที่เหมาะสมที่สุดของเภสัชกร', '[{"label": "A", "text": "รับมาจำหน่ายได้ หากตรวจสอบแล้วว่าผลิตภัณฑ์มีเลขทะเบียนหรือเลขที่ใบรับแจ้งถูกต้อง"}, {"label": "B", "text": "ไม่นำสื่อโฆษณามาแสดงหรือขายด้วยข้อความนั้น และแจ้ง อย. ทางสายด่วน 1556"}, {"label": "C", "text": "รับมาจำหน่ายโดยเก็บแผ่นพับไว้หลังร้าน และให้ข้อมูลเฉพาะลูกค้าที่ถามถึงเท่านั้น"}, {"label": "D", "text": "รับมาจำหน่ายได้ หากติดป้ายเพิ่มว่า \"ผลลัพธ์ขึ้นอยู่กับแต่ละบุคคล\""}, {"label": "E", "text": "แจ้งเรื่องต่อ สคบ. เท่านั้น เพราะ อย. ไม่มีอำนาจกำกับการโฆษณาผลิตภัณฑ์สมุนไพร"}]'::jsonb, 'B', '{"summary": "คำตอบที่ถูกต้อง: B. ไม่นำสื่อโฆษณาดังกล่าวมาแสดงหรือจำหน่ายผลิตภัณฑ์ด้วยข้อความนั้น และแจ้ง อย. (1556) — ข้อความอวดอ้างรักษาโรคร้ายแรงเป็นการโฆษณาที่ผิดกฎหมายและเป็นอันตรายต่อผู้บริโภค", "reason": "ข้อความ \"ยับยั้งเซลล์มะเร็ง ใช้แทนเคมีบำบัดได้ ปลอดภัย 100%\" เป็นการโฆษณาอวดอ้างสรรพคุณเกินจริงเกี่ยวกับการรักษาโรคร้ายแรง ซึ่งกฎหมายที่กำกับผลิตภัณฑ์สุขภาพ (เช่น กฎหมายผลิตภัณฑ์สมุนไพร กฎหมายยา และกฎหมายอาหาร) ไม่อนุญาตให้โฆษณาในลักษณะนี้ และข้อความว่า \"ใช้แทนเคมีบำบัดได้\" อาจทำให้ผู้ป่วยมะเร็งหยุดการรักษาที่จำเป็นจนเกิดอันตรายร้ายแรง\n\nเภสัชกรมีหน้าที่คุ้มครองผู้บริโภค จึงไม่ควรนำสื่อดังกล่าวมาแสดงในร้าน ไม่ควรจำหน่ายผลิตภัณฑ์โดยอ้างสรรพคุณนั้น ควรตรวจสอบสถานะการอนุญาตของผลิตภัณฑ์ และแจ้งเบาะแสการโฆษณาที่ผิดกฎหมายต่อ อย. ผ่านสายด่วน 1556 หรือ สสจ. ในพื้นที่ การได้รับส่วนแบ่งกำไรสูงไม่สามารถเป็นเหตุผลให้ละเลยหน้าที่นี้ได้", "choices": [{"label": "A", "text": "รับมาจำหน่ายได้ หากตรวจสอบแล้วว่าผลิตภัณฑ์มีเลขทะเบียนหรือเลขที่ใบรับแจ้งถูกต้อง", "is_correct": false, "explanation": "ผิด แม้ผลิตภัณฑ์ได้รับอนุญาต แต่การโฆษณาอวดอ้างรักษามะเร็งเกินจริงยังคงผิดกฎหมาย การมีเลขอนุญาตไม่ได้รับรองข้อความโฆษณา"}, {"label": "B", "text": "ไม่นำสื่อโฆษณามาแสดงหรือขายด้วยข้อความนั้น และแจ้ง อย. ทางสายด่วน 1556", "is_correct": true, "explanation": "ถูก ปฏิเสธการมีส่วนร่วมในการโฆษณาเกินจริงที่เป็นอันตราย และแจ้งหน่วยงานที่มีอำนาจตรวจสอบ"}, {"label": "C", "text": "รับมาจำหน่ายโดยเก็บแผ่นพับไว้หลังร้าน และให้ข้อมูลเฉพาะลูกค้าที่ถามถึงเท่านั้น", "is_correct": false, "explanation": "ผิด การสื่อสารสรรพคุณเกินจริงแก่ลูกค้าเป็นรายบุคคลยังคงเป็นการชักจูงที่อาจก่ออันตราย ไม่ได้แก้ปัญหา"}, {"label": "D", "text": "รับมาจำหน่ายได้ หากติดป้ายเพิ่มว่า \"ผลลัพธ์ขึ้นอยู่กับแต่ละบุคคล\"", "is_correct": false, "explanation": "ผิด ข้อความปฏิเสธความรับผิดชอบไม่ได้ทำให้การอวดอ้างรักษามะเร็งกลายเป็นข้อความที่ชอบด้วยกฎหมาย"}, {"label": "E", "text": "แจ้งเรื่องต่อ สคบ. เท่านั้น เพราะ อย. ไม่มีอำนาจกำกับการโฆษณาผลิตภัณฑ์สมุนไพร", "is_correct": false, "explanation": "ผิด อย. เป็นหน่วยงานหลักที่กำกับผลิตภัณฑ์สุขภาพรวมถึงผลิตภัณฑ์สมุนไพรและการโฆษณา จึงเป็นช่องทางที่เหมาะสมโดยตรง"}], "key_takeaway": "ข้อความอวดอ้างว่ารักษาโรคร้ายแรงหรือใช้แทนการรักษามาตรฐานเป็นโฆษณาผิดกฎหมาย เภสัชกรต้องไม่มีส่วนร่วมและควรแจ้ง อย. (1556)"}'::jsonb, 'medium', 'law-day2 • การคุ้มครองผู้บริโภค: การโฆษณาผลิตภัณฑ์สุขภาพเกินจริงในร้านยา'),
('7a604e75d8c31370431165c7cb2f185f', 92, 'เภสัชกรชายรายหนึ่งรู้สึกถูกใจผู้ป่วยหญิงที่มารับยาต้านซึมเศร้าที่ร้านเป็นประจำ จึงนำเบอร์โทรศัพท์ของผู้ป่วยจากระบบสมาชิกของร้านไปเพิ่มเป็นเพื่อนในแอปพลิเคชันส่วนตัวเพื่อชวนไปรับประทานอาหาร ข้อใดอธิบายประเด็นนี้ได้ถูกต้องที่สุด', '[{"label": "A", "text": "เหมาะสม เพราะทั้งสองฝ่ายเป็นผู้ใหญ่และเป็นเรื่องส่วนตัวนอกเวลางาน"}, {"label": "B", "text": "เหมาะสม หากผู้ป่วยตอบรับคำเชิญและไม่ได้ร้องเรียนต่อร้านภายหลัง"}, {"label": "C", "text": "ไม่เหมาะสม เฉพาะในส่วนที่ทำให้ร้านยาเสียภาพลักษณ์ทางธุรกิจเท่านั้น"}, {"label": "D", "text": "ไม่เหมาะสม เพราะใช้ข้อมูลผู้ป่วยนอกวัตถุประสงค์และข้ามขอบเขตวิชาชีพ"}, {"label": "E", "text": "ไม่เหมาะสม เพราะเภสัชกรต้องไม่มีความสัมพันธ์ส่วนตัวกับผู้ใดที่เคยมาซื้อยาตลอดชีวิต"}]'::jsonb, 'D', '{"summary": "คำตอบที่ถูกต้อง: D. ไม่เหมาะสม เพราะใช้ข้อมูลผู้ป่วยนอกวัตถุประสงค์ที่เก็บ และละเมิดขอบเขตความสัมพันธ์ทางวิชาชีพกับผู้ป่วยที่อยู่ในความดูแล", "reason": "ความสัมพันธ์ระหว่างเภสัชกรกับผู้ป่วยมีความไม่เท่าเทียมของอำนาจและข้อมูล เภสัชกรรู้ข้อมูลสุขภาพที่อ่อนไหวของผู้ป่วย โดยเฉพาะผู้ป่วยที่รับยาจิตเวชซึ่งอาจเปราะบาง การริเริ่มความสัมพันธ์ส่วนตัวหรือเชิงชู้สาวกับผู้ป่วยที่อยู่ในความดูแลจึงเป็นการละเมิดขอบเขตทางวิชาชีพ และอาจทำให้ผู้ป่วยรู้สึกถูกกดดันหรือไม่กล้ามารับบริการ\n\nนอกจากนี้ เบอร์โทรศัพท์ในระบบสมาชิกของร้านถูกเก็บเพื่อวัตถุประสงค์ในการให้บริการ การนำไปใช้เพื่อประโยชน์ส่วนตัวเป็นการใช้ข้อมูลส่วนบุคคลนอกวัตถุประสงค์ ซึ่งขัดต่อหลักการของ พ.ร.บ.คุ้มครองข้อมูลส่วนบุคคล พ.ศ. 2562 และหน้าที่รักษาความลับของผู้ป่วย การที่ทั้งสองฝ่ายเป็นผู้ใหญ่หรือการติดต่อนอกเวลางานไม่ได้ทำให้การกระทำนี้เหมาะสม", "choices": [{"label": "A", "text": "เหมาะสม เพราะทั้งสองฝ่ายเป็นผู้ใหญ่และเป็นเรื่องส่วนตัวนอกเวลางาน", "is_correct": false, "explanation": "ผิด การเป็นผู้ใหญ่ไม่ได้ลบล้างความไม่เท่าเทียมในความสัมพันธ์ทางวิชาชีพ และข้อมูลที่ใช้ได้มาจากการให้บริการ"}, {"label": "B", "text": "เหมาะสม หากผู้ป่วยตอบรับคำเชิญและไม่ได้ร้องเรียนต่อร้านภายหลัง", "is_correct": false, "explanation": "ผิด การที่ผู้ป่วยตอบรับไม่ได้ทำให้การใช้ข้อมูลนอกวัตถุประสงค์และการข้ามขอบเขตวิชาชีพกลายเป็นสิ่งที่เหมาะสม"}, {"label": "C", "text": "ไม่เหมาะสม เฉพาะในส่วนที่ทำให้ร้านยาเสียภาพลักษณ์ทางธุรกิจเท่านั้น", "is_correct": false, "explanation": "ผิด ประเด็นหลักคือการละเมิดขอบเขตวิชาชีพและการใช้ข้อมูลผู้ป่วยโดยมิชอบ ไม่ใช่เรื่องภาพลักษณ์ทางธุรกิจ"}, {"label": "D", "text": "ไม่เหมาะสม เพราะใช้ข้อมูลผู้ป่วยนอกวัตถุประสงค์และข้ามขอบเขตวิชาชีพ", "is_correct": true, "explanation": "ถูก ครอบคลุมทั้งการใช้ข้อมูลส่วนบุคคลนอกวัตถุประสงค์และการข้ามขอบเขตกับผู้ป่วยที่อยู่ในความดูแล"}, {"label": "E", "text": "ไม่เหมาะสม เพราะเภสัชกรต้องไม่มีความสัมพันธ์ส่วนตัวกับผู้ใดที่เคยมาซื้อยาตลอดชีวิต", "is_correct": false, "explanation": "ผิด เป็นการกล่าวเกินจริง หลักขอบเขตวิชาชีพมุ่งที่ความสัมพันธ์กับผู้ป่วยที่อยู่ในความดูแลและการใช้ข้อมูลโดยมิชอบ ไม่ได้ห้ามตลอดชีวิตกับทุกคนที่เคยซื้อยา"}], "key_takeaway": "เภสัชกรต้องรักษาขอบเขตความสัมพันธ์ทางวิชาชีพกับผู้ป่วยในความดูแล และห้ามใช้ข้อมูลผู้ป่วยเพื่อประโยชน์ส่วนตัว"}'::jsonb, 'medium', 'law-day2 • ขอบเขตความสัมพันธ์ทางวิชาชีพ (professional boundaries)')
) AS v(id, qn, scenario, choices, correct_answer, detailed_explanation, difficulty, ai_notes)
CROSS JOIN (SELECT id FROM public.mcq_subjects WHERE name = 'PharmacyLaw') s
ON CONFLICT (id) DO NOTHING;
